INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ArD', 'The root ارض (ا ر ض)', 'grammar', 2, '{"explanation":"The root ارض occurs 461 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْأَرْضَ","transliteration":"","meaning":"and the earth","rule":"2:255"},{"arabic":"ٱلْأَرْضُ","transliteration":"","meaning":"the earth","rule":"2:61"},{"arabic":"ٱلْأَرْضَ","transliteration":"","meaning":"the earth","rule":"2:22"},{"arabic":"وَٱلْأَرْضُ","transliteration":"","meaning":"and the earth","rule":"3:133"},{"arabic":"ٱلْأَرْضِ","transliteration":"","meaning":"the earth","rule":"2:11"},{"arabic":"وَٱلْأَرْضِ","transliteration":"","meaning":"and the earth","rule":"2:33"}],"rules":[{"name":"Words on ارض","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْأَرْضَ","ٱلْأَرْضُ","ٱلْأَرْضَ","وَٱلْأَرْضُ","ٱلْأَرْضِ","وَٱلْأَرْضِ","أَرْضُ"]},{"name":"Parts of speech attested for ارض","description":"The morphology corpus tags words on this root as N — one part of speech across the 7 glossed words attested.","examples":["وَٱلْأَرْضَ","ٱلْأَرْضُ","ٱلْأَرْضَ","وَٱلْأَرْضُ","ٱلْأَرْضِ","وَٱلْأَرْضِ"]},{"name":"Where ارض occurs","description":"The 7 glossed words on this root are attested across 3 distinct surahs.","examples":["وَٱلْأَرْضَ (2:255)","ٱلْأَرْضُ (2:61)","ٱلْأَرْضَ (2:22)","وَٱلْأَرْضُ (3:133)","ٱلْأَرْضِ (2:11)","وَٱلْأَرْضِ (2:33)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ارض?","options":["فَأْتِ","أَهْلُ","وَأَخَذْتُمْ","وَٱلْأَرْضَ"],"correct":3,"explanation":"وَٱلْأَرْضَ — glossed \"and the earth\" at 2:255 — carries the root ارض. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْأَرْضُ mean?","options":["do you hurt me","they take you","the earth","could bring you"],"correct":2,"explanation":"\"the earth\", from the word-by-word gloss at 2:61."},{"type":"fill_blank","question":"Type the root of ٱلْأَرْضَ in Arabic (three letters).","correct":"ارض","explanation":"ارض. Diacritics are ignored when checking, so ا ر ض is enough."}]', '["root-rsl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ywm', 'The root يوم (ي و م)', 'grammar', 2, '{"explanation":"The root يوم occurs 405 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَوْمٍۢ","transliteration":"","meaning":"(of) a day","rule":"2:259"},{"arabic":"بِٱلْيَوْمِ","transliteration":"","meaning":"in the Day","rule":"4:38"},{"arabic":"ٱلْأَيَّامُ","transliteration":"","meaning":"[the] days","rule":"3:140"},{"arabic":"يَوْمٌۭ","transliteration":"","meaning":"a Day","rule":"2:254"},{"arabic":"يَوْمًا","transliteration":"","meaning":"(for) a day","rule":"2:259"},{"arabic":"وَٱلْيَوْمِ","transliteration":"","meaning":"and the Day","rule":"2:62"}],"rules":[{"name":"Words on يوم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَوْمٍۢ","بِٱلْيَوْمِ","ٱلْأَيَّامُ","يَوْمٌۭ","يَوْمًا","وَٱلْيَوْمِ","أَيَّامٍ","يَوْمِ"]},{"name":"Parts of speech attested for يوم","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 19 glossed words attested.","examples":["يَوْمٍۢ","بِٱلْيَوْمِ","ٱلْأَيَّامُ","يَوْمٌۭ","يَوْمًا","وَٱلْيَوْمِ"]},{"name":"Where يوم occurs","description":"The 19 glossed words on this root are attested across 5 distinct surahs.","examples":["يَوْمٍۢ (2:259)","بِٱلْيَوْمِ (4:38)","ٱلْأَيَّامُ (3:140)","يَوْمٌۭ (2:254)","يَوْمًا (2:259)","وَٱلْيَوْمِ (2:62)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root يوم?","options":["أَئِمَّةًۭ","ٱللَّهُ","يَوْمٍۢ","لَذَهَبَ"],"correct":2,"explanation":"يَوْمٍۢ — glossed \"(of) a day\" at 2:259 — carries the root يوم. The others come from different roots."},{"type":"multiple_choice","question":"What does بِٱلْيَوْمِ mean?","options":["in the Verses","the remembrance","something","in the Day"],"correct":3,"explanation":"\"in the Day\", from the word-by-word gloss at 4:38."},{"type":"fill_blank","question":"Type the root of ٱلْأَيَّامُ in Arabic (three letters).","correct":"يوم","explanation":"يوم. Diacritics are ignored when checking, so ي و م is enough."}]', '["root-ArD"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ayy', 'The root ايي (ا ي ي)', 'grammar', 2, '{"explanation":"The root ايي occurs 382 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَـَٔايَةًۭ","transliteration":"","meaning":"(is) surely a sign","rule":"2:248"},{"arabic":"بِـَٔايَـٰتِنَا","transliteration":"","meaning":"Our Signs","rule":"3:11"},{"arabic":"ءَايَةٍۭ","transliteration":"","meaning":"(the) Sign(s)","rule":"2:211"},{"arabic":"لَـَٔايَـٰتٍۢ","transliteration":"","meaning":"surely (are) Signs","rule":"2:164"},{"arabic":"ءَايَةًۭ","transliteration":"","meaning":"a sign","rule":"2:259"},{"arabic":"ءَايَـٰتِنَا","transliteration":"","meaning":"Our verses","rule":"2:151"}],"rules":[{"name":"Words on ايي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَـَٔايَةًۭ","بِـَٔايَـٰتِنَا","ءَايَةٍۭ","لَـَٔايَـٰتٍۢ","ءَايَةًۭ","ءَايَـٰتِنَا","بِـَٔايَـٰتِ","ءَايَـٰتٍۭ"]},{"name":"Parts of speech attested for ايي","description":"The morphology corpus tags words on this root as N — one part of speech across the 25 glossed words attested.","examples":["لَـَٔايَةًۭ","بِـَٔايَـٰتِنَا","ءَايَةٍۭ","لَـَٔايَـٰتٍۢ","ءَايَةًۭ","ءَايَـٰتِنَا"]},{"name":"Where ايي occurs","description":"The 25 glossed words on this root are attested across 4 distinct surahs.","examples":["لَـَٔايَةًۭ (2:248)","بِـَٔايَـٰتِنَا (3:11)","ءَايَةٍۭ (2:211)","لَـَٔايَـٰتٍۢ (2:164)","ءَايَةًۭ (2:259)","ءَايَـٰتِنَا (2:151)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ايي?","options":["ٱلْإِيمَـٰنِ","لَـَٔايَةًۭ","لِلشَّيْطَـٰنِ","يَشْهَدُونَ"],"correct":1,"explanation":"لَـَٔايَةًۭ — glossed \"(is) surely a sign\" at 2:248 — carries the root ايي. The others come from different roots."},{"type":"multiple_choice","question":"What does بِـَٔايَـٰتِنَا mean?","options":["something","Our Signs","the Shaitaan throws","ask your permission"],"correct":1,"explanation":"\"Our Signs\", from the word-by-word gloss at 3:11."},{"type":"fill_blank","question":"Type the root of ءَايَةٍۭ in Arabic (three letters).","correct":"ايي","explanation":"ايي. Diacritics are ignored when checking, so ا ي ي is enough."}]', '["root-ywm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-smw', 'The root سمو (س م و)', 'grammar', 2, '{"explanation":"The root سمو occurs 381 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱسْمُهُ","transliteration":"","meaning":"his name","rule":"3:45"},{"arabic":"ٱسْمُهُۥ","transliteration":"","meaning":"His name","rule":"2:114"},{"arabic":"ٱلسَّمَـٰوَٰتُ","transliteration":"","meaning":"(is like that of) the heavens","rule":"3:133"},{"arabic":"ٱلسَّمَآءَ","transliteration":"","meaning":"(rain from) the sky","rule":"6:6"},{"arabic":"ٱلْأَسْمَآءَ","transliteration":"","meaning":"the names","rule":"2:31"},{"arabic":"بِأَسْمَآئِهِمْ","transliteration":"","meaning":"of their names","rule":"2:33"}],"rules":[{"name":"Words on سمو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱسْمُهُ","ٱسْمُهُۥ","ٱلسَّمَـٰوَٰتُ","ٱلسَّمَآءَ","ٱلْأَسْمَآءَ","بِأَسْمَآئِهِمْ","ٱسْمَ","سَمَـٰوَٰتٍۢ"]},{"name":"Parts of speech attested for سمو","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 16 glossed words attested.","examples":["ٱسْمُهُ","ٱسْمُهُۥ","ٱلسَّمَـٰوَٰتُ","ٱلسَّمَآءَ","ٱلْأَسْمَآءَ","بِأَسْمَآئِهِمْ"]},{"name":"Verb forms attested for سمو","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["ٱسْمُهُ","ٱسْمُهُۥ","ٱلسَّمَـٰوَٰتُ","ٱلسَّمَآءَ","ٱلْأَسْمَآءَ","بِأَسْمَآئِهِمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سمو?","options":["ٱسْمُهُ","شَهَـٰدَةَ","شُرَكَآءَ","إِلَـٰهِكَ"],"correct":0,"explanation":"ٱسْمُهُ — glossed \"his name\" at 3:45 — carries the root سمو. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱسْمُهُۥ mean?","options":["and your forefathers","and tamarisks","His name","You exhausted"],"correct":2,"explanation":"\"His name\", from the word-by-word gloss at 2:114."},{"type":"fill_blank","question":"Type the root of ٱلسَّمَـٰوَٰتُ in Arabic (three letters).","correct":"سمو","explanation":"سمو. Diacritics are ignored when checking, so س م و is enough."}]', '["root-Ayy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kll', 'The root كلل (ك ل ل)', 'grammar', 2, '{"explanation":"The root كلل occurs 377 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as T, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كُلُّ","transliteration":"","meaning":"all","rule":"2:60"},{"arabic":"كُلَّهَا","transliteration":"","meaning":"all of them","rule":"2:31"},{"arabic":"كَلَـٰلَةً","transliteration":"","meaning":"(has) no parent or child","rule":"4:12"},{"arabic":"وَلِكُلٍّۢ","transliteration":"","meaning":"And for everyone","rule":"2:148"},{"arabic":"أَفَكُلَّمَا","transliteration":"","meaning":"Is it (not) so (that) whenever","rule":"2:87"},{"arabic":"ٱلْكَلَـٰلَةِ","transliteration":"","meaning":"the Kalala","rule":"4:176"}],"rules":[{"name":"Words on كلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كُلُّ","كُلَّهَا","كَلَـٰلَةً","وَلِكُلٍّۢ","أَفَكُلَّمَا","ٱلْكَلَـٰلَةِ","وَكُلًّۭا","كُلَّهُۥ"]},{"name":"Parts of speech attested for كلل","description":"The morphology corpus tags words on this root as T, N — 2 distinct parts of speech across the 22 glossed words attested.","examples":["كُلُّ","كُلَّهَا","كَلَـٰلَةً","وَلِكُلٍّۢ","أَفَكُلَّمَا","ٱلْكَلَـٰلَةِ"]},{"name":"Where كلل occurs","description":"The 22 glossed words on this root are attested across 4 distinct surahs.","examples":["كُلُّ (2:60)","كُلَّهَا (2:31)","كَلَـٰلَةً (4:12)","وَلِكُلٍّۢ (2:148)","أَفَكُلَّمَا (2:87)","ٱلْكَلَـٰلَةِ (4:176)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كلل?","options":["ٱلْأَرْضِ","لَـَٔاتِيَةٌۭ","ٱلْأُمِّىَّ","كُلُّ"],"correct":3,"explanation":"كُلُّ — glossed \"all\" at 2:60 — carries the root كلل. The others come from different roots."},{"type":"multiple_choice","question":"What does كُلَّهَا mean?","options":["all of them","its drink","was given to you","believers"],"correct":0,"explanation":"\"all of them\", from the word-by-word gloss at 2:31."},{"type":"fill_blank","question":"Type the root of كَلَـٰلَةً in Arabic (three letters).","correct":"كلل","explanation":"كلل. Diacritics are ignored when checking, so ك ل ل is enough."}]', '["root-smw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-E*b', 'The root عذب (ع ذ ب)', 'grammar', 2, '{"explanation":"The root عذب occurs 373 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as N, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَذَابًۭا","transliteration":"","meaning":"(with) a punishment","rule":"3:56"},{"arabic":"عَذَابٌ","transliteration":"","meaning":"(is) a punishment","rule":"2:7"},{"arabic":"ٱلْعَذَابَ","transliteration":"","meaning":"the punishment","rule":"2:165"},{"arabic":"عَذَابَ","transliteration":"","meaning":"(from the) punishment","rule":"2:201"},{"arabic":"فَيُعَذِّبُهُمْ","transliteration":"","meaning":"then He will punish them","rule":"4:173"},{"arabic":"ٱلْعَذَابِ","transliteration":"","meaning":"torment","rule":"2:49"}],"rules":[{"name":"Words on عذب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَذَابًۭا","عَذَابٌ","ٱلْعَذَابَ","عَذَابَ","فَيُعَذِّبُهُمْ","ٱلْعَذَابِ","عَذَابٌۭ","يُعَذِّبُكُم"]},{"name":"Parts of speech attested for عذب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 18 glossed words attested.","examples":["عَذَابًۭا","عَذَابٌ","ٱلْعَذَابَ","عَذَابَ","فَيُعَذِّبُهُمْ","ٱلْعَذَابِ"]},{"name":"Verb forms attested for عذب","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["عَذَابًۭا","عَذَابٌ","ٱلْعَذَابَ","عَذَابَ","فَيُعَذِّبُهُمْ","ٱلْعَذَابِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عذب?","options":["أَمْرٍ","ءَايَةً","وَأُمَّهَـٰتُكُمُ","عَذَابًۭا"],"correct":3,"explanation":"عَذَابًۭا — glossed \"(with) a punishment\" at 3:56 — carries the root عذب. The others come from different roots."},{"type":"multiple_choice","question":"What does عَذَابٌ mean?","options":["(is) a punishment","and the female","daughters","for those"],"correct":0,"explanation":"\"(is) a punishment\", from the word-by-word gloss at 2:7."},{"type":"fill_blank","question":"Type the root of ٱلْعَذَابَ in Arabic (three letters).","correct":"عذب","explanation":"عذب. Diacritics are ignored when checking, so ع ذ ب is enough."}]', '["root-kll"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Eml', 'The root عمل (ع م ل)', 'grammar', 2, '{"explanation":"The root عمل occurs 360 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَعْمَلُونَ","transliteration":"","meaning":"you do","rule":"2:74"},{"arabic":"أَعْمَـٰلُكُمْ","transliteration":"","meaning":"(are) your deeds","rule":"2:139"},{"arabic":"عَمَلَ","transliteration":"","meaning":"deeds","rule":"3:195"},{"arabic":"عَمِلَتْ","transliteration":"","meaning":"it did","rule":"3:30"},{"arabic":"عَمَلِ","transliteration":"","meaning":"(the) work","rule":"5:90"},{"arabic":"أَعْمَـٰلُنَا","transliteration":"","meaning":"(are) our deeds","rule":"2:139"}],"rules":[{"name":"Words on عمل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَعْمَلُونَ","أَعْمَـٰلُكُمْ","عَمَلَ","عَمِلَتْ","عَمَلِ","أَعْمَـٰلُنَا","وَعَمِلُوا۟","أَعْمَـٰلُهُمْ"]},{"name":"Parts of speech attested for عمل","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 15 glossed words attested.","examples":["تَعْمَلُونَ","أَعْمَـٰلُكُمْ","عَمَلَ","عَمِلَتْ","عَمَلِ","أَعْمَـٰلُنَا"]},{"name":"Where عمل occurs","description":"The 15 glossed words on this root are attested across 4 distinct surahs.","examples":["تَعْمَلُونَ (2:74)","أَعْمَـٰلُكُمْ (2:139)","عَمَلَ (3:195)","عَمِلَتْ (3:30)","عَمَلِ (5:90)","أَعْمَـٰلُنَا (2:139)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عمل?","options":["شَاكِرًۭا","لِذَنۢبِكِ","أَشَدَّ","تَعْمَلُونَ"],"correct":3,"explanation":"تَعْمَلُونَ — glossed \"you do\" at 2:74 — carries the root عمل. The others come from different roots."},{"type":"multiple_choice","question":"What does أَعْمَـٰلُكُمْ mean?","options":["(are) your deeds","Remember","we have believed","their sins"],"correct":0,"explanation":"\"(are) your deeds\", from the word-by-word gloss at 2:139."},{"type":"fill_blank","question":"Type the root of عَمَلَ in Arabic (three letters).","correct":"عمل","explanation":"عمل. Diacritics are ignored when checking, so ع م ل is enough."}]', '["root-E*b"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jEl', 'The root جعل (ج ع ل)', 'grammar', 2, '{"explanation":"The root جعل occurs 346 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَجَعَلَكُمْ","transliteration":"","meaning":"He (would have) made you","rule":"5:48"},{"arabic":"وَلِنَجْعَلَكَ","transliteration":"","meaning":"and We will make you","rule":"2:259"},{"arabic":"جَعَلَكُمْ","transliteration":"","meaning":"(has) made you","rule":"6:165"},{"arabic":"وَيَجْعَلَ","transliteration":"","meaning":"and has placed","rule":"4:19"},{"arabic":"تَجْعَلُوا۟","transliteration":"","meaning":"set up","rule":"2:22"},{"arabic":"وَجَاعِلُ","transliteration":"","meaning":"and I will make","rule":"3:55"}],"rules":[{"name":"Words on جعل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَجَعَلَكُمْ","وَلِنَجْعَلَكَ","جَعَلَكُمْ","وَيَجْعَلَ","تَجْعَلُوا۟","وَجَاعِلُ","تَجْعَلُونَهُۥ","ٱجْعَلْ"]},{"name":"Parts of speech attested for جعل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 34 glossed words attested.","examples":["لَجَعَلَكُمْ","وَلِنَجْعَلَكَ","جَعَلَكُمْ","وَيَجْعَلَ","تَجْعَلُوا۟","وَجَاعِلُ"]},{"name":"Where جعل occurs","description":"The 34 glossed words on this root are attested across 5 distinct surahs.","examples":["لَجَعَلَكُمْ (5:48)","وَلِنَجْعَلَكَ (2:259)","جَعَلَكُمْ (6:165)","وَيَجْعَلَ (4:19)","تَجْعَلُوا۟ (2:22)","وَجَاعِلُ (3:55)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جعل?","options":["لَجَعَلَكُمْ","أُخْتَهَا","أَجَلَ","أَبُوهُمْ"],"correct":0,"explanation":"لَجَعَلَكُمْ — glossed \"He (would have) made you\" at 5:48 — carries the root جعل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَلِنَجْعَلَكَ mean?","options":["their (specified) term","and We will make you","come (to) us","you have taken"],"correct":1,"explanation":"\"and We will make you\", from the word-by-word gloss at 2:259."},{"type":"fill_blank","question":"Type the root of جَعَلَكُمْ in Arabic (three letters).","correct":"جعل","explanation":"جعل. Diacritics are ignored when checking, so ج ع ل is enough."}]', '["root-Eml"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rHm', 'The root رحم (ر ح م)', 'grammar', 2, '{"explanation":"The root رحم occurs 339 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as ADJ, N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"رَّحِيمًۭا","transliteration":"","meaning":"Most-Merciful","rule":"4:23"},{"arabic":"أَرْحَامِهِنَّ","transliteration":"","meaning":"their wombs","rule":"2:228"},{"arabic":"ٱلْأَرْحَامِ","transliteration":"","meaning":"the wombs","rule":"3:6"},{"arabic":"رَحْمَةٍۢ","transliteration":"","meaning":"(of) Mercy","rule":"3:159"},{"arabic":"وَرَحْمَةًۭ","transliteration":"","meaning":"and mercy","rule":"4:96"},{"arabic":"ٱلرَّحِيمُ","transliteration":"","meaning":"the Most Merciful","rule":"2:37"}],"rules":[{"name":"Words on رحم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["رَّحِيمًۭا","أَرْحَامِهِنَّ","ٱلْأَرْحَامِ","رَحْمَةٍۢ","وَرَحْمَةًۭ","ٱلرَّحِيمُ","رَحْمَةِ","رَحْمَتَ"]},{"name":"Parts of speech attested for رحم","description":"The morphology corpus tags words on this root as ADJ, N, V — 3 distinct parts of speech across the 26 glossed words attested.","examples":["رَّحِيمًۭا","أَرْحَامِهِنَّ","ٱلْأَرْحَامِ","رَحْمَةٍۢ","وَرَحْمَةًۭ","ٱلرَّحِيمُ"]},{"name":"Where رحم occurs","description":"The 26 glossed words on this root are attested across 5 distinct surahs.","examples":["رَّحِيمًۭا (4:23)","أَرْحَامِهِنَّ (2:228)","ٱلْأَرْحَامِ (3:6)","رَحْمَةٍۢ (3:159)","وَرَحْمَةًۭ (4:96)","ٱلرَّحِيمُ (2:37)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رحم?","options":["فَأَخَذْتُهُمْ","رَّحِيمًۭا","أَشَدُّ","تُؤْمِنُونَ"],"correct":1,"explanation":"رَّحِيمًۭا — glossed \"Most-Merciful\" at 4:23 — carries the root رحم. The others come from different roots."},{"type":"multiple_choice","question":"What does أَرْحَامِهِنَّ mean?","options":["their wombs","he came (to) it","and Allah will turn (in Mercy)","and the mankind"],"correct":0,"explanation":"\"their wombs\", from the word-by-word gloss at 2:228."},{"type":"fill_blank","question":"Type the root of ٱلْأَرْحَامِ in Arabic (three letters).","correct":"رحم","explanation":"رحم. Diacritics are ignored when checking, so ر ح م is enough."}]', '["root-jEl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rAy', 'The root راي (ر ا ي)', 'grammar', 2, '{"explanation":"The root راي occurs 328 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, III, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَرَأَوُا۟","transliteration":"","meaning":"and they will see","rule":"2:166"},{"arabic":"أَرِنِى","transliteration":"","meaning":"show me","rule":"2:260"},{"arabic":"رَأَيْتُمُوهُ","transliteration":"","meaning":"you have seen it","rule":"3:143"},{"arabic":"أَرِنِىٓ","transliteration":"","meaning":"Show me","rule":"7:143"},{"arabic":"نُرِىٓ","transliteration":"","meaning":"We show(ed)","rule":"6:75"},{"arabic":"تَرَ","transliteration":"","meaning":"you see","rule":"2:243"}],"rules":[{"name":"Words on راي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَرَأَوُا۟","أَرِنِى","رَأَيْتُمُوهُ","أَرِنِىٓ","نُرِىٓ","تَرَ","تَرَىٰ","يَرَوْنَهُم"]},{"name":"Parts of speech attested for راي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 37 glossed words attested.","examples":["وَرَأَوُا۟","أَرِنِى","رَأَيْتُمُوهُ","أَرِنِىٓ","نُرِىٓ","تَرَ"]},{"name":"Verb forms attested for راي","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, III, VI.","examples":["وَرَأَوُا۟","أَرِنِى","رَأَيْتُمُوهُ","أَرِنِىٓ","نُرِىٓ","تَرَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root راي?","options":["أَمْرَهُمْ","وَرَأَوُا۟","ٱللَّهُ","أَبِى"],"correct":1,"explanation":"وَرَأَوُا۟ — glossed \"and they will see\" at 2:166 — carries the root راي. The others come from different roots."},{"type":"multiple_choice","question":"What does أَرِنِى mean?","options":["show me","comes (to) it","brought forth","surely, (would) have believed"],"correct":0,"explanation":"\"show me\", from the word-by-word gloss at 2:260."},{"type":"fill_blank","question":"Type the root of رَأَيْتُمُوهُ in Arabic (three letters).","correct":"راي","explanation":"راي. Diacritics are ignored when checking, so ر ا ي is enough."}]', '["root-rHm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ktb', 'The root كتب (ك ت ب)', 'grammar', 2, '{"explanation":"The root كتب occurs 319 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms III, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَاتِبٌ","transliteration":"","meaning":"a scribe","rule":"2:282"},{"arabic":"فَٱكْتُبُوهُ","transliteration":"","meaning":"then write it","rule":"2:282"},{"arabic":"وَٱلْكِتَـٰبِ","transliteration":"","meaning":"and the Book","rule":"2:177"},{"arabic":"كَاتِبًۭا","transliteration":"","meaning":"a scribe","rule":"2:283"},{"arabic":"كَاتِبٌۢ","transliteration":"","meaning":"a scribe","rule":"2:282"},{"arabic":"كَاتِبٌۭ","transliteration":"","meaning":"(the) scribe","rule":"2:282"}],"rules":[{"name":"Words on كتب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَاتِبٌ","فَٱكْتُبُوهُ","وَٱلْكِتَـٰبِ","كَاتِبًۭا","كَاتِبٌۢ","كَاتِبٌۭ","كَتَبَ","تَكْتُبُوهُ"]},{"name":"Parts of speech attested for كتب","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 23 glossed words attested.","examples":["كَاتِبٌ","فَٱكْتُبُوهُ","وَٱلْكِتَـٰبِ","كَاتِبًۭا","كَاتِبٌۢ","كَاتِبٌۭ"]},{"name":"Verb forms attested for كتب","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VIII.","examples":["كَاتِبٌ","فَٱكْتُبُوهُ","وَٱلْكِتَـٰبِ","كَاتِبًۭا","كَاتِبٌۢ","كَاتِبٌۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كتب?","options":["ءَايَةٌۭ","ٱلشَّجَرِ","كَاتِبٌ","يَتَّخِذُونَكَ"],"correct":2,"explanation":"كَاتِبٌ — glossed \"a scribe\" at 2:282 — carries the root كتب. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱكْتُبُوهُ mean?","options":["they come to you","then write it","associate partners (with Him)","god"],"correct":1,"explanation":"\"then write it\", from the word-by-word gloss at 2:282."},{"type":"fill_blank","question":"Type the root of وَٱلْكِتَـٰبِ in Arabic (three letters).","correct":"كتب","explanation":"كتب. Diacritics are ignored when checking, so ك ت ب is enough."}]', '["root-rAy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-hdy', 'The root هدي (ه د ي)', 'grammar', 2, '{"explanation":"The root هدي occurs 316 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"هَدَىٰكُمْ","transliteration":"","meaning":"He guided you","rule":"2:185"},{"arabic":"ٱلْمُهْتَدُونَ","transliteration":"","meaning":"(are) the guided ones","rule":"2:157"},{"arabic":"يَهْتَدُونَ","transliteration":"","meaning":"were they guided","rule":"2:170"},{"arabic":"بِٱلْهُدَىٰ","transliteration":"","meaning":"for [the] guidance","rule":"2:16"},{"arabic":"ٱلْهَدْىَ","transliteration":"","meaning":"the sacrificial animals","rule":"5:2"},{"arabic":"وَيَهْدِيَكُمْ","transliteration":"","meaning":"and to guide you","rule":"4:26"}],"rules":[{"name":"Words on هدي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["هَدَىٰكُمْ","ٱلْمُهْتَدُونَ","يَهْتَدُونَ","بِٱلْهُدَىٰ","ٱلْهَدْىَ","وَيَهْدِيَكُمْ","ٱلْهَدْىُ","تَهْدُوا۟"]},{"name":"Parts of speech attested for هدي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 32 glossed words attested.","examples":["هَدَىٰكُمْ","ٱلْمُهْتَدُونَ","يَهْتَدُونَ","بِٱلْهُدَىٰ","ٱلْهَدْىَ","وَيَهْدِيَكُمْ"]},{"name":"Verb forms attested for هدي","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["هَدَىٰكُمْ","ٱلْمُهْتَدُونَ","يَهْتَدُونَ","بِٱلْهُدَىٰ","ٱلْهَدْىَ","وَيَهْدِيَكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root هدي?","options":["هَدَىٰكُمْ","أَشْرَكْتُمُونِ","ٱللَّهِ","وَإِخْوَٰنُكُمْ"],"correct":0,"explanation":"هَدَىٰكُمْ — glossed \"He guided you\" at 2:185 — carries the root هدي. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُهْتَدُونَ mean?","options":["any","your gods","(are) the guided ones","(are) more intense"],"correct":2,"explanation":"\"(are) the guided ones\", from the word-by-word gloss at 2:157."},{"type":"fill_blank","question":"Type the root of يَهْتَدُونَ in Arabic (three letters).","correct":"هدي","explanation":"هدي. Diacritics are ignored when checking, so ه د ي is enough."}]', '["root-ktb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Zlm', 'The root ظلم (ظ ل م)', 'grammar', 2, '{"explanation":"The root ظلم occurs 315 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَظْلِمُونَ","transliteration":"","meaning":"wrong","rule":"2:279"},{"arabic":"يَظْلِمُونَ","transliteration":"","meaning":"doing wrong","rule":"2:57"},{"arabic":"ظَالِمِىٓ","transliteration":"","meaning":"(while) they (were) wronging","rule":"4:97"},{"arabic":"ٱلظَّالِمِ","transliteration":"","meaning":"[the] oppressor(s)","rule":"4:75"},{"arabic":"ٱلظُّلُمَـٰتِ","transliteration":"","meaning":"[the] darkness","rule":"2:257"},{"arabic":"ظُلُمَـٰتٍۢ","transliteration":"","meaning":"darkness[es]","rule":"2:17"}],"rules":[{"name":"Words on ظلم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَظْلِمُونَ","يَظْلِمُونَ","ظَالِمِىٓ","ٱلظَّالِمِ","ٱلظُّلُمَـٰتِ","ظُلُمَـٰتٍۢ","أَظْلَمَ","ظَلَمْتُمْ"]},{"name":"Parts of speech attested for ظلم","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 33 glossed words attested.","examples":["تَظْلِمُونَ","يَظْلِمُونَ","ظَالِمِىٓ","ٱلظَّالِمِ","ٱلظُّلُمَـٰتِ","ظُلُمَـٰتٍۢ"]},{"name":"Verb forms attested for ظلم","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تَظْلِمُونَ","يَظْلِمُونَ","ظَالِمِىٓ","ٱلظَّالِمِ","ٱلظُّلُمَـٰتِ","ظُلُمَـٰتٍۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ظلم?","options":["أَشَدَّ","ٱلْأُمُورِ","تَظْلِمُونَ","ٱللَّهِ"],"correct":2,"explanation":"تَظْلِمُونَ — glossed \"wrong\" at 2:279 — carries the root ظلم. The others come from different roots."},{"type":"multiple_choice","question":"What does يَظْلِمُونَ mean?","options":["and the tree","doing wrong","we believe[d]","they brought"],"correct":1,"explanation":"\"doing wrong\", from the word-by-word gloss at 2:57."},{"type":"fill_blank","question":"Type the root of ظَالِمِىٓ in Arabic (three letters).","correct":"ظلم","explanation":"ظلم. Diacritics are ignored when checking, so ظ ل م is enough."}]', '["root-hdy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nfs', 'The root نفس (ن ف س)', 'grammar', 2, '{"explanation":"The root نفس occurs 298 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, in verb forms V, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَأَنفُسَنَا","transliteration":"","meaning":"and ourselves","rule":"3:61"},{"arabic":"وَٱلْأَنفُسِ","transliteration":"","meaning":"and [the] lives","rule":"2:155"},{"arabic":"وَأَنفُسِكُمْ","transliteration":"","meaning":"and yourselves","rule":"3:186"},{"arabic":"لِنَفْسٍ","transliteration":"","meaning":"for a soul","rule":"3:145"},{"arabic":"أَنفُسِكُمُ","transliteration":"","meaning":"yourselves","rule":"3:168"},{"arabic":"وَأَنفُسَكُمْ","transliteration":"","meaning":"and yourselves","rule":"3:61"}],"rules":[{"name":"Words on نفس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَأَنفُسَنَا","وَٱلْأَنفُسِ","وَأَنفُسِكُمْ","لِنَفْسٍ","أَنفُسِكُمُ","وَأَنفُسَكُمْ","أَنفُسِكُمْ","أَنفُسَهُم"]},{"name":"Parts of speech attested for نفس","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 29 glossed words attested.","examples":["وَأَنفُسَنَا","وَٱلْأَنفُسِ","وَأَنفُسِكُمْ","لِنَفْسٍ","أَنفُسِكُمُ","وَأَنفُسَكُمْ"]},{"name":"Verb forms attested for نفس","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, VI.","examples":["وَأَنفُسَنَا","وَٱلْأَنفُسِ","وَأَنفُسِكُمْ","لِنَفْسٍ","أَنفُسِكُمُ","وَأَنفُسَكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نفس?","options":["ٱلشَّرَابُ","ٱلْأَوَّلِينَ","وَأَنفُسَنَا","فَكُلَا"],"correct":2,"explanation":"وَأَنفُسَنَا — glossed \"and ourselves\" at 3:61 — carries the root نفس. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْأَنفُسِ mean?","options":["(by the) family","So seized them","(is) a Reminder","and [the] lives"],"correct":3,"explanation":"\"and [the] lives\", from the word-by-word gloss at 2:155."},{"type":"fill_blank","question":"Type the root of وَأَنفُسِكُمْ in Arabic (three letters).","correct":"نفس","explanation":"نفس. Diacritics are ignored when checking, so ن ف س is enough."}]', '["root-Zlm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qbl', 'The root قبل (ق ب ل)', 'grammar', 2, '{"explanation":"The root قبل occurs 294 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, V, LOC, T, in verb forms V, IV, VI, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَبْلِنَا","transliteration":"","meaning":"before us","rule":"2:286"},{"arabic":"يُقْبَلُ","transliteration":"","meaning":"will be accepted","rule":"2:48"},{"arabic":"قَبْلُ","transliteration":"","meaning":"before","rule":"2:25"},{"arabic":"قَبْلِى","transliteration":"","meaning":"before me","rule":"3:183"},{"arabic":"قَبْلِكُم","transliteration":"","meaning":"before you","rule":"2:214"},{"arabic":"قَبْلِهِم","transliteration":"","meaning":"before them","rule":"2:118"}],"rules":[{"name":"Words on قبل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَبْلِنَا","يُقْبَلُ","قَبْلُ","قَبْلِى","قَبْلِكُم","قَبْلِهِم","قَبْلِكَ","قِبْلَتَهُمْ"]},{"name":"Parts of speech attested for قبل","description":"The morphology corpus tags words on this root as N, V, LOC, T — 4 distinct parts of speech across the 30 glossed words attested.","examples":["قَبْلِنَا","يُقْبَلُ","قَبْلُ","قَبْلِى","قَبْلِكُم","قَبْلِهِم"]},{"name":"Verb forms attested for قبل","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, IV, VI, X.","examples":["قَبْلِنَا","يُقْبَلُ","قَبْلُ","قَبْلِى","قَبْلِكُم","قَبْلِهِم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قبل?","options":["يَشْهَدُ","يَأْتِيَكُمَا","قَبْلِنَا","وَأَخَوَٰتُكُم"],"correct":2,"explanation":"قَبْلِنَا — glossed \"before us\" at 2:286 — carries the root قبل. The others come from different roots."},{"type":"multiple_choice","question":"What does يُقْبَلُ mean?","options":["your father","by the leave","then seized them","will be accepted"],"correct":3,"explanation":"\"will be accepted\", from the word-by-word gloss at 2:48."},{"type":"fill_blank","question":"Type the root of قَبْلُ in Arabic (three letters).","correct":"قبل","explanation":"قبل. Diacritics are ignored when checking, so ق ب ل is enough."}]', '["root-nfs"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nzl', 'The root نزل (ن ز ل)', 'grammar', 2, '{"explanation":"The root نزل occurs 293 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنزَلَ","transliteration":"","meaning":"has revealed","rule":"2:90"},{"arabic":"أُنزِلَتِ","transliteration":"","meaning":"was revealed","rule":"3:65"},{"arabic":"يُنَزِّلْ","transliteration":"","meaning":"He sent down","rule":"3:151"},{"arabic":"مُنزَلِينَ","transliteration":"","meaning":"[the ones] sent down","rule":"3:124"},{"arabic":"أَنزَلْنَآ","transliteration":"","meaning":"We revealed","rule":"2:99"},{"arabic":"تُنَزَّلَ","transliteration":"","meaning":"(was) revealed","rule":"3:93"}],"rules":[{"name":"Words on نزل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنزَلَ","أُنزِلَتِ","يُنَزِّلْ","مُنزَلِينَ","أَنزَلْنَآ","تُنَزَّلَ","أُنزِلَ","تُنَزِّلَ"]},{"name":"Parts of speech attested for نزل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 22 glossed words attested.","examples":["أَنزَلَ","أُنزِلَتِ","يُنَزِّلْ","مُنزَلِينَ","أَنزَلْنَآ","تُنَزَّلَ"]},{"name":"Verb forms attested for نزل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II, V.","examples":["أَنزَلَ","أُنزِلَتِ","يُنَزِّلْ","مُنزَلِينَ","أَنزَلْنَآ","تُنَزَّلَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نزل?","options":["تَأْتِهِم","ٱللَّهُ","يُؤْفَكُونَ","أَنزَلَ"],"correct":3,"explanation":"أَنزَلَ — glossed \"has revealed\" at 2:90 — carries the root نزل. The others come from different roots."},{"type":"multiple_choice","question":"What does أُنزِلَتِ mean?","options":["Allah wills","(to) Allah","the later ones","was revealed"],"correct":3,"explanation":"\"was revealed\", from the word-by-word gloss at 3:65."},{"type":"fill_blank","question":"Type the root of يُنَزِّلْ in Arabic (three letters).","correct":"نزل","explanation":"نزل. Diacritics are ignored when checking, so ن ز ل is enough."}]', '["root-qbl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*kr', 'The root ذكر (ذ ك ر)', 'grammar', 2, '{"explanation":"The root ذكر occurs 292 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱذْكُرْ","transliteration":"","meaning":"Remember","rule":"5:110"},{"arabic":"يَتَذَكَّرُونَ","transliteration":"","meaning":"take heed","rule":"2:221"},{"arabic":"ذَكَرُوا۟","transliteration":"","meaning":"they remember","rule":"3:135"},{"arabic":"فَٱذْكُرُوا۟","transliteration":"","meaning":"then remember","rule":"2:198"},{"arabic":"ذُكِّرُوا۟","transliteration":"","meaning":"they were reminded","rule":"5:13"},{"arabic":"يُذْكَرَ","transliteration":"","meaning":"be mentioned","rule":"2:114"}],"rules":[{"name":"Words on ذكر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱذْكُرْ","يَتَذَكَّرُونَ","ذَكَرُوا۟","فَٱذْكُرُوا۟","ذُكِّرُوا۟","يُذْكَرَ","ذُكِرَ","وَٱذْكُرُوا۟"]},{"name":"Parts of speech attested for ذكر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 37 glossed words attested.","examples":["ٱذْكُرْ","يَتَذَكَّرُونَ","ذَكَرُوا۟","فَٱذْكُرُوا۟","ذُكِّرُوا۟","يُذْكَرَ"]},{"name":"Verb forms attested for ذكر","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, II, VIII.","examples":["ٱذْكُرْ","يَتَذَكَّرُونَ","ذَكَرُوا۟","فَٱذْكُرُوا۟","ذُكِّرُوا۟","يُذْكَرَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذكر?","options":["شَيْـًۭٔا","أَخَذْنَـٰهُم","ٱذْكُرْ","يَأْذَنَ"],"correct":2,"explanation":"ٱذْكُرْ — glossed \"Remember\" at 5:110 — carries the root ذكر. The others come from different roots."},{"type":"multiple_choice","question":"What does يَتَذَكَّرُونَ mean?","options":["take heed","came to them","they bring","its preparation"],"correct":0,"explanation":"\"take heed\", from the word-by-word gloss at 2:221."},{"type":"fill_blank","question":"Type the root of ذَكَرُوا۟ in Arabic (three letters).","correct":"ذكر","explanation":"ذكر. Diacritics are ignored when checking, so ذ ك ر is enough."}]', '["root-nzl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hqq', 'The root حقق (ح ق ق)', 'grammar', 2, '{"explanation":"The root حقق occurs 287 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِٱلْحَقِّ","transliteration":"","meaning":"with the truth","rule":"2:71"},{"arabic":"أَحَقُّ","transliteration":"","meaning":"(have) better right","rule":"2:228"},{"arabic":"حَقَّ","transliteration":"","meaning":"(as it has the) right","rule":"2:121"},{"arabic":"ٱلْحَقِّ","transliteration":"","meaning":"[the] right","rule":"2:61"},{"arabic":"ٱلْحَقَّ","transliteration":"","meaning":"the Truth","rule":"2:42"},{"arabic":"حَقًّا","transliteration":"","meaning":"a duty","rule":"2:180"}],"rules":[{"name":"Words on حقق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِٱلْحَقِّ","أَحَقُّ","حَقَّ","ٱلْحَقِّ","ٱلْحَقَّ","حَقًّا","حَقًّۭا","بِحَقٍّ"]},{"name":"Parts of speech attested for حقق","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 14 glossed words attested.","examples":["بِٱلْحَقِّ","أَحَقُّ","حَقَّ","ٱلْحَقِّ","ٱلْحَقَّ","حَقًّا"]},{"name":"Verb forms attested for حقق","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, IV.","examples":["بِٱلْحَقِّ","أَحَقُّ","حَقَّ","ٱلْحَقِّ","ٱلْحَقَّ","حَقًّا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حقق?","options":["إِثْمٌۭ","أَشْتَاتًۭا","بِٱلْحَقِّ","ٱللَّهُ"],"correct":2,"explanation":"بِٱلْحَقِّ — glossed \"with the truth\" at 2:71 — carries the root حقق. The others come from different roots."},{"type":"multiple_choice","question":"What does أَحَقُّ mean?","options":["(have) better right","harmed","So Allah seized them","Do you commit"],"correct":0,"explanation":"\"(have) better right\", from the word-by-word gloss at 2:228."},{"type":"fill_blank","question":"Type the root of حَقَّ in Arabic (three letters).","correct":"حقق","explanation":"حقق. Diacritics are ignored when checking, so ح ق ق is enough."}]', '["root-*kr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-k*b', 'The root كذب (ك ذ ب)', 'grammar', 2, '{"explanation":"The root كذب occurs 282 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَذِبًۭا","transliteration":"","meaning":"a lie","rule":"6:144"},{"arabic":"لِلْكَذِبِ","transliteration":"","meaning":"to falsehood","rule":"5:41"},{"arabic":"كَذَّبُوا۟","transliteration":"","meaning":"They denied","rule":"3:11"},{"arabic":"لَكَـٰذِبُونَ","transliteration":"","meaning":"certainly are liars","rule":"6:28"},{"arabic":"كَذَبُوا۟","transliteration":"","meaning":"they lied","rule":"6:24"},{"arabic":"كَذَّبْتُمْ","transliteration":"","meaning":"you denied","rule":"2:87"}],"rules":[{"name":"Words on كذب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَذِبًۭا","لِلْكَذِبِ","كَذَّبُوا۟","لَكَـٰذِبُونَ","كَذَبُوا۟","كَذَّبْتُمْ","كُذِّبَ","نُكَذِّبَ"]},{"name":"Parts of speech attested for كذب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 22 glossed words attested.","examples":["كَذِبًۭا","لِلْكَذِبِ","كَذَّبُوا۟","لَكَـٰذِبُونَ","كَذَبُوا۟","كَذَّبْتُمْ"]},{"name":"Verb forms attested for كذب","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["كَذِبًۭا","لِلْكَذِبِ","كَذَّبُوا۟","لَكَـٰذِبُونَ","كَذَبُوا۟","كَذَّبْتُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كذب?","options":["يَأْتِ","وَذَكِّرْهُم","كَذِبًۭا","وَّءَامَنُوا۟"],"correct":2,"explanation":"كَذِبًۭا — glossed \"a lie\" at 6:144 — carries the root كذب. The others come from different roots."},{"type":"multiple_choice","question":"What does لِلْكَذِبِ mean?","options":["drinks","painful","Bring us","to falsehood"],"correct":3,"explanation":"\"to falsehood\", from the word-by-word gloss at 5:41."},{"type":"fill_blank","question":"Type the root of كَذَّبُوا۟ in Arabic (three letters).","correct":"كذب","explanation":"كذب. Diacritics are ignored when checking, so ك ذ ب is enough."}]', '["root-Hqq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jyA', 'The root جيا (ج ي ا)', 'grammar', 2, '{"explanation":"The root جيا occurs 278 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"جِئْتَ","transliteration":"","meaning":"you have come","rule":"2:71"},{"arabic":"جَآءَهُۥ","transliteration":"","meaning":"comes to him","rule":"2:275"},{"arabic":"وَجَآءَهُمُ","transliteration":"","meaning":"and came to them","rule":"3:86"},{"arabic":"جَآءَتْهُمْ","transliteration":"","meaning":"came to them","rule":"5:32"},{"arabic":"جَآءَهُم","transliteration":"","meaning":"came to them","rule":"2:89"},{"arabic":"جِئْتَهُم","transliteration":"","meaning":"you came to them","rule":"5:110"}],"rules":[{"name":"Words on جيا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["جِئْتَ","جَآءَهُۥ","وَجَآءَهُمُ","جَآءَتْهُمْ","جَآءَهُم","جِئْتَهُم","جَآءَكَ","وَجِئْتُكُم"]},{"name":"Parts of speech attested for جيا","description":"The morphology corpus tags words on this root as V — one part of speech across the 26 glossed words attested.","examples":["جِئْتَ","جَآءَهُۥ","وَجَآءَهُمُ","جَآءَتْهُمْ","جَآءَهُم","جِئْتَهُم"]},{"name":"Where جيا occurs","description":"The 26 glossed words on this root are attested across 5 distinct surahs.","examples":["جِئْتَ (2:71)","جَآءَهُۥ (2:275)","وَجَآءَهُمُ (3:86)","جَآءَتْهُمْ (5:32)","جَآءَهُم (2:89)","جِئْتَهُم (5:110)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جيا?","options":["ٱلتَّذْكِرَةِ","جِئْتَ","وَيَشْتَرُونَ","شَأْنٌۭ"],"correct":1,"explanation":"جِئْتَ — glossed \"you have come\" at 2:71 — carries the root جيا. The others come from different roots."},{"type":"multiple_choice","question":"What does جَآءَهُۥ mean?","options":["believed","witnessed","they spread","comes to him"],"correct":3,"explanation":"\"comes to him\", from the word-by-word gloss at 2:275."},{"type":"fill_blank","question":"Type the root of وَجَآءَهُمُ in Arabic (three letters).","correct":"جيا","explanation":"جيا. Diacritics are ignored when checking, so ج ي ا is enough."}]', '["root-k*b"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ebd', 'The root عبد (ع ب د)', 'grammar', 2, '{"explanation":"The root عبد occurs 275 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَعْبُدَ","transliteration":"","meaning":"we worship","rule":"3:64"},{"arabic":"عِبَادِى","transliteration":"","meaning":"My servants","rule":"2:186"},{"arabic":"عِبَادِهِۦ","transliteration":"","meaning":"His servants","rule":"2:90"},{"arabic":"لِّلْعَبِيدِ","transliteration":"","meaning":"to (His) slaves","rule":"3:182"},{"arabic":"أَعْبُدُ","transliteration":"","meaning":"I worship","rule":"10:104"},{"arabic":"وَلَعَبْدٌۭ","transliteration":"","meaning":"and a bondman","rule":"2:221"}],"rules":[{"name":"Words on عبد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَعْبُدَ","عِبَادِى","عِبَادِهِۦ","لِّلْعَبِيدِ","أَعْبُدُ","وَلَعَبْدٌۭ","لِيَعْبُدُوٓا۟","۞ وَٱعْبُدُوا۟"]},{"name":"Parts of speech attested for عبد","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 33 glossed words attested.","examples":["نَعْبُدَ","عِبَادِى","عِبَادِهِۦ","لِّلْعَبِيدِ","أَعْبُدُ","وَلَعَبْدٌۭ"]},{"name":"Verb forms attested for عبد","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["نَعْبُدَ","عِبَادِى","عِبَادِهِۦ","لِّلْعَبِيدِ","أَعْبُدُ","وَلَعَبْدٌۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عبد?","options":["ٱللَّهُ","نَعْبُدَ","ذَكَرْتَ","أُوتُوا۟"],"correct":1,"explanation":"نَعْبُدَ — glossed \"we worship\" at 3:64 — carries the root عبد. The others come from different roots."},{"type":"multiple_choice","question":"What does عِبَادِى mean?","options":["and you believe","My servants","Allah disliked","testify"],"correct":1,"explanation":"\"My servants\", from the word-by-word gloss at 2:186."},{"type":"fill_blank","question":"Type the root of عِبَادِهِۦ in Arabic (three letters).","correct":"عبد","explanation":"عبد. Diacritics are ignored when checking, so ع ب د is enough."}]', '["root-jyA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ax*', 'The root اخذ (ا خ ذ)', 'grammar', 2, '{"explanation":"The root اخذ occurs 273 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 45 distinct glossed words, tagged in the corpus as V, N, in verb forms VIII, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَأَخَذْتُمْ","transliteration":"","meaning":"and take","rule":"3:81"},{"arabic":"يَتَّخِذِ","transliteration":"","meaning":"take","rule":"3:28"},{"arabic":"وَأَخَذْنَ","transliteration":"","meaning":"and they have taken","rule":"4:21"},{"arabic":"يَتَّخِذُونَ","transliteration":"","meaning":"take","rule":"4:139"},{"arabic":"تَأْخُذُوا۟","transliteration":"","meaning":"you take (back)","rule":"2:229"},{"arabic":"وَٱتَّخِذُوا۟","transliteration":"","meaning":"and (said), \"Take","rule":"2:125"}],"rules":[{"name":"Words on اخذ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَأَخَذْتُمْ","يَتَّخِذِ","وَأَخَذْنَ","يَتَّخِذُونَ","تَأْخُذُوا۟","وَٱتَّخِذُوا۟","فَأَخَذَتْهُمُ","وَيَتَّخِذَ"]},{"name":"Parts of speech attested for اخذ","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 45 glossed words attested.","examples":["وَأَخَذْتُمْ","يَتَّخِذِ","وَأَخَذْنَ","يَتَّخِذُونَ","تَأْخُذُوا۟","وَٱتَّخِذُوا۟"]},{"name":"Verb forms attested for اخذ","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, III.","examples":["وَأَخَذْتُمْ","يَتَّخِذِ","وَأَخَذْنَ","يَتَّخِذُونَ","تَأْخُذُوا۟","وَٱتَّخِذُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اخذ?","options":["وَأَخَذْتُمْ","ذُكِرَ","ذِكْرَىٰ","مَّذْكُورًا"],"correct":0,"explanation":"وَأَخَذْتُمْ — glossed \"and take\" at 3:81 — carries the root اخذ. The others come from different roots."},{"type":"multiple_choice","question":"What does يَتَّخِذِ mean?","options":["associated partners (with Him)","(of) each point of sunrise","take","(the) masajid of Allah"],"correct":2,"explanation":"\"take\", from the word-by-word gloss at 3:28."},{"type":"fill_blank","question":"Type the root of وَأَخَذْنَ in Arabic (three letters).","correct":"اخذ","explanation":"اخذ. Diacritics are ignored when checking, so ا خ ذ is enough."}]', '["root-Ebd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xlq', 'The root خلق (خ ل ق)', 'grammar', 2, '{"explanation":"The root خلق occurs 261 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"خَلَقَهُمْ","transliteration":"","meaning":"He created them","rule":"11:119"},{"arabic":"خَلْقٍۢ","transliteration":"","meaning":"a creation","rule":"13:5"},{"arabic":"خَلَقْتَ","transliteration":"","meaning":"You have created","rule":"3:191"},{"arabic":"بِخَلْقٍۢ","transliteration":"","meaning":"a creation","rule":"14:19"},{"arabic":"خَلَقَكُم","transliteration":"","meaning":"created you","rule":"4:1"},{"arabic":"خَلَقْتَنِى","transliteration":"","meaning":"You created me","rule":"7:12"}],"rules":[{"name":"Words on خلق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["خَلَقَهُمْ","خَلْقٍۢ","خَلَقْتَ","بِخَلْقٍۢ","خَلَقَكُم","خَلَقْتَنِى","خَلْقِ","خَلَـٰقٍۢ"]},{"name":"Parts of speech attested for خلق","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 35 glossed words attested.","examples":["خَلَقَهُمْ","خَلْقٍۢ","خَلَقْتَ","بِخَلْقٍۢ","خَلَقَكُم","خَلَقْتَنِى"]},{"name":"Verb forms attested for خلق","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VIII.","examples":["خَلَقَهُمْ","خَلْقٍۢ","خَلَقْتَ","بِخَلْقٍۢ","خَلَقَكُم","خَلَقْتَنِى"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلق?","options":["خَلَقَهُمْ","ءَامَنَّا","شِئْنَا","وَذِكْرَىٰ"],"correct":0,"explanation":"خَلَقَهُمْ — glossed \"He created them\" at 11:119 — carries the root خلق. The others come from different roots."},{"type":"multiple_choice","question":"What does خَلْقٍۢ mean?","options":["let him believe","Our command","a creation","and the ear"],"correct":2,"explanation":"\"a creation\", from the word-by-word gloss at 13:5."},{"type":"fill_blank","question":"Type the root of خَلَقْتَ in Arabic (three letters).","correct":"خلق","explanation":"خلق. Diacritics are ignored when checking, so خ ل ق is enough."}]', '["root-Ax*"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wqy', 'The root وقي (و ق ي)', 'grammar', 2, '{"explanation":"The root وقي occurs 258 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N, V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱتَّقَىٰ","transliteration":"","meaning":"and fears (Allah)","rule":"3:76"},{"arabic":"وَلْيَتَّقِ","transliteration":"","meaning":"and let him fear","rule":"2:282"},{"arabic":"يَتَّقُونَ","transliteration":"","meaning":"(become) righteous","rule":"2:187"},{"arabic":"ٱلتَّقْوَىٰ","transliteration":"","meaning":"(is) righteousness","rule":"2:197"},{"arabic":"تُقَىٰةًۭ","transliteration":"","meaning":"(as) a precaution","rule":"3:28"},{"arabic":"فَقِنَا","transliteration":"","meaning":"so save us","rule":"3:191"}],"rules":[{"name":"Words on وقي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱتَّقَىٰ","وَلْيَتَّقِ","يَتَّقُونَ","ٱلتَّقْوَىٰ","تُقَىٰةًۭ","فَقِنَا","ٱتَّقَوْا۟","وَٱتَّقَوْا۟"]},{"name":"Parts of speech attested for وقي","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 26 glossed words attested.","examples":["وَٱتَّقَىٰ","وَلْيَتَّقِ","يَتَّقُونَ","ٱلتَّقْوَىٰ","تُقَىٰةًۭ","فَقِنَا"]},{"name":"Verb forms attested for وقي","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["وَٱتَّقَىٰ","وَلْيَتَّقِ","يَتَّقُونَ","ٱلتَّقْوَىٰ","تُقَىٰةًۭ","فَقِنَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وقي?","options":["وَٱتَّقَىٰ","فَيُؤْخَذُ","أَتَىٰكُمْ","ءَاثِ