INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Axr', 'The root اخر (ا خ ر)', 'grammar', 2, '{"explanation":"The root اخر occurs 250 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, ADJ, V, T, in verb forms V, II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ءَاخِرَهُۥ","transliteration":"","meaning":"(at) its end","rule":"3:72"},{"arabic":"ٱلْـَٔاخِرِ","transliteration":"","meaning":"[the] Last","rule":"2:8"},{"arabic":"وَءَاخِرِنَا","transliteration":"","meaning":"and last of us","rule":"5:114"},{"arabic":"وَٱلْـَٔاخِرَةُ","transliteration":"","meaning":"and the Hereafter","rule":"4:77"},{"arabic":"ٱلْـَٔاخِرَةِ","transliteration":"","meaning":"the Hereafter","rule":"2:102"},{"arabic":"ٱلْأُخْرَىٰ","transliteration":"","meaning":"the other","rule":"2:282"}],"rules":[{"name":"Words on اخر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ءَاخِرَهُۥ","ٱلْـَٔاخِرِ","وَءَاخِرِنَا","وَٱلْـَٔاخِرَةُ","ٱلْـَٔاخِرَةِ","ٱلْأُخْرَىٰ","ءَاخَرِينَ","وَبِٱلْـَٔاخِرَةِ"]},{"name":"Parts of speech attested for اخر","description":"The morphology corpus tags words on this root as N, ADJ, V, T — 4 distinct parts of speech across the 23 glossed words attested.","examples":["ءَاخِرَهُۥ","ٱلْـَٔاخِرِ","وَءَاخِرِنَا","وَٱلْـَٔاخِرَةُ","ٱلْـَٔاخِرَةِ","ٱلْأُخْرَىٰ"]},{"name":"Verb forms attested for اخر","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, II, X.","examples":["ءَاخِرَهُۥ","ٱلْـَٔاخِرِ","وَءَاخِرِنَا","وَٱلْـَٔاخِرَةُ","ٱلْـَٔاخِرَةِ","ٱلْأُخْرَىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اخر?","options":["أَشْرَكُوٓا۟","بِٱلْأُفُقِ","ءَاخِرَهُۥ","وَيَأْمُرُونَ"],"correct":2,"explanation":"ءَاخِرَهُۥ — glossed \"(at) its end\" at 3:72 — carries the root اخر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْـَٔاخِرِ mean?","options":["[the] Last","And the believing men","(and) severe","Allah had willed"],"correct":0,"explanation":"\"[the] Last\", from the word-by-word gloss at 2:8."},{"type":"fill_blank","question":"Type the root of وَءَاخِرِنَا in Arabic (three letters).","correct":"اخر","explanation":"اخر. Diacritics are ignored when checking, so ا خ ر is enough."}]', '["root-wqy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Amr', 'The root امر (ا م ر)', 'grammar', 2, '{"explanation":"The root امر occurs 248 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْأَمْرُ","transliteration":"","meaning":"the matter","rule":"2:210"},{"arabic":"يَأْمُرُكُم","transliteration":"","meaning":"orders you (to do) it","rule":"2:93"},{"arabic":"أَمَرْتَنِى","transliteration":"","meaning":"You commanded me","rule":"5:117"},{"arabic":"وَٱلْأَمْرُ","transliteration":"","meaning":"and the command","rule":"7:54"},{"arabic":"أَمَرَ","transliteration":"","meaning":"has ordered","rule":"2:27"},{"arabic":"وَيَأْمُرُكُم","transliteration":"","meaning":"and orders you","rule":"2:268"}],"rules":[{"name":"Words on امر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْأَمْرُ","يَأْمُرُكُم","أَمَرْتَنِى","وَٱلْأَمْرُ","أَمَرَ","وَيَأْمُرُكُم","وَيَأْمُرُونَ","أُمِرْتُ"]},{"name":"Parts of speech attested for امر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 39 glossed words attested.","examples":["ٱلْأَمْرُ","يَأْمُرُكُم","أَمَرْتَنِى","وَٱلْأَمْرُ","أَمَرَ","وَيَأْمُرُكُم"]},{"name":"Verb forms attested for امر","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["ٱلْأَمْرُ","يَأْمُرُكُم","أَمَرْتَنِى","وَٱلْأَمْرُ","أَمَرَ","وَيَأْمُرُكُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root امر?","options":["لَيَأْتِيَنِّى","ٱلْأَمْرُ","شَيْطَـٰنًۭا","ٱللَّهُ"],"correct":1,"explanation":"ٱلْأَمْرُ — glossed \"the matter\" at 2:210 — carries the root امر. The others come from different roots."},{"type":"multiple_choice","question":"What does يَأْمُرُكُم mean?","options":["And remember","orders you (to do) it","associate","he ran away"],"correct":1,"explanation":"\"orders you (to do) it\", from the word-by-word gloss at 2:93."},{"type":"fill_blank","question":"Type the root of أَمَرْتَنِى in Arabic (three letters).","correct":"امر","explanation":"امر. Diacritics are ignored when checking, so ا م ر is enough."}]', '["root-Axr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nws', 'The root نوس (ن و س)', 'grammar', 2, '{"explanation":"The root نوس occurs 241 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلنَّاسِ","transliteration":"","meaning":"and the mankind","rule":"2:161"},{"arabic":"ٱلنَّاسَ","transliteration":"","meaning":"[the] people","rule":"2:44"},{"arabic":"لِّلنَّاسِ","transliteration":"","meaning":"for mankind","rule":"2:125"},{"arabic":"لِلنَّاسِ","transliteration":"","meaning":"to [the] people","rule":"2:83"},{"arabic":"ٱلنَّاسِ","transliteration":"","meaning":"the people","rule":"2:8"},{"arabic":"بِٱلنَّاسِ","transliteration":"","meaning":"(is) to [the] mankind","rule":"2:143"}],"rules":[{"name":"Words on نوس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلنَّاسِ","ٱلنَّاسَ","لِّلنَّاسِ","لِلنَّاسِ","ٱلنَّاسِ","بِٱلنَّاسِ","ٱلنَّاسُ"]},{"name":"Parts of speech attested for نوس","description":"The morphology corpus tags words on this root as N — one part of speech across the 7 glossed words attested.","examples":["وَٱلنَّاسِ","ٱلنَّاسَ","لِّلنَّاسِ","لِلنَّاسِ","ٱلنَّاسِ","بِٱلنَّاسِ"]},{"name":"Where نوس occurs","description":"The 7 glossed words on this root are attested across 1 distinct surah.","examples":["وَٱلنَّاسِ (2:161)","ٱلنَّاسَ (2:44)","لِّلنَّاسِ (2:125)","لِلنَّاسِ (2:83)","ٱلنَّاسِ (2:8)","بِٱلنَّاسِ (2:143)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نوس?","options":["وَأُخِذُوا۟","لِيُذِيقَهُم","وَٱلنَّاسِ","يَشَآءُ"],"correct":2,"explanation":"وَٱلنَّاسِ — glossed \"and the mankind\" at 2:161 — carries the root نوس. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلنَّاسَ mean?","options":["Allah gave them","the (one) mighty","[the] people","then (the) testimony"],"correct":2,"explanation":"\"[the] people\", from the word-by-word gloss at 2:44."},{"type":"fill_blank","question":"Type the root of لِّلنَّاسِ in Arabic (three letters).","correct":"نوس","explanation":"نوس. Diacritics are ignored when checking, so ن و س is enough."}]', '["root-Amr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bEd', 'The root بعد (ب ع د)', 'grammar', 2, '{"explanation":"The root بعد occurs 235 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, T, ADJ, V, in verb forms IV, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَعِيدًۭا","transliteration":"","meaning":"great","rule":"3:30"},{"arabic":"بَعِيدًا","transliteration":"","meaning":"far away","rule":"4:116"},{"arabic":"بَعْدِهِۦٓ","transliteration":"","meaning":"after him","rule":"3:65"},{"arabic":"بَعْدِهِۦ","transliteration":"","meaning":"after him","rule":"2:51"},{"arabic":"بَعْدُ","transliteration":"","meaning":"after (that)","rule":"2:230"},{"arabic":"بَعْدِى","transliteration":"","meaning":"after me","rule":"2:133"}],"rules":[{"name":"Words on بعد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَعِيدًۭا","بَعِيدًا","بَعْدِهِۦٓ","بَعْدِهِۦ","بَعْدُ","بَعْدِى","بَعْدِهِم","بَعْدَ"]},{"name":"Parts of speech attested for بعد","description":"The morphology corpus tags words on this root as N, T, ADJ, V — 4 distinct parts of speech across the 11 glossed words attested.","examples":["بَعِيدًۭا","بَعِيدًا","بَعْدِهِۦٓ","بَعْدِهِۦ","بَعْدُ","بَعْدِى"]},{"name":"Verb forms attested for بعد","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, III.","examples":["بَعِيدًۭا","بَعِيدًا","بَعْدِهِۦٓ","بَعْدِهِۦ","بَعْدُ","بَعْدِى"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بعد?","options":["ذَكَرَهُۥ","بَعِيدًۭا","أَشْرَكُوا۟","وَٱلشَّهْرَ"],"correct":1,"explanation":"بَعِيدًۭا — glossed \"great\" at 3:30 — carries the root بعد. The others come from different roots."},{"type":"multiple_choice","question":"What does بَعِيدًا mean?","options":["the Favors of Allah","painful","they (will) remain behind","far away"],"correct":3,"explanation":"\"far away\", from the word-by-word gloss at 4:116."},{"type":"fill_blank","question":"Type the root of بَعْدِهِۦٓ in Arabic (three letters).","correct":"بعد","explanation":"بعد. Diacritics are ignored when checking, so ب ع د is enough."}]', '["root-nws"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gfr', 'The root غفر (غ ف ر)', 'grammar', 2, '{"explanation":"The root غفر occurs 234 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْمَغْفِرَةِ","transliteration":"","meaning":"and [the] forgiveness","rule":"2:221"},{"arabic":"فَيَغْفِرُ","transliteration":"","meaning":"Then, He will forgive","rule":"2:284"},{"arabic":"مَّغْفِرَةًۭ","transliteration":"","meaning":"forgiveness","rule":"2:268"},{"arabic":"وَمَغْفِرَةٌ","transliteration":"","meaning":"and (seeking) forgiveness","rule":"2:263"},{"arabic":"ٱغْفِرْ","transliteration":"","meaning":"forgive","rule":"3:147"},{"arabic":"فَٱغْفِرْ","transliteration":"","meaning":"so forgive","rule":"3:16"}],"rules":[{"name":"Words on غفر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْمَغْفِرَةِ","فَيَغْفِرُ","مَّغْفِرَةًۭ","وَمَغْفِرَةٌ","ٱغْفِرْ","فَٱغْفِرْ","لَمَغْفِرَةٌۭ","نَّغْفِرْ"]},{"name":"Parts of speech attested for غفر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["وَٱلْمَغْفِرَةِ","فَيَغْفِرُ","مَّغْفِرَةًۭ","وَمَغْفِرَةٌ","ٱغْفِرْ","فَٱغْفِرْ"]},{"name":"Verb forms attested for غفر","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["وَٱلْمَغْفِرَةِ","فَيَغْفِرُ","مَّغْفِرَةًۭ","وَمَغْفِرَةٌ","ٱغْفِرْ","فَٱغْفِرْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غفر?","options":["ءَالَآءَ","مُؤْمِنٌۭ","ٱتَّخِذِى","وَٱلْمَغْفِرَةِ"],"correct":3,"explanation":"وَٱلْمَغْفِرَةِ — glossed \"and [the] forgiveness\" at 2:221 — carries the root غفر. The others come from different roots."},{"type":"multiple_choice","question":"What does فَيَغْفِرُ mean?","options":["Then, He will forgive","And an announcement","and you both eat","(is) mightier"],"correct":0,"explanation":"\"Then, He will forgive\", from the word-by-word gloss at 2:284."},{"type":"fill_blank","question":"Type the root of مَّغْفِرَةًۭ in Arabic (three letters).","correct":"غفر","explanation":"غفر. Diacritics are ignored when checking, so غ ف ر is enough."}]', '["root-bEd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wly', 'The root ولي (و ل ي)', 'grammar', 2, '{"explanation":"The root ولي occurs 232 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَتَوَلَّىٰ","transliteration":"","meaning":"turns away","rule":"3:23"},{"arabic":"أَوْلِيَآءَ","transliteration":"","meaning":"(as) allies","rule":"3:28"},{"arabic":"وَلَّىٰهُمْ","transliteration":"","meaning":"(has) turned them","rule":"2:142"},{"arabic":"مَوَٰلِىَ","transliteration":"","meaning":"heirs","rule":"4:33"},{"arabic":"فَلَنُوَلِّيَنَّكَ","transliteration":"","meaning":"So We will surely turn you","rule":"2:144"},{"arabic":"يُوَلُّوكُمُ","transliteration":"","meaning":"they will turn (towards) you","rule":"3:111"}],"rules":[{"name":"Words on ولي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَتَوَلَّىٰ","أَوْلِيَآءَ","وَلَّىٰهُمْ","مَوَٰلِىَ","فَلَنُوَلِّيَنَّكَ","يُوَلُّوكُمُ","وَلِيُّهُمَا","مَوْلَىٰنَا"]},{"name":"Parts of speech attested for ولي","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 31 glossed words attested.","examples":["يَتَوَلَّىٰ","أَوْلِيَآءَ","وَلَّىٰهُمْ","مَوَٰلِىَ","فَلَنُوَلِّيَنَّكَ","يُوَلُّوكُمُ"]},{"name":"Verb forms attested for ولي","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, II.","examples":["يَتَوَلَّىٰ","أَوْلِيَآءَ","وَلَّىٰهُمْ","مَوَٰلِىَ","فَلَنُوَلِّيَنَّكَ","يُوَلُّوكُمُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ولي?","options":["يُذْهِبَنَّ","وَٱلْمُشْرِكِينَ","أَتَىٰهُمْ","يَتَوَلَّىٰ"],"correct":3,"explanation":"يَتَوَلَّىٰ — glossed \"turns away\" at 3:23 — carries the root ولي. The others come from different roots."},{"type":"multiple_choice","question":"What does أَوْلِيَآءَ mean?","options":["our land","the witnesses","to his father","(as) allies"],"correct":3,"explanation":"\"(as) allies\", from the word-by-word gloss at 3:28."},{"type":"fill_blank","question":"Type the root of وَلَّىٰهُمْ in Arabic (three letters).","correct":"ولي","explanation":"ولي. Diacritics are ignored when checking, so و ل ي is enough."}]', '["root-gfr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dEw', 'The root دعو (د ع و)', 'grammar', 2, '{"explanation":"The root دعو occurs 212 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَدْعُونَآ","transliteration":"","meaning":"you call us","rule":"11:62"},{"arabic":"تَدْعُوهُمْ","transliteration":"","meaning":"you call them","rule":"7:193"},{"arabic":"دَعْوَىٰهُمْ","transliteration":"","meaning":"their plea","rule":"7:5"},{"arabic":"فَٱدْعُوهُ","transliteration":"","meaning":"so invoke Him","rule":"7:180"},{"arabic":"وَٱدْعُوا۟","transliteration":"","meaning":"and call","rule":"2:23"},{"arabic":"أَدْعُوٓا۟","transliteration":"","meaning":"I invite","rule":"12:108"}],"rules":[{"name":"Words on دعو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَدْعُونَآ","تَدْعُوهُمْ","دَعْوَىٰهُمْ","فَٱدْعُوهُ","وَٱدْعُوا۟","أَدْعُوٓا۟","دَعْوَةُ","أَنَدْعُوا۟"]},{"name":"Parts of speech attested for دعو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 38 glossed words attested.","examples":["تَدْعُونَآ","تَدْعُوهُمْ","دَعْوَىٰهُمْ","فَٱدْعُوهُ","وَٱدْعُوا۟","أَدْعُوٓا۟"]},{"name":"Verb forms attested for دعو","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["تَدْعُونَآ","تَدْعُوهُمْ","دَعْوَىٰهُمْ","فَٱدْعُوهُ","وَٱدْعُوا۟","أَدْعُوٓا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دعو?","options":["ذَنۢبٍۢ","تَدْعُونَآ","ٱللَّهُ","ءَامِنُونَ"],"correct":1,"explanation":"تَدْعُونَآ — glossed \"you call us\" at 11:62 — carries the root دعو. The others come from different roots."},{"type":"multiple_choice","question":"What does تَدْعُوهُمْ mean?","options":["will forget","receive admonition","you call them","believe"],"correct":2,"explanation":"\"you call them\", from the word-by-word gloss at 7:193."},{"type":"fill_blank","question":"Type the root of دَعْوَىٰهُمْ in Arabic (three letters).","correct":"دعو","explanation":"دعو. Diacritics are ignored when checking, so د ع و is enough."}]', '["root-wly"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hkm', 'The root حكم (ح ك م)', 'grammar', 2, '{"explanation":"The root حكم occurs 210 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms IV, VI, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَٱحْكُم","transliteration":"","meaning":"then judge","rule":"5:42"},{"arabic":"يُحَكِّمُونَكَ","transliteration":"","meaning":"they appoint you a judge","rule":"5:43"},{"arabic":"ٱلْحِكْمَةَ","transliteration":"","meaning":"[the] wisdom","rule":"2:269"},{"arabic":"يَحْكُمُ","transliteration":"","meaning":"will judge","rule":"2:113"},{"arabic":"وَٱلْحُكْمَ","transliteration":"","meaning":"and the wisdom","rule":"3:79"},{"arabic":"وَلْيَحْكُمْ","transliteration":"","meaning":"And let judge","rule":"5:47"}],"rules":[{"name":"Words on حكم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَٱحْكُم","يُحَكِّمُونَكَ","ٱلْحِكْمَةَ","يَحْكُمُ","وَٱلْحُكْمَ","وَلْيَحْكُمْ","يَتَحَاكَمُوٓا۟","وَحَكَمًۭا"]},{"name":"Parts of speech attested for حكم","description":"The morphology corpus tags words on this root as ADJ, V, N — 3 distinct parts of speech across the 29 glossed words attested.","examples":["فَٱحْكُم","يُحَكِّمُونَكَ","ٱلْحِكْمَةَ","يَحْكُمُ","وَٱلْحُكْمَ","وَلْيَحْكُمْ"]},{"name":"Verb forms attested for حكم","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VI, II.","examples":["فَٱحْكُم","يُحَكِّمُونَكَ","ٱلْحِكْمَةَ","يَحْكُمُ","وَٱلْحُكْمَ","وَلْيَحْكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حكم?","options":["أَثَرِى","أَمِنتُمْ","فَٱحْكُم","إِخْوَتِكَ"],"correct":2,"explanation":"فَٱحْكُم — glossed \"then judge\" at 5:42 — carries the root حكم. The others come from different roots."},{"type":"multiple_choice","question":"What does يُحَكِّمُونَكَ mean?","options":["we have testified","surely (is) a witness","they appoint you a judge","For Allah"],"correct":2,"explanation":"\"they appoint you a judge\", from the word-by-word gloss at 5:43."},{"type":"fill_blank","question":"Type the root of ٱلْحِكْمَةَ in Arabic (three letters).","correct":"حكم","explanation":"حكم. Diacritics are ignored when checking, so ح ك م is enough."}]', '["root-dEw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mlk', 'The root ملك (م ل ك)', 'grammar', 2, '{"explanation":"The root ملك occurs 206 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, PN, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَمْلِكُ","transliteration":"","meaning":"has power","rule":"5:17"},{"arabic":"مَلِكًۭا","transliteration":"","meaning":"a king","rule":"2:246"},{"arabic":"مُّلُوكًۭا","transliteration":"","meaning":"kings","rule":"5:20"},{"arabic":"ٱلْمَلَـٰٓئِكَةِ","transliteration":"","meaning":"the angels","rule":"2:31"},{"arabic":"ٱلْمُلْكُ","transliteration":"","meaning":"the kingship","rule":"2:247"},{"arabic":"أَمْلِكُ","transliteration":"","meaning":"(have) power","rule":"5:25"}],"rules":[{"name":"Words on ملك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَمْلِكُ","مَلِكًۭا","مُّلُوكًۭا","ٱلْمَلَـٰٓئِكَةِ","ٱلْمُلْكُ","أَمْلِكُ","مَلَكًۭا","مُّلْكًا"]},{"name":"Parts of speech attested for ملك","description":"The morphology corpus tags words on this root as N, V, PN, ADJ — 4 distinct parts of speech across the 29 glossed words attested.","examples":["يَمْلِكُ","مَلِكًۭا","مُّلُوكًۭا","ٱلْمَلَـٰٓئِكَةِ","ٱلْمُلْكُ","أَمْلِكُ"]},{"name":"Where ملك occurs","description":"The 29 glossed words on this root are attested across 6 distinct surahs.","examples":["يَمْلِكُ (5:17)","مَلِكًۭا (2:246)","مُّلُوكًۭا (5:20)","ٱلْمَلَـٰٓئِكَةِ (2:31)","ٱلْمُلْكُ (2:247)","أَمْلِكُ (5:25)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ملك?","options":["ٱللَّهِ","وَٱتَّخَذَ","يَمْلِكُ","فَٱذْهَبْ"],"correct":2,"explanation":"يَمْلِكُ — glossed \"has power\" at 5:17 — carries the root ملك. The others come from different roots."},{"type":"multiple_choice","question":"What does مَلِكًۭا mean?","options":["And Allah is sufficient","Then go","a king","and order"],"correct":2,"explanation":"\"a king\", from the word-by-word gloss at 2:246."},{"type":"fill_blank","question":"Type the root of مُّلُوكًۭا in Arabic (three letters).","correct":"ملك","explanation":"ملك. Diacritics are ignored when checking, so م ل ك is enough."}]', '["root-Hkm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-End', 'The root عند (ع ن د)', 'grammar', 2, '{"explanation":"The root عند occurs 201 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as LOC, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عِندِ","transliteration":"","meaning":"from","rule":"2:79"},{"arabic":"عِندَهَا","transliteration":"","meaning":"with her","rule":"3:37"},{"arabic":"عِندَهُمُ","transliteration":"","meaning":"with them","rule":"4:139"},{"arabic":"عِندَهُۥ","transliteration":"","meaning":"(that) he has","rule":"2:140"},{"arabic":"عِندِهِۦ","transliteration":"","meaning":"(of) Him","rule":"5:52"},{"arabic":"عِندَنَا","transliteration":"","meaning":"with us","rule":"3:156"}],"rules":[{"name":"Words on عند","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عِندِ","عِندَهَا","عِندَهُمُ","عِندَهُۥ","عِندِهِۦ","عِندَنَا","عِندَهُۥٓ","عِندَ"]},{"name":"Parts of speech attested for عند","description":"The morphology corpus tags words on this root as LOC, N, ADJ — 3 distinct parts of speech across the 14 glossed words attested.","examples":["عِندِ","عِندَهَا","عِندَهُمُ","عِندَهُۥ","عِندِهِۦ","عِندَنَا"]},{"name":"Where عند occurs","description":"The 14 glossed words on this root are attested across 5 distinct surahs.","examples":["عِندِ (2:79)","عِندَهَا (3:37)","عِندَهُمُ (4:139)","عِندَهُۥ (2:140)","عِندِهِۦ (5:52)","عِندَنَا (3:156)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عند?","options":["ءَامَنَّا","عِندِ","تَأْوِيلِ","تَأْوِيلِ"],"correct":1,"explanation":"عِندِ — glossed \"from\" at 2:79 — carries the root عند. The others come from different roots."},{"type":"multiple_choice","question":"What does عِندَهَا mean?","options":["those who associate partners (with Allah)","(the) term","with her","my tracks"],"correct":2,"explanation":"\"with her\", from the word-by-word gloss at 3:37."},{"type":"fill_blank","question":"Type the root of عِندَهُمُ in Arabic (three letters).","correct":"عند","explanation":"عند. Diacritics are ignored when checking, so ع ن د is enough."}]', '["root-mlk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jnn', 'The root جنن (ج ن ن)', 'grammar', 2, '{"explanation":"The root جنن occurs 201 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, PN, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْجِنِّ","transliteration":"","meaning":"and the jinn","rule":"6:112"},{"arabic":"وَجَنَّـٰتٌۭ","transliteration":"","meaning":"and Gardens","rule":"3:136"},{"arabic":"ٱلْجِنَّ","transliteration":"","meaning":"jinn","rule":"6:100"},{"arabic":"جَنَّـٰتِ","transliteration":"","meaning":"(to) Gardens","rule":"5:65"},{"arabic":"جَنَّـٰتٍۢ","transliteration":"","meaning":"(will be) Gardens","rule":"2:25"},{"arabic":"ٱلْجَنَّةُ","transliteration":"","meaning":"(is) Paradise","rule":"7:43"}],"rules":[{"name":"Words on جنن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْجِنِّ","وَجَنَّـٰتٌۭ","ٱلْجِنَّ","جَنَّـٰتِ","جَنَّـٰتٍۢ","ٱلْجَنَّةُ","ٱلْجَنَّةَ","ٱلْجِنَّةِ"]},{"name":"Parts of speech attested for جنن","description":"The morphology corpus tags words on this root as N, PN, V — 3 distinct parts of speech across the 19 glossed words attested.","examples":["وَٱلْجِنِّ","وَجَنَّـٰتٌۭ","ٱلْجِنَّ","جَنَّـٰتِ","جَنَّـٰتٍۢ","ٱلْجَنَّةُ"]},{"name":"Where جنن occurs","description":"The 19 glossed words on this root are attested across 8 distinct surahs.","examples":["وَٱلْجِنِّ (6:112)","وَجَنَّـٰتٌۭ (3:136)","ٱلْجِنَّ (6:100)","جَنَّـٰتِ (5:65)","جَنَّـٰتٍۢ (2:25)","ٱلْجَنَّةُ (7:43)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جنن?","options":["أَشَقُّ","وَٱلْجِنِّ","ٱلْمَشْرِقِ","ٱللَّهُ"],"correct":1,"explanation":"وَٱلْجِنِّ — glossed \"and the jinn\" at 6:112 — carries the root جنن. The others come from different roots."},{"type":"multiple_choice","question":"What does وَجَنَّـٰتٌۭ mean?","options":["and the Command","my family","and Gardens","give"],"correct":2,"explanation":"\"and Gardens\", from the word-by-word gloss at 3:136."},{"type":"fill_blank","question":"Type the root of ٱلْجِنَّ in Arabic (three letters).","correct":"جنن","explanation":"جنن. Diacritics are ignored when checking, so ج ن ن is enough."}]', '["root-End"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xyr', 'The root خير (خ ي ر)', 'grammar', 3, '{"explanation":"The root خير occurs 196 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"خَيْرٍۢ","transliteration":"","meaning":"good","rule":"2:105"},{"arabic":"خَيْرَ","transliteration":"","meaning":"(the) best","rule":"2:197"},{"arabic":"خَيْرُ","transliteration":"","meaning":"(is the) best","rule":"3:54"},{"arabic":"ٱلْخَيْرِ","transliteration":"","meaning":"the good","rule":"3:104"},{"arabic":"خَيْرًا","transliteration":"","meaning":"good","rule":"2:180"},{"arabic":"ٱلْخَيْرَٰتِ","transliteration":"","meaning":"(to) the good","rule":"2:148"}],"rules":[{"name":"Words on خير","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["خَيْرٍۢ","خَيْرَ","خَيْرُ","ٱلْخَيْرِ","خَيْرًا","ٱلْخَيْرَٰتِ","ٱلْخَيْرُ","خَيْرًۭا"]},{"name":"Parts of speech attested for خير","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 11 glossed words attested.","examples":["خَيْرٍۢ","خَيْرَ","خَيْرُ","ٱلْخَيْرِ","خَيْرًا","ٱلْخَيْرَٰتِ"]},{"name":"Verb forms attested for خير","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, V.","examples":["خَيْرٍۢ","خَيْرَ","خَيْرُ","ٱلْخَيْرِ","خَيْرًا","ٱلْخَيْرَٰتِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خير?","options":["خَيْرٍۢ","أَتَتَّخِذُ","تَتَّخِذُونَ","ذَهَابٍۭ"],"correct":0,"explanation":"خَيْرٍۢ — glossed \"good\" at 2:105 — carries the root خير. The others come from different roots."},{"type":"multiple_choice","question":"What does خَيْرَ mean?","options":["And take for yourselves","(the) best","We have believed","He commanded him"],"correct":1,"explanation":"\"(the) best\", from the word-by-word gloss at 2:197."},{"type":"fill_blank","question":"Type the root of خَيْرُ in Arabic (three letters).","correct":"خير","explanation":"خير. Diacritics are ignored when checking, so خ ي ر is enough."}]', '["root-jnn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hsn', 'The root حسن (ح س ن)', 'grammar', 3, '{"explanation":"The root حسن occurs 194 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَحُسْنَ","transliteration":"","meaning":"and good","rule":"3:148"},{"arabic":"حُسْنًۭا","transliteration":"","meaning":"good","rule":"2:83"},{"arabic":"بِأَحْسَنَ","transliteration":"","meaning":"with better","rule":"4:86"},{"arabic":"ٱلْمُحْسِنِينَ","transliteration":"","meaning":"the good-doers (in reward)","rule":"2:58"},{"arabic":"ٱلْحُسْنَيَيْنِ","transliteration":"","meaning":"(of) the two best (things)","rule":"9:52"},{"arabic":"تُحْسِنُوا۟","transliteration":"","meaning":"you do good","rule":"4:128"}],"rules":[{"name":"Words on حسن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَحُسْنَ","حُسْنًۭا","بِأَحْسَنَ","ٱلْمُحْسِنِينَ","ٱلْحُسْنَيَيْنِ","تُحْسِنُوا۟","مُحْسِنٌۭ","حَسَنًا"]},{"name":"Parts of speech attested for حسن","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 30 glossed words attested.","examples":["وَحُسْنَ","حُسْنًۭا","بِأَحْسَنَ","ٱلْمُحْسِنِينَ","ٱلْحُسْنَيَيْنِ","تُحْسِنُوا۟"]},{"name":"Verb forms attested for حسن","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَحُسْنَ","حُسْنًۭا","بِأَحْسَنَ","ٱلْمُحْسِنِينَ","ٱلْحُسْنَيَيْنِ","تُحْسِنُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حسن?","options":["لِمُؤْمِنٍۢ","وَحُسْنَ","أَحَدُهُمَآ","تُؤْمِنُوٓا۟"],"correct":1,"explanation":"وَحُسْنَ — glossed \"and good\" at 3:148 — carries the root حسن. The others come from different roots."},{"type":"multiple_choice","question":"What does حُسْنًۭا mean?","options":["(does) Allah","good","(of) humility","(as) nations"],"correct":1,"explanation":"\"good\", from the word-by-word gloss at 2:83."},{"type":"fill_blank","question":"Type the root of بِأَحْسَنَ in Arabic (three letters).","correct":"حسن","explanation":"حسن. Diacritics are ignored when checking, so ح س ن is enough."}]', '["root-xyr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nwr', 'The root نور (ن و ر)', 'grammar', 3, '{"explanation":"The root نور occurs 194 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلنُّورِ","transliteration":"","meaning":"[the] light","rule":"2:257"},{"arabic":"نُورٌۭ","transliteration":"","meaning":"a light","rule":"5:15"},{"arabic":"ٱلنَّارِ","transliteration":"","meaning":"(of) the Fire","rule":"2:39"},{"arabic":"ٱلنَّارَ","transliteration":"","meaning":"the Fire","rule":"2:24"},{"arabic":"وَنُورٌۭ","transliteration":"","meaning":"and light","rule":"5:44"},{"arabic":"ٱلنُّورَ","transliteration":"","meaning":"the light","rule":"7:157"}],"rules":[{"name":"Words on نور","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلنُّورِ","نُورٌۭ","ٱلنَّارِ","ٱلنَّارَ","وَنُورٌۭ","ٱلنُّورَ","وَٱلنُّورَ","ٱلنَّارُ"]},{"name":"Parts of speech attested for نور","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 17 glossed words attested.","examples":["ٱلنُّورِ","نُورٌۭ","ٱلنَّارِ","ٱلنَّارَ","وَنُورٌۭ","ٱلنُّورَ"]},{"name":"Verb forms attested for نور","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["ٱلنُّورِ","نُورٌۭ","ٱلنَّارِ","ٱلنَّارَ","وَنُورٌۭ","ٱلنُّورَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نور?","options":["ٱلْأُمُورُ","ٱلنُّورِ","وَءَابَآؤُكُم","ٱلذِّكْرِ"],"correct":1,"explanation":"ٱلنُّورِ — glossed \"[the] light\" at 2:257 — carries the root نور. The others come from different roots."},{"type":"multiple_choice","question":"What does نُورٌۭ mean?","options":["Is there any god","a light","and your partners","So Allah protected him"],"correct":1,"explanation":"\"a light\", from the word-by-word gloss at 5:15."},{"type":"fill_blank","question":"Type the root of ٱلنَّارِ in Arabic (three letters).","correct":"نور","explanation":"نور. Diacritics are ignored when checking, so ن و ر is enough."}]', '["root-Hsn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Dll', 'The root ضلل (ض ل ل)', 'grammar', 3, '{"explanation":"The root ضلل occurs 191 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَضِلُّوا۟","transliteration":"","meaning":"you stray","rule":"4:44"},{"arabic":"يَضِلُّ","transliteration":"","meaning":"strays","rule":"6:117"},{"arabic":"ٱلضَّآلِّينَ","transliteration":"","meaning":"(of) those who go astray","rule":"1:7"},{"arabic":"ضَلُّوا۟","transliteration":"","meaning":"they have strayed","rule":"4:167"},{"arabic":"ٱلضَّلَـٰلَةُ","transliteration":"","meaning":"the astraying","rule":"7:30"},{"arabic":"أَضَلَّ","transliteration":"","meaning":"is let astray","rule":"4:88"}],"rules":[{"name":"Words on ضلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَضِلُّوا۟","يَضِلُّ","ٱلضَّآلِّينَ","ضَلُّوا۟","ٱلضَّلَـٰلَةُ","أَضَلَّ","ٱلضَّلَـٰلَةَ","ضَلَلْتُ"]},{"name":"Parts of speech attested for ضلل","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 35 glossed words attested.","examples":["تَضِلُّوا۟","يَضِلُّ","ٱلضَّآلِّينَ","ضَلُّوا۟","ٱلضَّلَـٰلَةُ","أَضَلَّ"]},{"name":"Verb forms attested for ضلل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["تَضِلُّوا۟","يَضِلُّ","ٱلضَّآلِّينَ","ضَلُّوا۟","ٱلضَّلَـٰلَةُ","أَضَلَّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ضلل?","options":["ٱللَّهُ","يَأْتِىٓ","ٱلشَّيَـٰطِينُ","تَضِلُّوا۟"],"correct":3,"explanation":"تَضِلُّوا۟ — glossed \"you stray\" at 4:44 — carries the root ضلل. The others come from different roots."},{"type":"multiple_choice","question":"What does يَضِلُّ mean?","options":["the remembrance","a sign","strays","let swear"],"correct":2,"explanation":"\"strays\", from the word-by-word gloss at 6:117."},{"type":"fill_blank","question":"Type the root of ٱلضَّآلِّينَ in Arabic (three letters).","correct":"ضلل","explanation":"ضلل. Diacritics are ignored when checking, so ض ل ل is enough."}]', '["root-nwr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-smE', 'The root سمع (س م ع)', 'grammar', 3, '{"explanation":"The root سمع occurs 185 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَمِيعُ","transliteration":"","meaning":"(are) All-Hearer","rule":"3:38"},{"arabic":"وَٱسْمَعُوا۟","transliteration":"","meaning":"and listen","rule":"2:93"},{"arabic":"سَمِعْتُمْ","transliteration":"","meaning":"you hear","rule":"4:140"},{"arabic":"سَمِيعًۢا","transliteration":"","meaning":"All-Hearing","rule":"4:58"},{"arabic":"وَلَتَسْمَعُنَّ","transliteration":"","meaning":"And you will certainly hear","rule":"3:186"},{"arabic":"أَسْمَعَهُمْ","transliteration":"","meaning":"He had made them hear","rule":"8:23"}],"rules":[{"name":"Words on سمع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَمِيعُ","وَٱسْمَعُوا۟","سَمِعْتُمْ","سَمِيعًۢا","وَلَتَسْمَعُنَّ","أَسْمَعَهُمْ","سَمْعِهِمْ","يَسْمَعُوا۟"]},{"name":"Parts of speech attested for سمع","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 28 glossed words attested.","examples":["سَمِيعُ","وَٱسْمَعُوا۟","سَمِعْتُمْ","سَمِيعًۢا","وَلَتَسْمَعُنَّ","أَسْمَعَهُمْ"]},{"name":"Verb forms attested for سمع","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII, V.","examples":["سَمِيعُ","وَٱسْمَعُوا۟","سَمِعْتُمْ","سَمِيعًۢا","وَلَتَسْمَعُنَّ","أَسْمَعَهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سمع?","options