INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bny', 'The root بني (ب ن ي)', 'grammar', 3, '{"explanation":"The root بني occurs 184 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَبْنَآءَهُمُ","transliteration":"","meaning":"their sons","rule":"6:20"},{"arabic":"وَأَبْنَآءَكُمْ","transliteration":"","meaning":"and your sons","rule":"3:61"},{"arabic":"بَنِيهِ","transliteration":"","meaning":"(upon) his sons","rule":"2:132"},{"arabic":"يَـٰبَنِىٓ","transliteration":"","meaning":"O Children","rule":"2:40"},{"arabic":"وَأَبْنَآؤُكُمْ","transliteration":"","meaning":"and your children","rule":"4:11"},{"arabic":"وَٱلْبَنِينَ","transliteration":"","meaning":"and [the] sons","rule":"3:14"}],"rules":[{"name":"Words on بني","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَبْنَآءَهُمُ","وَأَبْنَآءَكُمْ","بَنِيهِ","يَـٰبَنِىٓ","وَأَبْنَآؤُكُمْ","وَٱلْبَنِينَ","بَنِىٓ","بَنِينَ"]},{"name":"Parts of speech attested for بني","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 29 glossed words attested.","examples":["أَبْنَآءَهُمُ","وَأَبْنَآءَكُمْ","بَنِيهِ","يَـٰبَنِىٓ","وَأَبْنَآؤُكُمْ","وَٱلْبَنِينَ"]},{"name":"Where بني occurs","description":"The 29 glossed words on this root are attested across 6 distinct surahs.","examples":["أَبْنَآءَهُمُ (6:20)","وَأَبْنَآءَكُمْ (3:61)","بَنِيهِ (2:132)","يَـٰبَنِىٓ (2:40)","وَأَبْنَآؤُكُمْ (4:11)","وَٱلْبَنِينَ (3:14)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بني?","optio