INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-SlH', 'The root صلح (ص ل ح)', 'grammar', 3, '{"explanation":"The root صلح occurs 180 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as N, V, ADJ, PN, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُصْلِحُونَ","transliteration":"","meaning":"(are) reformers","rule":"2:11"},{"arabic":"يَـٰصَـٰلِحُ","transliteration":"","meaning":"O Salih","rule":"7:77"},{"arabic":"وَأَصْلِحْ","transliteration":"","meaning":"and do right","rule":"7:142"},{"arabic":"ٱلْمُصْلِحِ","transliteration":"","meaning":"the amender","rule":"2:220"},{"arabic":"وَأَصْلِحُوا۟","transliteration":"","meaning":"and set right","rule":"8:1"},{"arabic":"ٱلصَّـٰلِحِينَ","transliteration":"","meaning":"the righteous","rule":"2:130"}],"rules":[{"name":"Words on صلح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُصْلِحُونَ","يَـٰصَـٰلِحُ","وَأَصْلِحْ","ٱلْمُصْلِحِ","وَأَصْلِحُوا۟","ٱلصَّـٰلِحِينَ","وَأَصْلَحُوا۟","ٱلْمُصْلِحِينَ"]},{"name":"Parts of speech attested for صلح","description":"The morphology corpus tags words on this root as N, V, ADJ, PN — 4 distinct parts of speech across the 27 glossed words attested.","examples":["مُصْلِحُونَ","يَـٰصَـٰلِحُ","وَأَصْلِحْ","ٱلْمُصْلِحِ","وَأَصْلِحُوا۟","ٱلصَّـٰلِحِينَ"]},{"name":"Verb forms attested for صلح","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["مُصْلِحُونَ","يَـٰصَـٰلِحُ","وَأَصْلِحْ","ٱلْمُصْلِحِ","وَأَصْلِحُوا۟","ٱلصَّـٰلِحِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صلح?","options":["