INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sbl', 'The root سبل (س ب ل)', 'grammar', 3, '{"explanation":"The root سبل occurs 176 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلسَّبِيلَ","transliteration":"","meaning":"(from) the way","rule":"4:44"},{"arabic":"سَبِيلًۢا","transliteration":"","meaning":"(to) a (right) way","rule":"4:137"},{"arabic":"سَبِيلًا","transliteration":"","meaning":"way","rule":"4:22"},{"arabic":"سَبِيلًۭا","transliteration":"","meaning":"(find) a way","rule":"3:97"},{"arabic":"سَبِيلٍ","transliteration":"","meaning":"(through) a way","rule":"4:43"},{"arabic":"ٱلسَّبِيلِ","transliteration":"","meaning":"(of) the way","rule":"2:108"}],"rules":[{"name":"Words on سبل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلسَّبِيلَ","سَبِيلًۢا","سَبِيلًا","سَبِيلًۭا","سَبِيلٍ","ٱلسَّبِيلِ","سَبِيلُ","سَبِيلِهِۦ"]},{"name":"Parts of speech attested for سبل","description":"The morphology corpus tags words on this root as N — one part of speech across the 13 glossed words attested.","examples":["ٱلسَّبِيلَ","سَبِيلًۢا","سَبِيلًا","سَبِيلًۭا","سَبِيلٍ","ٱلسَّبِيلِ"]},{"name":"Where سبل occurs","description":"The 13 glossed words on this root are attested across 5 distinct surahs.","examples":["ٱلسَّبِيلَ (4:44)","سَبِيلًۢا (4:137)","سَبِيلًا (4:22)","سَبِيلًۭا (3:97)","سَبِيلٍ (4:43)","ٱلسَّبِيلِ (2:108)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سبل?","options":["ءَاثِمٌۭ","وَأَخَذْنَـٰهُم","أَهْلُهَا","ٱلسَّبِيلَ"],"correct":3,"explanation":"ٱلسَّبِيلَ — glossed \"(from) the way\" at 4:44 — carries the root سبل. The others come from different roots."},{"type":"multiple_choice","question":"What does سَبِيلًۢا mean?","options":["(to) a (right) way","Allah has imposed","and (the) captive","(of) the risings"],"correct":0,"explanation":"\"(to) a (right) way\", from the word-by-word gloss at 4:137."},{"type":"fill_blank","question":"Type the root of سَبِيلًا in Arabic (three letters).","correct":"سبل","explanation":"سبل. Diacritics are ignored when checking, so س ب ل is enough."}]', '["root-SlH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-tbE', 'The root تبع (ت ب ع)', 'grammar', 3, '{"explanation":"The root تبع occurs 172 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 40 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VIII, IV, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَتَّبِعَ","transliteration":"","meaning":"you follow","rule":"2:120"},{"arabic":"تَبِعَكَ","transliteration":"","meaning":"follows you","rule":"7:18"},{"arabic":"مُتَتَابِعَيْنِ","transliteration":"","meaning":"consecutively","rule":"4:92"},{"arabic":"أَتَّبِعُ","transliteration":"","meaning":"(do) I follow","rule":"6:50"},{"arabic":"تَبِعَ","transliteration":"","meaning":"follows","rule":"2:38"},{"arabic":"ٱتَّبِعُوا۟","transliteration":"","meaning":"Follow","rule":"2:170"}],"rules":[{"name":"Words on تبع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَتَّبِعَ","تَبِعَكَ","مُتَتَابِعَيْنِ","أَتَّبِعُ","تَبِعَ","ٱتَّبِعُوا۟","بِتَابِعٍۢ","ٱتَّبَعَ"]},{"name":"Parts of speech attested for تبع","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 40 glossed words attested.","examples":["تَتَّبِعَ","تَبِعَكَ","مُتَتَابِعَيْنِ","أَتَّبِعُ","تَبِعَ","ٱتَّبِعُوا۟"]},{"name":"Verb forms attested for تبع","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, IV, VI.","examples":["تَتَّبِعَ","تَبِعَكَ","مُتَتَابِعَيْنِ","أَتَّبِعُ","تَبِعَ","ٱتَّبِعُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root تبع?","options":["ٱللَّهِ","تَتَّبِعَ","أَجْرًۭا","مُشْرِكِينَ"],"correct":1,"explanation":"تَتَّبِعَ — glossed \"you follow\" at 2:120 — carries the root تبع. The others come from different roots."},{"type":"multiple_choice","question":"What does تَبِعَكَ mean?","options":["Is there any god","(have) they taken","follows you","the signs"],"correct":2,"explanation":"\"follows you\", from the word-by-word gloss at 7:18."},{"type":"fill_blank","question":"Type the root of مُتَتَابِعَيْنِ in Arabic (three letters).","correct":"تبع","explanation":"تبع. Diacritics are ignored when checking, so ت ب ع is enough."}]', '["root-sbl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Awl', 'The root اول (ا و ل)', 'grammar', 3, '{"explanation":"The root اول occurs 170 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, T, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أُو۟لُوا۟","transliteration":"","meaning":"those","rule":"2:269"},{"arabic":"ٱلْأَوَّلِينَ","transliteration":"","meaning":"(of) the former (people)","rule":"6:25"},{"arabic":"وَأُو۟لِى","transliteration":"","meaning":"and those","rule":"4:59"},{"arabic":"أُو۟لِى","transliteration":"","meaning":"those","rule":"4:83"},{"arabic":"ءَالَ","transliteration":"","meaning":"(the) people","rule":"2:50"},{"arabic":"تَأْوِيلِهِۦ","transliteration":"","meaning":"its interpretation","rule":"3:7"}],"rules":[{"name":"Words on اول","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أُو۟لُوا۟","ٱلْأَوَّلِينَ","وَأُو۟لِى","أُو۟لِى","ءَالَ","تَأْوِيلِهِۦ","ءَالِ","أَوَّلُ"]},{"name":"Parts of speech attested for اول","description":"The morphology corpus tags words on this root as N, T, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["أُو۟لُوا۟","ٱلْأَوَّلِينَ","وَأُو۟لِى","أُو۟لِى","ءَالَ","تَأْوِيلِهِۦ"]},{"name":"Verb forms attested for اول","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["أُو۟لُوا۟","ٱلْأَوَّلِينَ","وَأُو۟لِى","أُو۟لِى","ءَالَ","تَأْوِيلِهِۦ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اول?","options":["وَيَشْفِ","ٱلْأَمْرُ","أُو۟لُوا۟","يَتَّخِذْ"],"correct":2,"explanation":"أُو۟لُوا۟ — glossed \"those\" at 2:269 — carries the root اول. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْأَوَّلِينَ mean?","options":["(of) the former (people)","they will come","the trusts","(to) one of you"],"correct":0,"explanation":"\"(of) the former (people)\", from the word-by-word gloss at 6:25."},{"type":"fill_blank","question":"Type the root of وَأُو۟لِى in Arabic (three letters).","correct":"اول","explanation":"اول. Diacritics are ignored when checking, so ا و ل is enough."}]', '["root-tbE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qtl', 'The root قتل (ق ت ل)', 'grammar', 3, '{"explanation":"The root قتل occurs 170 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 46 distinct glossed words, tagged in the corpus as V, N, in verb forms III, VIII, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قِتَالٌۭ","transliteration":"","meaning":"Fighting","rule":"2:217"},{"arabic":"يُقَـٰتِلُونَكُمْ","transliteration":"","meaning":"fight you","rule":"2:190"},{"arabic":"۞ فَلْيُقَـٰتِلْ","transliteration":"","meaning":"So let fight","rule":"4:74"},{"arabic":"وَٱقْتُلُوهُمْ","transliteration":"","meaning":"And kill them","rule":"2:191"},{"arabic":"قِتَالٍۢ","transliteration":"","meaning":"(concerning) fighting","rule":"2:217"},{"arabic":"ٱلْقَتْلِ","transliteration":"","meaning":"[the] killing","rule":"2:191"}],"rules":[{"name":"Words on قتل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قِتَالٌۭ","يُقَـٰتِلُونَكُمْ","۞ فَلْيُقَـٰتِلْ","وَٱقْتُلُوهُمْ","قِتَالٍۢ","ٱلْقَتْلِ","فَٱقْتُلُوٓا۟","تُقَـٰتِلُوا۟"]},{"name":"Parts of speech attested for قتل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 46 glossed words attested.","examples":["قِتَالٌۭ","يُقَـٰتِلُونَكُمْ","۞ فَلْيُقَـٰتِلْ","وَٱقْتُلُوهُمْ","قِتَالٍۢ","ٱلْقَتْلِ"]},{"name":"Verb forms attested for قتل","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VIII, II.","examples":["قِتَالٌۭ","يُقَـٰتِلُونَكُمْ","۞ فَلْيُقَـٰتِلْ","وَٱقْتُلُوهُمْ","قِتَالٍۢ","ٱلْقَتْلِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قتل?","options":["ذَرَأْنَا","بِٱللَّهِ","إِثْمًا","قِتَالٌۭ"],"correct":3,"explanation":"قِتَالٌۭ — glossed \"Fighting\" at 2:217 — carries the root قتل. The others come from different roots."},{"type":"multiple_choice","question":"What does يُقَـٰتِلُونَكُمْ mean?","options":["surely is a sign","fight you","and that may take heed","(the) people"],"correct":1,"explanation":"\"fight you\", from the word-by-word gloss at 2:190."},{"type":"fill_blank","question":"Type the root of ۞ فَلْيُقَـٰتِلْ in Arabic (three letters).","correct":"قتل","explanation":"قتل. Diacritics are ignored when checking, so ق ت ل is enough."}]', '["root-Awl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mvl', 'The root مثل (م ث ل)', 'grammar', 3, '{"explanation":"The root مثل occurs 169 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb form V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مِّثْلُ","transliteration":"","meaning":"(is) similar","rule":"5:95"},{"arabic":"أَمْثَالُكُم","transliteration":"","meaning":"like you","rule":"6:38"},{"arabic":"مِّثْلُهُمْ","transliteration":"","meaning":"(would be) like them","rule":"4:140"},{"arabic":"وَمَثَلُ","transliteration":"","meaning":"And (the) example","rule":"2:171"},{"arabic":"مِّثْلَيْهَا","transliteration":"","meaning":"twice of it","rule":"3:165"},{"arabic":"مِّثْلُهُۥ","transliteration":"","meaning":"like it","rule":"3:140"}],"rules":[{"name":"Words on مثل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مِّثْلُ","أَمْثَالُكُم","مِّثْلُهُمْ","وَمَثَلُ","مِّثْلَيْهَا","مِّثْلُهُۥ","مَثَلًۭا","مِّثْلَيْهِمْ"]},{"name":"Parts of speech attested for مثل","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 30 glossed words attested.","examples":["مِّثْلُ","أَمْثَالُكُم","مِّثْلُهُمْ","وَمَثَلُ","مِّثْلَيْهَا","مِّثْلُهُۥ"]},{"name":"Verb forms attested for مثل","description":"Where this root is tagged as a verb, the corpus attests derived Form V.","examples":["مِّثْلُ","أَمْثَالُكُم","مِّثْلُهُمْ","وَمَثَلُ","مِّثْلَيْهَا","مِّثْلُهُۥ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مثل?","options":["لَـَٔاتٍۢ","ٱللَّهُ","أَخَّرْنَا","مِّثْلُ"],"correct":3,"explanation":"مِّثْلُ — glossed \"(is) similar\" at 5:95 — carries the root مثل. The others come from different roots."},{"type":"multiple_choice","question":"What does أَمْثَالُكُم mean?","options":["believing","like you","mightier","they come to you"],"correct":1,"explanation":"\"like you\", from the word-by-word gloss at 6:38."},{"type":"fill_blank","question":"Type the root of مِّثْلُهُمْ in Arabic (three letters).","correct":"مثل","explanation":"مثل. Diacritics are ignored when checking, so م ث ل is enough."}]', '["root-qtl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$rk', 'The root شرك (ش ر ك)', 'grammar', 3, '{"explanation":"The root شرك occurs 168 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, III, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَشْرَكُوٓا۟","transliteration":"","meaning":"associate partners with Allah","rule":"3:186"},{"arabic":"ٱلْمُشْرِكِينَ","transliteration":"","meaning":"those who associate partners (with Allah)","rule":"2:105"},{"arabic":"ٱلْمُشْرِكَـٰتِ","transliteration":"","meaning":"[the] polytheistic women","rule":"2:221"},{"arabic":"شُرَكَآءَ","transliteration":"","meaning":"partners","rule":"6:100"},{"arabic":"شَرِيكَ","transliteration":"","meaning":"partners","rule":"6:163"},{"arabic":"نُشْرِكَ","transliteration":"","meaning":"we associate partners","rule":"3:64"}],"rules":[{"name":"Words on شرك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَشْرَكُوٓا۟","ٱلْمُشْرِكِينَ","ٱلْمُشْرِكَـٰتِ","شُرَكَآءَ","شَرِيكَ","نُشْرِكَ","أَشْرَكْتُمْ","تُشْرِكُونَ"]},{"name":"Parts of speech attested for شرك","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 29 glossed words attested.","examples":["أَشْرَكُوٓا۟","ٱلْمُشْرِكِينَ","ٱلْمُشْرِكَـٰتِ","شُرَكَآءَ","شَرِيكَ","نُشْرِكَ"]},{"name":"Verb forms attested for شرك","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, III, VIII.","examples":["أَشْرَكُوٓا۟","ٱلْمُشْرِكِينَ","ٱلْمُشْرِكَـٰتِ","شُرَكَآءَ","شَرِيكَ","نُشْرِكَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شرك?","options":["أَشْرَكُوٓا۟","تُشْطِطْ","تُؤَدُّوا۟","يَتَّخِذُوا۟"],"correct":0,"explanation":"أَشْرَكُوٓا۟ — glossed \"associate partners with Allah\" at 3:186 — carries the root شرك. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُشْرِكِينَ mean?","options":["those who associate partners (with Allah)","Allah sets a seal","He wills","its produce"],"correct":0,"explanation":"\"those who associate partners (with Allah)\", from the word-by-word gloss at 2:105."},{"type":"fill_blank","question":"Type the root of ٱلْمُشْرِكَـٰتِ in Arabic (three letters).","correct":"شرك","explanation":"شرك. Diacritics are ignored when checking, so ش ر ك is enough."}]', '["root-mvl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qlb', 'The root قلب (ق ل ب)', 'grammar', 3, '{"explanation":"The root قلب occurs 168 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as N, V, in verb forms VII, V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَلْبِهِۦ","transliteration":"","meaning":"his heart","rule":"2:204"},{"arabic":"قُلُوبُكُمْ","transliteration":"","meaning":"your hearts","rule":"2:225"},{"arabic":"فَتَنقَلِبُوا۟","transliteration":"","meaning":"then you will turn back","rule":"3:149"},{"arabic":"فَٱنقَلَبُوا۟","transliteration":"","meaning":"So they returned","rule":"3:174"},{"arabic":"قَلْبُهُۥ","transliteration":"","meaning":"his heart","rule":"2:283"},{"arabic":"قُلُوبِهِم","transliteration":"","meaning":"their hearts","rule":"2:10"}],"rules":[{"name":"Words on قلب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَلْبِهِۦ","قُلُوبُكُمْ","فَتَنقَلِبُوا۟","فَٱنقَلَبُوا۟","قَلْبُهُۥ","قُلُوبِهِم","قُلُوبِهِمْ","قُلُوبَهُمْ"]},{"name":"Parts of speech attested for قلب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 31 glossed words attested.","examples":["قَلْبِهِۦ","قُلُوبُكُمْ","فَتَنقَلِبُوا۟","فَٱنقَلَبُوا۟","قَلْبُهُۥ","قُلُوبِهِم"]},{"name":"Verb forms attested for قلب","description":"Where this root is tagged as a verb, the corpus attests derived Forms VII, V, II.","examples":["قَلْبِهِۦ","قُلُوبُكُمْ","فَتَنقَلِبُوا۟","فَٱنقَلَبُوا۟","قَلْبُهُۥ","قُلُوبِهِم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قلب?","options":["بِٱلْـَٔاخِرَةِ","تَأْتِيهِمْ","قَلْبِهِۦ","أُسِّسَ"],"correct":2,"explanation":"قَلْبِهِۦ — glossed \"his heart\" at 2:204 — carries the root قلب. The others come from different roots."},{"type":"multiple_choice","question":"What does قُلُوبُكُمْ mean?","options":["Our Signs","your hearts","had willed","and give"],"correct":1,"explanation":"\"your hearts\", from the word-by-word gloss at 2:225."},{"type":"fill_blank","question":"Type the root of فَتَنقَلِبُوا۟ in Arabic (three letters).","correct":"قلب","explanation":"قلب. Diacritics are ignored when checking, so ق ل ب is enough."}]', '["root-$rk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kvr', 'The root كثر (ك ث ر)', 'grammar', 3, '{"explanation":"The root كثر occurs 167 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms X, II, IV, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَكْثَرَهُمْ","transliteration":"","meaning":"most of them","rule":"6:37"},{"arabic":"لِأَكْثَرِهِم","transliteration":"","meaning":"for most of them","rule":"7:102"},{"arabic":"لِكَثِيرٍۢ","transliteration":"","meaning":"to many","rule":"6:137"},{"arabic":"كَثْرَتُكُمْ","transliteration":"","meaning":"your multitude","rule":"9:25"},{"arabic":"فَكَثَّرَكُمْ","transliteration":"","meaning":"and He increased you","rule":"7:86"},{"arabic":"كَثِيرٍۢ","transliteration":"","meaning":"much","rule":"4:114"}],"rules":[{"name":"Words on كثر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَكْثَرَهُمْ","لِأَكْثَرِهِم","لِكَثِيرٍۢ","كَثْرَتُكُمْ","فَكَثَّرَكُمْ","كَثِيرٍۢ","كَثِيرَةًۢ","أَكْثَرُهُمْ"]},{"name":"Parts of speech attested for كثر","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 24 glossed words attested.","examples":["أَكْثَرَهُمْ","لِأَكْثَرِهِم","لِكَثِيرٍۢ","كَثْرَتُكُمْ","فَكَثَّرَكُمْ","كَثِيرٍۢ"]},{"name":"Verb forms attested for كثر","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, II, IV, III.","examples":["أَكْثَرَهُمْ","لِأَكْثَرِهِم","لِكَثِيرٍۢ","كَثْرَتُكُمْ","فَكَثَّرَكُمْ","كَثِيرٍۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كثر?","options":["أَوَّلِ","ٱللَّهُ","أَهْلَهُۥ","أَكْثَرَهُمْ"],"correct":3,"explanation":"أَكْثَرَهُمْ — glossed \"most of them\" at 6:37 — carries the root كثر. The others come from different roots."},{"type":"multiple_choice","question":"What does لِأَكْثَرِهِم mean?","options":["he is harmed","for most of them","a witness","(of) the risings"],"correct":1,"explanation":"\"for most of them\", from the word-by-word gloss at 7:102."},{"type":"fill_blank","question":"Type the root of لِكَثِيرٍۢ in Arabic (three letters).","correct":"كثر","explanation":"كثر. Diacritics are ignored when checking, so ك ث ر is enough."}]', '["root-qlb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-swA', 'The root سوا (س و ا)', 'grammar', 3, '{"explanation":"The root سوا occurs 167 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَسُؤْكُمْ","transliteration":"","meaning":"it may distress you","rule":"5:101"},{"arabic":"سُوٓءٍۢ","transliteration":"","meaning":"evil","rule":"3:30"},{"arabic":"وَسَآءَ","transliteration":"","meaning":"and (an) evil","rule":"4:22"},{"arabic":"سُوٓءًۭا","transliteration":"","meaning":"evil","rule":"4:123"},{"arabic":"ٱلسَّوْءِ","transliteration":"","meaning":"(of) the evil","rule":"9:98"},{"arabic":"ٱلسُّوٓءِ","transliteration":"","meaning":"the evil","rule":"7:165"}],"rules":[{"name":"Words on سوا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَسُؤْكُمْ","سُوٓءٍۢ","وَسَآءَ","سُوٓءًۭا","ٱلسَّوْءِ","ٱلسُّوٓءِ","تَسُؤْهُمْ","سُوٓءٌۭ"]},{"name":"Parts of speech attested for سوا","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 38 glossed words attested.","examples":["تَسُؤْكُمْ","سُوٓءٍۢ","وَسَآءَ","سُوٓءًۭا","ٱلسَّوْءِ","ٱلسُّوٓءِ"]},{"name":"Verb forms attested for سوا","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تَسُؤْكُمْ","سُوٓءٍۢ","وَسَآءَ","سُوٓءًۭا","ٱلسَّوْءِ","ٱلسُّوٓءِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سوا?","options":["تَسُؤْكُمْ","وَإِلَـٰهَ","أَبِينَا","إِخْوَٰنًۭا"],"correct":0,"explanation":"تَسُؤْكُمْ — glossed \"it may distress you\" at 5:101 — carries the root سوا. The others come from different roots."},{"type":"multiple_choice","question":"What does سُوٓءٍۢ mean?","options":["a sign","evil","reward","So, seized them"],"correct":1,"explanation":"\"evil\", from the word-by-word gloss at 3:30."},{"type":"fill_blank","question":"Type the root of وَسَآءَ in Arabic (three letters).","correct":"سوا","explanation":"سوا. Diacritics are ignored when checking, so س و ا is enough."}]', '["root-kvr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mwt', 'The root موت (م و ت)', 'grammar', 3, '{"explanation":"The root موت occurs 165 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُّتُّمْ","transliteration":"","meaning":"you die","rule":"3:158"},{"arabic":"ٱلْمَيِّتِ","transliteration":"","meaning":"the dead","rule":"3:27"},{"arabic":"مَوْتِكُمْ","transliteration":"","meaning":"your death","rule":"2:56"},{"arabic":"مَّيْتَةًۭ","transliteration":"","meaning":"(born) dead","rule":"6:139"},{"arabic":"ٱلْمَيِّتَ","transliteration":"","meaning":"the dead","rule":"3:27"},{"arabic":"ٱلْمَوْتَىٰ","transliteration":"","meaning":"the dead","rule":"2:73"}],"rules":[{"name":"Words on موت","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُّتُّمْ","ٱلْمَيِّتِ","مَوْتِكُمْ","مَّيْتَةًۭ","ٱلْمَيِّتَ","ٱلْمَوْتَىٰ","فَيَمُتْ","ٱلْمَوْتُ"]},{"name":"Parts of speech attested for موت","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 35 glossed words attested.","examples":["مُّتُّمْ","ٱلْمَيِّتِ","مَوْتِكُمْ","مَّيْتَةًۭ","ٱلْمَيِّتَ","ٱلْمَوْتَىٰ"]},{"name":"Verb forms attested for موت","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["مُّتُّمْ","ٱلْمَيِّتِ","مَوْتِكُمْ","مَّيْتَةًۭ","ٱلْمَيِّتَ","ٱلْمَوْتَىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root موت?","options":["ٱللَّهُ","ٱلْأُولَىٰ","مُّتُّمْ","ذَرْعُهَا"],"correct":2,"explanation":"مُّتُّمْ — glossed \"you die\" at 3:158 — carries the root موت. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمَيِّتِ mean?","options":["the dead","(A) mention","(is) severe","His Verses"],"correct":0,"explanation":"\"the dead\", from the word-by-word gloss at 3:27."},{"type":"fill_blank","question":"Type the root of مَوْتِكُمْ in Arabic (three letters).","correct":"موت","explanation":"موت. Diacritics are ignored when checking, so م و ت is enough."}]', '["root-swA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kbr', 'The root كبر (ك ب ر)', 'grammar', 3, '{"explanation":"The root كبر occurs 161 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms X, II, V, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَبِيرَةًۭ","transliteration":"","meaning":"big","rule":"9:121"},{"arabic":"كَبِيرٍ","transliteration":"","meaning":"(of) a Great Day","rule":"11:3"},{"arabic":"ٱلْأَكْبَرِ","transliteration":"","meaning":"(of) the greater Pilgrimage","rule":"9:3"},{"arabic":"ٱسْتَكْبَرْتُمْ","transliteration":"","meaning":"you acted arrogantly","rule":"2:87"},{"arabic":"وَٱسْتَكْبَرَ","transliteration":"","meaning":"and was arrogant","rule":"2:34"},{"arabic":"فَٱسْتَكْبَرُوا۟","transliteration":"","meaning":"but they showed arrogance","rule":"7:133"}],"rules":[{"name":"Words on كبر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَبِيرَةًۭ","كَبِيرٍ","ٱلْأَكْبَرِ","ٱسْتَكْبَرْتُمْ","وَٱسْتَكْبَرَ","فَٱسْتَكْبَرُوا۟","ٱسْتَكْبَرُوا۟","مُّسْتَكْبِرُونَ"]},{"name":"Parts of speech attested for كبر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 35 glossed words attested.","examples":["كَبِيرَةًۭ","كَبِيرٍ","ٱلْأَكْبَرِ","ٱسْتَكْبَرْتُمْ","وَٱسْتَكْبَرَ","فَٱسْتَكْبَرُوا۟"]},{"name":"Verb forms attested for كبر","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, II, V, IV.","examples":["كَبِيرَةًۭ","كَبِيرٍ","ٱلْأَكْبَرِ","ٱسْتَكْبَرْتُمْ","وَٱسْتَكْبَرَ","فَٱسْتَكْبَرُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كبر?","options":["كَبِيرَةًۭ","لِّيَذْكُرُوا۟","وَءَامَنُوا۟","لِلذَّٰكِرِينَ"],"correct":0,"explanation":"كَبِيرَةًۭ — glossed \"big\" at 9:121 — carries the root كبر. The others come from different roots."},{"type":"multiple_choice","question":"What does كَبِيرٍ mean?","options":["He has given them","(and) grateful","sheltered him","(of) a Great Day"],"correct":3,"explanation":"\"(of) a Great Day\", from the word-by-word gloss at 11:3."},{"type":"fill_blank","question":"Type the root of ٱلْأَكْبَرِ in Arabic (three letters).","correct":"كبر","explanation":"كبر. Diacritics are ignored when checking, so ك ب ر is enough."}]', '["root-mwt"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$hd', 'The root شهد (ش ه د)', 'grammar', 3, '{"explanation":"The root شهد occurs 160 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 42 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلشَّهَـٰدَةَ","transliteration":"","meaning":"the evidence","rule":"2:283"},{"arabic":"فَٱسْتَشْهِدُوا۟","transliteration":"","meaning":"then call to witness","rule":"4:15"},{"arabic":"شَهِدَ","transliteration":"","meaning":"witnesses","rule":"2:185"},{"arabic":"يَشْهَدُونَ","transliteration":"","meaning":"bear witness","rule":"4:166"},{"arabic":"شَهِيدٌۭ","transliteration":"","meaning":"(the) witness","rule":"2:282"},{"arabic":"فَٱشْهَدُوا۟","transliteration":"","meaning":"Then bear witness","rule":"3:81"}],"rules":[{"name":"Words on شهد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلشَّهَـٰدَةَ","فَٱسْتَشْهِدُوا۟","شَهِدَ","يَشْهَدُونَ","شَهِيدٌۭ","فَٱشْهَدُوا۟","يَشْهَدُ","وَشَهِدُوٓا۟"]},{"name":"Parts of speech attested for شهد","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 42 glossed words attested.","examples":["ٱلشَّهَـٰدَةَ","فَٱسْتَشْهِدُوا۟","شَهِدَ","يَشْهَدُونَ","شَهِيدٌۭ","فَٱشْهَدُوا۟"]},{"name":"Verb forms attested for شهد","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["ٱلشَّهَـٰدَةَ","فَٱسْتَشْهِدُوا۟","شَهِدَ","يَشْهَدُونَ","شَهِيدٌۭ","فَٱشْهَدُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شهد?","options":["ٱلْأَوَّلِينَ","تَسْتَـْٔخِرُونَ","ٱلشَّهَـٰدَةَ","ءَالِهَةً"],"correct":2,"explanation":"ٱلشَّهَـٰدَةَ — glossed \"the evidence\" at 2:283 — carries the root شهد. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱسْتَشْهِدُوا۟ mean?","options":["their term","then call to witness","your brothers","his kind"],"correct":1,"explanation":"\"then call to witness\", from the word-by-word gloss at 4:15."},{"type":"fill_blank","question":"Type the root of شَهِدَ in Arabic (three letters).","correct":"شهد","explanation":"شهد. Diacritics are ignored when checking, so ش ه د is enough."}]', '["root-kbr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nbA', 'The root نبا (ن ب ا)', 'grammar', 3, '{"explanation":"The root نبا occurs 160 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنۢبَآءِ","transliteration":"","meaning":"(the) news","rule":"3:44"},{"arabic":"ٱلنَّبِيِّـۧنَ","transliteration":"","meaning":"the Prophets","rule":"2:61"},{"arabic":"نَبَإٍۢ","transliteration":"","meaning":"news","rule":"6:67"},{"arabic":"يُنَبِّئُهُمُ","transliteration":"","meaning":"will inform them","rule":"5:14"},{"arabic":"وَٱلنَّبِيِّـۧنَ","transliteration":"","meaning":"and the Prophets","rule":"2:177"},{"arabic":"نَبِىٍّ","transliteration":"","meaning":"Prophet","rule":"6:112"}],"rules":[{"name":"Words on نبا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنۢبَآءِ","ٱلنَّبِيِّـۧنَ","نَبَإٍۢ","يُنَبِّئُهُمُ","وَٱلنَّبِيِّـۧنَ","نَبِىٍّ","وَنَبِيًّۭا","ٱلنَّبِىَّ"]},{"name":"Parts of speech attested for نبا","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 39 glossed words attested.","examples":["أَنۢبَآءِ","ٱلنَّبِيِّـۧنَ","نَبَإٍۢ","يُنَبِّئُهُمُ","وَٱلنَّبِيِّـۧنَ","نَبِىٍّ"]},{"name":"Verb forms attested for نبا","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II, X.","examples":["أَنۢبَآءِ","ٱلنَّبِيِّـۧنَ","نَبَإٍۢ","يُنَبِّئُهُمُ","وَٱلنَّبِيِّـۧنَ","نَبِىٍّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نبا?","options":["ٱللَّهَ","أَنۢبَآءِ","أَحَدٍۢ","أَمْرًۭا"],"correct":1,"explanation":"أَنۢبَآءِ — glossed \"(the) news\" at 3:44 — carries the root نبا. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلنَّبِيِّـۧنَ mean?","options":["the Prophets","(are) brothers","miserly","for his father"],"correct":0,"explanation":"\"the Prophets\", from the word-by-word gloss at 2:61."},{"type":"fill_blank","question":"Type the root of نَبَإٍۢ in Arabic (three letters).","correct":"نبا","explanation":"نبا. Diacritics are ignored when checking, so ن ب ا is enough."}]', '["root-$hd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bED', 'The root بعض (ب ع ض)', 'grammar', 3, '{"explanation":"The root بعض occurs 158 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَعْضِ","transliteration":"","meaning":"some","rule":"5:49"},{"arabic":"بِبَعْضٍۢ","transliteration":"","meaning":"in part","rule":"2:85"},{"arabic":"بَعْضَهُۥ","transliteration":"","meaning":"some of them","rule":"8:37"},{"arabic":"بَعْضُهَا","transliteration":"","meaning":"some of them","rule":"3:34"},{"arabic":"بَعْضَهُمْ","transliteration":"","meaning":"some of them","rule":"2:253"},{"arabic":"بَعْضًۢا","transliteration":"","meaning":"(to) others","rule":"6:129"}],"rules":[{"name":"Words on بعض","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَعْضِ","بِبَعْضٍۢ","بَعْضَهُۥ","بَعْضُهَا","بَعْضَهُمْ","بَعْضًۢا","بَعْضُكُمْ","بَعْضَكُمْ"]},{"name":"Parts of speech attested for بعض","description":"The morphology corpus tags words on this root as N — one part of speech across the 24 glossed words attested.","examples":["بَعْضِ","بِبَعْضٍۢ","بَعْضَهُۥ","بَعْضُهَا","بَعْضَهُمْ","بَعْضًۢا"]},{"name":"Where بعض occurs","description":"The 24 glossed words on this root are attested across 6 distinct surahs.","examples":["بَعْضِ (5:49)","بِبَعْضٍۢ (2:85)","بَعْضَهُۥ (8:37)","بَعْضُهَا (3:34)","بَعْضَهُمْ (2:253)","بَعْضًۢا (6:129)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بعض?","options":["ذَكَرٍۢ","يَأْتِينِى","بَعْضِ","ءَاتَىٰنِۦَ"],"correct":2,"explanation":"بَعْضِ — glossed \"some\" at 5:49 — carries the root بعض. The others come from different roots."},{"type":"multiple_choice","question":"What does بِبَعْضٍۢ mean?","options":["Our Command","and a term","witnesses","in part"],"correct":3,"explanation":"\"in part\", from the word-by-word gloss at 2:85."},{"type":"fill_blank","question":"Type the root of بَعْضَهُۥ in Arabic (three letters).","correct":"بعض","explanation":"بعض. Diacritics are ignored when checking, so ب ع ض is enough."}]', '["root-nbA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nSr', 'The root نصر (ن ص ر)', 'grammar', 3, '{"explanation":"The root نصر occurs 158 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, PN, N, ADJ, in verb forms X, VIII, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَصْرَكُمْ","transliteration":"","meaning":"(to) help you","rule":"7:197"},{"arabic":"نَصِيرًۭا","transliteration":"","meaning":"(as) a Helper","rule":"4:45"},{"arabic":"ٱسْتَنصَرُوكُمْ","transliteration":"","meaning":"they seek your help","rule":"8:72"},{"arabic":"فَٱنصُرْنَا","transliteration":"","meaning":"so help us","rule":"2:286"},{"arabic":"نَصْرُ","transliteration":"","meaning":"[will] (the) help","rule":"2:214"},{"arabic":"نَّـٰصِرِينَ","transliteration":"","meaning":"helpers","rule":"3:22"}],"rules":[{"name":"Words on نصر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَصْرَكُمْ","نَصِيرًۭا","ٱسْتَنصَرُوكُمْ","فَٱنصُرْنَا","نَصْرُ","نَّـٰصِرِينَ","نَصَـٰرَىٰ","نَصْرَانِيًّۭا"]},{"name":"Parts of speech attested for نصر","description":"The morphology corpus tags words on this root as V, PN, N, ADJ — 4 distinct parts of speech across the 35 glossed words attested.","examples":["نَصْرَكُمْ","نَصِيرًۭا","ٱسْتَنصَرُوكُمْ","فَٱنصُرْنَا","نَصْرُ","نَّـٰصِرِينَ"]},{"name":"Verb forms attested for نصر","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, VIII, VI.","examples":["نَصْرَكُمْ","نَصِيرًۭا","ٱسْتَنصَرُوكُمْ","فَٱنصُرْنَا","نَصْرُ","نَّـٰصِرِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نصر?","options":["نَصْرَكُمْ","أَكَّـٰلُونَ","شَيْطَـٰنًۭا","أَذِنَ"],"correct":0,"explanation":"نَصْرَكُمْ — glossed \"(to) help you\" at 7:197 — carries the root نصر. The others come from different roots."},{"type":"multiple_choice","question":"What does نَصِيرًۭا mean?","options":["partners","desires","(as) a Helper","Allah has decreed"],"correct":2,"explanation":"\"(as) a Helper\", from the word-by-word gloss at 4:45."},{"type":"fill_blank","question":"Type the root of ٱسْتَنصَرُوكُمْ in Arabic (three letters).","correct":"نصر","explanation":"نصر. Diacritics are ignored when checking, so ن ص ر is enough."}]', '["root-bED"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Sdq', 'The root صدق (ص د ق)', 'grammar', 3, '{"explanation":"The root صدق occurs 155 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صَدَقَـٰتِكُم","transliteration":"","meaning":"your charities","rule":"2:264"},{"arabic":"ٱلصَّدَقَـٰتُ","transliteration":"","meaning":"the charities","rule":"9:60"},{"arabic":"تَصَدَّقَ","transliteration":"","meaning":"gives charity","rule":"5:45"},{"arabic":"صِدْقًۭا","transliteration":"","meaning":"(in) truth","rule":"6:115"},{"arabic":"مُصَدِّقٌۭ","transliteration":"","meaning":"confirming","rule":"2:89"},{"arabic":"صَـٰدِقِينَ","transliteration":"","meaning":"truthful","rule":"2:23"}],"rules":[{"name":"Words on صدق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صَدَقَـٰتِكُم","ٱلصَّدَقَـٰتُ","تَصَدَّقَ","صِدْقًۭا","مُصَدِّقٌۭ","صَـٰدِقِينَ","تَصْدِيقَ","صَدَقَةٍ"]},{"name":"Parts of speech attested for صدق","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 33 glossed words attested.","examples":["صَدَقَـٰتِكُم","ٱلصَّدَقَـٰتُ","تَصَدَّقَ","صِدْقًۭا","مُصَدِّقٌۭ","صَـٰدِقِينَ"]},{"name":"Verb forms attested for صدق","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["صَدَقَـٰتِكُم","ٱلصَّدَقَـٰتُ","تَصَدَّقَ","صِدْقًۭا","مُصَدِّقٌۭ","صَـٰدِقِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صدق?","options":["صَدَقَـٰتِكُم","ٱللَّهُ","ٱلشَّيَـٰطِينَ","لِّلْمُؤْمِنِينَ"],"correct":0,"explanation":"صَدَقَـٰتِكُم — glossed \"your charities\" at 2:264 — carries the root صدق. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلصَّدَقَـٰتُ mean?","options":["any trouble","their bridal due","the charities","will remove"],"correct":2,"explanation":"\"the charities\", from the word-by-word gloss at 9:60."},{"type":"fill_blank","question":"Type the root of تَصَدَّقَ in Arabic (three letters).","correct":"صدق","explanation":"صدق. Diacritics are ignored when checking, so ص د ق is enough."}]', '["root-nSr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gyr', 'The root غير (غ ي ر)', 'grammar', 3, '{"explanation":"The root غير occurs 154 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms II, V, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"غَيْرِهِۦ","transliteration":"","meaning":"other than it","rule":"6:68"},{"arabic":"فَلَيُغَيِّرُنَّ","transliteration":"","meaning":"so they will surely change","rule":"4:119"},{"arabic":"غَيْرَهُۥ","transliteration":"","meaning":"other than him","rule":"2:230"},{"arabic":"أَفَغَيْرَ","transliteration":"","meaning":"So is (it) other than","rule":"3:83"},{"arabic":"غَيْرِهِۦٓ","transliteration":"","meaning":"other than that","rule":"4:140"},{"arabic":"غَيْرِكُمْ","transliteration":"","meaning":"other than you","rule":"5:106"}],"rules":[{"name":"Words on غير","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["غَيْرِهِۦ","فَلَيُغَيِّرُنَّ","غَيْرَهُۥ","أَفَغَيْرَ","غَيْرِهِۦٓ","غَيْرِكُمْ","غَيْرُهُۥ","وَغَيْرَ"]},{"name":"Parts of speech attested for غير","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 16 glossed words attested.","examples":["غَيْرِهِۦ","فَلَيُغَيِّرُنَّ","غَيْرَهُۥ","أَفَغَيْرَ","غَيْرِهِۦٓ","غَيْرِكُمْ"]},{"name":"Verb forms attested for غير","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V, IV.","examples":["غَيْرِهِۦ","فَلَيُغَيِّرُنَّ","غَيْرَهُۥ","أَفَغَيْرَ","غَيْرِهِۦٓ","غَيْرِكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غير?","options":["بِذَنۢبِهِمْ","غَيْرِهِۦ","أَهْلَهَا","يَأْتِيهَا"],"correct":1,"explanation":"غَيْرِهِۦ — glossed \"other than it\" at 6:68 — carries the root غير. The others come from different roots."},{"type":"multiple_choice","question":"What does فَلَيُغَيِّرُنَّ mean?","options":["we believe","And enjoin","so they will surely change","(the) term"],"correct":2,"explanation":"\"so they will surely change\", from the word-by-word gloss at 4:119."},{"type":"fill_blank","question":"Type the root of غَيْرَهُۥ in Arabic (three letters).","correct":"غير","explanation":"غير. Diacritics are ignored when checking, so غ ي ر is enough."}]', '["root-Sdq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wEd', 'The root وعد (و ع د)', 'grammar', 3, '{"explanation":"The root وعد occurs 151 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms III, IV, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَعَدَكُمْ","transliteration":"","meaning":"promised you","rule":"14:22"},{"arabic":"وَعَدَهَآ","transliteration":"","meaning":"he had promised it","rule":"9:114"},{"arabic":"وَعْدًا","transliteration":"","meaning":"A promise","rule":"9:111"},{"arabic":"وَعَدَنَا","transliteration":"","meaning":"(had) promised us","rule":"7:44"},{"arabic":"تُوَاعِدُوهُنَّ","transliteration":"","meaning":"promise them (widows)","rule":"2:235"},{"arabic":"ٱلْوَعْدُ","transliteration":"","meaning":"the promise (be fulfilled)","rule":"10:48"}],"rules":[{"name":"Words on وعد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَعَدَكُمْ","وَعَدَهَآ","وَعْدًا","وَعَدَنَا","تُوَاعِدُوهُنَّ","ٱلْوَعْدُ","وَعَدَ","مَّوْعِدٌۭ"]},{"name":"Parts of speech attested for وعد","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 39 glossed words attested.","examples":["وَعَدَكُمْ","وَعَدَهَآ","وَعْدًا","وَعَدَنَا","تُوَاعِدُوهُنَّ","ٱلْوَعْدُ"]},{"name":"Verb forms attested for وعد","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, IV, VI.","examples":["وَعَدَكُمْ","وَعَدَهَآ","وَعْدًا","وَعَدَنَا","تُوَاعِدُوهُنَّ","ٱلْوَعْدُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وعد?","options":["لَـَٔاتٍۢ","يُذْكَرُ","ٱلشَّيَـٰطِينُ","وَعَدَكُمْ"],"correct":3,"explanation":"وَعَدَكُمْ — glossed \"promised you\" at 14:22 — carries the root وعد. The others come from different roots."},{"type":"multiple_choice","question":"What does وَعَدَهَآ mean?","options":["in faith","he had promised it","remember","and the ones who believe"],"correct":1,"explanation":"\"he had promised it\", from the word-by-word gloss at 9:114."},{"type":"fill_blank","question":"Type the root of وَعْدًا in Arabic (three letters).","correct":"وعد","explanation":"وعد. Diacritics are ignored when checking, so و ع د is enough."}]', '["root-gyr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bSr', 'The root بصر (ب ص ر)', 'grammar', 3, '{"explanation":"The root بصر occurs 148 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, X, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَبْصَـٰرَهُمْ","transliteration":"","meaning":"their sight","rule":"2:20"},{"arabic":"يُبْصِرُ","transliteration":"","meaning":"sees","rule":"19:42"},{"arabic":"وَٱلْبَصِيرِ","transliteration":"","meaning":"and the seer","rule":"11:24"},{"arabic":"بَصَآئِرُ","transliteration":"","meaning":"enlightenment","rule":"6:104"},{"arabic":"يُبْصِرُونَ","transliteration":"","meaning":"(do) they see","rule":"2:17"},{"arabic":"بَصَآئِرَ","transliteration":"","meaning":"(as) evidence","rule":"17:102"}],"rules":[{"name":"Words on بصر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَبْصَـٰرَهُمْ","يُبْصِرُ","وَٱلْبَصِيرِ","بَصَآئِرُ","يُبْصِرُونَ","بَصَآئِرَ","وَٱلْبَصِيرُ","وَأَبْصَـٰرَكُمْ"]},{"name":"Parts of speech attested for بصر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 32 glossed words attested.","examples":["أَبْصَـٰرَهُمْ","يُبْصِرُ","وَٱلْبَصِيرِ","بَصَآئِرُ","يُبْصِرُونَ","بَصَآئِرَ"]},{"name":"Verb forms attested for بصر","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X, II.","examples":["أَبْصَـٰرَهُمْ","يُبْصِرُ","وَٱلْبَصِيرِ","بَصَآئِرُ","يُبْصِرُونَ","بَصَآئِرَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بصر?","options":["أَبْصَـٰرَهُمْ","ٱتَّخَذُوا۟","تُؤْفَكُونَ","شَهْوَةًۭ"],"correct":0,"explanation":"أَبْصَـٰرَهُمْ — glossed \"their sight\" at 2:20 — carries the root بصر. The others come from different roots."},{"type":"multiple_choice","question":"What does يُبْصِرُ mean?","options":["sees","Your parents","(are) [the] believers","that they may mention"],"correct":0,"explanation":"\"sees\", from the word-by-word gloss at 19:42."},{"type":"fill_blank","question":"Type the root of وَٱلْبَصِيرِ in Arabic (three letters).","correct":"بصر","explanation":"بصر. Diacritics are ignored when checking, so ب ص ر is enough."}]', '["root-wEd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rwd', 'The root رود (ر و د)', 'grammar', 3, '{"explanation":"The root رود occurs 148 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَرَادَ","transliteration":"","meaning":"(did) intend","rule":"2:26"},{"arabic":"يُرِدْكَ","transliteration":"","meaning":"He intends for you","rule":"10:107"},{"arabic":"يُرِيدُوٓا۟","transliteration":"","meaning":"they intend","rule":"8:62"},{"arabic":"أَرَادَا","transliteration":"","meaning":"they both desire","rule":"2:233"},{"arabic":"وَيُرِيدُ","transliteration":"","meaning":"but wish","rule":"4:27"},{"arabic":"تُرِيدُونَ","transliteration":"","meaning":"(do) you wish","rule":"2:108"}],"rules":[{"name":"Words on رود","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَرَادَ","يُرِدْكَ","يُرِيدُوٓا۟","أَرَادَا","وَيُرِيدُ","تُرِيدُونَ","يُرِدِ","أَرَدتُّمْ"]},{"name":"Parts of speech attested for رود","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 22 glossed words attested.","examples":["أَرَادَ","يُرِدْكَ","يُرِيدُوٓا۟","أَرَادَا","وَيُرِيدُ","تُرِيدُونَ"]},{"name":"Verb forms attested for رود","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, III.","examples":["أَرَادَ","يُرِدْكَ","يُرِيدُوٓا۟","أَرَادَا","وَيُرِيدُ","تُرِيدُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رود?","options":["بِمُؤْمِنٍۢ","لَتَأْتِيَنَّكُمْ","ٱللَّهُ","أَرَادَ"],"correct":3,"explanation":"أَرَادَ — glossed \"(did) intend\" at 2:26 — carries the root رود. The others come from different roots."},{"type":"multiple_choice","question":"What does يُرِدْكَ mean?","options":["He intends for you","(are) months","Allah returns you","an ordained way"],"correct":0,"explanation":"\"He intends for you\", from the word-by-word gloss at 10:107."},{"type":"fill_blank","question":"Type the root of يُرِيدُوٓا۟ in Arabic (three letters).","correct":"رود","explanation":"رود. Diacritics are ignored when checking, so ر و د is enough."}]', '["root-bSr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lqy', 'The root لقي (ل ق ي)', 'grammar', 3, '{"explanation":"The root لقي occurs 146 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 45 distinct glossed words, tagged in the corpus as V, N, LOC, in verb forms V, III, IV, VIII, II, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تِلْقَآءَ","transliteration":"","meaning":"towards","rule":"7:47"},{"arabic":"سَنُلْقِى","transliteration":"","meaning":"We will cast","rule":"3:151"},{"arabic":"فَأَلْقَىٰ","transliteration":"","meaning":"So he threw","rule":"7:107"},{"arabic":"لَقُوا۟","transliteration":"","meaning":"they meet","rule":"2:14"},{"arabic":"وَأَلْقُوهُ","transliteration":"","meaning":"but throw him","rule":"12:10"},{"arabic":"أَلْقُوا۟","transliteration":"","meaning":"Throw","rule":"7:116"}],"rules":[{"name":"Words on لقي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تِلْقَآءَ","سَنُلْقِى","فَأَلْقَىٰ","لَقُوا۟","وَأَلْقُوهُ","أَلْقُوا۟","وَأَلْقَى","لَقُوكُمْ"]},{"name":"Parts of speech attested for لقي","description":"The morphology corpus tags words on this root as V, N, LOC — 3 distinct parts of speech across the 45 glossed words attested.","examples":["تِلْقَآءَ","سَنُلْقِى","فَأَلْقَىٰ","لَقُوا۟","وَأَلْقُوهُ","أَلْقُوا۟"]},{"name":"Verb forms attested for لقي","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, III, IV, VIII, II, VI.","examples":["تِلْقَآءَ","سَنُلْقِى","فَأَلْقَىٰ","لَقُوا۟","وَأَلْقُوهُ","أَلْقُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لقي?","options":["أَجَلُهُنَّ","بِٱلْإِيمَـٰنِ","تِلْقَآءَ","ٱلْمَأْوَىٰ"],"correct":2,"explanation":"تِلْقَآءَ — glossed \"towards\" at 7:47 — carries the root لقي. The others come from different roots."},{"type":"multiple_choice","question":"What does سَنُلْقِى mean?","options":["for one of them","Allah has made unlawful","We will cast","the chins"],"correct":2,"explanation":"\"We will cast\", from the word-by-word gloss at 3:151."},{"type":"fill_blank","question":"Type the root of فَأَلْقَىٰ in Arabic (three letters).","correct":"لقي","explanation":"لقي. Diacritics are ignored when checking, so ل ق ي is enough."}]', '["root-rwd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dwn', 'The root دون (د و ن)', 'grammar', 3, '{"explanation":"The root دون occurs 144 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 9 distinct glossed words, tagged in the corpus as N, LOC. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"دُونِ","transliteration":"","meaning":"other than","rule":"2:23"},{"arabic":"دُونِهِۦٓ","transliteration":"","meaning":"besides Him","rule":"4:117"},{"arabic":"دُونِكَ","transliteration":"","meaning":"besides You","rule":"16:86"},{"arabic":"وَدُونَ","transliteration":"","meaning":"and without","rule":"7:205"},{"arabic":"دُونِهِۦ","transliteration":"","meaning":"other than Him","rule":"6:51"},{"arabic":"دُونِى","transliteration":"","meaning":"other than Me","rule":"17:2"}],"rules":[{"name":"Words on دون","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["دُونِ","دُونِهِۦٓ","دُونِكَ","وَدُونَ","دُونِهِۦ","دُونِى","دُونِهِمْ","دُونِكُمْ"]},{"name":"Parts of speech attested for دون","description":"The morphology corpus tags words on this root as N, LOC — 2 distinct parts of speech across the 9 glossed words attested.","examples":["دُونِ","دُونِهِۦٓ","دُونِكَ","وَدُونَ","دُونِهِۦ","دُونِى"]},{"name":"Where دون occurs","description":"The 9 glossed words on this root are attested across 8 distinct surahs.","examples":["دُونِ (2:23)","دُونِهِۦٓ (4:117)","دُونِكَ (16:86)","وَدُونَ (7:205)","دُونِهِۦ (6:51)","دُونِى (17:2)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دون?","options":["دُونِ","أَرْضًۭا","إِيمَـٰنَهُم","أَثِيمًۭا"],"correct":0,"explanation":"دُونِ — glossed \"other than\" at 2:23 — carries the root دون. The others come from different roots."},{"type":"multiple_choice","question":"What does دُونِهِۦٓ mean?","options":["other","a Witness","besides Him","lustfully"],"correct":2,"explanation":"\"besides Him\", from the word-by-word gloss at 4:117."},{"type":"fill_blank","question":"Type the root of دُونِكَ in Arabic (three letters).","correct":"دون","explanation":"دون. Diacritics are ignored when checking, so د و ن is enough."}]', '["root-lqy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nEm', 'The root نعم (ن ع م)', 'grammar', 3, '{"explanation":"The root نعم occurs 140 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنْعَـٰمٌۭ","transliteration":"","meaning":"(are) cattle","rule":"6:138"},{"arabic":"نِعْمَتَ","transliteration":"","meaning":"(the) Favors","rule":"2:231"},{"arabic":"ٱلنَّعِيمِ","transliteration":"","meaning":"(of) Bliss","rule":"5:65"},{"arabic":"أَنْعَمْتَ","transliteration":"","meaning":"You have bestowed (Your) Favors","rule":"1:7"},{"arabic":"كَٱلْأَنْعَـٰمِ","transliteration":"","meaning":"(are) like cattle","rule":"7:179"},{"arabic":"فَنِعِمَّا","transliteration":"","meaning":"then good","rule":"2:271"}],"rules":[{"name":"Words on نعم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنْعَـٰمٌۭ","نِعْمَتَ","ٱلنَّعِيمِ","أَنْعَمْتَ","كَٱلْأَنْعَـٰمِ","فَنِعِمَّا","وَٱلْأَنْعَـٰمِ","وَٱلْأَنْعَـٰمُ"]},{"name":"Parts of speech attested for نعم","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 33 glossed words attested.","examples":["أَنْعَـٰمٌۭ","نِعْمَتَ","ٱلنَّعِيمِ","أَنْعَمْتَ","كَٱلْأَنْعَـٰمِ","فَنِعِمَّا"]},{"name":"Verb forms attested for نعم","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["أَنْعَـٰمٌۭ","نِعْمَتَ","ٱلنَّعِيمِ","أَنْعَمْتَ","كَٱلْأَنْعَـٰمِ","فَنِعِمَّا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نعم?","options":["شَرِيكٌۭ","ٱلشَّيَـٰطِينِ","ذَهَبُوا۟","أَنْعَـٰمٌۭ"],"correct":3,"explanation":"أَنْعَـٰمٌۭ — glossed \"(are) cattle\" at 6:138 — carries the root نعم. The others come from different roots."},{"type":"multiple_choice","question":"What does نِعْمَتَ mean?","options":["He willed","(which) came to them","a polytheistic woman","(the) Favors"],"correct":3,"explanation":"\"(the) Favors\", from the word-by-word gloss at 2:231."},{"type":"fill_blank","question":"Type the root of ٱلنَّعِيمِ in Arabic (three letters).","correct":"نعم","explanation":"نعم. Diacritics are ignored when checking, so ن ع م is enough."}]', '["root-dwn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-slm', 'The root سلم (س ل م)', 'grammar', 3, '{"explanation":"The root سلم occurs 140 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as ADJ, V, N, PN, in verb forms II, IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُّسْلِمِينَ","transliteration":"","meaning":"Muslims","rule":"10:84"},{"arabic":"مُّسْلِمًۭا","transliteration":"","meaning":"Muslim","rule":"3:67"},{"arabic":"سَلَّمْتُم","transliteration":"","meaning":"you pay","rule":"2:233"},{"arabic":"وَيُسَلِّمُوا۟","transliteration":"","meaning":"and submit","rule":"4:65"},{"arabic":"ٱلْإِسْلَـٰمَ","transliteration":"","meaning":"[the] Islam","rule":"5:3"},{"arabic":"مُسْلِمِينَ","transliteration":"","meaning":"(as) Muslims","rule":"7:126"}],"rules":[{"name":"Words on سلم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُّسْلِمِينَ","مُّسْلِمًۭا","سَلَّمْتُم","وَيُسَلِّمُوا۟","ٱلْإِسْلَـٰمَ","مُسْلِمِينَ","ٱلسَّلَـٰمَ","سُلَّمًۭا"]},{"name":"Parts of speech attested for سلم","description":"The morphology corpus tags words on this root as ADJ, V, N, PN — 4 distinct parts of speech across the 37 glossed words attested.","examples":["مُّسْلِمِينَ","مُّسْلِمًۭا","سَلَّمْتُم","وَيُسَلِّمُوا۟","ٱلْإِسْلَـٰمَ","مُسْلِمِينَ"]},{"name":"Verb forms attested for سلم","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV, X.","examples":["مُّسْلِمِينَ","مُّسْلِمًۭا","سَلَّمْتُم","وَيُسَلِّمُوا۟","ٱلْإِسْلَـٰمَ","مُسْلِمِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سلم?","options":["أَجْرًا","ٱلشَّيْطَـٰنُ","مُّسْلِمِينَ","أَلِيمًۭا"],"correct":2,"explanation":"مُّسْلِمِينَ — glossed \"Muslims\" at 10:84 — carries the root سلم. The others come from different roots."},{"type":"multiple_choice","question":"What does مُّسْلِمًۭا mean?","options":["associate","will be accepted","[so] take it","Muslim"],"correct":3,"explanation":"\"Muslim\", from the word-by-word gloss at 3:67."},{"type":"fill_blank","question":"Type the root of سَلَّمْتُم in Arabic (three letters).","correct":"سلم","explanation":"سلم. Diacritics are ignored when checking, so س ل م is enough."}]', '["root-nEm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dnw', 'The root دنو (د ن و)', 'grammar', 3, '{"explanation":"The root دنو occurs 133 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N, ADJ, V, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَدْنَىٰٓ","transliteration":"","meaning":"(is) more appropriate","rule":"4:3"},{"arabic":"ٱلدُّنْيَآ","transliteration":"","meaning":"(of) the world","rule":"3:185"},{"arabic":"أَدْنَىٰ","transliteration":"","meaning":"(is) inferior","rule":"2:61"},{"arabic":"ٱلْأَدْنَىٰ","transliteration":"","meaning":"the lower (life)","rule":"7:169"},{"arabic":"وَأَدْنَىٰٓ","transliteration":"","meaning":"and nearer","rule":"2:282"},{"arabic":"دَانِيَةٌۭ","transliteration":"","meaning":"hanging low","rule":"6:99"}],"rules":[{"name":"Words on دنو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَدْنَىٰٓ","ٱلدُّنْيَآ","أَدْنَىٰ","ٱلْأَدْنَىٰ","وَأَدْنَىٰٓ","دَانِيَةٌۭ","ٱلدُّنْيَا"]},{"name":"Parts of speech attested for دنو","description":"The morphology corpus tags words on this root as N, ADJ, V, T — 4 distinct parts of speech across the 7 glossed words attested.","examples":["أَدْنَىٰٓ","ٱلدُّنْيَآ","أَدْنَىٰ","ٱلْأَدْنَىٰ","وَأَدْنَىٰٓ","دَانِيَةٌۭ"]},{"name":"Where دنو occurs","description":"The 7 glossed words on this root are attested across 5 distinct surahs.","examples":["أَدْنَىٰٓ (4:3)","ٱلدُّنْيَآ (3:185)","أَدْنَىٰ (2:61)","ٱلْأَدْنَىٰ (7:169)","وَأَدْنَىٰٓ (2:282)","دَانِيَةٌۭ (6:99)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دنو?","options":["لِشَىْءٍ","أَدْنَىٰٓ","ءَالِهَةًۭ","ٱلْمُؤْمِنُونَ"],"correct":1,"explanation":"أَدْنَىٰٓ — glossed \"(is) more appropriate\" at 4:3 — carries the root دنو. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلدُّنْيَآ mean?","options":["(of) the world","Allah rewards","And (due) to Allah","and Allah will see"],"correct":0,"explanation":"\"(of) the world\", from the word-by-word gloss at 3:185."},{"type":"fill_blank","question":"Type the root of أَدْنَىٰ in Arabic (three letters).","correct":"دنو","explanation":"دنو. Diacritics are ignored when checking, so د ن و is enough."}]', '["root-slm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qdr', 'The root قدر (ق د ر)', 'grammar', 3, '{"explanation":"The root قدر occurs 132 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَدَرُهُۥ","transliteration":"","meaning":"according to his means","rule":"2:236"},{"arabic":"تَقْدِرُوا۟","transliteration":"","meaning":"you overpower","rule":"5:34"},{"arabic":"لَقَـٰدِرُونَ","transliteration":"","meaning":"surely (are) Able","rule":"23:18"},{"arabic":"تَقْدِيرُ","transliteration":"","meaning":"(is the) ordaining","rule":"6:96"},{"arabic":"يَقْدِرُونَ","transliteration":"","meaning":"they have control","rule":"2:264"},{"arabic":"قَدِيرًۭا","transliteration":"","meaning":"All-Powerful","rule":"4:133"}],"rules":[{"name":"Words on قدر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَدَرُهُۥ","تَقْدِرُوا۟","لَقَـٰدِرُونَ","تَقْدِيرُ","يَقْدِرُونَ","قَدِيرًۭا","بِقَدَرِهَا","قَدَّرْنَـٰهَا"]},{"name":"Parts of speech attested for قدر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["قَدَرُهُۥ","تَقْدِرُوا۟","لَقَـٰدِرُونَ","تَقْدِيرُ","يَقْدِرُونَ","قَدِيرًۭا"]},{"name":"Verb forms attested for قدر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VIII.","examples":["قَدَرُهُۥ","تَقْدِرُوا۟","لَقَـٰدِرُونَ","تَقْدِيرُ","يَقْدِرُونَ","قَدِيرًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قدر?","options":["تَتَذَكَّرُونَ","قَدَرُهُۥ","لِّيَشْهَدُوا۟","ءَاتَيْنَـٰكُم"],"correct":1,"explanation":"قَدَرُهُۥ — glossed \"according to his means\" at 2:236 — carries the root قدر. The others come from different roots."},{"type":"multiple_choice","question":"What does تَقْدِرُوا۟ mean?","options":["fathers","(of) the devils","(of) his deed","you overpower"],"correct":3,"explanation":"\"you overpower\", from the word-by-word gloss at 5:34."},{"type":"fill_blank","question":"Type the root of لَقَـٰدِرُونَ in Arabic (three letters).","correct":"قدر","explanation":"قدر. Diacritics are ignored when checking, so ق د ر is enough."}]', '["root-dnw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-n*r', 'The root نذر (ن ذ ر)', 'grammar', 3, '{"explanation":"The root نذر occurs 130 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُنذِرٌۭ","transliteration":"","meaning":"(are) a warner","rule":"13:7"},{"arabic":"ٱلْمُنذَرِينَ","transliteration":"","meaning":"(of) those who were warned","rule":"10:73"},{"arabic":"نَّذِيرًۭا","transliteration":"","meaning":"a warner","rule":"25:51"},{"arabic":"وَلِتُنذِرَ","transliteration":"","meaning":"so that you may warn","rule":"6:92"},{"arabic":"أَنذِرِ","transliteration":"","meaning":"Warn","rule":"10:2"},{"arabic":"نَذَرْتُ","transliteration":"","meaning":"[I] vowed","rule":"3:35"}],"rules":[{"name":"Words on نذر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُنذِرٌۭ","ٱلْمُنذَرِينَ","نَّذِيرًۭا","وَلِتُنذِرَ","أَنذِرِ","نَذَرْتُ","وَأَنذِرْهُمْ","وَٱلنُّذُرُ"]},{"name":"Parts of speech attested for نذر","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 38 glossed words attested.","examples":["مُنذِرٌۭ","ٱلْمُنذَرِينَ","نَّذِيرًۭا","وَلِتُنذِرَ","أَنذِرِ","نَذَرْتُ"]},{"name":"Verb forms attested for نذر","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["مُنذِرٌۭ","ٱلْمُنذَرِينَ","نَّذِيرًۭا","وَلِتُنذِرَ","أَنذِرِ","نَذَرْتُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نذر?","options":["أُوتُوا۟","فَـَٔاوَىٰكُمْ","مُنذِرٌۭ","أَبُوهُمْ"],"correct":2,"explanation":"مُنذِرٌۭ — glossed \"(are) a warner\" at 13:7 — carries the root نذر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُنذَرِينَ mean?","options":["(of) those who were warned","We will bring","believing women","(of) the Shaitaan"],"correct":0,"explanation":"\"(of) those who were warned\", from the word-by-word gloss at 10:73."},{"type":"fill_blank","question":"Type the root of نَّذِيرًۭا in Arabic (three letters).","correct":"نذر","explanation":"نذر. Diacritics are ignored when checking, so ن ذ ر is enough."}]', '["root-qdr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-TwE', 'The root طوع (ط و ع)', 'grammar', 3, '{"explanation":"The root طوع occurs 129 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, X, IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَطَاعُونَا","transliteration":"","meaning":"they (had) obeyed us","rule":"3:168"},{"arabic":"ٱسْتَطَعْتَ","transliteration":"","meaning":"you are able","rule":"6:35"},{"arabic":"طَوْعًۭا","transliteration":"","meaning":"willingly","rule":"3:83"},{"arabic":"ٱسْتَطَعْنَا","transliteration":"","meaning":"we were able","rule":"9:42"},{"arabic":"ٱسْتَطَعْتُ","transliteration":"","meaning":"as much as I am able","rule":"11:88"},{"arabic":"يُطِعِ","transliteration":"","meaning":"obeys","rule":"4:13"}],"rules":[{"name":"Words on طوع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَطَاعُونَا","ٱسْتَطَعْتَ","طَوْعًۭا","ٱسْتَطَعْنَا","ٱسْتَطَعْتُ","يُطِعِ","تَسْتَطِع","وَيُطِيعُونَ"]},{"name":"Parts of speech attested for طوع","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 32 glossed words attested.","examples":["أَطَاعُونَا","ٱسْتَطَعْتَ","طَوْعًۭا","ٱسْتَطَعْنَا","ٱسْتَطَعْتُ","يُطِعِ"]},{"name":"Verb forms attested for طوع","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, X, IV, II.","examples":["أَطَاعُونَا","ٱسْتَطَعْتَ","طَوْعًۭا","ٱسْتَطَعْنَا","ٱسْتَطَعْتُ","يُطِعِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طوع?","options":["أَطَاعُونَا","أَحَدٍ","ذِرَاعَيْهِ","ٱللَّهُ"],"correct":0,"explanation":"أَطَاعُونَا — glossed \"they (had) obeyed us\" at 3:168 — carries the root طوع. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱسْتَطَعْتَ mean?","options":["(is) my payment","(whom) Allah","you are able","(by) our forefathers"],"correct":2,"explanation":"\"you are able\", from the word-by-word gloss at 6:35."},{"type":"fill_blank","question":"Type the root of طَوْعًۭا in Arabic (three letters).","correct":"طوع","explanation":"طوع. Diacritics are ignored when checking, so ط و ع is enough."}]', '["root-n*r"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jmE', 'The root جمع (ج م ع)', 'grammar', 3, '{"explanation":"The root جمع occurs 129 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as N, V, PN, in verb forms IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَجَمَعَهُمْ","transliteration":"","meaning":"surely He (would) have gathered them","rule":"6:35"},{"arabic":"يَجْمَعُونَ","transliteration":"","meaning":"they accumulate","rule":"3:157"},{"arabic":"جَمِيعًا","transliteration":"","meaning":"together","rule":"2:148"},{"arabic":"لَيَجْمَعَنَّكُمْ","transliteration":"","meaning":"surely He will gather you","rule":"4:87"},{"arabic":"ٱلْجَمْعَانِ","transliteration":"","meaning":"the two hosts","rule":"3:155"},{"arabic":"فَأَجْمِعُوٓا۟","transliteration":"","meaning":"So you all resolve","rule":"10:71"}],"rules":[{"name":"Words on جمع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَجَمَعَهُمْ","يَجْمَعُونَ","جَمِيعًا","لَيَجْمَعَنَّكُمْ","ٱلْجَمْعَانِ","فَأَجْمِعُوٓا۟","أَجْمَعُونَ","جَمِيعًۭا"]},{"name":"Parts of speech attested for جمع","description":"The morphology corpus tags words on this root as N, V, PN — 3 distinct parts of speech across the 18 glossed words attested.","examples":["لَجَمَعَهُمْ","يَجْمَعُونَ","جَمِيعًا","لَيَجْمَعَنَّكُمْ","ٱلْجَمْعَانِ","فَأَجْمِعُوٓا۟"]},{"name":"Verb forms attested for جمع","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII.","examples":["لَجَمَعَهُمْ","يَجْمَعُونَ","جَمِيعًا","لَيَجْمَعَنَّكُمْ","ٱلْجَمْعَانِ","فَأَجْمِعُوٓا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جمع?","options":["لَجَمَعَهُمْ","إِنَـٰثًا","شَهَـٰدَةَ","فَأَنَّىٰ"],"correct":0,"explanation":"لَجَمَعَهُمْ — glossed \"surely He (would) have gathered them\" at 6:35 — carries the root جمع. The others come from different roots."},{"type":"multiple_choice","question":"What does يَجْمَعُونَ mean?","options":["they accumulate","about your faith","while the earth","I will betake myself"],"correct":0,"explanation":"\"they accumulate\", from the word-by-word gloss at 3:157."},{"type":"fill_blank","question":"Type the root of جَمِيعًا in Arabic (three letters).","correct":"جمع","explanation":"جمع. Diacritics are ignored when checking, so ج م ع is enough."}]', '["root-TwE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nZr', 'The root نظر (ن ظ ر)', 'grammar', 3, '{"explanation":"The root نظر occurs 129 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنظِرْنِىٓ","transliteration":"","meaning":"Give me respite","rule":"7:14"},{"arabic":"لِلنَّـٰظِرِينَ","transliteration":"","meaning":"for the observers","rule":"7:108"},{"arabic":"ٱلْمُنتَظِرِينَ","transliteration":"","meaning":"the ones who wait","rule":"7:71"},{"arabic":"يَنظُرُونَ","transliteration":"","meaning":"they waiting","rule":"2:210"},{"arabic":"يَنظُرُ","transliteration":"","meaning":"look","rule":"3:77"},{"arabic":"فَٱنظُرْ","transliteration":"","meaning":"Then look","rule":"2:259"}],"rules":[{"name":"Words on نظر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنظِرْنِىٓ","لِلنَّـٰظِرِينَ","ٱلْمُنتَظِرِينَ","يَنظُرُونَ","يَنظُرُ","فَٱنظُرْ","يَنظُرُوا۟","أَنظُرْ"]},{"name":"Parts of speech attested for نظر","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 32 glossed words attested.","examples":["أَنظِرْنِىٓ","لِلنَّـٰظِرِينَ","ٱلْمُنتَظِرِينَ","يَنظُرُونَ","يَنظُرُ","فَٱنظُرْ"]},{"name":"Verb forms attested for نظر","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII.","examples":["أَنظِرْنِىٓ","لِلنَّـٰظِرِينَ","ٱلْمُنتَظِرِينَ","يَنظُرُونَ","يَنظُرُ","فَٱنظُرْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نظر?","options":["ٱللَّهُ","وَٱلْإِشْرَاقِ","أَنظِرْنِىٓ","يُشْرِكْ"],"correct":2,"explanation":"أَنظِرْنِىٓ — glossed \"Give me respite\" at 7:14 — carries the root نظر. The others come from different roots."},{"type":"multiple_choice","question":"What does لِلنَّـٰظِرِينَ mean?","options":["We cleaved","for his sin","and the polytheist women","for the observers"],"correct":3,"explanation":"\"for the observers\", from the word-by-word gloss at 7:108."},{"type":"fill_blank","question":"Type the root of ٱلْمُنتَظِرِينَ in Arabic (three letters).","correct":"نظر","explanation":"نظر. Diacritics are ignored when checking, so ن ظ ر is enough."}]', '["root-jmE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sAl', 'The root سال (س ا ل)', 'grammar', 3, '{"explanation":"The root سال occurs 129 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 42 distinct glossed words, tagged in the corpus as V, N, in verb form VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَسْـَٔلُونَكَ","transliteration":"","meaning":"They ask you","rule":"2:215"},{"arabic":"سَأَلْتُكَ","transliteration":"","meaning":"I ask you","rule":"18:76"},{"arabic":"وَسْـَٔلُوا۟","transliteration":"","meaning":"And ask","rule":"4:32"},{"arabic":"فَلَنَسْـَٔلَنَّ","transliteration":"","meaning":"Then surely We will question","rule":"7:6"},{"arabic":"نَسْـَٔلُكَ","transliteration":"","meaning":"We ask you","rule":"20:132"},{"arabic":"سَأَلْتُكُم","transliteration":"","meaning":"I have asked you","rule":"10:72"}],"rules":[{"name":"Words on سال","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَسْـَٔلُونَكَ","سَأَلْتُكَ","وَسْـَٔلُوا۟","فَلَنَسْـَٔلَنَّ","نَسْـَٔلُكَ","سَأَلْتُكُم","تَسْـَٔلْنِ","وَٱلسَّآئِلِينَ"]},{"name":"Parts of speech attested for سال","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 42 glossed words attested.","examples":["يَسْـَٔلُونَكَ","سَأَلْتُكَ","وَسْـَٔلُوا۟","فَلَنَسْـَٔلَنَّ","نَسْـَٔلُكَ","سَأَلْتُكُم"]},{"name":"Verb forms attested for سال","description":"Where this root is tagged as a verb, the corpus attests derived Form VI.","examples":["يَسْـَٔلُونَكَ","سَأَلْتُكَ","وَسْـَٔلُوا۟","فَلَنَسْـَٔلَنَّ","نَسْـَٔلُكَ","سَأَلْتُكُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سال?","options":["أَبُوهُمْ","يَسْـَٔلُونَكَ","أَهْلِهِۦ","وَٱلشَّيَـٰطِينَ"],"correct":1,"explanation":"يَسْـَٔلُونَكَ — glossed \"They ask you\" at 2:215 — carries the root سال. The others come from different roots."},{"type":"multiple_choice","question":"What does سَأَلْتُكَ mean?","options":["I ask you","my brother","about their brothers","we were humiliated"],"correct":0,"explanation":"\"I ask you\", from the word-by-word gloss at 18:76."},{"type":"fill_blank","question":"Type the root of وَسْـَٔلُوا۟ in Arabic (three letters).","correct":"سال","explanation":"سال. Diacritics are ignored when checking, so س ا ل is enough."}]', '["root-nZr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-EZm', 'The root عظم (ع ظ م)', 'grammar', 3, '{"explanation":"The root عظم occurs 128 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as ADJ, N, V, in verb forms II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَظِيمٍ","transliteration":"","meaning":"great","rule":"3:174"},{"arabic":"ٱلْعَظِيمَ","transliteration":"","meaning":"Great","rule":"15:87"},{"arabic":"أَعْظَمُ","transliteration":"","meaning":"(are) greater","rule":"9:20"},{"arabic":"ٱلْعِظَامِ","transliteration":"","meaning":"the bones","rule":"2:259"},{"arabic":"ٱلْعَظِيمُ","transliteration":"","meaning":"the Most Great","rule":"2:255"},{"arabic":"عَظِيمٌ","transliteration":"","meaning":"great","rule":"3:172"}],"rules":[{"name":"Words on عظم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَظِيمٍ","ٱلْعَظِيمَ","أَعْظَمُ","ٱلْعِظَامِ","ٱلْعَظِيمُ","عَظِيمٌ","عَظِيمًۭا","عِظَـٰمًۭا"]},{"name":"Parts of speech attested for عظم","description":"The morphology corpus tags words on this root as ADJ, N, V — 3 distinct parts of speech across the 14 glossed words attested.","examples":["عَظِيمٍ","ٱلْعَظِيمَ","أَعْظَمُ","ٱلْعِظَامِ","ٱلْعَظِيمُ","عَظِيمٌ"]},{"name":"Verb forms attested for عظم","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV.","examples":["عَظِيمٍ","ٱلْعَظِيمَ","أَعْظَمُ","ٱلْعِظَامِ","ٱلْعَظِيمُ","عَظِيمٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عظم?","options":["فَـَٔامَنَت","ٱللَّهِ","تُشْرِكَ","عَظِيمٍ"],"correct":3,"explanation":"عَظِيمٍ — glossed \"great\" at 3:174 — carries the root عظم. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْعَظِيمَ mean?","options":["and the women who remember","Great","Allah willed","reminder"],"correct":1,"explanation":"\"Great\", from the word-by-word gloss at 15:87."},{"type":"fill_blank","question":"Type the root of أَعْظَمُ in Arabic (three letters).","correct":"عظم","explanation":"عظم. Diacritics are ignored when checking, so ع ظ م is enough."}]', '["root-sAl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ahl', 'The root اهل (ا ه ل)', 'grammar', 3, '{"explanation":"The root اهل occurs 127 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَهْلِهَآ","transliteration":"","meaning":"her family","rule":"4:35"},{"arabic":"وَأَهْلَهُۥٓ","transliteration":"","meaning":"and his family","rule":"7:83"},{"arabic":"بِأَهْلِكَ","transliteration":"","meaning":"with your family","rule":"11:81"},{"arabic":"أَهْلَهَا","transliteration":"","meaning":"its people","rule":"7:94"},{"arabic":"أَهْلِكَ","transliteration":"","meaning":"your household","rule":"3:121"},{"arabic":"أَهْلَ","transliteration":"","meaning":"(the) People","rule":"5:65"}],"rules":[{"name":"Words on اهل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَهْلِهَآ","وَأَهْلَهُۥٓ","بِأَهْلِكَ","أَهْلَهَا","أَهْلِكَ","أَهْلَ","وَأَهْلُهَا","أَهْلَنَا"]},{"name":"Parts of speech attested for اهل","description":"The morphology corpus tags words on this root as N — one part of speech across the 26 glossed words attested.","examples":["أَهْلِهَآ","وَأَهْلَهُۥٓ","بِأَهْلِكَ","أَهْلَهَا","أَهْلِكَ","أَهْلَ"]},{"name":"Where اهل occurs","description":"The 26 glossed words on this root are attested across 10 distinct surahs.","examples":["أَهْلِهَآ (4:35)","وَأَهْلَهُۥٓ (7:83)","بِأَهْلِكَ (11:81)","أَهْلَهَا (7:94)","أَهْلِكَ (3:121)","أَهْلَ (5:65)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اهل?","options":["أَهْلِهَآ","ءَاتَيْتُم","فَذُوقُوا۟","فَكُلُوهُ"],"correct":0,"explanation":"أَهْلِهَآ — glossed \"her family\" at 4:35 — carries the root اهل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَأَهْلَهُۥٓ mean?","options":["its type","and his family","(for) the last","(the) mother"],"correct":1,"explanation":"\"and his family\", from the word-by-word gloss at 7:83."},{"type":"fill_blank","question":"Type the root of بِأَهْلِكَ in Arabic (three letters).","correct":"اهل","explanation":"اهل. Diacritics are ignored when checking, so ا ه ل is enough."}]', '["root-EZm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xlf', 'The root خلف (خ ل ف)', 'grammar', 3, '{"explanation":"The root خلف occurs 127 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 42 distinct glossed words, tagged in the corpus as N, LOC, V, in verb forms IV, VIII, X, II, V, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَٱخْتَلَفُوا۟","transliteration":"","meaning":"then they differed","rule":"10:19"},{"arabic":"خِلَـٰفٍۢ","transliteration":"","meaning":"opposite (sides)","rule":"7:124"},{"arabic":"خَلْفَكَ","transliteration":"","meaning":"succeed you","rule":"10:92"},{"arabic":"فَأَخْلَفْتُكُمْ","transliteration":"","meaning":"but I betrayed you","rule":"14:22"},{"arabic":"ٱخْتِلَـٰفِ","transliteration":"","meaning":"(the) alternation","rule":"10:6"},{"arabic":"ٱخْتِلَـٰفًۭا","transliteration":"","meaning":"contradiction","rule":"4:82"}],"rules":[{"name":"Words on خلف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَٱخْتَلَفُوا۟","خِلَـٰفٍۢ","خَلْفَكَ","فَأَخْلَفْتُكُمْ","ٱخْتِلَـٰفِ","ٱخْتِلَـٰفًۭا","خَلَـٰٓئِفَ","وَيَسْتَخْلِفَكُمْ"]},{"name":"Parts of speech attested for خلف","description":"The morphology corpus tags words on this root as N, LOC, V — 3 distinct parts of speech across the 42 glossed words attested.","examples":["فَٱخْتَلَفُوا۟","خِلَـٰفٍۢ","خَلْفَكَ","فَأَخْلَفْتُكُمْ","ٱخْتِلَـٰفِ","ٱخْتِلَـٰفًۭا"]},{"name":"Verb forms attested for خلف","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII, X, II, V, III.","examples":["فَٱخْتَلَفُوا۟","خِلَـٰفٍۢ","خَلْفَكَ","فَأَخْلَفْتُكُمْ","ٱخْتِلَـٰفِ","ٱخْتِلَـٰفًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلف?","options":["ذَاقُوا۟","ٱللَّهِ","فَٱخْتَلَفُوا۟","ٱللَّهِ"],"correct":2,"explanation":"فَٱخْتَلَفُوا۟ — glossed \"then they differed\" at 10:19 — carries the root خلف. The others come from different roots."},{"type":"multiple_choice","question":"What does خِلَـٰفٍۢ mean?","options":["Descendents","opposite (sides)","with the knowledge of Allah","and eat"],"correct":1,"explanation":"\"opposite (sides)\", from the word-by-word gloss at 7:124."},{"type":"fill_blank","question":"Type the root of خَلْفَكَ in Arabic (three letters).","correct":"خلف","explanation":"خلف. Diacritics are ignored when checking, so خ ل ف is enough."}]', '["root-Ahl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dxl', 'The root دخل (د خ ل)', 'grammar', 3, '{"explanation":"The root دخل occurs 126 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَٱدْخُلُوٓا۟","transliteration":"","meaning":"So enter","rule":"16:29"},{"arabic":"سَيُدْخِلُهُمُ","transliteration":"","meaning":"Allah will admit them","rule":"9:99"},{"arabic":"فَسَيُدْخِلُهُمْ","transliteration":"","meaning":"then He will admit them","rule":"4:175"},{"arabic":"وَلَأُدْخِلَنَّهُمْ","transliteration":"","meaning":"and surely I will admit them","rule":"3:195"},{"arabic":"وَنُدْخِلْكُم","transliteration":"","meaning":"and We will admit you","rule":"4:31"},{"arabic":"يَدْخُلَ","transliteration":"","meaning":"will enter","rule":"2:111"}],"rules":[{"name":"Words on دخل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَٱدْخُلُوٓا۟","سَيُدْخِلُهُمُ","فَسَيُدْخِلُهُمْ","وَلَأُدْخِلَنَّهُمْ","وَنُدْخِلْكُم","يَدْخُلَ","وَنُدْخِلُهُمْ","دَخَلْتُم"]},{"name":"Parts of speech attested for دخل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 37 glossed words attested.","examples":["فَٱدْخُلُوٓا۟","سَيُدْخِلُهُمُ","فَسَيُدْخِلُهُمْ","وَلَأُدْخِلَنَّهُمْ","وَنُدْخِلْكُم","يَدْخُلَ"]},{"name":"Verb forms attested for دخل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII.","examples":["فَٱدْخُلُوٓا۟","سَيُدْخِلُهُمُ","فَسَيُدْخِلُهُمْ","وَلَأُدْخِلَنَّهُمْ","وَنُدْخِلْكُم","يَدْخُلَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دخل?","options":["فَٱدْخُلُوٓا۟","أُمَّةٌۭ","أَشَدَّ","يُؤْذَنَ"],"correct":0,"explanation":"فَٱدْخُلُوٓا۟ — glossed \"So enter\" at 16:29 — carries the root دخل. The others come from different roots."},{"type":"multiple_choice","question":"What does سَيُدْخِلُهُمُ mean?","options":["(are) polytheists","and Stronger","your brother","Allah will admit them"],"correct":3,"explanation":"\"Allah will admit them\", from the word-by-word gloss at 9:99."},{"type":"fill_blank","question":"Type the root of فَسَيُدْخِلُهُمْ in Arabic (three letters).","correct":"دخل","explanation":"دخل. Diacritics are ignored when checking, so د خ ل is enough."}]', '["root-xlf"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xwf', 'The root خوف (خ و ف)', 'grammar', 3, '{"explanation":"The root خوف occurs 124 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as N, V, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَخَفْ","transliteration":"","meaning":"fear","rule":"11:70"},{"arabic":"خَافَتْ","transliteration":"","meaning":"fears","rule":"4:128"},{"arabic":"يَخَافُونَ","transliteration":"","meaning":"feared (Allah)","rule":"5:23"},{"arabic":"أَخَافُ","transliteration":"","meaning":"fear","rule":"5:28"},{"arabic":"ٱلْخَوْفِ","transliteration":"","meaning":"[the] fear","rule":"2:155"},{"arabic":"خِيفَةًۭ","transliteration":"","meaning":"[a fear]","rule":"11:70"}],"rules":[{"name":"Words on خوف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَخَفْ","خَافَتْ","يَخَافُونَ","أَخَافُ","ٱلْخَوْفِ","خِيفَةًۭ","خَوْفًۭا","خَوْفٌ"]},{"name":"Parts of speech attested for خوف","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 27 glossed words attested.","examples":["تَخَفْ","خَافَتْ","يَخَافُونَ","أَخَافُ","ٱلْخَوْفِ","خِيفَةًۭ"]},{"name":"Verb forms attested for خوف","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["تَخَفْ","خَافَتْ","يَخَافُونَ","أَخَافُ","ٱلْخَوْفِ","خِيفَةًۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خوف?","options":["ٱللَّهِ","تَخَفْ","ٱلْمُسْتَـْٔخِرِينَ","يَأْتِ"],"correct":1,"explanation":"تَخَفْ — glossed \"fear\" at 11:70 — carries the root خوف. The others come from different roots."},{"type":"multiple_choice","question":"What does خَافَتْ mean?","options":["you take","We (had) given them","fears","man"],"correct":2,"explanation":"\"fears\", from the word-by-word gloss at 4:128."},{"type":"fill_blank","question":"Type the root of يَخَافُونَ in Arabic (three letters).","correct":"خوف","explanation":"خوف. Diacritics are ignored when checking, so خ و ف is enough."}]', '["root-dxl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-b$r', 'The root بشر (ب ش ر)', 'grammar', 3, '{"explanation":"The root بشر occurs 123 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, III, X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَسْتَبْشِرُونَ","transliteration":"","meaning":"rejoice","rule":"9:124"},{"arabic":"بَشَرٌۭ","transliteration":"","meaning":"any man","rule":"3:47"},{"arabic":"بُشْرَىٰ","transliteration":"","meaning":"(as) good news","rule":"3:126"},{"arabic":"وَبُشْرَىٰ","transliteration":"","meaning":"and glad tiding(s)","rule":"2:97"},{"arabic":"بُشْرًۢا","transliteration":"","meaning":"(as) glad tidings","rule":"7:57"},{"arabic":"بَشَرًا","transliteration":"","meaning":"a man","rule":"12:31"}],"rules":[{"name":"Words on بشر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَسْتَبْشِرُونَ","بَشَرٌۭ","بُشْرَىٰ","وَبُشْرَىٰ","بُشْرًۢا","بَشَرًا","نُبَشِّرُكَ","بَشِيرٌۭ"]},{"name":"Parts of speech attested for بشر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 37 glossed words attested.","examples":["يَسْتَبْشِرُونَ","بَشَرٌۭ","بُشْرَىٰ","وَبُشْرَىٰ","بُشْرًۢا","بَشَرًا"]},{"name":"Verb forms attested for بشر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, III, X, IV.","examples":["يَسْتَبْشِرُونَ","بَشَرٌۭ","بُشْرَىٰ","وَبُشْرَىٰ","بُشْرًۢا","بَشَرًا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بشر?","options":["سَـَٔاتِيكُم","وَٱلْـَٔاخِرَةُ","يَسْتَبْشِرُونَ","ٱلْأَمِينُ"],"correct":2,"explanation":"يَسْتَبْشِرُونَ — glossed \"rejoice\" at 9:124 — carries the root بشر. The others come from different roots."},{"type":"multiple_choice","question":"What does بَشَرٌۭ mean?","options":["who remember","Then they both ate","any man","his maturity"],"correct":2,"explanation":"\"any man\", from the word-by-word gloss at 3:47."},{"type":"fill_blank","question":"Type the root of بُشْرَىٰ in Arabic (three letters).","correct":"بشر","explanation":"بشر. Diacritics are ignored when checking, so ب ش ر is enough."}]', '["root-xwf"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rzq', 'The root رزق (ر ز ق)', 'grammar', 3, '{"explanation":"The root رزق occurs 123 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَرَزَقْنَـٰهُم","transliteration":"","meaning":"and We provided them","rule":"10:93"},{"arabic":"رُزِقُوا۟","transliteration":"","meaning":"they are provided","rule":"2:25"},{"arabic":"يَرْزُقُ","transliteration":"","meaning":"provides","rule":"2:212"},{"arabic":"رِزْقًا","transliteration":"","meaning":"a good provision","rule":"11:88"},{"arabic":"يُرْزَقُونَ","transliteration":"","meaning":"they are given provision","rule":"3:169"},{"arabic":"رَزَقْنَـٰكُم","transliteration":"","meaning":"We (have) provided you","rule":"2:254"}],"rules":[{"name":"Words on رزق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَرَزَقْنَـٰهُم","رُزِقُوا۟","يَرْزُقُ","رِزْقًا","يُرْزَقُونَ","رَزَقْنَـٰكُم","رَزَقْنَـٰهُمْ","بِرِزْقٍۢ"]},{"name":"Parts of speech attested for رزق","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 39 glossed words attested.","examples":["وَرَزَقْنَـٰهُم","رُزِقُوا۟","يَرْزُقُ","رِزْقًا","يُرْزَقُونَ","رَزَقْنَـٰكُم"]},{"name":"Where رزق occurs","description":"The 39 glossed words on this root are attested across 17 distinct surahs.","examples":["وَرَزَقْنَـٰهُم (10:93)","رُزِقُوا۟ (2:25)","يَرْزُقُ (2:212)","رِزْقًا (11:88)","يُرْزَقُونَ (3:169)","رَزَقْنَـٰكُم (2:254)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رزق?","options":["شَآقُّوا۟","وَرَزَقْنَـٰهُم","أَحَدٌ","أَحَدٍۢ"],"correct":1,"explanation":"وَرَزَقْنَـٰهُم — glossed \"and We provided them\" at 10:93 — carries the root رزق. The others come from different roots."},{"type":"multiple_choice","question":"What does رُزِقُوا۟ mean?","options":["a reminder","they are provided","And other","come (the) time"],"correct":1,"explanation":"\"they are provided\", from the word-by-word gloss at 2:25."},{"type":"fill_blank","question":"Type the root of يَرْزُقُ in Arabic (three letters).","correct":"رزق","explanation":"رزق. Diacritics are ignored when checking, so ر ز ق is enough."}]', '["root-b$r"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ydy', 'The root يدي (ي د ي)', 'grammar', 3, '{"explanation":"The root يدي occurs 120 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَدَىْ","transliteration":"","meaning":"before","rule":"7:57"},{"arabic":"وَأَيْدِيكُم","transliteration":"","meaning":"and your hands","rule":"5:6"},{"arabic":"يَدَىَّ","transliteration":"","meaning":"before me","rule":"3:50"},{"arabic":"يَدَيْهِ","transliteration":"","meaning":"before it","rule":"2:97"},{"arabic":"بِيَدِكَ","transliteration":"","meaning":"In Your hand","rule":"3:26"},{"arabic":"يَدَهُۥ","transliteration":"","meaning":"his hand","rule":"7:108"}],"rules":[{"name":"Words on يدي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَدَىْ","وَأَيْدِيكُم","يَدَىَّ","يَدَيْهِ","بِيَدِكَ","يَدَهُۥ","بِيَدِ","أَيْدِيَهُمَا"]},{"name":"Parts of speech attested for يدي","description":"The morphology corpus tags words on this root as N — one part of speech across the 28 glossed words attested.","examples":["يَدَىْ","وَأَيْدِيكُم","يَدَىَّ","يَدَيْهِ","بِيَدِكَ","يَدَهُۥ"]},{"name":"Where يدي occurs","description":"The 28 glossed words on this root are attested across 9 distinct surahs.","examples":["يَدَىْ (7:57)","وَأَيْدِيكُم (5:6)","يَدَىَّ (3:50)","يَدَيْهِ (2:97)","بِيَدِكَ (3:26)","يَدَهُۥ (7:108)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root يدي?","options":["ءَآلذَّكَرَيْنِ","يَدَىْ","أَخَذَتْهُ","أَذِنَ"],"correct":1,"explanation":"يَدَىْ — glossed \"before\" at 7:57 — carries the root يدي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَأَيْدِيكُم mean?","options":["a state","and your hands","And preferred","And remember"],"correct":1,"explanation":"\"and your hands\", from the word-by-word gloss at 5:6."},{"type":"fill_blank","question":"Type the root of يَدَىَّ in Arabic (three letters).","correct":"يدي","explanation":"يدي. Diacritics are ignored when checking, so ي د ي is enough."}]', '["root-rzq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Amm', 'The root امم (ا م م)', 'grammar', 3, '{"explanation":"The root امم occurs 119 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, ADJ, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أُمَمٍۢ","transliteration":"","meaning":"nations","rule":"6:42"},{"arabic":"أُمُّ","transliteration":"","meaning":"the foundation","rule":"3:7"},{"arabic":"أُمَّهَـٰتُكُمْ","transliteration":"","meaning":"(are) your mothers","rule":"4:23"},{"arabic":"أَئِمَّةَ","transliteration":"","meaning":"the leaders","rule":"9:12"},{"arabic":"أُمَّةًۭ","transliteration":"","meaning":"a community","rule":"2:128"},{"arabic":"أُمَمٌۭ","transliteration":"","meaning":"nations","rule":"13:30"}],"rules":[{"name":"Words on امم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أُمَمٍۢ","أُمُّ","أُمَّهَـٰتُكُمْ","أَئِمَّةَ","أُمَّةًۭ","أُمَمٌۭ","أُمِّيُّونَ","وَأُمَمٌۭ"]},{"name":"Parts of speech attested for امم","description":"The morphology corpus tags words on this root as N, ADJ, T — 3 distinct parts of speech across the 30 glossed words attested.","examples":["أُمَمٍۢ","أُمُّ","أُمَّهَـٰتُكُمْ","أَئِمَّةَ","أُمَّةًۭ","أُمَمٌۭ"]},{"name":"Where امم occurs","description":"The 30 glossed words on this root are attested across 12 distinct surahs.","examples":["أُمَمٍۢ (6:42)","أُمُّ (3:7)","أُمَّهَـٰتُكُمْ (4:23)","أَئِمَّةَ (9:12)","أُمَّةًۭ (2:128)","أُمَمٌۭ (13:30)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root امم?","options":["يَشَآءَ","وَأَبِيهِ","أُمَمٍۢ","لَـَٔايَـٰتٍۢ"],"correct":2,"explanation":"أُمَمٍۢ — glossed \"nations\" at 6:42 — carries the root امم. The others come from different roots."},{"type":"multiple_choice","question":"What does أُمُّ mean?","options":["testimony","our families","the foundation","Do then feel secure"],"correct":2,"explanation":"\"the foundation\", from the word-by-word gloss at 3:7."},{"type":"fill_blank","question":"Type the root of أُمَّهَـٰتُكُمْ in Arabic (three letters).","correct":"امم","explanation":"امم. Diacritics are ignored when checking, so ا م م is enough."}]', '["root-ydy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ezz', 'The root عزز (ع ز ز)', 'grammar', 3, '{"explanation":"The root عزز occurs 119 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعَزِيزِ","transliteration":"","meaning":"the All-Mighty","rule":"3:126"},{"arabic":"بِعِزَّةِ","transliteration":"","meaning":"By the might","rule":"26:44"},{"arabic":"ٱلْعِزَّةَ","transliteration":"","meaning":"the honor","rule":"4:139"},{"arabic":"عِزًّۭا","transliteration":"","meaning":"an honor","rule":"19:81"},{"arabic":"وَتُعِزُّ","transliteration":"","meaning":"and You honor","rule":"3:26"},{"arabic":"أَعَزُّ","transliteration":"","meaning":"mightier","rule":"11:92"}],"rules":[{"name":"Words on عزز","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعَزِيزِ","بِعِزَّةِ","ٱلْعِزَّةَ","عِزًّۭا","وَتُعِزُّ","أَعَزُّ","أَعِزَّةَ","بِعَزِيزٍۢ"]},{"name":"Parts of speech attested for عزز","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 15 glossed words attested.","examples":["ٱلْعَزِيزِ","بِعِزَّةِ","ٱلْعِزَّةَ","عِزًّۭا","وَتُعِزُّ","أَعَزُّ"]},{"name":"Verb forms attested for عزز","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["ٱلْعَزِيزِ","بِعِزَّةِ","ٱلْعِزَّةَ","عِزًّۭا","وَتُعِزُّ","أَعَزُّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عزز?","options":["ٱلْعَزِيزِ","ذُرِّيَّةَ","وَأَشْعَارِهَآ","وَذِلَّةٌۭ"],"correct":0,"explanation":"ٱلْعَزِيزِ — glossed \"the All-Mighty\" at 3:126 — carries the root عزز. The others come from different roots."},{"type":"multiple_choice","question":"What does بِعِزَّةِ mean?","options":["By the might","(there) come to you","(that) Allah","we take"],"correct":0,"explanation":"\"By the might\", from the word-by-word gloss at 26:44."},{"type":"fill_blank","question":"Type the root of ٱلْعِزَّةَ in Arabic (three letters).","correct":"عزز","explanation":"عزز. Diacritics are ignored when checking, so ع ز ز is enough."}]', '["root-Amm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jzy', 'The root جزي (ج ز ي)', 'grammar', 3, '{"explanation":"The root جزي occurs 118 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as V, N, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"جَزَيْتُهُمُ","transliteration":"","meaning":"have rewarded them","rule":"23:111"},{"arabic":"وَسَيَجْزِى","transliteration":"","meaning":"And will reward","rule":"3:144"},{"arabic":"ٱلْجِزْيَةَ","transliteration":"","meaning":"the jizyah","rule":"9:29"},{"arabic":"سَيُجْزَوْنَ","transliteration":"","meaning":"they will be recompensed","rule":"6:120"},{"arabic":"نَجْزِى","transliteration":"","meaning":"We reward","rule":"6:84"},{"arabic":"وَلَنَجْزِيَنَّهُمْ","transliteration":"","meaning":"and We will pay them","rule":"16:97"}],"rules":[{"name":"Words on جزي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["جَزَيْتُهُمُ","وَسَيَجْزِى","ٱلْجِزْيَةَ","سَيُجْزَوْنَ","نَجْزِى","وَلَنَجْزِيَنَّهُمْ","لِيَجْزِىَ","جَزَآؤُهُمْ"]},{"name":"Parts of speech attested for جزي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 34 glossed words attested.","examples":["جَزَيْتُهُمُ","وَسَيَجْزِى","ٱلْجِزْيَةَ","سَيُجْزَوْنَ","نَجْزِى","وَلَنَجْزِيَنَّهُمْ"]},{"name":"Verb forms attested for جزي","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["جَزَيْتُهُمُ","وَسَيَجْزِى","ٱلْجِزْيَةَ","سَيُجْزَوْنَ","نَجْزِى","وَلَنَجْزِيَنَّهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جزي?","options":["جَزَيْتُهُمُ","وَيَشْرَبُ","بِتَأْوِيلِهِۦٓ","ٱلشَّيَـٰطِينِ"],"correct":0,"explanation":"جَزَيْتُهُمُ — glossed \"have rewarded them\" at 23:111 — carries the root جزي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَسَيَجْزِى mean?","options":["And will reward","other","any god","testify"],"correct":0,"explanation":"\"And will reward\", from the word-by-word gloss at 3:144."},{"type":"fill_blank","question":"Type the root of ٱلْجِزْيَةَ in Arabic (three letters).","correct":"جزي","explanation":"جزي. Diacritics are ignored when checking, so ج ز ي is enough."}]', '["root-Ezz"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Abw', 'The root ابو (ا ب و)', 'grammar', 3, '{"explanation":"The root ابو occurs 117 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَبَوَيْكَ","transliteration":"","meaning":"your two forefathers","rule":"12:6"},{"arabic":"أَبَاهُمْ","transliteration":"","meaning":"(to) their father","rule":"12:16"},{"arabic":"أَبُوهُمْ","transliteration":"","meaning":"their father said","rule":"12:94"},{"arabic":"أَبَانَا","transliteration":"","meaning":"our father","rule":"12:8"},{"arabic":"لِـَٔابَآئِهِمْ","transliteration":"","meaning":"their forefathers","rule":"18:5"},{"arabic":"أَبِىٓ","transliteration":"","meaning":"my father","rule":"12:80"}],"rules":[{"name":"Words on ابو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَبَوَيْكَ","أَبَاهُمْ","أَبُوهُمْ","أَبَانَا","لِـَٔابَآئِهِمْ","أَبِىٓ","وَلِأَبَوَيْهِ","ءَابَآءَكُمْ"]},{"name":"Parts of speech attested for ابو","description":"The morphology corpus tags words on this root as N — one part of speech across the 35 glossed words attested.","examples":["أَبَوَيْكَ","أَبَاهُمْ","أَبُوهُمْ","أَبَانَا","لِـَٔابَآئِهِمْ","أَبِىٓ"]},{"name":"Where ابو occurs","description":"The 35 glossed words on this root are attested across 7 distinct surahs.","examples":["أَبَوَيْكَ (12:6)","أَبَاهُمْ (12:16)","أَبُوهُمْ (12:94)","أَبَانَا (12:8)","لِـَٔابَآئِهِمْ (18:5)","أَبِىٓ (12:80)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ابو?","options":["شَأْنٍۢ","بِمُؤْمِنِينَ","فَـَٔاوَىٰكُمْ","أَبَوَيْكَ"],"correct":3,"explanation":"أَبَوَيْكَ — glossed \"your two forefathers\" at 12:6 — carries the root ابو. The others come from different roots."},{"type":"multiple_choice","question":"What does أَبَاهُمْ mean?","options":["(to) their father","(the covenant with) Allah","for the ear","And testified"],"correct":0,"explanation":"\"(to) their father\", from the word-by-word gloss at 12:16."},{"type":"fill_blank","question":"Type the root of أَبُوهُمْ in Arabic (three letters).","correct":"ابو","explanation":"ابو. Diacritics are ignored when checking, so ا ب و is enough."}]', '["root-jzy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nhr', 'The root نهر (ن ه ر)', 'grammar', 3, '{"explanation":"The root نهر occurs 113 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, V, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِٱلنَّهَارِ","transliteration":"","meaning":"by the day","rule":"6:60"},{"arabic":"ٱلنَّهَارِ","transliteration":"","meaning":"the day","rule":"3:27"},{"arabic":"وَأَنْهَـٰرًۭا","transliteration":"","meaning":"and rivers","rule":"13:3"},{"arabic":"وَٱلنَّهَارَ","transliteration":"","meaning":"and the day","rule":"10:67"},{"arabic":"ٱلنَّهَارَ","transliteration":"","meaning":"the day","rule":"3:27"},{"arabic":"نَهَرًۭا","transliteration":"","meaning":"a river","rule":"18:33"}],"rules":[{"name":"Words on نهر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِٱلنَّهَارِ","ٱلنَّهَارِ","وَأَنْهَـٰرًۭا","وَٱلنَّهَارَ","ٱلنَّهَارَ","نَهَرًۭا","بِنَهَرٍۢ","نَهَارًۭا"]},{"name":"Parts of speech attested for نهر","description":"The morphology corpus tags words on this root as N, V, T — 3 distinct parts of speech across the 12 glossed words attested.","examples":["بِٱلنَّهَارِ","ٱلنَّهَارِ","وَأَنْهَـٰرًۭا","وَٱلنَّهَارَ","ٱلنَّهَارَ","نَهَرًۭا"]},{"name":"Where نهر occurs","description":"The 12 glossed words on this root are attested across 7 distinct surahs.","examples":["بِٱلنَّهَارِ (6:60)","ٱلنَّهَارِ (3:27)","وَأَنْهَـٰرًۭا (13:3)","وَٱلنَّهَارَ (10:67)","ٱلنَّهَارَ (3:27)","نَهَرًۭا (18:33)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نهر?","options":["ٱلْمَشْرِقُ","بِٱلنَّهَارِ","لِذُنُوبِهِمْ","أُوتِىَ"],"correct":1,"explanation":"بِٱلنَّهَارِ — glossed \"by the day\" at 6:60 — carries the root نهر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلنَّهَارِ mean?","options":["severe","my dissension","the day","and let them take"],"correct":2,"explanation":"\"the day\", from the word-by-word gloss at 3:27."},{"type":"fill_blank","question":"Type the root of وَأَنْهَـٰرًۭا in Arabic (three letters).","correct":"نهر","explanation":"نهر. Diacritics are ignored when checking, so ن ه ر is enough."}]', '["root-Abw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nfq', 'The root نفق (ن ف ق)', 'grammar', 3, '{"explanation":"The root نفق occurs 111 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَنِفَاقًۭا","transliteration":"","meaning":"and hypocrisy","rule":"9:97"},{"arabic":"وَأَنفِقُوا۟","transliteration":"","meaning":"And spend","rule":"2:195"},{"arabic":"ٱلْمُنَـٰفِقُونَ","transliteration":"","meaning":"the hypocrites","rule":"8:49"},{"arabic":"وَأَنفَقُوا۟","transliteration":"","meaning":"and spent","rule":"4:39"},{"arabic":"مُنَـٰفِقُونَ","transliteration":"","meaning":"(are) hypocrites","rule":"9:101"},{"arabic":"تُنفِقُونَ","transliteration":"","meaning":"you spend","rule":"2:267"}],"rules":[{"name":"Words on نفق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَنِفَاقًۭا","وَأَنفِقُوا۟","ٱلْمُنَـٰفِقُونَ","وَأَنفَقُوا۟","مُنَـٰفِقُونَ","تُنفِقُونَ","أَنفَقُوا۟","نَّفَقَةٍ"]},{"name":"Parts of speech attested for نفق","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 26 glossed words attested.","examples":["وَنِفَاقًۭا","وَأَنفِقُوا۟","ٱلْمُنَـٰفِقُونَ","وَأَنفَقُوا۟","مُنَـٰفِقُونَ","تُنفِقُونَ"]},{"name":"Verb forms attested for نفق","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, III.","examples":["وَنِفَاقًۭا","وَأَنفِقُوا۟","ٱلْمُنَـٰفِقُونَ","وَأَنفَقُوا۟","مُنَـٰفِقُونَ","تُنفِقُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نفق?","options":["بِأَخِيكَ","يَأْخُذُ","وَنِفَاقًۭا","يَذَّكَّرُونَ"],"correct":2,"explanation":"وَنِفَاقًۭا — glossed \"and hypocrisy\" at 9:97 — carries the root نفق. The others come from different roots."},{"type":"multiple_choice","question":"What does وَأَنفِقُوا۟ mean?","options":["they associated partners","of Allah","And spend","And a bondwoman"],"correct":2,"explanation":"\"And spend\", from the word-by-word gloss at 2:195."},{"type":"fill_blank","question":"Type the root of ٱلْمُنَـٰفِقُونَ in Arabic (three letters).","correct":"نفق","explanation":"نفق. Diacritics are ignored when checking, so ن ف ق is enough."}]', '["root-nhr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Akl', 'The root اكل (ا ك ل)', 'grammar', 3, '{"explanation":"The root اكل occurs 109 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 36 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَكَلَهُ","transliteration":"","meaning":"eats him","rule":"12:14"},{"arabic":"يَأْكُلُهُنَّ","transliteration":"","meaning":"eating them","rule":"12:43"},{"arabic":"وَكُلَا","transliteration":"","meaning":"and [you both] eat","rule":"2:35"},{"arabic":"أُكُلُهَا","transliteration":"","meaning":"Its food","rule":"13:35"},{"arabic":"لِتَأْكُلُوا۟","transliteration":"","meaning":"so that you may eat","rule":"2:188"},{"arabic":"فَتَأْكُلُ","transliteration":"","meaning":"and will eat","rule":"12:41"}],"rules":[{"name":"Words on اكل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَكَلَهُ","يَأْكُلُهُنَّ","وَكُلَا","أُكُلُهَا","لِتَأْكُلُوا۟","فَتَأْكُلُ","أُكُلُهُۥ","وَأَكْلِهِمُ"]},{"name":"Parts of speech attested for اكل","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 36 glossed words attested.","examples":["أَكَلَهُ","يَأْكُلُهُنَّ","وَكُلَا","أُكُلُهَا","لِتَأْكُلُوا۟","فَتَأْكُلُ"]},{"name":"Where اكل occurs","description":"The 36 glossed words on this root are attested across 11 distinct surahs.","examples":["أَكَلَهُ (12:14)","يَأْكُلُهُنَّ (12:43)","وَكُلَا (2:35)","أُكُلُهَا (13:35)","لِتَأْكُلُوا۟ (2:188)","فَتَأْكُلُ (12:41)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اكل?","options":["ذِكْرًا","أَكَلَهُ","أَمَامَهُۥ","يَشْتَرِى"],"correct":1,"explanation":"أَكَلَهُ — glossed \"eats him\" at 12:14 — carries the root اكل. The others come from different roots."},{"type":"multiple_choice","question":"What does يَأْكُلُهُنَّ mean?","options":["and in the Hereafter","had willed","gave them","eating them"],"correct":3,"explanation":"\"eating them\", from the word-by-word gloss at 12:43."},{"type":"fill_blank","question":"Type the root of وَكُلَا in Arabic (three letters).","correct":"اكل","explanation":"اكل. Diacritics are ignored when checking, so ا ك ل is enough."}]', '["root-nfq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hsb', 'The root حسب (ح س ب)', 'grammar', 3, '{"explanation":"The root حسب occurs 109 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms III, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَحْسَبَنَّ","transliteration":"","meaning":"think","rule":"3:169"},{"arabic":"حَسْبُهُمْ","transliteration":"","meaning":"sufficient for them","rule":"9:68"},{"arabic":"حَسِبْتُمْ","transliteration":"","meaning":"(do) you think","rule":"2:214"},{"arabic":"حَسِيبًۭا","transliteration":"","meaning":"(as) a Reckoner","rule":"4:6"},{"arabic":"حَسْبُكَ","transliteration":"","meaning":"Sufficient for you","rule":"8:64"},{"arabic":"حِسَابِهِم","transliteration":"","meaning":"their account","rule":"6:52"}],"rules":[{"name":"Words on حسب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَحْسَبَنَّ","حَسْبُهُمْ","حَسِبْتُمْ","حَسِيبًۭا","حَسْبُكَ","حِسَابِهِم","حَسْبَكَ","يُحَاسِبْكُم"]},{"name":"Parts of speech attested for حسب","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 37 glossed words attested.","examples":["تَحْسَبَنَّ","حَسْبُهُمْ","حَسِبْتُمْ","حَسِيبًۭا","حَسْبُكَ","حِسَابِهِم"]},{"name":"Verb forms attested for حسب","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VIII.","examples":["تَحْسَبَنَّ","حَسْبُهُمْ","حَسِبْتُمْ","حَسِيبًۭا","حَسْبُكَ","حِسَابِهِم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حسب?","options":["تَحْسَبَنَّ","ٱللَّهِ","وَلَأَجْرُ","ٱللَّهُ"],"correct":0,"explanation":"تَحْسَبَنَّ — glossed \"think\" at 3:169 — carries the root حسب. The others come from different roots."},{"type":"multiple_choice","question":"What does حَسْبُهُمْ mean?","options":["sufficient for them","the former (people)","consume","And we have come to you"],"correct":0,"explanation":"\"sufficient for them\", from the word-by-word gloss at 9:68."},{"type":"fill_blank","question":"Type the root of حَسِبْتُمْ in Arabic (three letters).","correct":"حسب","explanation":"حسب. Diacritics are ignored when checking, so ح س ب is enough."}]', '["root-Akl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ajr', 'The root اجر (ا ج ر)', 'grammar', 3, '{"explanation":"The root اجر occurs 108 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَجْرُ","transliteration":"","meaning":"reward","rule":"3:136"},{"arabic":"أُجُورَهُمْ","transliteration":"","meaning":"their reward","rule":"3:57"},{"arabic":"أُجُورَهُنَّ","transliteration":"","meaning":"their bridal due","rule":"4:24"},{"arabic":"أَجْرُهُۥ","transliteration":"","meaning":"(is) his reward","rule":"2:112"},{"arabic":"أُجُورَكُمْ","transliteration":"","meaning":"your reward","rule":"3:185"},{"arabic":"أَجْرِىَ","transliteration":"","meaning":"(is) my reward","rule":"10:72"}],"rules":[{"name":"Words on اجر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَجْرُ","أُجُورَهُمْ","أُجُورَهُنَّ","أَجْرُهُۥ","أُجُورَكُمْ","أَجْرِىَ","أَجْرَ","أَجْرُهُمْ"]},{"name":"Parts of speech attested for اجر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["أَجْرُ","أُجُورَهُمْ","أُجُورَهُنَّ","أَجْرُهُۥ","أُجُورَكُمْ","أَجْرِىَ"]},{"name":"Verb forms attested for اجر","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["أَجْرُ","أُجُورَهُمْ","أُجُورَهُنَّ","أَجْرُهُۥ","أُجُورَكُمْ","أَجْرِىَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اجر?","options":["بِشُرَكَآئِهِمْ","ٱلْإِرْبَةِ","شَىْءٍ","أَجْرُ"],"correct":3,"explanation":"أَجْرُ — glossed \"reward\" at 3:136 — carries the root اجر. The others come from different roots."},{"type":"multiple_choice","question":"What does أُجُورَهُمْ mean?","options":["their reward","we believe","And Allah will surely make evident","for their sin"],"correct":0,"explanation":"\"their reward\", from the word-by-word gloss at 3:57."},{"type":"fill_blank","question":"Type the root of أُجُورَهُنَّ in Arabic (three letters).","correct":"اجر","explanation":"اجر. Diacritics are ignored when checking, so ا ج ر is enough."}]', '["root-Hsb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fEl', 'The root فعل (ف ع ل)', 'grammar', 3, '{"explanation":"The root فعل occurs 108 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَعَلْنَا","transliteration":"","meaning":"We dealt","rule":"14:45"},{"arabic":"فَٱفْعَلُوا۟","transliteration":"","meaning":"so do","rule":"2:68"},{"arabic":"فَعَلْتَ","transliteration":"","meaning":"you did so","rule":"10:106"},{"arabic":"يَفْعَلُونَ","transliteration":"","meaning":"(to) doing (it)","rule":"2:71"},{"arabic":"تَفْعَلُونَ","transliteration":"","meaning":"you do","rule":"16:91"},{"arabic":"وَيَفْعَلُونَ","transliteration":"","meaning":"and they do","rule":"16:50"}],"rules":[{"name":"Words on فعل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَعَلْنَا","فَٱفْعَلُوا۟","فَعَلْتَ","يَفْعَلُونَ","تَفْعَلُونَ","وَيَفْعَلُونَ","تَفْعَلُوا۟","لَفَـٰعِلُونَ"]},{"name":"Parts of speech attested for فعل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 28 glossed words attested.","examples":["فَعَلْنَا","فَٱفْعَلُوا۟","فَعَلْتَ","يَفْعَلُونَ","تَفْعَلُونَ","وَيَفْعَلُونَ"]},{"name":"Where فعل occurs","description":"The 28 glossed words on this root are attested across 13 distinct surahs.","examples":["فَعَلْنَا (14:45)","فَٱفْعَلُوا۟ (2:68)","فَعَلْتَ (10:106)","يَفْعَلُونَ (2:71)","تَفْعَلُونَ (16:91)","وَيَفْعَلُونَ (16:50)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فعل?","options":["ٱللَّهُ","فَعَلْنَا","ٱلشِّتَآءِ","وَٱنشَقَّ"],"correct":1,"explanation":"فَعَلْنَا — glossed \"We dealt\" at 14:45 — carries the root فعل. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱفْعَلُوا۟ mean?","options":["but refused","so do","grateful","an amazing thing"],"correct":1,"explanation":"\"so do\", from the word-by-word gloss at 2:68."},{"type":"fill_blank","question":"Type the root of فَعَلْتَ in Arabic (three letters).","correct":"فعل","explanation":"فعل. Diacritics are ignored when checking, so ف ع ل is enough."}]', '["root-Ajr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wjd', 'The root وجد (و ج د)', 'grammar', 3, '{"explanation":"The root وجد occurs 107 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَأَجِدُ","transliteration":"","meaning":"[I] find","rule":"12:94"},{"arabic":"لَأَجِدَنَّ","transliteration":"","meaning":"I will surely find","rule":"18:36"},{"arabic":"فَوَجَدَا","transliteration":"","meaning":"Then they found","rule":"18:65"},{"arabic":"لَوَجَدُوا۟","transliteration":"","meaning":"surely they would have found","rule":"4:64"},{"arabic":"وَلْيَجِدُوا۟","transliteration":"","meaning":"and let them find","rule":"9:123"},{"arabic":"تَجِدَ","transliteration":"","meaning":"will you find","rule":"4:52"}],"rules":[{"name":"Words on وجد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَأَجِدُ","لَأَجِدَنَّ","فَوَجَدَا","لَوَجَدُوا۟","وَلْيَجِدُوا۟","تَجِدَ","يَجِدُوا۟","وَجَدتُّم"]},{"name":"Parts of speech attested for وجد","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 27 glossed words attested.","examples":["لَأَجِدُ","لَأَجِدَنَّ","فَوَجَدَا","لَوَجَدُوا۟","وَلْيَجِدُوا۟","تَجِدَ"]},{"name":"Where وجد occurs","description":"The 27 glossed words on this root are attested across 9 distinct surahs.","examples":["لَأَجِدُ (12:94)","لَأَجِدَنَّ (18:36)","فَوَجَدَا (18:65)","لَوَجَدُوا۟ (4:64)","وَلْيَجِدُوا۟ (9:123)","تَجِدَ (4:52)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وجد?","options":["أَوَءَابَآؤُنَا","تَأْتِيَهُمُ","أَوَيْنَآ","لَأَجِدُ"],"correct":3,"explanation":"لَأَجِدُ — glossed \"[I] find\" at 12:94 — carries the root وجد. The others come from different roots."},{"type":"multiple_choice","question":"What does لَأَجِدَنَّ mean?","options":["time","I will surely find","the decision","surely (is) a Sign"],"correct":1,"explanation":"\"I will surely find\", from the word-by-word gloss at 18:36."},{"type":"fill_blank","question":"Type the root of فَوَجَدَا in Arabic (three letters).","correct":"وجد","explanation":"وجد. Diacritics are ignored when checking, so و ج د is enough."}]', '["root-fEl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Edw', 'The root عدو (ع د و)', 'grammar', 3, '{"explanation":"The root عدو occurs 106 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms VIII, V, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعَدَاوَةَ","transliteration":"","meaning":"[the] enmity","rule":"5:14"},{"arabic":"لِّتَعْتَدُوا۟","transliteration":"","meaning":"so that you transgress","rule":"2:231"},{"arabic":"وَٱلْعُدْوَٰنِ","transliteration":"","meaning":"and [the] transgression","rule":"2:85"},{"arabic":"ٱعْتَدَوْا۟","transliteration":"","meaning":"transgressed","rule":"2:65"},{"arabic":"ٱعْتَدَىٰ","transliteration":"","meaning":"transgresses","rule":"2:178"},{"arabic":"تَعْدُوا۟","transliteration":"","meaning":"transgress","rule":"4:154"}],"rules":[{"name":"Words on عدو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعَدَاوَةَ","لِّتَعْتَدُوا۟","وَٱلْعُدْوَٰنِ","ٱعْتَدَوْا۟","ٱعْتَدَىٰ","تَعْدُوا۟","تَعْتَدُوا۟","عُدْوَٰنَ"]},{"name":"Parts of speech attested for عدو","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 35 glossed words attested.","examples":["ٱلْعَدَاوَةَ","لِّتَعْتَدُوا۟","وَٱلْعُدْوَٰنِ","ٱعْتَدَوْا۟","ٱعْتَدَىٰ","تَعْدُوا۟"]},{"name":"Verb forms attested for عدو","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, V, III.","examples":["ٱلْعَدَاوَةَ","لِّتَعْتَدُوا۟","وَٱلْعُدْوَٰنِ","ٱعْتَدَوْا۟","ٱعْتَدَىٰ","تَعْدُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عدو?","options":["شُرَكَآءَ","ٱلْعَدَاوَةَ","نَشَآءُ","شَمَآئِلِهِمْ"],"correct":1,"explanation":"ٱلْعَدَاوَةَ — glossed \"[the] enmity\" at 5:14 — carries the root عدو. The others come from different roots."},{"type":"multiple_choice","question":"What does لِّتَعْتَدُوا۟ mean?","options":["one of you","so that you transgress","offspring","remember"],"correct":1,"explanation":"\"so that you transgress\", from the word-by-word gloss at 2:231."},{"type":"fill_blank","question":"Type the root of وَٱلْعُدْوَٰنِ in Arabic (three letters).","correct":"عدو","explanation":"عدو. Diacritics are ignored when checking, so ع د و is enough."}]', '["root-wjd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fDl', 'The root فضل (ف ض ل)', 'grammar', 3, '{"explanation":"The root فضل occurs 104 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْفَضْلُ","transliteration":"","meaning":"(is) the Bounty","rule":"4:70"},{"arabic":"فَضْلِ","transliteration":"","meaning":"(the) Grace","rule":"12:38"},{"arabic":"بِفَضْلِ","transliteration":"","meaning":"In the Bounty","rule":"10:58"},{"arabic":"فَضْلِهِۦ","transliteration":"","meaning":"His Grace","rule":"2:90"},{"arabic":"فَضْلُ","transliteration":"","meaning":"(for the) Grace","rule":"2:64"},{"arabic":"فَضْلٍۭ","transliteration":"","meaning":"merit","rule":"11:27"}],"rules":[{"name":"Words on فضل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْفَضْلُ","فَضْلِ","بِفَضْلِ","فَضْلِهِۦ","فَضْلُ","فَضْلٍۭ","وَفَضْلًۭا","فَضَّلَكُمْ"]},{"name":"Parts of speech attested for فضل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 25 glossed words attested.","examples":["ٱلْفَضْلُ","فَضْلِ","بِفَضْلِ","فَضْلِهِۦ","فَضْلُ","فَضْلٍۭ"]},{"name":"Verb forms attested for فضل","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["ٱلْفَضْلُ","فَضْلِ","بِفَضْلِ","فَضْلِهِۦ","فَضْلُ","فَضْلٍۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فضل?","options":["فَتَأْتُونَ","نَشَآءُ","ٱلْفَضْلُ","وَلِلْمُؤْمِنِينَ"],"correct":2,"explanation":"ٱلْفَضْلُ — glossed \"(is) the Bounty\" at 4:70 — carries the root فضل. The others come from different roots."},{"type":"multiple_choice","question":"What does فَضْلِ mean?","options":["That Allah may reward them","they are seized","and make (you) taste","(the) Grace"],"correct":3,"explanation":"\"(the) Grace\", from the word-by-word gloss at 12:38."},{"type":"fill_blank","question":"Type the root of بِفَضْلِ in Arabic (three letters).","correct":"فضل","explanation":"فضل. Diacritics are ignored when checking, so ف ض ل is enough."}]', '["root-Edw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rjE', 'The root رجع (ر ج ع)', 'grammar', 3, '{"explanation":"The root رجع occurs 104 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as V, N, in verb form VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَرَجَعْنَـٰكَ","transliteration":"","meaning":"So We returned you","rule":"20:40"},{"arabic":"يَرْجِعَ","transliteration":"","meaning":"returns","rule":"20:91"},{"arabic":"يَرْجِعُ","transliteration":"","meaning":"it (could) return","rule":"20:89"},{"arabic":"يَرْجِعُونَ","transliteration":"","meaning":"[they] will not return","rule":"2:18"},{"arabic":"ٱرْجِعُوٓا۟","transliteration":"","meaning":"Return","rule":"12:81"},{"arabic":"فَرَجَعَ","transliteration":"","meaning":"Then Musa returned","rule":"20:86"}],"rules":[{"name":"Words on رجع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَرَجَعْنَـٰكَ","يَرْجِعَ","يَرْجِعُ","يَرْجِعُونَ","ٱرْجِعُوٓا۟","فَرَجَعَ","يَتَرَاجَعَآ","رَجَعَ"]},{"name":"Parts of speech attested for رجع","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 27 glossed words attested.","examples":["فَرَجَعْنَـٰكَ","يَرْجِعَ","يَرْجِعُ","يَرْجِعُونَ","ٱرْجِعُوٓا۟","فَرَجَعَ"]},{"name":"Verb forms attested for رجع","description":"Where this root is tagged as a verb, the corpus attests derived Form VI.","examples":["فَرَجَعْنَـٰكَ","يَرْجِعَ","يَرْجِعُ","يَرْجِعُونَ","ٱرْجِعُوٓا۟","فَرَجَعَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رجع?","options":["أَجْرٌ","يَأْتِىَ","فَرَجَعْنَـٰكَ","أَشْيَآءَهُمْ"],"correct":2,"explanation":"فَرَجَعْنَـٰكَ — glossed \"So We returned you\" at 20:40 — carries the root رجع. The others come from different roots."},{"type":"multiple_choice","question":"What does يَرْجِعَ mean?","options":["one of you","his offspring","returns","whether evil"],"correct":2,"explanation":"\"returns\", from the word-by-word gloss at 20:91."},{"type":"fill_blank","question":"Type the root of يَرْجِعُ in Arabic (three letters).","correct":"رجع","explanation":"رجع. Diacritics are ignored when checking, so ر ج ع is enough."}]', '["root-fDl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Sbr', 'The root صبر (ص ب ر)', 'grammar', 3, '{"explanation":"The root صبر occurs 103 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms III, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَصْبَرَهُمْ","transliteration":"","meaning":"their endurance","rule":"2:175"},{"arabic":"صَبَّارٍۢ","transliteration":"","meaning":"patient","rule":"14:5"},{"arabic":"فَٱصْبِرْ","transliteration":"","meaning":"So be patient","rule":"11:49"},{"arabic":"فَصَبَرُوا۟","transliteration":"","meaning":"but they were patient","rule":"6:34"},{"arabic":"لِّلصَّـٰبِرِينَ","transliteration":"","meaning":"for those who are patient","rule":"16:126"},{"arabic":"تَصْبِرُ","transliteration":"","meaning":"you have patience","rule":"18:68"}],"rules":[{"name":"Words on صبر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَصْبَرَهُمْ","صَبَّارٍۢ","فَٱصْبِرْ","فَصَبَرُوا۟","لِّلصَّـٰبِرِينَ","تَصْبِرُ","وَٱلصَّـٰبِرِينَ","صَبَرُوٓا۟"]},{"name":"Parts of speech attested for صبر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 31 glossed words attested.","examples":["أَصْبَرَهُمْ","صَبَّارٍۢ","فَٱصْبِرْ","فَصَبَرُوا۟","لِّلصَّـٰبِرِينَ","تَصْبِرُ"]},{"name":"Verb forms attested for صبر","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VIII.","examples":["أَصْبَرَهُمْ","صَبَّارٍۢ","فَٱصْبِرْ","فَصَبَرُوا۟","لِّلصَّـٰبِرِينَ","تَصْبِرُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صبر?","options":["فَأَخَذْنَـٰهُ","أَصْبَرَهُمْ","أُولَىٰهُمْ","بِذِكْرِهِمْ"],"correct":1,"explanation":"أَصْبَرَهُمْ — glossed \"their endurance\" at 2:175 — carries the root صبر. The others come from different roots."},{"type":"multiple_choice","question":"What does صَبَّارٍۢ mean?","options":["Allah were to seize","patient","come (the) time","(of) winter"],"correct":1,"explanation":"\"patient\", from the word-by-word gloss at 14:5."},{"type":"fill_blank","question":"Type the root of فَٱصْبِرْ in Arabic (three letters).","correct":"صبر","explanation":"صبر. Diacritics are ignored when checking, so ص ب ر is enough."}]', '["root-rjE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$dd', 'The root شدد (ش د د)', 'grammar', 3, '{"explanation":"The root شدد occurs 102 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَدِيدٍ","transliteration":"","meaning":"severe","rule":"14:2"},{"arabic":"شَدِيدًا","transliteration":"","meaning":"severe","rule":"27:21"},{"arabic":"لَشَدِيدُ","transliteration":"","meaning":"(is) severe","rule":"13:6"},{"arabic":"لَشَدِيدٌۭ","transliteration":"","meaning":"(is) surely severe","rule":"14:7"},{"arabic":"وَٱشْدُدْ","transliteration":"","meaning":"and harden","rule":"10:88"},{"arabic":"وَأَشَدُّ","transliteration":"","meaning":"and Stronger","rule":"4:84"}],"rules":[{"name":"Words on شدد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَدِيدٍ","شَدِيدًا","لَشَدِيدُ","لَشَدِيدٌۭ","وَٱشْدُدْ","وَأَشَدُّ","أَشُدَّهُمَا","شَدِيدٍۢ"]},{"name":"Parts of speech attested for شدد","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 25 glossed words attested.","examples":["شَدِيدٍ","شَدِيدًا","لَشَدِيدُ","لَشَدِيدٌۭ","وَٱشْدُدْ","وَأَشَدُّ"]},{"name":"Verb forms attested for شدد","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["شَدِيدٍ","شَدِيدًا","لَشَدِيدُ","لَشَدِيدٌۭ","وَٱشْدُدْ","وَأَشَدُّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شدد?","options":["ءَالِهَةًۢ","ٱللَّهُ","شَدِيدٍ","يَأْتِيَهُمْ"],"correct":2,"explanation":"شَدِيدٍ — glossed \"severe\" at 14:2 — carries the root شدد. The others come from different roots."},{"type":"multiple_choice","question":"What does شَدِيدًا mean?","options":["severe","a god","(the) first","the male"],"correct":0,"explanation":"\"severe\", from the word-by-word gloss at 27:21."},{"type":"fill_blank","question":"Type the root of لَشَدِيدُ in Arabic (three letters).","correct":"شدد","explanation":"شدد. Diacritics are ignored when checking, so ش د د is enough."}]', '["root-Sbr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-A*n', 'The root اذن (ا ذ ن)', 'grammar', 3, '{"explanation":"The root اذن occurs 102 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as N, V, in verb forms II, V, X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُؤَذِّنٌ","transliteration":"","meaning":"an announcer","rule":"12:70"},{"arabic":"أَذِنتَ","transliteration":"","meaning":"you grant leave","rule":"9:43"},{"arabic":"فَٱسْتَـْٔذَنُوكَ","transliteration":"","meaning":"and they ask you permission","rule":"9:83"},{"arabic":"مُؤَذِّنٌۢ","transliteration":"","meaning":"an announcer","rule":"7:44"},{"arabic":"يَأْذَنَ","transliteration":"","meaning":"permits","rule":"12:80"},{"arabic":"ءَاذَانَ","transliteration":"","meaning":"(the) ears","rule":"4:119"}],"rules":[{"name":"Words on اذن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُؤَذِّنٌ","أَذِنتَ","فَٱسْتَـْٔذَنُوكَ","مُؤَذِّنٌۢ","يَأْذَنَ","ءَاذَانَ","ءَاذَانِهِمْ","ءَاذَنتُكُمْ"]},{"name":"Parts of speech attested for اذن","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 32 glossed words attested.","examples":["مُؤَذِّنٌ","أَذِنتَ","فَٱسْتَـْٔذَنُوكَ","مُؤَذِّنٌۢ","يَأْذَنَ","ءَاذَانَ"]},{"name":"Verb forms attested for اذن","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V, X, IV.","examples":["مُؤَذِّنٌ","أَذِنتَ","فَٱسْتَـْٔذَنُوكَ","مُؤَذِّنٌۢ","يَأْذَنَ","ءَاذَانَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اذن?","options":["وَيُؤْثِرُونَ","تَأْلَمُونَ","مُؤَذِّنٌ","أَمْرِهِمْ"],"correct":2,"explanation":"مُؤَذِّنٌ — glossed \"an announcer\" at 12:70 — carries the root اذن. The others come from different roots."},{"type":"multiple_choice","question":"What does أَذِنتَ mean?","options":["And sufficient is Allah","Allah warns you","you grant leave","one of them"],"correct":2,"explanation":"\"you grant leave\", from the word-by-word gloss at 9:43."},{"type":"fill_blank","question":"Type the root of فَٱسْتَـْٔذَنُوكَ in Arabic (three letters).","correct":"اذن","explanation":"اذن. Diacritics are ignored when checking, so ا ذ ن is enough."}]', '["root-$dd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wld', 'The root ولد (و ل د)', 'grammar', 3, '{"explanation":"The root ولد occurs 102 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْوِلْدَٰنِ","transliteration":"","meaning":"the children","rule":"4:127"},{"arabic":"مَوْلُودٌۭ","transliteration":"","meaning":"(the) father","rule":"2:233"},{"arabic":"لِلْوَٰلِدَيْنِ","transliteration":"","meaning":"for the parents","rule":"2:180"},{"arabic":"ءَأَلِدُ","transliteration":"","meaning":"Shall I bear a child","rule":"11:72"},{"arabic":"وَلِوَٰلِدَىَّ","transliteration":"","meaning":"and my parents","rule":"14:41"},{"arabic":"وَلَدًا","transliteration":"","meaning":"a son","rule":"19:92"}],"rules":[{"name":"Words on ولد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْوِلْدَٰنِ","مَوْلُودٌۭ","لِلْوَٰلِدَيْنِ","ءَأَلِدُ","وَلِوَٰلِدَىَّ","وَلَدًا","أَوْلَـٰدُهُمْ","وَأَوْلَـٰدًۭا"]},{"name":"Parts of speech attested for ولد","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 38 glossed words attested.","examples":["ٱلْوِلْدَٰنِ","مَوْلُودٌۭ","لِلْوَٰلِدَيْنِ","ءَأَلِدُ","وَلِوَٰلِدَىَّ","وَلَدًا"]},{"name":"Where ولد occurs","description":"The 38 glossed words on this root are attested across 12 distinct surahs.","examples":["ٱلْوِلْدَٰنِ (4:127)","مَوْلُودٌۭ (2:233)","لِلْوَٰلِدَيْنِ (2:180)","ءَأَلِدُ (11:72)","وَلِوَٰلِدَىَّ (14:41)","وَلَدًا (19:92)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ولد?","options":["ٱلْوِلْدَٰنِ","ٱلْإِنسِ","وَءَاتَى","ٱللَّهِ"],"correct":0,"explanation":"ٱلْوِلْدَٰنِ — glossed \"the children\" at 4:127 — carries the root ولد. The others come from different roots."},{"type":"multiple_choice","question":"What does مَوْلُودٌۭ mean?","options":["(the) father","and to the left","one of you","my affair"],"correct":0,"explanation":"\"(the) father\", from the word-by-word gloss at 2:233."},{"type":"fill_blank","question":"Type the root of لِلْوَٰلِدَيْنِ in Arabic (three letters).","correct":"ولد","explanation":"ولد. Diacritics are ignored when checking, so و ل د is enough."}]', '["root-A*n"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dyn', 'The root دين (د ي ن)', 'grammar', 3, '{"explanation":"The root دين occurs 101 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as N, V, in verb form VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"دِينِهِم","transliteration":"","meaning":"their religion","rule":"3:24"},{"arabic":"ٱلدِّينُ","transliteration":"","meaning":"the religion","rule":"2:193"},{"arabic":"بِدَيْنٍ","transliteration":"","meaning":"any debt","rule":"2:282"},{"arabic":"دِينًۭا","transliteration":"","meaning":"(as) religion","rule":"3:85"},{"arabic":"دِينِهِۦ","transliteration":"","meaning":"his religion","rule":"2:217"},{"arabic":"دِينَهُمْ","transliteration":"","meaning":"(in) their religion","rule":"4:146"}],"rules":[{"name":"Words on دين","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["دِينِهِم","ٱلدِّينُ","بِدَيْنٍ","دِينًۭا","دِينِهِۦ","دِينَهُمْ","دِينُهُمْ","دِينِ"]},{"name":"Parts of speech attested for دين","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 21 glossed words attested.","examples":["دِينِهِم","ٱلدِّينُ","بِدَيْنٍ","دِينًۭا","دِينِهِۦ","دِينَهُمْ"]},{"name":"Verb forms attested for دين","description":"Where this root is tagged as a verb, the corpus attests derived Form VI.","examples":["دِينِهِم","ٱلدِّينُ","بِدَيْنٍ","دِينًۭا","دِينِهِۦ","دِينَهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دين?","options":["لِذِكْرِىٓ","بِـَٔايَـٰتِ","ٱللَّهُ","دِينِهِم"],"correct":3,"explanation":"دِينِهِم — glossed \"their religion\" at 3:24 — carries the root دين. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلدِّينُ mean?","options":["(as) his god","the religion","(each) one of them","seized him"],"correct":1,"explanation":"\"the religion\", from the word-by-word gloss at 2:193."},{"type":"fill_blank","question":"Type the root of بِدَيْنٍ in Arabic (three letters).","correct":"دين","explanation":"دين. Diacritics are ignored when checking, so د ي ن is enough."}]', '["root-wld"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Slw', 'The root صلو (ص ل و)', 'grammar', 3, '{"explanation":"The root صلو occurs 99 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صَلَوٰتَكَ","transliteration":"","meaning":"your blessings","rule":"9:103"},{"arabic":"صَلَوَٰتٌۭ","transliteration":"","meaning":"(are) blessings","rule":"2:157"},{"arabic":"وَٱلصَّلَوٰةِ","transliteration":"","meaning":"and the prayer","rule":"2:45"},{"arabic":"يُصَلُّوا۟","transliteration":"","meaning":"prayed","rule":"4:102"},{"arabic":"وَصَلَوَٰتِ","transliteration":"","meaning":"and blessings","rule":"9:99"},{"arabic":"ٱلصَّلَوٰةَ","transliteration":"","meaning":"the prayer","rule":"2:3"}],"rules":[{"name":"Words on صلو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صَلَوٰتَكَ","صَلَوَٰتٌۭ","وَٱلصَّلَوٰةِ","يُصَلُّوا۟","وَصَلَوَٰتِ","ٱلصَّلَوٰةَ","مُصَلًّۭى","ٱلصَّلَوَٰتِ"]},{"name":"Parts of speech attested for صلو","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 19 glossed words attested.","examples":["صَلَوٰتَكَ","صَلَوَٰتٌۭ","وَٱلصَّلَوٰةِ","يُصَلُّوا۟","وَصَلَوَٰتِ","ٱلصَّلَوٰةَ"]},{"name":"Verb forms attested for صلو","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["صَلَوٰتَكَ","صَلَوَٰتٌۭ","وَٱلصَّلَوٰةِ","يُصَلُّوا۟","وَصَلَوَٰتِ","ٱلصَّلَوٰةَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صلو?","options":["فَأَنَّىٰ","بِشَرٍّۢ","وَءَاثَارًۭا","صَلَوٰتَكَ"],"correct":3,"explanation":"صَلَوٰتَكَ — glossed \"your blessings\" at 9:103 — carries the root صلو. The others come from different roots."},{"type":"multiple_choice","question":"What does صَلَوَٰتٌۭ mean?","options":["(are) blessings","(Are) the two males","splitting","anyone"],"correct":0,"explanation":"\"(are) blessings\", from the word-by-word gloss at 2:157."},{"type":"fill_blank","question":"Type the root of وَٱلصَّلَوٰةِ in Arabic (three letters).","correct":"صلو","explanation":"صلو. Diacritics are ignored when checking, so ص ل و is enough."}]', '["root-dyn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ans', 'The root انس (ا ن س)', 'grammar', 3, '{"explanation":"The root انس occurs 97 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْإِنسَـٰنَ","transliteration":"","meaning":"the man","rule":"10:12"},{"arabic":"أُنَاسٌۭ","transliteration":"","meaning":"(are) people","rule":"7:82"},{"arabic":"ٱلْإِنسَـٰنُ","transliteration":"","meaning":"the mankind","rule":"4:28"},{"arabic":"إِنسِيًّۭا","transliteration":"","meaning":"(to any) human being","rule":"19:26"},{"arabic":"ٱلْإِنسُ","transliteration":"","meaning":"the mankind","rule":"17:88"},{"arabic":"ٱلْإِنسِ","transliteration":"","meaning":"(from) the mankind","rule":"6:112"}],"rules":[{"name":"Words on انس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْإِنسَـٰنَ","أُنَاسٌۭ","ٱلْإِنسَـٰنُ","إِنسِيًّۭا","ٱلْإِنسُ","ٱلْإِنسِ","إِنسَـٰنٍ","ءَانَسْتُ"]},{"name":"Parts of speech attested for انس","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 19 glossed words attested.","examples":["ٱلْإِنسَـٰنَ","أُنَاسٌۭ","ٱلْإِنسَـٰنُ","إِنسِيًّۭا","ٱلْإِنسُ","ٱلْإِنسِ"]},{"name":"Verb forms attested for انس","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["ٱلْإِنسَـٰنَ","أُنَاسٌۭ","ٱلْإِنسَـٰنُ","إِنسِيًّۭا","ٱلْإِنسُ","ٱلْإِنسِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root انس?","options":["أَشَدُّ","وَإِلَـٰهُنَا","ٱلْإِنسَـٰنَ","وَأَصِيلًا"],"correct":2,"explanation":"ٱلْإِنسَـٰنَ — glossed \"the man\" at 10:12 — carries the root انس. The others come from different roots."},{"type":"multiple_choice","question":"What does أُنَاسٌۭ mean?","options":["(are) people","who take heed","to anyone","for evidence"],"correct":0,"explanation":"\"(are) people\", from the word-by-word gloss at 7:82."},{"type":"fill_blank","question":"Type the root of ٱلْإِنسَـٰنُ in Arabic (three letters).","correct":"انس","explanation":"انس. Diacritics are ignored when checking, so ا ن س is enough."}]', '["root-Slw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-SHb', 'The root صحب (ص ح ب)', 'grammar', 3, '{"explanation":"The root صحب occurs 97 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صَاحِبُهُۥ","transliteration":"","meaning":"his companion","rule":"18:37"},{"arabic":"يَـٰصَـٰحِبَىِ","transliteration":"","meaning":"O my two companions","rule":"12:39"},{"arabic":"وَأَصْحَـٰبِ","transliteration":"","meaning":"and (the) companions","rule":"9:70"},{"arabic":"أَصْحَـٰبَ","transliteration":"","meaning":"companions","rule":"4:47"},{"arabic":"أَصْحَـٰبٌۭ","transliteration":"","meaning":"companions","rule":"6:71"},{"arabic":"أَصْحَـٰبِ","transliteration":"","meaning":"(the) companions","rule":"2:119"}],"rules":[{"name":"Words on صحب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صَاحِبُهُۥ","يَـٰصَـٰحِبَىِ","وَأَصْحَـٰبِ","أَصْحَـٰبَ","أَصْحَـٰبٌۭ","أَصْحَـٰبِ","يُصْحَبُونَ","لِصَـٰحِبِهِۦ"]},{"name":"Parts of speech attested for صحب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["صَاحِبُهُۥ","يَـٰصَـٰحِبَىِ","وَأَصْحَـٰبِ","أَصْحَـٰبَ","أَصْحَـٰبٌۭ","أَصْحَـٰبِ"]},{"name":"Verb forms attested for صحب","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["صَاحِبُهُۥ","يَـٰصَـٰحِبَىِ","وَأَصْحَـٰبِ","أَصْحَـٰبَ","أَصْحَـٰبٌۭ","أَصْحَـٰبِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صحب?","options":["صَاحِبُهُۥ","فَأَنَّىٰ","يُؤْمِنُونَ","وَٱلْأَمْرُ"],"correct":0,"explanation":"صَاحِبُهُۥ — glossed \"his companion\" at 18:37 — carries the root صحب. The others come from different roots."},{"type":"multiple_choice","question":"What does يَـٰصَـٰحِبَىِ mean?","options":["O my two companions","And Allah makes clear","ears","you come"],"correct":0,"explanation":"\"O my two companions\", from the word-by-word gloss at 12:39."},{"type":"fill_blank","question":"Type the root of وَأَصْحَـٰبِ in Arabic (three letters).","correct":"صحب","explanation":"صحب. Diacritics are ignored when checking, so ص ح ب is enough."}]', '["root-Ans"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Axw', 'The root اخو (ا خ و)', 'grammar', 3, '{"explanation":"The root اخو occurs 96 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَخَاهُمْ","transliteration":"","meaning":"(We sent) their brother","rule":"7:65"},{"arabic":"وَإِخْوَٰنُكُمْ","transliteration":"","meaning":"and your brothers","rule":"9:24"},{"arabic":"أُخْتٌۭ","transliteration":"","meaning":"a sister","rule":"4:12"},{"arabic":"وَإِخْوَتِهِۦٓ","transliteration":"","meaning":"and his brothers","rule":"12:7"},{"arabic":"لِأَخِيهِ","transliteration":"","meaning":"to his brother","rule":"7:142"},{"arabic":"لِإِخْوَٰنِهِمْ","transliteration":"","meaning":"about their brothers","rule":"3:156"}],"rules":[{"name":"Words on اخو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَخَاهُمْ","وَإِخْوَٰنُكُمْ","أُخْتٌۭ","وَإِخْوَتِهِۦٓ","لِأَخِيهِ","لِإِخْوَٰنِهِمْ","أَخَانَا","إِخْوَتِىٓ"]},{"name":"Parts of speech attested for اخو","description":"The morphology corpus tags words on this root as N — one part of speech across the 39 glossed words attested.","examples":["أَخَاهُمْ","وَإِخْوَٰنُكُمْ","أُخْتٌۭ","وَإِخْوَتِهِۦٓ","لِأَخِيهِ","لِإِخْوَٰنِهِمْ"]},{"name":"Where اخو occurs","description":"The 39 glossed words on this root are attested across 13 distinct surahs.","examples":["أَخَاهُمْ (7:65)","وَإِخْوَٰنُكُمْ (9:24)","أُخْتٌۭ (4:12)","وَإِخْوَتِهِۦٓ (12:7)","لِأَخِيهِ (7:142)","لِإِخْوَٰنِهِمْ (3:156)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اخو?","options":["نَأْتِى","وَٱتَّخِذُوا۟","أَوَّلَ","أَخَاهُمْ"],"correct":3,"explanation":"أَخَاهُمْ — glossed \"(We sent) their brother\" at 7:65 — carries the root اخو. The others come from different roots."},{"type":"multiple_choice","question":"What does وَإِخْوَٰنُكُمْ mean?","options":["what your Lord wills","of the Verses","My partners","and your brothers"],"correct":3,"explanation":"\"and your brothers\", from the word-by-word gloss at 9:24."},{"type":"fill_blank","question":"Type the root of أُخْتٌۭ in Arabic (three letters).","correct":"اخو","explanation":"اخو. Diacritics are ignored when checking, so ا خ و is enough."}]', '["root-SHb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bgy', 'The root بغي (ب غ ي)', 'grammar', 3, '{"explanation":"The root بغي occurs 96 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 41 distinct glossed words, tagged in the corpus as N, V, in verb forms VIII, VII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَبْتَغِ","transliteration":"","meaning":"seeks","rule":"3:85"},{"arabic":"وَٱبْتِغَآءَ","transliteration":"","meaning":"and seeking","rule":"3:7"},{"arabic":"يَنۢبَغِى","transliteration":"","meaning":"is appropriate","rule":"19:92"},{"arabic":"بَغْيًۭا","transliteration":"","meaning":"(in) rebellion","rule":"10:90"},{"arabic":"ٱبْتِغَآءَ","transliteration":"","meaning":"seeking","rule":"2:207"},{"arabic":"بَغْيًا","transliteration":"","meaning":"grudging","rule":"2:90"}],"rules":[{"name":"Words on بغي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَبْتَغِ","وَٱبْتِغَآءَ","يَنۢبَغِى","بَغْيًۭا","ٱبْتِغَآءَ","بَغْيًا","بَغْيًۢا","وَٱبْتَغُوٓا۟"]},{"name":"Parts of speech attested for بغي","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 41 glossed words attested.","examples":["يَبْتَغِ","وَٱبْتِغَآءَ","يَنۢبَغِى","بَغْيًۭا","ٱبْتِغَآءَ","بَغْيًا"]},{"name":"Verb forms attested for بغي","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, VII.","examples":["يَبْتَغِ","وَٱبْتِغَآءَ","يَنۢبَغِى","بَغْيًۭا","ٱبْتِغَآءَ","بَغْيًا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بغي?","options":["يَبْتَغِ","أُخْرَىٰهُمْ","ذُنُوبِهِمُ","شَهِدْنَآ"],"correct":0,"explanation":"يَبْتَغِ — glossed \"seeks\" at 3:85 — carries the root بغي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱبْتِغَآءَ mean?","options":["about their affair","and a sign","and seeking","partners be associated"],"correct":2,"explanation":"\"and seeking\", from the word-by-word gloss at 3:7."},{"type":"fill_blank","question":"Type the root of يَنۢبَغِى in Arabic (three letters).","correct":"بغي","explanation":"بغي. Diacritics are ignored when checking, so ب غ ي is enough."}]', '["root-Axw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qrb', 'The root قرب (ق ر ب)', 'grammar', 3, '{"explanation":"The root قرب occurs 96 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَقْرَبُوا۟","transliteration":"","meaning":"go near","rule":"4:43"},{"arabic":"قُرْبَانًۭا","transliteration":"","meaning":"a sacrifice","rule":"5:27"},{"arabic":"ٱلْمُقَرَّبِينَ","transliteration":"","meaning":"those brought near (to Allah)","rule":"3:45"},{"arabic":"قُرُبَـٰتٍ","transliteration":"","meaning":"(as) means of nearness","rule":"9:99"},{"arabic":"وَٱلْأَقْرَبُونَ","transliteration":"","meaning":"and the near relatives","rule":"4:7"},{"arabic":"قُرْبَىٰ","transliteration":"","meaning":"a near relative","rule":"5:106"}],"rules":[{"name":"Words on قرب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَقْرَبُوا۟","قُرْبَانًۭا","ٱلْمُقَرَّبِينَ","قُرُبَـٰتٍ","وَٱلْأَقْرَبُونَ","قُرْبَىٰ","وَٱلْأَقْرَبِينَ","قَرِيبٌ"]},{"name":"Parts of speech attested for قرب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["تَقْرَبُوا۟","قُرْبَانًۭا","ٱلْمُقَرَّبِينَ","قُرُبَـٰتٍ","وَٱلْأَقْرَبُونَ","قُرْبَىٰ"]},{"name":"Verb forms attested for قرب","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VIII.","examples":["تَقْرَبُوا۟","قُرْبَانًۭا","ٱلْمُقَرَّبِينَ","قُرُبَـٰتٍ","وَٱلْأَقْرَبُونَ","قُرْبَىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قرب?","options":["بِـَٔايَـٰتِنَآ","شِيَعًۭا","تَقْرَبُوا۟","يَأْتِيَهُمْ"],"correct":2,"explanation":"تَقْرَبُوا۟ — glossed \"go near\" at 4:43 — carries the root قرب. The others come from different roots."},{"type":"multiple_choice","question":"What does قُرْبَانًۭا mean?","options":["schism","a sacrifice","He can take you away","for those who remember"],"correct":1,"explanation":"\"a sacrifice\", from the word-by-word gloss at 5:27."},{"type":"fill_blank","question":"Type the root of ٱلْمُقَرَّبِينَ in Arabic (three letters).","correct":"قرب","explanation":"قرب. Diacritics are ignored when checking, so ق ر ب is enough."}]', '["root-bgy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hbb', 'The root حبب (ح ب ب)', 'grammar', 3, '{"explanation":"The root حبب occurs 95 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, X, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُحِبُّهُمْ","transliteration":"","meaning":"whom He loves","rule":"5:54"},{"arabic":"وَيُحِبُّ","transliteration":"","meaning":"and loves","rule":"2:222"},{"arabic":"يُحِبُّ","transliteration":"","meaning":"like","rule":"2:190"},{"arabic":"يَسْتَحِبُّونَ","transliteration":"","meaning":"love more","rule":"14:3"},{"arabic":"حُبُّ","transliteration":"","meaning":"(is) love","rule":"3:14"},{"arabic":"تُحِبُّوا۟","transliteration":"","meaning":"you love","rule":"2:216"}],"rules":[{"name":"Words on حبب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُحِبُّهُمْ","وَيُحِبُّ","يُحِبُّ","يَسْتَحِبُّونَ","حُبُّ","تُحِبُّوا۟","يُحْبِبْكُمُ","أَحَبَّ"]},{"name":"Parts of speech attested for حبب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 27 glossed words attested.","examples":["يُحِبُّهُمْ","وَيُحِبُّ","يُحِبُّ","يَسْتَحِبُّونَ","حُبُّ","تُحِبُّوا۟"]},{"name":"Verb forms attested for حبب","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X, II.","examples":["يُحِبُّهُمْ","وَيُحِبُّ","يُحِبُّ","يَسْتَحِبُّونَ","حُبُّ","تُحِبُّوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حبب?","options":["أَبِٱللَّهِ","سَيُؤْتِينَا","يُحِبُّهُمْ","وَأُمَمٌۭ"],"correct":2,"explanation":"يُحِبُّهُمْ — glossed \"whom He loves\" at 5:54 — carries the root حبب. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيُحِبُّ mean?","options":["and loves","(the) way of Allah","you associate (with Allah)","and the earth"],"correct":0,"explanation":"\"and loves\", from the word-by-word gloss at 2:222."},{"type":"fill_blank","question":"Type the root of يُحِبُّ in Arabic (three letters).","correct":"حبب","explanation":"حبب. Diacritics are ignored when checking, so ح ب ب is enough."}]', '["root-qrb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lyl', 'The root ليل (ل ي ل)', 'grammar', 3, '{"explanation":"The root ليل occurs 92 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِٱلَّيْلِ","transliteration":"","meaning":"by night","rule":"2:274"},{"arabic":"لَيَالِىَ","transliteration":"","meaning":"(by) night","rule":"34:18"},{"arabic":"لَيْلًا","transliteration":"","meaning":"(by) night","rule":"10:24"},{"arabic":"ٱلَّيْلَ","transliteration":"","meaning":"the night","rule":"3:27"},{"arabic":"لَيَالٍۢ","transliteration":"","meaning":"nights","rule":"19:10"},{"arabic":"لَيْلًۭا","transliteration":"","meaning":"(by) night","rule":"17:1"}],"rules":[{"name":"Words on ليل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِٱلَّيْلِ","لَيَالِىَ","لَيْلًا","ٱلَّيْلَ","لَيَالٍۢ","لَيْلًۭا","لَيْلَةَ","ٱلَّيْلِ"]},{"name":"Parts of speech attested for ليل","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 12 glossed words attested.","examples":["بِٱلَّيْلِ","لَيَالِىَ","لَيْلًا","ٱلَّيْلَ","لَيَالٍۢ","لَيْلًۭا"]},{"name":"Where ليل occurs","description":"The 12 glossed words on this root are attested across 9 distinct surahs.","examples":["بِٱلَّيْلِ (2:274)","لَيَالِىَ (34:18)","لَيْلًا (10:24)","ٱلَّيْلَ (3:27)","لَيَالٍۢ (19:10)","لَيْلًۭا (17:1)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ليل?","options":["ٱلْمُؤْمِنِينَ","أُوتُوا۟","بِٱلَّيْلِ","فَأَخَذَهُمُ"],"correct":2,"explanation":"بِٱلَّيْلِ — glossed \"by night\" at 2:274 — carries the root ليل. The others come from different roots."},{"type":"multiple_choice","question":"What does لَيَالِىَ mean?","options":["bring (upon) us","severe","(by) night","the Signs"],"correct":2,"explanation":"\"(by) night\", from the word-by-word gloss at 34:18."},{"type":"fill_blank","question":"Type the root of لَيْلًا in Arabic (three letters).","correct":"ليل","explanation":"ليل. Diacritics are ignored when checking, so ل ي ل is enough."}]', '["root-Hbb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sbH', 'The root سبح (س ب ح)', 'grammar', 3, '{"explanation":"The root سبح occurs 92 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَيُسَبِّحُ","transliteration":"","meaning":"And glorifies","rule":"13:13"},{"arabic":"يُسَبِّحْنَ","transliteration":"","meaning":"(to) glorify Our praises","rule":"21:79"},{"arabic":"وَسُبْحَـٰنَ","transliteration":"","meaning":"And Glory be","rule":"12:108"},{"arabic":"وَيُسَبِّحُونَهُۥ","transliteration":"","meaning":"And they glorify Him","rule":"7:206"},{"arabic":"سُبْحَـٰنَهُۥٓ","transliteration":"","meaning":"Glory be to Him","rule":"4:171"},{"arabic":"سُبْحَـٰنَهُۥ","transliteration":"","meaning":"Glory be to Him","rule":"2:116"}],"rules":[{"name":"Words on سبح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَيُسَبِّحُ","يُسَبِّحْنَ","وَسُبْحَـٰنَ","وَيُسَبِّحُونَهُۥ","سُبْحَـٰنَهُۥٓ","سُبْحَـٰنَهُۥ","وَتَسْبِيحَهُۥ","تُسَبِّحُ"]},{"name":"Parts of speech attested for سبح","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 25 glossed words attested.","examples":["وَيُسَبِّحُ","يُسَبِّحْنَ","وَسُبْحَـٰنَ","وَيُسَبِّحُونَهُۥ","سُبْحَـٰنَهُۥٓ","سُبْحَـٰنَهُۥ"]},{"name":"Verb forms attested for سبح","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["وَيُسَبِّحُ","يُسَبِّحْنَ","وَسُبْحَـٰنَ","وَيُسَبِّحُونَهُۥ","سُبْحَـٰنَهُۥٓ","سُبْحَـٰنَهُۥ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سبح?","options":["وَيُسَبِّحُ","يَذَّكَّرُونَ","ءَايَةَ","ٱللَّهُ"],"correct":0,"explanation":"وَيُسَبِّحُ — glossed \"And glorifies\" at 13:13 — carries the root سبح. The others come from different roots."},{"type":"multiple_choice","question":"What does يُسَبِّحْنَ mean?","options":["unblessed","(to) glorify Our praises","leaders","one of them"],"correct":1,"explanation":"\"(to) glorify Our praises\", from the word-by-word gloss at 21:79."},{"type":"fill_blank","question":"Type the root of وَسُبْحَـٰنَ in Arabic (three letters).","correct":"سبح","explanation":"سبح. Diacritics are ignored when checking, so س ب ح is enough."}]', '["root-lyl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sjd', 'The root سجد (س ج د)', 'grammar', 3, '{"explanation":"The root سجد occurs 92 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمَسَـٰجِدِ","transliteration":"","meaning":"the masajid","rule":"2:187"},{"arabic":"مَسْجِدٍۢ","transliteration":"","meaning":"masjid","rule":"7:29"},{"arabic":"ٱلسَّـٰجِدِينَ","transliteration":"","meaning":"those who prostrated","rule":"7:11"},{"arabic":"ءَأَسْجُدُ","transliteration":"","meaning":"Shall I prostrate","rule":"17:61"},{"arabic":"سَجَدُوا۟","transliteration":"","meaning":"they have prostrated","rule":"4:102"},{"arabic":"لَّمَسْجِدٌ","transliteration":"","meaning":"A masjid","rule":"9:108"}],"rules":[{"name":"Words on سجد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمَسَـٰجِدِ","مَسْجِدٍۢ","ٱلسَّـٰجِدِينَ","ءَأَسْجُدُ","سَجَدُوا۟","لَّمَسْجِدٌ","يَسْجُدُ","مَّسْجِدًۭا"]},{"name":"Parts of speech attested for سجد","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 24 glossed words attested.","examples":["ٱلْمَسَـٰجِدِ","مَسْجِدٍۢ","ٱلسَّـٰجِدِينَ","ءَأَسْجُدُ","سَجَدُوا۟","لَّمَسْجِدٌ"]},{"name":"Where سجد occurs","description":"The 24 glossed words on this root are attested across 9 distinct surahs.","examples":["ٱلْمَسَـٰجِدِ (2:187)","مَسْجِدٍۢ (7:29)","ٱلسَّـٰجِدِينَ (7:11)","ءَأَسْجُدُ (17:61)","سَجَدُوا۟ (4:102)","لَّمَسْجِدٌ (9:108)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سجد?","options":["أُمَمٌ","لِلْإِنسَـٰنِ","لِذِكْرِىٓ","ٱلْمَسَـٰجِدِ"],"correct":3,"explanation":"ٱلْمَسَـٰجِدِ — glossed \"the masajid\" at 2:187 — carries the root سجد. The others come from different roots."},{"type":"multiple_choice","question":"What does مَسْجِدٍۢ mean?","options":["associate partners (with Allah)","and his offspring","and harden","masjid"],"correct":3,"explanation":"\"masjid\", from the word-by-word gloss at 7:29."},{"type":"fill_blank","question":"Type the root of ٱلسَّـٰجِدِينَ in Arabic (three letters).","correct":"سجد","explanation":"سجد. Diacritics are ignored when checking, so س ج د is enough."}]', '["root-sbH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lys', 'The root ليس (ل ي س)', 'grammar', 3, '{"explanation":"The root ليس occurs 89 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَّيْسَ","transliteration":"","meaning":"Not","rule":"4:123"},{"arabic":"أَلَيْسَ","transliteration":"","meaning":"Is not","rule":"6:30"},{"arabic":"وَلَيْسَ","transliteration":"","meaning":"And it is not","rule":"2:189"},{"arabic":"أَوَلَيْسَ","transliteration":"","meaning":"Is not","rule":"29:10"},{"arabic":"۞ لَيْسُوا۟","transliteration":"","meaning":"They are not","rule":"3:113"},{"arabic":"لَيْسَ","transliteration":"","meaning":"Not is","rule":"2:198"}],"rules":[{"name":"Words on ليس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَّيْسَ","أَلَيْسَ","وَلَيْسَ","أَوَلَيْسَ","۞ لَيْسُوا۟","لَيْسَ","أَلَسْتُ","لَّيْسُوا۟"]},{"name":"Parts of speech attested for ليس","description":"The morphology corpus tags words on this root as V — one part of speech across the 18 glossed words attested.","examples":["لَّيْسَ","أَلَيْسَ","وَلَيْسَ","أَوَلَيْسَ","۞ لَيْسُوا۟","لَيْسَ"]},{"name":"Where ليس occurs","description":"The 18 glossed words on this root are attested across 8 distinct surahs.","examples":["لَّيْسَ (4:123)","أَلَيْسَ (6:30)","وَلَيْسَ (2:189)","أَوَلَيْسَ (29:10)","۞ لَيْسُوا۟ (3:113)","لَيْسَ (2:198)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ليس?","options":["مُؤْمِنٍ","لَّيْسَ","ٱللَّهُ","أَخَوَٰتِكُمْ"],"correct":1,"explanation":"لَّيْسَ — glossed \"Not\" at 4:123 — carries the root ليس. The others come from different roots."},{"type":"multiple_choice","question":"What does أَلَيْسَ mean?","options":["Is not","to his sister","(for) a term","he comes"],"correct":0,"explanation":"\"Is not\", from the word-by-word gloss at 6:30."},{"type":"fill_blank","question":"Type the root of وَلَيْسَ in Arabic (three letters).","correct":"ليس","explanation":"ليس. Diacritics are ignored when checking, so ل ي س is enough."}]', '["root-sjd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$Tn', 'The root شطن (ش ط ن)', 'grammar', 3, '{"explanation":"The root شطن occurs 88 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, PN. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَيَـٰطِينِهِمْ","transliteration":"","meaning":"their evil ones","rule":"2:14"},{"arabic":"ٱلشَّيَـٰطِينَ","transliteration":"","meaning":"the devils","rule":"2:102"},{"arabic":"ٱلشَّيَـٰطِينِ","transliteration":"","meaning":"(of) the devils","rule":"17:27"},{"arabic":"شَيْطَـٰنٍۢ","transliteration":"","meaning":"devil","rule":"15:17"},{"arabic":"لِلشَّيْطَـٰنِ","transliteration":"","meaning":"to the Shaitaan","rule":"19:45"},{"arabic":"وَٱلشَّيَـٰطِينَ","transliteration":"","meaning":"and the devils","rule":"19:68"}],"rules":[{"name":"Words on شطن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَيَـٰطِينِهِمْ","ٱلشَّيَـٰطِينَ","ٱلشَّيَـٰطِينِ","شَيْطَـٰنٍۢ","لِلشَّيْطَـٰنِ","وَٱلشَّيَـٰطِينَ","شَيَـٰطِينَ","شَيْطَـٰنًۭا"]},{"name":"Parts of speech attested for شطن","description":"The morphology corpus tags words on this root as N, PN — 2 distinct parts of speech across the 12 glossed words attested.","examples":["شَيَـٰطِينِهِمْ","ٱلشَّيَـٰطِينَ","ٱلشَّيَـٰطِينِ","شَيْطَـٰنٍۢ","لِلشَّيْطَـٰنِ","وَٱلشَّيَـٰطِينَ"]},{"name":"Where شطن occurs","description":"The 12 glossed words on this root are attested across 6 distinct surahs.","examples":["شَيَـٰطِينِهِمْ (2:14)","ٱلشَّيَـٰطِينَ (2:102)","ٱلشَّيَـٰطِينِ (17:27)","شَيْطَـٰنٍۢ (15:17)","لِلشَّيْطَـٰنِ (19:45)","وَٱلشَّيَـٰطِينَ (19:68)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شطن?","options":["وَٱلشَّمْسِ","بِـَٔايَـٰتِ","فَبِإِذْنِ","شَيَـٰطِينِهِمْ"],"correct":3,"explanation":"شَيَـٰطِينِهِمْ — glossed \"their evil ones\" at 2:14 — carries the root شطن. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلشَّيَـٰطِينَ mean?","options":["So would you approach","the devils","are (also) suffering","your (having) faith"],"correct":1,"explanation":"\"the devils\", from the word-by-word gloss at 2:102."},{"type":"fill_blank","question":"Type the root of ٱلشَّيَـٰطِينِ in Arabic (three letters).","correct":"شطن","explanation":"شطن. Diacritics are ignored when checking, so ش ط ن is enough."}]', '["root-lys"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qrA', 'The root قرا (ق ر ا)', 'grammar', 3, '{"explanation":"The root قرا occurs 88 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as PN, N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَقْرَءُونَ","transliteration":"","meaning":"(have been) reading","rule":"10:94"},{"arabic":"قُرْءَانًا","transliteration":"","meaning":"(the) Quran","rule":"20:113"},{"arabic":"قُرْءَانًۭا","transliteration":"","meaning":"any Quran","rule":"13:31"},{"arabic":"قُرْءَانَ","transliteration":"","meaning":"the Quran","rule":"17:78"},{"arabic":"وَقُرْءَانَ","transliteration":"","meaning":"and Quran","rule":"17:78"},{"arabic":"ٱلْقُرْءَانِ","transliteration":"","meaning":"the Quran","rule":"17:41"}],"rules":[{"name":"Words on قرا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَقْرَءُونَ","قُرْءَانًا","قُرْءَانًۭا","قُرْءَانَ","وَقُرْءَانَ","ٱلْقُرْءَانِ","قَرَأْتَ","قُرِئَ"]},{"name":"Parts of speech attested for قرا","description":"The morphology corpus tags words on this root as PN, N, V — 3 distinct parts of speech across the 24 glossed words attested.","examples":["يَقْرَءُونَ","قُرْءَانًا","قُرْءَانًۭا","قُرْءَانَ","وَقُرْءَانَ","ٱلْقُرْءَانِ"]},{"name":"Verb forms attested for قرا","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["يَقْرَءُونَ","قُرْءَانًا","قُرْءَانًۭا","قُرْءَانَ","وَقُرْءَانَ","ٱلْقُرْءَانِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قرا?","options":["يَقْرَءُونَ","وَأُو۟لِى","إِلَـٰهُكُمْ","يَأْمَنُوكُمْ"],"correct":0,"explanation":"يَقْرَءُونَ — glossed \"(have been) reading\" at 10:94 — carries the root قرا. The others come from different roots."},{"type":"multiple_choice","question":"What does قُرْءَانًا mean?","options":["my affair","(the) Quran","the former people","so that they may taste"],"correct":1,"explanation":"\"(the) Quran\", from the word-by-word gloss at 20:113."},{"type":"fill_blank","question":"Type the root of قُرْءَانًۭا in Arabic (three letters).","correct":"قرا","explanation":"قرا. Diacritics are ignored when checking, so ق ر ا is enough."}]', '["root-$Tn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-twb', 'The root توب (ت و ب)', 'grammar', 3, '{"explanation":"The root توب occurs 87 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلتَّوَّٰبِينَ","transliteration":"","meaning":"those who turn in repentance","rule":"2:222"},{"arabic":"مَتَابِ","transliteration":"","meaning":"(is) my return","rule":"13:30"},{"arabic":"تَابَ","transliteration":"","meaning":"repented","rule":"5:39"},{"arabic":"يَتُوبُوا۟","transliteration":"","meaning":"they repent","rule":"9:74"},{"arabic":"ٱلتَّوْبَةُ","transliteration":"","meaning":"the acceptance of repentance","rule":"4:17"},{"arabic":"أَتُوبُ","transliteration":"","meaning":"I will accept repentance","rule":"2:160"}],"rules":[{"name":"Words on توب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلتَّوَّٰبِينَ","مَتَابِ","تَابَ","يَتُوبُوا۟","ٱلتَّوْبَةُ","أَتُوبُ","تَوَّابًۭا","يَتُوبَ"]},{"name":"Parts of speech attested for توب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 27 glossed words attested.","examples":["ٱلتَّوَّٰبِينَ","مَتَابِ","تَابَ","يَتُوبُوا۟","ٱلتَّوْبَةُ","أَتُوبُ"]},{"name":"Where توب occurs","description":"The 27 glossed words on this root are attested across 7 distinct surahs.","examples":["ٱلتَّوَّٰبِينَ (2:222)","مَتَابِ (13:30)","تَابَ (5:39)","يَتُوبُوا۟ (9:74)","ٱلتَّوْبَةُ (4:17)","أَتُوبُ (2:160)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root توب?","options":["فَٱللَّهُ","وَشَهِدُوا۟","إِيمَـٰنُهُمْ","ٱلتَّوَّٰبِينَ"],"correct":3,"explanation":"ٱلتَّوَّٰبِينَ — glossed \"those who turn in repentance\" at 2:222 — carries the root توب. The others come from different roots."},{"type":"multiple_choice","question":"What does مَتَابِ mean?","options":["any man","will eat it","we believe[d]","(is) my return"],"correct":3,"explanation":"\"(is) my return\", from the word-by-word gloss at 13:30."},{"type":"fill_blank","question":"Type the root of تَابَ in Arabic (three letters).","correct":"توب","explanation":"توب. Diacritics are ignored when checking, so ت و ب is enough."}]', '["root-qrA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xld', 'The root خلد (خ ل د)', 'grammar', 3, '{"explanation":"The root خلد occurs 87 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَخْلُدُونَ","transliteration":"","meaning":"live forever","rule":"26:129"},{"arabic":"ٱلْخُلْدَ","transliteration":"","meaning":"[the] immortality","rule":"21:34"},{"arabic":"أَخْلَدَ","transliteration":"","meaning":"adhered","rule":"7:176"},{"arabic":"ٱلْخَـٰلِدُونَ","transliteration":"","meaning":"live forever","rule":"21:34"},{"arabic":"خَـٰلِدًۭا","transliteration":"","meaning":"(will) abide forever","rule":"4:14"},{"arabic":"ٱلْخُلْدِ","transliteration":"","meaning":"the everlasting","rule":"10:52"}],"rules":[{"name":"Words on خلد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَخْلُدُونَ","ٱلْخُلْدَ","أَخْلَدَ","ٱلْخَـٰلِدُونَ","خَـٰلِدًۭا","ٱلْخُلْدِ","خَـٰلِدِينَ","وَيَخْلُدْ"]},{"name":"Parts of speech attested for خلد","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 10 glossed words attested.","examples":["تَخْلُدُونَ","ٱلْخُلْدَ","أَخْلَدَ","ٱلْخَـٰلِدُونَ","خَـٰلِدًۭا","ٱلْخُلْدِ"]},{"name":"Verb forms attested for خلد","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["تَخْلُدُونَ","ٱلْخُلْدَ","أَخْلَدَ","ٱلْخَـٰلِدُونَ","خَـٰلِدًۭا","ٱلْخُلْدِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلد?","options":["لَّيُؤْمِنُنَّ","أَمْرِى","تَخْلُدُونَ","ٱلْأَمَدُ"],"correct":2,"explanation":"تَخْلُدُونَ — glossed \"live forever\" at 26:129 — carries the root خلد. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْخُلْدَ mean?","options":["her family","his trust","[the] immortality","and a land"],"correct":2,"explanation":"\"[the] immortality\", from the word-by-word gloss at 21:34."},{"type":"fill_blank","question":"Type the root of أَخْلَدَ in Arabic (three letters).","correct":"خلد","explanation":"خلد. Diacritics are ignored when checking, so خ ل د is enough."}]', '["root-twb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mwl', 'The root مول (م و ل)', 'grammar', 3, '{"explanation":"The root مول occurs 86 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَمْوَٰلِكُمْ","transliteration":"","meaning":"your capital","rule":"2:279"},{"arabic":"أَمْوَٰلَهُمُ","transliteration":"","meaning":"their wealth","rule":"2:265"},{"arabic":"أَمْوَٰلَهُم","transliteration":"","meaning":"their wealth","rule":"2:274"},{"arabic":"بِمَالٍۢ","transliteration":"","meaning":"with wealth","rule":"27:36"},{"arabic":"وَأَمْوَٰلَهُم","transliteration":"","meaning":"and their wealth","rule":"9:111"},{"arabic":"أَمْوَٰلِ","transliteration":"","meaning":"(the) wealth","rule":"2:188"}],"rules":[{"name":"Words on مول","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَمْوَٰلِكُمْ","أَمْوَٰلَهُمُ","أَمْوَٰلَهُم","بِمَالٍۢ","وَأَمْوَٰلَهُم","أَمْوَٰلِ","أَمْوَٰلُهُمْ","مَالَهُۥ"]},{"name":"Parts of speech attested for مول","description":"The morphology corpus tags words on this root as N — one part of speech across the 33 glossed words attested.","examples":["أَمْوَٰلِكُمْ","أَمْوَٰلَهُمُ","أَمْوَٰلَهُم","بِمَالٍۢ","وَأَمْوَٰلَهُم","أَمْوَٰلِ"]},{"name":"Where مول occurs","description":"The 33 glossed words on this root are attested across 15 distinct surahs.","examples":["أَمْوَٰلِكُمْ (2:279)","أَمْوَٰلَهُمُ (2:265)","أَمْوَٰلَهُم (2:274)","بِمَالٍۢ (27:36)","وَأَمْوَٰلَهُم (9:111)","أَمْوَٰلِ (2:188)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مول?","options":["شِقَاقِىٓ","تَأْتِيهِم","أَمْوَٰلِكُمْ","شُهَدَآءَ"],"correct":2,"explanation":"أَمْوَٰلِكُمْ — glossed \"your capital\" at 2:279 — carries the root مول. The others come from different roots."},{"type":"multiple_choice","question":"What does أَمْوَٰلَهُمُ mean?","options":["their wealth","(is) for man","wills","He has commanded"],"correct":0,"explanation":"\"their wealth\", from the word-by-word gloss at 2:265."},{"type":"fill_blank","question":"Type the root of أَمْوَٰلَهُم in Arabic (three letters).","correct":"مول","explanation":"مول. Diacritics are ignored when checking, so م و ل is enough."}]', '["root-xld"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-AHd', 'The root احد (ا ح د)', 'grammar', 3, '{"explanation":"The root احد occurs 85 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَحَدٍۢ","transliteration":"","meaning":"any","rule":"2:136"},{"arabic":"أَحَدَكُم","transliteration":"","meaning":"one of you","rule":"18:19"},{"arabic":"أَحَدِهِمْ","transliteration":"","meaning":"(of) one of them","rule":"24:6"},{"arabic":"إِحْدَىٰهُنَّ","transliteration":"","meaning":"one of them","rule":"4:20"},{"arabic":"أَحَدُكُمَا","transliteration":"","meaning":"one of you","rule":"12:41"},{"arabic":"أَحَدَنَا","transliteration":"","meaning":"one of us","rule":"12:78"}],"rules":[{"name":"Words on احد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَحَدٍۢ","أَحَدَكُم","أَحَدِهِمْ","إِحْدَىٰهُنَّ","أَحَدُكُمَا","أَحَدَنَا","أَحَدًا","أَحَدُكُمْ"]},{"name":"Parts of speech attested for احد","description":"The morphology corpus tags words on this root as N — one part of speech across the 25 glossed words attested.","examples":["أَحَدٍۢ","أَحَدَكُم","أَحَدِهِمْ","إِحْدَىٰهُنَّ","أَحَدُكُمَا","أَحَدَنَا"]},{"name":"Where احد occurs","description":"The 25 glossed words on this root are attested across 11 distinct surahs.","examples":["أَحَدٍۢ (2:136)","أَحَدَكُم (18:19)","أَحَدِهِمْ (24:6)","إِحْدَىٰهُنَّ (4:20)","أَحَدُكُمَا (12:41)","أَحَدَنَا (12:78)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root احد?","options":["ءَابَآءَهُمْ","لِأُو۟لِى","أَحَدٍۢ","أَتَّخِذْ"],"correct":2,"explanation":"أَحَدٍۢ — glossed \"any\" at 2:136 — carries the root احد. The others come from different roots."},{"type":"multiple_choice","question":"What does أَحَدَكُم mean?","options":["then he believed","(is) sinful","tires Him","one of you"],"correct":3,"explanation":"\"one of you\", from the word-by-word gloss at 18:19."},{"type":"fill_blank","question":"Type the root of أَحَدِهِمْ in Arabic (three letters).","correct":"احد","explanation":"احد. Diacritics are ignored when checking, so ا ح د is enough."}]', '["root-mwl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-njw', 'The root نجو (ن ج و)', 'grammar', 3, '{"explanation":"The root نجو occurs 84 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 41 distinct glossed words, tagged in the corpus as V, N, in verb forms II, IV, VI, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَنَجْوَىٰهُمْ","transliteration":"","meaning":"and their secret conversation","rule":"9:78"},{"arabic":"نَجْوَىٰٓ","transliteration":"","meaning":"(are) in private conversation","rule":"17:47"},{"arabic":"نَّجْوَىٰهُمْ","transliteration":"","meaning":"their secret talk","rule":"4:114"},{"arabic":"فَنُجِّىَ","transliteration":"","meaning":"and was saved","rule":"12:110"},{"arabic":"نَجَّيْنَا","transliteration":"","meaning":"We saved","rule":"11:58"},{"arabic":"أَنجَيْنَـٰكُم","transliteration":"","meaning":"We saved you","rule":"7:141"}],"rules":[{"name":"Words on نجو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَنَجْوَىٰهُمْ","نَجْوَىٰٓ","نَّجْوَىٰهُمْ","فَنُجِّىَ","نَجَّيْنَا","أَنجَيْنَـٰكُم","نُـۨجِى","فَنَجَّيْنَـٰهُ"]},{"name":"Parts of speech attested for نجو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 41 glossed words attested.","examples":["وَنَجْوَىٰهُمْ","نَجْوَىٰٓ","نَّجْوَىٰهُمْ","فَنُجِّىَ","نَجَّيْنَا","أَنجَيْنَـٰكُم"]},{"name":"Verb forms attested for نجو","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV, VI, III.","examples":["وَنَجْوَىٰهُمْ","نَجْوَىٰٓ","نَّجْوَىٰهُمْ","فَنُجِّىَ","نَجَّيْنَا","أَنجَيْنَـٰكُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نجو?","options":["أَمْرُنَا","وَنَجْوَىٰهُمْ","وَءَاثَـٰرَهُمْ","ٱللَّهُ"],"correct":1,"explanation":"وَنَجْوَىٰهُمْ — glossed \"and their secret conversation\" at 9:78 — carries the root نجو. The others come from different roots."},{"type":"multiple_choice","question":"What does نَجْوَىٰٓ mean?","options":["perceive","Allah has imposed","(are) in private conversation","concerning the Hereafter"],"correct":2,"explanation":"\"(are) in private conversation\", from the word-by-word gloss at 17:47."},{"type":"fill_blank","question":"Type the root of نَّجْوَىٰهُمْ in Arabic (three letters).","correct":"نجو","explanation":"نجو. Diacritics are ignored when checking, so ن ج و is enough."}]', '["root-AHd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hrm', 'The root حرم (ح ر م)', 'grammar', 3, '{"explanation":"The root حرم occurs 83 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"حَرَّمَ","transliteration":"","meaning":"He has forbidden","rule":"2:173"},{"arabic":"وَيُحَرِّمُ","transliteration":"","meaning":"and makes unlawful","rule":"7:157"},{"arabic":"حَرَامًۭا","transliteration":"","meaning":"unlawful","rule":"10:59"},{"arabic":"حَرَّمْنَا","transliteration":"","meaning":"We made unlawful","rule":"4:160"},{"arabic":"وَحَرَّمُوا۟","transliteration":"","meaning":"and forbid","rule":"6:140"},{"arabic":"ٱلْمُحَرَّمِ","transliteration":"","meaning":"Your Sacred House","rule":"14:37"}],"rules":[{"name":"Words on حرم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["حَرَّمَ","وَيُحَرِّمُ","حَرَامًۭا","حَرَّمْنَا","وَحَرَّمُوا۟","ٱلْمُحَرَّمِ","ٱلْحَرَامَ","حُرِّمَتْ"]},{"name":"Parts of speech attested for حرم","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 26 glossed words attested.","examples":["حَرَّمَ","وَيُحَرِّمُ","حَرَامًۭا","حَرَّمْنَا","وَحَرَّمُوا۟","ٱلْمُحَرَّمِ"]},{"name":"Verb forms attested for حرم","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["حَرَّمَ","وَيُحَرِّمُ","حَرَامًۭا","حَرَّمْنَا","وَحَرَّمُوا۟","ٱلْمُحَرَّمِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حرم?","options":["سَـَٔاوِىٓ","إِلَـٰهَ","ءَاتَىٰهُمُ","حَرَّمَ"],"correct":3,"explanation":"حَرَّمَ — glossed \"He has forbidden\" at 2:173 — carries the root حرم. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيُحَرِّمُ mean?","options":["(the) interpretation","will it be permitted","(the) affair","and makes unlawful"],"correct":3,"explanation":"\"and makes unlawful\", from the word-by-word gloss at 7:157."},{"type":"fill_blank","question":"Type the root of حَرَامًۭا in Arabic (three letters).","correct":"حرم","explanation":"حرم. Diacritics are ignored when checking, so ح ر م is enough."}]', '["root-njw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-swy', 'The root سوي (س و ي)', 'grammar', 3, '{"explanation":"The root سوي occurs 83 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms VIII, II, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلسَّوِىِّ","transliteration":"","meaning":"[the] even","rule":"20:135"},{"arabic":"سَوَآءَ","transliteration":"","meaning":"(the) evenness","rule":"2:108"},{"arabic":"سَوَآءٍۢ","transliteration":"","meaning":"equally","rule":"21:109"},{"arabic":"يَسْتَوُۥنَ","transliteration":"","meaning":"They are not equal","rule":"9:19"},{"arabic":"وَٱسْتَوَىٰٓ","transliteration":"","meaning":"and became mature","rule":"28:14"},{"arabic":"سَوَآءِ","transliteration":"","meaning":"(the) even","rule":"5:60"}],"rules":[{"name":"Words on سوي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلسَّوِىِّ","سَوَآءَ","سَوَآءٍۢ","يَسْتَوُۥنَ","وَٱسْتَوَىٰٓ","سَوَآءِ","ٱسْتَوَىٰ","سَوَآءٍۭ"]},{"name":"Parts of speech attested for سوي","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["ٱلسَّوِىِّ","سَوَآءَ","سَوَآءٍۢ","يَسْتَوُۥنَ","وَٱسْتَوَىٰٓ","سَوَآءِ"]},{"name":"Verb forms attested for سوي","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, II, III.","examples":["ٱلسَّوِىِّ","سَوَآءَ","سَوَآءٍۢ","يَسْتَوُۥنَ","وَٱسْتَوَىٰٓ","سَوَآءِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سوي?","options":["أَمِنتُم","أَمْرٍۢ","يَأْتِ","ٱلسَّوِىِّ"],"correct":3,"explanation":"ٱلسَّوِىِّ — glossed \"[the] even\" at 20:135 — carries the root سوي. The others come from different roots."},{"type":"multiple_choice","question":"What does سَوَآءَ mean?","options":["[in] Our Verses","(will be the) wretched","(the) evenness","[two] gods"],"correct":2,"explanation":"\"(the) evenness\", from the word-by-word gloss at 2:108."},{"type":"fill_blank","question":"Type the root of سَوَآءٍۢ in Arabic (three letters).","correct":"سوي","explanation":"سوي. Diacritics are ignored when checking, so س و ي is enough."}]', '["root-Hrm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-zwj', 'The root زوج (ز و ج)', 'grammar', 3, '{"explanation":"The root زوج occurs 81 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَزَوْجِهِۦ","transliteration":"","meaning":"and his spouse","rule":"2:102"},{"arabic":"وَأَزْوَٰجُكُمْ","transliteration":"","meaning":"and your spouses","rule":"9:24"},{"arabic":"زَوْجٍۭ","transliteration":"","meaning":"kind","rule":"22:5"},{"arabic":"وَلِزَوْجِكَ","transliteration":"","meaning":"and to your wife","rule":"20:117"},{"arabic":"زَوْجَكَ","transliteration":"","meaning":"your wife","rule":"33:37"},{"arabic":"وَأَزْوَٰجَهُمْ","transliteration":"","meaning":"and their kinds","rule":"37:22"}],"rules":[{"name":"Words on زوج","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَزَوْجِهِۦ","وَأَزْوَٰجُكُمْ","زَوْجٍۭ","وَلِزَوْجِكَ","زَوْجَكَ","وَأَزْوَٰجَهُمْ","زَوْجًا","أَزْوَٰجِ"]},{"name":"Parts of speech attested for زوج","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 35 glossed words attested.","examples":["وَزَوْجِهِۦ","وَأَزْوَٰجُكُمْ","زَوْجٍۭ","وَلِزَوْجِكَ","زَوْجَكَ","وَأَزْوَٰجَهُمْ"]},{"name":"Verb forms attested for زوج","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["وَزَوْجِهِۦ","وَأَزْوَٰجُكُمْ","زَوْجٍۭ","وَلِزَوْجِكَ","زَوْجَكَ","وَأَزْوَٰجَهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root زوج?","options":["وَزَوْجِهِۦ","ٱللَّهُ","شَرًّۭا","وَأَهْلَهُۥ"],"correct":0,"explanation":"وَزَوْجِهِۦ — glossed \"and his spouse\" at 2:102 — carries the root زوج. The others come from different roots."},{"type":"multiple_choice","question":"What does وَأَزْوَٰجُكُمْ mean?","options":["And others","by their fathers","the Signs","and your spouses"],"correct":3,"explanation":"\"and your spouses\", from the word-by-word gloss at 9:24."},{"type":"fill_blank","question":"Type the root of زَوْجٍۭ in Arabic (three letters).","correct":"زوج","explanation":"زوج. Diacritics are ignored when checking, so ز و ج is enough."}]', '["root-swy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Eqb', 'The root عقب (ع ق ب)', 'grammar', 3, '{"explanation":"The root عقب occurs 80 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, II, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعِقَابِ","transliteration":"","meaning":"(in) retribution","rule":"2:196"},{"arabic":"فَأَعْقَبَهُمْ","transliteration":"","meaning":"So He penalized them","rule":"9:77"},{"arabic":"مُعَقِّبَـٰتٌۭ","transliteration":"","meaning":"(are) successive (Angels)","rule":"13:11"},{"arabic":"وَّعُقْبَى","transliteration":"","meaning":"and (the) end","rule":"13:35"},{"arabic":"أَعْقَـٰبِكُمْ","transliteration":"","meaning":"your heels","rule":"3:144"},{"arabic":"عُقْبًۭا","transliteration":"","meaning":"(for) the final end","rule":"18:44"}],"rules":[{"name":"Words on عقب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعِقَابِ","فَأَعْقَبَهُمْ","مُعَقِّبَـٰتٌۭ","وَّعُقْبَى","أَعْقَـٰبِكُمْ","عُقْبًۭا","عِقَابِ","عَـٰقِبَةُ"]},{"name":"Parts of speech attested for عقب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 21 glossed words attested.","examples":["ٱلْعِقَابِ","فَأَعْقَبَهُمْ","مُعَقِّبَـٰتٌۭ","وَّعُقْبَى","أَعْقَـٰبِكُمْ","عُقْبًۭا"]},{"name":"Verb forms attested for عقب","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II, III.","examples":["ٱلْعِقَابِ","فَأَعْقَبَهُمْ","مُعَقِّبَـٰتٌۭ","وَّعُقْبَى","أَعْقَـٰبِكُمْ","عُقْبًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عقب?","options":["ٱلْعِقَابِ","ٱلْـَٔاخِرَةَ","وَيَأْمُرُونَ","شَرِّ"],"correct":0,"explanation":"ٱلْعِقَابِ — glossed \"(in) retribution\" at 2:196 — carries the root عقب. The others come from different roots."},{"type":"multiple_choice","question":"What does فَأَعْقَبَهُمْ mean?","options":["his maturity","So He penalized them","Allah will bring it forth","they eat"],"correct":1,"explanation":"\"So He penalized them\", from the word-by-word gloss at 9:77."},{"type":"fill_blank","question":"Type the root of مُعَقِّبَـٰتٌۭ in Arabic (three letters).","correct":"عقب","explanation":"عقب. Diacritics are ignored when checking, so ع ق ب is enough."}]', '["root-zwj"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ErD', 'The root عرض (ع ر ض)', 'grammar', 4, '{"explanation":"The root عرض occurs 79 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَأَعْرِضْ","transliteration":"","meaning":"so turn away","rule":"4:63"},{"arabic":"فَأَعْرَضَ","transliteration":"","meaning":"but turns away","rule":"18:57"},{"arabic":"أَعْرَضَ","transliteration":"","meaning":"he turns away","rule":"17:83"},{"arabic":"إِعْرَاضًۭا","transliteration":"","meaning":"desertion","rule":"4:128"},{"arabic":"أَعْرِضْ","transliteration":"","meaning":"turn away","rule":"5:42"},{"arabic":"مُعْرِضِينَ","transliteration":"","meaning":"turning away","rule":"6:4"}],"rules":[{"name":"Words on عرض","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَأَعْرِضْ","فَأَعْرَضَ","أَعْرَضَ","إِعْرَاضًۭا","أَعْرِضْ","مُعْرِضِينَ","عَرَضَ","وَعَرَضْنَا"]},{"name":"Parts of speech attested for عرض","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 31 glossed words attested.","examples":["فَأَعْرِضْ","فَأَعْرَضَ","أَعْرَضَ","إِعْرَاضًۭا","أَعْرِضْ","مُعْرِضِينَ"]},{"name":"Verb forms attested for عرض","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["فَأَعْرِضْ","فَأَعْرَضَ","أَعْرَضَ","إِعْرَاضًۭا","أَعْرِضْ","مُعْرِضِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عرض?","options":["يَأْمُرُونَ","فَأَعْرِضْ","وَإِنَـٰثًۭا","أُمِّهِۦ"],"correct":1,"explanation":"فَأَعْرِضْ — glossed \"so turn away\" at 4:63 — carries the root عرض. The others come from different roots."},{"type":"multiple_choice","question":"What does فَأَعْرَضَ mean?","options":["thousand[s]","but turns away","I had taken","so that you may eat"],"correct":1,"explanation":"\"but turns away\", from the word-by-word gloss at 18:57."},{"type":"fill_blank","question":"Type the root of أَعْرَضَ in Arabic (three letters).","correct":"عرض","explanation":"عرض. Diacritics are ignored when checking, so ع ر ض is enough."}]', '["root-Eqb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wHy', 'The root وحي (و ح ي)', 'grammar', 4, '{"explanation":"The root وحي occurs 78 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَوْحَيْتُ","transliteration":"","meaning":"I inspired","rule":"5:111"},{"arabic":"وَوَحْيِنَا","transliteration":"","meaning":"and Our inspiration","rule":"11:37"},{"arabic":"يُوحِى","transliteration":"","meaning":"inspiring","rule":"6:112"},{"arabic":"وَحْيُهُۥ","transliteration":"","meaning":"its revelation","rule":"20:114"},{"arabic":"يُوحَىٰٓ","transliteration":"","meaning":"is revealed","rule":"6:50"},{"arabic":"أَوْحَىٰٓ","transliteration":"","meaning":"(was) revealed","rule":"17:39"}],"rules":[{"name":"Words on وحي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَوْحَيْتُ","وَوَحْيِنَا","يُوحِى","وَحْيُهُۥ","يُوحَىٰٓ","أَوْحَىٰٓ","أُوحِىَ","نُوحِيهَآ"]},{"name":"Parts of speech attested for وحي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 22 glossed words attested.","examples":["أَوْحَيْتُ","وَوَحْيِنَا","يُوحِى","وَحْيُهُۥ","يُوحَىٰٓ","أَوْحَىٰٓ"]},{"name":"Verb forms attested for وحي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["أَوْحَيْتُ","وَوَحْيِنَا","يُوحِى","وَحْيُهُۥ","يُوحَىٰٓ","أَوْحَىٰٓ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وحي?","options":["ٱلْإِنسِ","وَلِلْمُؤْمِنِينَ","أَوْحَيْتُ","أَخَذَ"],"correct":2,"explanation":"أَوْحَيْتُ — glossed \"I inspired\" at 5:111 — carries the root وحي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَوَحْيِنَا mean?","options":["Descendents","and Our inspiration","(the) sign","harmed"],"correct":1,"explanation":"\"and Our inspiration\", from the word-by-word gloss at 11:37."},{"type":"fill_blank","question":"Type the root of يُوحِى in Arabic (three letters).","correct":"وحي","explanation":"وحي. Diacritics are ignored when checking, so و ح ي is enough."}]', '["root-ErD"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wjh', 'The root وجه (و ج ه)', 'grammar', 4, '{"explanation":"The root وجه occurs 78 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, T, V, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَجْهَهُۥ","transliteration":"","meaning":"his face","rule":"2:112"},{"arabic":"بِوَجْهِهِۦ","transliteration":"","meaning":"with his face","rule":"39:24"},{"arabic":"وَجْهِكَ","transliteration":"","meaning":"(of) your face","rule":"2:144"},{"arabic":"وَجْهَ","transliteration":"","meaning":"(at the) beginning","rule":"3:72"},{"arabic":"وَجْهِهَآ","transliteration":"","meaning":"its (true) form","rule":"5:108"},{"arabic":"وَجْهُ","transliteration":"","meaning":"(is the) face","rule":"2:115"}],"rules":[{"name":"Words on وجه","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَجْهَهُۥ","بِوَجْهِهِۦ","وَجْهِكَ","وَجْهَ","وَجْهِهَآ","وَجْهُ","وَجْهَكَ","وُجُوهِ"]},{"name":"Parts of speech attested for وجه","description":"The morphology corpus tags words on this root as N, T, V — 3 distinct parts of speech across the 30 glossed words attested.","examples":["وَجْهَهُۥ","بِوَجْهِهِۦ","وَجْهِكَ","وَجْهَ","وَجْهِهَآ","وَجْهُ"]},{"name":"Verb forms attested for وجه","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["وَجْهَهُۥ","بِوَجْهِهِۦ","وَجْهِكَ","وَجْهَ","وَجْهِهَآ","وَجْهُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وجه?","options":["شَأْنٌۭ","أَخَوَٰتِكُمْ","وَجْهَهُۥ","ٱلشَّيْطَـٰنُ"],"correct":2,"explanation":"وَجْهَهُۥ — glossed \"his face\" at 2:112 — carries the root وجه. The others come from different roots."},{"type":"multiple_choice","question":"What does بِوَجْهِهِۦ mean?","options":["an excessive transgression","its term","with his face","were wretched"],"correct":2,"explanation":"\"with his face\", from the word-by-word gloss at 39:24."},{"type":"fill_blank","question":"Type the root of وَجْهِكَ in Arabic (three letters).","correct":"وجه","explanation":"وجه. Diacritics are ignored when checking, so و ج ه is enough."}]', '["root-wHy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Swb', 'The root صوب (ص و ب)', 'grammar', 4, '{"explanation":"The root صوب occurs 77 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 44 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُصِيبَنَآ","transliteration":"","meaning":"will befall us","rule":"9:51"},{"arabic":"أَصَابَهَا","transliteration":"","meaning":"fell on it","rule":"2:265"},{"arabic":"وَأَصَابَهُ","transliteration":"","meaning":"and strikes him","rule":"2:266"},{"arabic":"أَصَـٰبَكُمْ","transliteration":"","meaning":"(had) befallen you","rule":"3:153"},{"arabic":"تُصِيبَنَا","transliteration":"","meaning":"(may) strike us","rule":"5:52"},{"arabic":"يُصِيبَهُم","transliteration":"","meaning":"afflict them","rule":"5:49"}],"rules":[{"name":"Words on صوب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُصِيبَنَآ","أَصَابَهَا","وَأَصَابَهُ","أَصَـٰبَكُمْ","تُصِيبَنَا","يُصِيبَهُم","أَصَـٰبَتْهُم","فَأَصَـٰبَتْكُم"]},{"name":"Parts of speech attested for صوب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 44 glossed words attested.","examples":["يُصِيبَنَآ","أَصَابَهَا","وَأَصَابَهُ","أَصَـٰبَكُمْ","تُصِيبَنَا","يُصِيبَهُم"]},{"name":"Verb forms attested for صوب","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["يُصِيبَنَآ","أَصَابَهَا","وَأَصَابَهُ","أَصَـٰبَكُمْ","تُصِيبَنَا","يُصِيبَهُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صوب?","options":["يُصِيبَنَآ","ٱسْتَـْٔجِرْهُ","إِنَـٰثًا","أَفَأَمِنُوٓا۟"],"correct":0,"explanation":"يُصِيبَنَآ — glossed \"will befall us\" at 9:51 — carries the root صوب. The others come from different roots."},{"type":"multiple_choice","question":"What does أَصَابَهَا mean?","options":["Allah guided","to the believers","fell on it","And remembers"],"correct":2,"explanation":"\"fell on it\", from the word-by-word gloss at 2:265."},{"type":"fill_blank","question":"Type the root of وَأَصَابَهُ in Arabic (three letters).","correct":"صوب","explanation":"صوب. Diacritics are ignored when checking, so ص و ب is enough."}]', '["root-wjh"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-blg', 'The root بلغ (ب ل غ)', 'grammar', 4, '{"explanation":"The root بلغ occurs 77 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَـٰلِغُوهُ","transliteration":"","meaning":"were to reach [it]","rule":"7:135"},{"arabic":"أَبْلُغُ","transliteration":"","meaning":"reach","rule":"40:36"},{"arabic":"بَلَغُوا۟","transliteration":"","meaning":"they reach[ed]","rule":"4:6"},{"arabic":"وَبَلَغَتِ","transliteration":"","meaning":"and reached","rule":"33:10"},{"arabic":"بَلِيغًۭا","transliteration":"","meaning":"penetrating","rule":"4:63"},{"arabic":"أَبْلُغَ","transliteration":"","meaning":"I reach","rule":"18:60"}],"rules":[{"name":"Words on بلغ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَـٰلِغُوهُ","أَبْلُغُ","بَلَغُوا۟","وَبَلَغَتِ","بَلِيغًۭا","أَبْلُغَ","بَلَغْتُ","بِبَـٰلِغِيهِ"]},{"name":"Parts of speech attested for بلغ","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 37 glossed words attested.","examples":["بَـٰلِغُوهُ","أَبْلُغُ","بَلَغُوا۟","وَبَلَغَتِ","بَلِيغًۭا","أَبْلُغَ"]},{"name":"Verb forms attested for بلغ","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV.","examples":["بَـٰلِغُوهُ","أَبْلُغُ","بَلَغُوا۟","وَبَلَغَتِ","بَلِيغًۭا","أَبْلُغَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بلغ?","options":["لَذَآئِقُوا۟","ٱشْتَهَتْ","أَوَّلَ","بَـٰلِغُوهُ"],"correct":3,"explanation":"بَـٰلِغُوهُ — glossed \"were to reach [it]\" at 7:135 — carries the root بلغ. The others come from different roots."},{"type":"multiple_choice","question":"What does أَبْلُغُ mean?","options":["reach","will follow","to man","a sign"],"correct":0,"explanation":"\"reach\", from the word-by-word gloss at 40:36."},{"type":"fill_blank","question":"Type the root of بَلَغُوا۟ in Arabic (three letters).","correct":"بلغ","explanation":"بلغ. Diacritics are ignored when checking, so ب ل غ is enough."}]', '["root-Swb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qll', 'The root قلل (ق ل ل)', 'grammar', 4, '{"explanation":"The root قلل occurs 76 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as ADJ, N, V, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَلِيلَةٍ","transliteration":"","meaning":"small","rule":"2:249"},{"arabic":"قَلِيلٌۭ","transliteration":"","meaning":"little","rule":"3:197"},{"arabic":"فَقَلِيلًۭا","transliteration":"","meaning":"so little","rule":"2:88"},{"arabic":"قَلِيلًا","transliteration":"","meaning":"little","rule":"2:174"},{"arabic":"قَلِيلُونَ","transliteration":"","meaning":"small","rule":"26:54"},{"arabic":"قَلِيلٍۢ","transliteration":"","meaning":"After a little while","rule":"23:40"}],"rules":[{"name":"Words on قلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَلِيلَةٍ","قَلِيلٌۭ","فَقَلِيلًۭا","قَلِيلًا","قَلِيلُونَ","قَلِيلٍۢ","أَقَلَّ","قَلَّ"]},{"name":"Parts of speech attested for قلل","description":"The morphology corpus tags words on this root as ADJ, N, V — 3 distinct parts of speech across the 13 glossed words attested.","examples":["قَلِيلَةٍ","قَلِيلٌۭ","فَقَلِيلًۭا","قَلِيلًا","قَلِيلُونَ","قَلِيلٍۢ"]},{"name":"Verb forms attested for قلل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["قَلِيلَةٍ","قَلِيلٌۭ","فَقَلِيلًۭا","قَلِيلًا","قَلِيلُونَ","قَلِيلٍۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قلل?","options":["ءَاخَرَانِ","يَأْتِيَهُمُ","شَىْءٍۢ","قَلِيلَةٍ"],"correct":3,"explanation":"قَلِيلَةٍ — glossed \"small\" at 2:249 — carries the root قلل. The others come from different roots."},{"type":"multiple_choice","question":"What does قَلِيلٌۭ mean?","options":["little","My Signs","they believe","(to) their forefathers"],"correct":0,"explanation":"\"little\", from the word-by-word gloss at 3:197."},{"type":"fill_blank","question":"Type the root of فَقَلِيلًۭا in Arabic (three letters).","correct":"قلل","explanation":"قلل. Diacritics are ignored when checking, so ق ل ل is enough."}]', '["root-blg"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$kr', 'The root شكر (ش ك ر)', 'grammar', 4, '{"explanation":"The root شكر occurs 75 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَاكِرًۭا","transliteration":"","meaning":"Thankful","rule":"16:121"},{"arabic":"يَشْكُرُونَ","transliteration":"","meaning":"grateful","rule":"2:243"},{"arabic":"ٱشْكُرْ","transliteration":"","meaning":"Be grateful","rule":"31:12"},{"arabic":"شَكَرَ","transliteration":"","meaning":"(is) grateful","rule":"27:40"},{"arabic":"بِٱلشَّـٰكِرِينَ","transliteration":"","meaning":"of those who are grateful","rule":"6:53"},{"arabic":"شُكُورًۭا","transliteration":"","meaning":"to be thankful","rule":"25:62"}],"rules":[{"name":"Words on شكر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَاكِرًۭا","يَشْكُرُونَ","ٱشْكُرْ","شَكَرَ","بِٱلشَّـٰكِرِينَ","شُكُورًۭا","شَكُورًۭا","يَشْكُرُ"]},{"name":"Parts of speech attested for شكر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 25 glossed words attested.","examples":["شَاكِرًۭا","يَشْكُرُونَ","ٱشْكُرْ","شَكَرَ","بِٱلشَّـٰكِرِينَ","شُكُورًۭا"]},{"name":"Where شكر occurs","description":"The 25 glossed words on this root are attested across 14 distinct surahs.","examples":["شَاكِرًۭا (16:121)","يَشْكُرُونَ (2:243)","ٱشْكُرْ (31:12)","شَكَرَ (27:40)","بِٱلشَّـٰكِرِينَ (6:53)","شُكُورًۭا (25:62)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شكر?","options":["شَاكِرًۭا","شَيْخٌۭ","ءَايَةٍ","وَٱلْم