INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gny', 'The root غني (غ ن ي)', 'grammar', 4, '{"explanation":"The root غني occurs 73 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"غَنِيًّۭا","transliteration":"","meaning":"rich","rule":"4:6"},{"arabic":"أُغْنِى","transliteration":"","meaning":"I can avail","rule":"12:67"},{"arabic":"يُغْنُوا۟","transliteration":"","meaning":"will avail","rule":"45:19"},{"arabic":"مُّغْنُونَ","transliteration":"","meaning":"the one who avails","rule":"14:21"},{"arabic":"يُغْنِيَهُمُ","transliteration":"","meaning":"Allah enriches them","rule":"24:33"},{"arabic":"يُغْنِهِمُ","transliteration":"","meaning":"Allah will enrich them","rule":"24:32"}],"rules":[{"name":"Words on غني","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["غَنِيًّۭا","أُغْنِى","يُغْنُوا۟","مُّغْنُونَ","يُغْنِيَهُمُ","يُغْنِهِمُ","أَغْنَىٰ","يُغْنِيكُمُ"]},{"name":"Parts of speech attested for غني","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 25 glossed words attested.","examples":["غَنِيًّۭا","أُغْنِى","يُغْنُوا۟","مُّغْنُونَ","يُغْنِيَهُمُ","يُغْنِهِمُ"]},{"name":"Verb forms attested for غني","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["غَنِيًّۭا","أُغْنِى","يُغْنُوا۟","مُّغْنُونَ","يُغْنِيَهُمُ","يُغْنِهِمُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غني?","options":["شَيْخًۭا","غَنِيًّۭا","لِيَسْتَـْٔذِنكُمُ","تُشْرِكُونَ"],"correct":1,"explanation":"غَنِيًّۭا — glossed \"rich\" at 4:6 — carries the root غني. The others come from different roots."},{"type":"multiple_choice","question":"What does أُغْنِى mean?","options":["(with) greater","I can avail","their father","their bridal money"],"correct":1,"explanation":"\"I can avail\", from the word-by-word gloss at 12:67."},{"type":"fill_blank","question":"Type the root of يُغْنُوا۟ in Arabic (three letters).","correct":"غني","explanation":"غني. Diacritics are ignored when checking, so غ ن ي is enough."}]', '["root-byt"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rDw', 'The root رضو (ر ض و)', 'grammar', 4, '{"explanation":"The root رضو occurs 73 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VI, IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَرَضُوا۟","transliteration":"","meaning":"and they are pleased","rule":"5:119"},{"arabic":"يُرْضُوهُ","transliteration":"","meaning":"they should please Him","rule":"9:62"},{"arabic":"لِتَرْضَىٰ","transliteration":"","meaning":"that You be pleased","rule":"20:84"},{"arabic":"رَضُوا۟","transliteration":"","meaning":"they are pleased","rule":"9:58"},{"arabic":"لِيُرْضُوكُمْ","transliteration":"","meaning":"to please you","rule":"9:62"},{"arabic":"وَرِضْوَٰنٍ","transliteration":"","meaning":"and (His) pleasure","rule":"9:109"}],"rules":[{"name":"Words on رضو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَرَضُوا۟","يُرْضُوهُ","لِتَرْضَىٰ","رَضُوا۟","لِيُرْضُوكُمْ","وَرِضْوَٰنٍ","يُرْضُونَكُم","وَيَرْضَيْنَ"]},{"name":"Parts of speech attested for رضو","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 39 glossed words attested.","examples":["وَرَضُوا۟","يُرْضُوهُ","لِتَرْضَىٰ","رَضُوا۟","لِيُرْضُوكُمْ","وَرِضْوَٰنٍ"]},{"name":"Verb forms attested for رضو","description":"Where this root is tagged as a verb, the corpus attests derived Forms VI, IV, VIII.","examples":["وَرَضُوا۟","يُرْضُوهُ","لِتَرْضَىٰ","رَضُوا۟","لِيُرْضُوكُمْ","وَرِضْوَٰنٍ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رضو?","options":["أَشِدَّآءُ","يُؤْمِنُونَ","ٱتَّخَذَ","وَرَضُوا۟"],"correct":3,"explanation":"وَرَضُوا۟ — glossed \"and they are pleased\" at 5:119 — carries the root رضو. The others come from different roots."},{"type":"multiple_choice","question":"What does يُرْضُوهُ mean?","options":["(is) certainly a thing","and the tree","they should please Him","by the twilight glow"],"correct":2,"explanation":"\"they should please Him\", from the word-by-word gloss at 9:62."},{"type":"fill_blank","question":"Type the root of لِتَرْضَىٰ in Arabic (three letters).","correct":"رضو","explanation":"رضو. Diacritics are ignored when checking, so ر ض و is enough."}]', '["root-gny"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rjl', 'The root رجل (ر ج ل)', 'grammar', 4, '{"explanation":"The root رجل occurs 73 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَرَجُلٌۭ","transliteration":"","meaning":"then one man","rule":"2:282"},{"arabic":"رَجُلٌۭ","transliteration":"","meaning":"a man","rule":"4:12"},{"arabic":"رِّجَالًۭا","transliteration":"","meaning":"men","rule":"4:176"},{"arabic":"أَرْجُلٌۭ","transliteration":"","meaning":"feet","rule":"7:195"},{"arabic":"رِّجَالِكُمْ","transliteration":"","meaning":"your men","rule":"2:282"},{"arabic":"رَجُلٌ","transliteration":"","meaning":"a man","rule":"23:38"}],"rules":[{"name":"Words on رجل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَرَجُلٌۭ","رَجُلٌۭ","رِّجَالًۭا","أَرْجُلٌۭ","رِّجَالِكُمْ","رَجُلٌ","وَرَجِلِكَ","رَجُلَيْنِ"]},{"name":"Parts of speech attested for رجل","description":"The morphology corpus tags words on this root as N — one part of speech across the 30 glossed words attested.","examples":["فَرَجُلٌۭ","رَجُلٌۭ","رِّجَالًۭا","أَرْجُلٌۭ","رِّجَالِكُمْ","رَجُلٌ"]},{"name":"Where رجل occurs","description":"The 30 glossed words on this root are attested across 11 distinct surahs.","examples":["فَرَجُلٌۭ (2:282)","رَجُلٌۭ (4:12)","رِّجَالًۭا (4:176)","أَرْجُلٌۭ (7:195)","رِّجَالِكُمْ (2:282)","رَجُلٌ (23:38)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رجل?","options":["ٱللَّهُ","بِٱلشَّرِّ","فَرَجُلٌۭ","ٱللَّهُ"],"correct":2,"explanation":"فَرَجُلٌۭ — glossed \"then one man\" at 2:282 — carries the root رجل. The others come from different roots."},{"type":"multiple_choice","question":"What does رَجُلٌۭ mean?","options":["and took","and supported him","a man","(the) command"],"correct":2,"explanation":"\"a man\", from the word-by-word gloss at 4:12."},{"type":"fill_blank","question":"Type the root of رِّجَالًۭا in Arabic (three letters).","correct":"رجل","explanation":"رجل. Diacritics are ignored when checking, so ر ج ل is enough."}]', '["root-rDw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-frq', 'The root فرق (ف ر ق)', 'grammar', 4, '{"explanation":"The root فرق occurs 72 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as V, N, in verb forms II, V, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَفَرِيقًۭا","transliteration":"","meaning":"and a party","rule":"2:87"},{"arabic":"ٱلْفُرْقَانَ","transliteration":"","meaning":"the Criterion","rule":"3:4"},{"arabic":"فَرَقْنَا","transliteration":"","meaning":"We parted","rule":"2:50"},{"arabic":"فُرْقَانًۭا","transliteration":"","meaning":"a criterion","rule":"8:29"},{"arabic":"نُفَرِّقُ","transliteration":"","meaning":"we make distinction","rule":"2:136"},{"arabic":"وَٱلْفُرْقَانَ","transliteration":"","meaning":"and the Criterion","rule":"2:53"}],"rules":[{"name":"Words on فرق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَفَرِيقًۭا","ٱلْفُرْقَانَ","فَرَقْنَا","فُرْقَانًۭا","نُفَرِّقُ","وَٱلْفُرْقَانَ","فِرْقٍۢ","وَفَرِيقًا"]},{"name":"Parts of speech attested for فرق","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 34 glossed words attested.","examples":["وَفَرِيقًۭا","ٱلْفُرْقَانَ","فَرَقْنَا","فُرْقَانًۭا","نُفَرِّقُ","وَٱلْفُرْقَانَ"]},{"name":"Verb forms attested for فرق","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V, III.","examples":["وَفَرِيقًۭا","ٱلْفُرْقَانَ","فَرَقْنَا","فُرْقَانًۭا","نُفَرِّقُ","وَٱلْفُرْقَانَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فرق?","options":["ٱللَّهُ","وَفَرِيقًۭا","يَـٰٓأَبَانَآ","لِّنُذِيقَهُمْ"],"correct":1,"explanation":"وَفَرِيقًۭا — glossed \"and a party\" at 2:87 — carries the root فرق. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْفُرْقَانَ mean?","options":["a more difficult","the Criterion","and a reward","(with) anyone"],"correct":1,"explanation":"\"the Criterion\", from the word-by-word gloss at 3:4."},{"type":"fill_blank","question":"Type the root of فَرَقْنَا in Arabic (three letters).","correct":"فرق","explanation":"فرق. Diacritics are ignored when checking, so ف ر ق is enough."}]', '["root-rjl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ymn', 'The root يمن (ي م ن)', 'grammar', 4, '{"explanation":"The root يمن occurs 71 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْأَيْمَـٰنَ","transliteration":"","meaning":"(of) the oath","rule":"5:89"},{"arabic":"أَيْمَـٰنُهُمْ","transliteration":"","meaning":"their right hands","rule":"16:71"},{"arabic":"أَيْمَـٰنِهِمْ","transliteration":"","meaning":"(of) their oaths","rule":"5:53"},{"arabic":"يَمِينٍۢ","transliteration":"","meaning":"(the) right","rule":"34:15"},{"arabic":"ٱلْمَيْمَنَةِ","transliteration":"","meaning":"(of) the right","rule":"56:8"},{"arabic":"بِيَمِينِهِۦ","transliteration":"","meaning":"in his right hand","rule":"17:71"}],"rules":[{"name":"Words on يمن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْأَيْمَـٰنَ","أَيْمَـٰنُهُمْ","أَيْمَـٰنِهِمْ","يَمِينٍۢ","ٱلْمَيْمَنَةِ","بِيَمِينِهِۦ","أَيْمَـٰنُكُم","وَأَيْمَـٰنِهِمْ"]},{"name":"Parts of speech attested for يمن","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 25 glossed words attested.","examples":["ٱلْأَيْمَـٰنَ","أَيْمَـٰنُهُمْ","أَيْمَـٰنِهِمْ","يَمِينٍۢ","ٱلْمَيْمَنَةِ","بِيَمِينِهِۦ"]},{"name":"Where يمن occurs","description":"The 25 glossed words on this root are attested across 15 distinct surahs.","examples":["ٱلْأَيْمَـٰنَ (5:89)","أَيْمَـٰنُهُمْ (16:71)","أَيْمَـٰنِهِمْ (5:53)","يَمِينٍۢ (34:15)","ٱلْمَيْمَنَةِ (56:8)","بِيَمِينِهِۦ (17:71)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root يمن?","options":["فَأَخَذَتْهُمُ","ٱلْأَمْرِ","ٱلْأَيْمَـٰنَ","يَأْكُلَ"],"correct":2,"explanation":"ٱلْأَيْمَـٰنَ — glossed \"(of) the oath\" at 5:89 — carries the root يمن. The others come from different roots."},{"type":"multiple_choice","question":"What does أَيْمَـٰنُهُمْ mean?","options":["(all) ear","for the believers","its term","their right hands"],"correct":3,"explanation":"\"their right hands\", from the word-by-word gloss at 16:71."},{"type":"fill_blank","question":"Type the root of أَيْمَـٰنِهِمْ in Arabic (three letters).","correct":"يمن","explanation":"يمن. Diacritics are ignored when checking, so ي م ن is enough."}]', '["root-frq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Elw', 'The root علو (ع ل و)', 'grammar', 4, '{"explanation":"The root علو occurs 70 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, VI, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَعَـٰلَىٰ","transliteration":"","meaning":"Exalted is He","rule":"16:3"},{"arabic":"ٱلْعُلَىٰ","transliteration":"","meaning":"[the] high","rule":"20:75"},{"arabic":"عَالِينَ","transliteration":"","meaning":"haughty","rule":"23:46"},{"arabic":"ٱلْأَعْلَىٰٓ","transliteration":"","meaning":"the exalted","rule":"38:69"},{"arabic":"ٱلْأَعْلَوْنَ","transliteration":"","meaning":"[the] superior","rule":"3:139"},{"arabic":"عَلِيًّا","transliteration":"","meaning":"high","rule":"19:57"}],"rules":[{"name":"Words on علو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَعَـٰلَىٰ","ٱلْعُلَىٰ","عَالِينَ","ٱلْأَعْلَىٰٓ","ٱلْأَعْلَوْنَ","عَلِيًّا","عَالِيًۭا","لَعَالٍۢ"]},{"name":"Parts of speech attested for علو","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 33 glossed words attested.","examples":["تَعَـٰلَىٰ","ٱلْعُلَىٰ","عَالِينَ","ٱلْأَعْلَىٰٓ","ٱلْأَعْلَوْنَ","عَلِيًّا"]},{"name":"Verb forms attested for علو","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VI, X.","examples":["تَعَـٰلَىٰ","ٱلْعُلَىٰ","عَالِينَ","ٱلْأَعْلَىٰٓ","ٱلْأَعْلَوْنَ","عَلِيًّا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root علو?","options":["أَشْيَآءَهُمْ","فَخُذْ","تَعَـٰلَىٰ","يُؤْلُونَ"],"correct":2,"explanation":"تَعَـٰلَىٰ — glossed \"Exalted is He\" at 16:3 — carries the root علو. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْعُلَىٰ mean?","options":["and believe","[the] high","and gave him","(is) a poet"],"correct":1,"explanation":"\"[the] high\", from the word-by-word gloss at 20:75."},{"type":"fill_blank","question":"Type the root of عَالِينَ in Arabic (three letters).","correct":"علو","explanation":"علو. Diacritics are ignored when checking, so ع ل و is enough."}]', '["root-ymn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Erf', 'The root عرف (ع ر ف)', 'grammar', 4, '{"explanation":"The root عرف occurs 70 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VIII, VI, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَّعْرُوفٌۭ","transliteration":"","meaning":"kind","rule":"2:263"},{"arabic":"ٱلْمَعْرُوفِ","transliteration":"","meaning":"(is) the right","rule":"9:67"},{"arabic":"يَعْرِفُونَهَآ","transliteration":"","meaning":"may recognize it","rule":"12:62"},{"arabic":"فَتَعْرِفُونَهَا","transliteration":"","meaning":"and you will recognize them","rule":"27:93"},{"arabic":"مَّعْرُوفٍۢ","transliteration":"","meaning":"honorably","rule":"2:240"},{"arabic":"بِٱلْمَعْرُوفِ","transliteration":"","meaning":"with suitable","rule":"2:178"}],"rules":[{"name":"Words on عرف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَّعْرُوفٌۭ","ٱلْمَعْرُوفِ","يَعْرِفُونَهَآ","فَتَعْرِفُونَهَا","مَّعْرُوفٍۢ","بِٱلْمَعْرُوفِ","يَعْرِفُونَ","ٱعْتَرَفُوا۟"]},{"name":"Parts of speech attested for عرف","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 30 glossed words attested.","examples":["مَّعْرُوفٌۭ","ٱلْمَعْرُوفِ","يَعْرِفُونَهَآ","فَتَعْرِفُونَهَا","مَّعْرُوفٍۢ","بِٱلْمَعْرُوفِ"]},{"name":"Verb forms attested for عرف","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, VI, II.","examples":["مَّعْرُوفٌۭ","ٱلْمَعْرُوفِ","يَعْرِفُونَهَآ","فَتَعْرِفُونَهَا","مَّعْرُوفٍۢ","بِٱلْمَعْرُوفِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عرف?","options":["شَهِدْنَآ","مَّعْرُوفٌۭ","بِتَأْوِيلِهِۦ","يَأْكُلُ"],"correct":1,"explanation":"مَّعْرُوفٌۭ — glossed \"kind\" at 2:263 — carries the root عرف. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمَعْرُوفِ mean?","options":["(is) the right","its produce","a matter","(to) Allah"],"correct":0,"explanation":"\"(is) the right\", from the word-by-word gloss at 9:67."},{"type":"fill_blank","question":"Type the root of يَعْرِفُونَهَآ in Arabic (three letters).","correct":"عرف","explanation":"عرف. Diacritics are ignored when checking, so ع ر ف is enough."}]', '["root-Elw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mtE', 'The root متع (م ت ع)', 'grammar', 4, '{"explanation":"The root متع occurs 70 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 41 distinct glossed words, tagged in the corpus as N, V, in verb forms II, V, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَّتَـٰعًا","transliteration":"","meaning":"provision","rule":"2:240"},{"arabic":"فَٱسْتَمْتَعْتُم","transliteration":"","meaning":"and you have enjoyed","rule":"9:69"},{"arabic":"فَأُمَتِّعُهُۥ","transliteration":"","meaning":"[then] I will grant him enjoyment","rule":"2:126"},{"arabic":"وَمَتَّعْنَـٰهُمْ","transliteration":"","meaning":"and We granted them enjoyment","rule":"10:98"},{"arabic":"فَمَتِّعُوهُنَّ","transliteration":"","meaning":"So provide for them","rule":"33:49"},{"arabic":"أُمَتِّعْكُنَّ","transliteration":"","meaning":"I will provide for you","rule":"33:28"}],"rules":[{"name":"Words on متع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَّتَـٰعًا","فَٱسْتَمْتَعْتُم","فَأُمَتِّعُهُۥ","وَمَتَّعْنَـٰهُمْ","فَمَتِّعُوهُنَّ","أُمَتِّعْكُنَّ","مَّتَّعْتَهُمْ","تَمَتَّعُوا۟"]},{"name":"Parts of speech attested for متع","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 41 glossed words attested.","examples":["مَّتَـٰعًا","فَٱسْتَمْتَعْتُم","فَأُمَتِّعُهُۥ","وَمَتَّعْنَـٰهُمْ","فَمَتِّعُوهُنَّ","أُمَتِّعْكُنَّ"]},{"name":"Verb forms attested for متع","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V, X.","examples":["مَّتَـٰعًا","فَٱسْتَمْتَعْتُم","فَأُمَتِّعُهُۥ","وَمَتَّعْنَـٰهُمْ","فَمَتِّعُوهُنَّ","أُمَتِّعْكُنَّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root متع?","options":["أَمَرَ","مَّتَـٰعًا","ٱللَّهُ","وَشَهِدُوٓا۟"],"correct":1,"explanation":"مَّتَـٰعًا — glossed \"provision\" at 2:240 — carries the root متع. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱسْتَمْتَعْتُم mean?","options":["(the) worst","that surely you will bring him to me","and you have enjoyed","he believes"],"correct":2,"explanation":"\"and you have enjoyed\", from the word-by-word gloss at 9:69."},{"type":"fill_blank","question":"Type the root of فَأُمَتِّعُهُۥ in Arabic (three letters).","correct":"متع","explanation":"متع. Diacritics are ignored when checking, so م ت ع is enough."}]', '["root-Erf"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wkl', 'The root وكل (و ك ل)', 'grammar', 4, '{"explanation":"The root وكل occurs 70 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, in verb forms V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَتَوَكَّلَ","transliteration":"","meaning":"we put our trust","rule":"14:12"},{"arabic":"وَتَوَكَّلْ","transliteration":"","meaning":"and put (your) trust","rule":"4:81"},{"arabic":"يَتَوَكَّلُونَ","transliteration":"","meaning":"they put their trust","rule":"8:2"},{"arabic":"ٱلْمُتَوَكِّلِينَ","transliteration":"","meaning":"the ones who put trust (in Him)","rule":"3:159"},{"arabic":"وَكَّلْنَا","transliteration":"","meaning":"We have entrusted","rule":"6:89"},{"arabic":"وَكِيلٌۭ","transliteration":"","meaning":"a Guardian","rule":"6:102"}],"rules":[{"name":"Words on وكل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَتَوَكَّلَ","وَتَوَكَّلْ","يَتَوَكَّلُونَ","ٱلْمُتَوَكِّلِينَ","وَكَّلْنَا","وَكِيلٌۭ","يَتَوَكَّلُ","تَوَكَّلْنَا"]},{"name":"Parts of speech attested for وكل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 22 glossed words attested.","examples":["نَتَوَكَّلَ","وَتَوَكَّلْ","يَتَوَكَّلُونَ","ٱلْمُتَوَكِّلِينَ","وَكَّلْنَا","وَكِيلٌۭ"]},{"name":"Verb forms attested for وكل","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, II.","examples":["نَتَوَكَّلَ","وَتَوَكَّلْ","يَتَوَكَّلُونَ","ٱلْمُتَوَكِّلِينَ","وَكَّلْنَا","وَكِيلٌۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وكل?","options":["نَتَوَكَّلَ","أَمْرًۭا","ءَالِهَتُهُمُ","ٱللَّهِ"],"correct":0,"explanation":"نَتَوَكَّلَ — glossed \"we put our trust\" at 14:12 — carries the root وكل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَتَوَكَّلْ mean?","options":["So We seized them","desire","and put (your) trust","associate partners (with Allah)"],"correct":2,"explanation":"\"and put (your) trust\", from the word-by-word gloss at 4:81."},{"type":"fill_blank","question":"Type the root of يَتَوَكَّلُونَ in Arabic (three letters).","correct":"وكل","explanation":"وكل. Diacritics are ignored when checking, so و ك ل is enough."}]', '["root-mtE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Znn', 'The root ظنن (ظ ن ن)', 'grammar', 4, '{"explanation":"The root ظنن occurs 69 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَظُنُّكُمْ","transliteration":"","meaning":"we think you","rule":"11:27"},{"arabic":"وَظَنُّوٓا۟","transliteration":"","meaning":"and they thought","rule":"7:171"},{"arabic":"ٱلظَّنِّ","transliteration":"","meaning":"(of) assumption","rule":"4:157"},{"arabic":"وَظَنَّ","transliteration":"","meaning":"and think","rule":"10:24"},{"arabic":"ٱلظُّنُونَا۠","transliteration":"","meaning":"the assumptions","rule":"33:10"},{"arabic":"ظَنَنتُم","transliteration":"","meaning":"you assumed","rule":"41:23"}],"rules":[{"name":"Words on ظنن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَظُنُّكُمْ","وَظَنُّوٓا۟","ٱلظَّنِّ","وَظَنَّ","ٱلظُّنُونَا۠","ظَنَنتُم","ظَنًّۭا","ٱلظَّآنِّينَ"]},{"name":"Parts of speech attested for ظنن","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 30 glossed words attested.","examples":["نَظُنُّكُمْ","وَظَنُّوٓا۟","ٱلظَّنِّ","وَظَنَّ","ٱلظُّنُونَا۠","ظَنَنتُم"]},{"name":"Where ظنن occurs","description":"The 30 glossed words on this root are attested across 19 distinct surahs.","examples":["نَظُنُّكُمْ (11:27)","وَظَنُّوٓا۟ (7:171)","ٱلظَّنِّ (4:157)","وَظَنَّ (10:24)","ٱلظُّنُونَا۠ (33:10)","ظَنَنتُم (41:23)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ظنن?","options":["نَظُنُّكُمْ","خُذُوا۟","إِيمَـٰنِهِمْ","كُلِى"],"correct":0,"explanation":"نَظُنُّكُمْ — glossed \"we think you\" at 11:27 — carries the root ظنن. The others come from different roots."},{"type":"multiple_choice","question":"What does وَظَنُّوٓا۟ mean?","options":["you ordered them","and they thought","Allah has given me","Allah willed"],"correct":1,"explanation":"\"and they thought\", from the word-by-word gloss at 7:171."},{"type":"fill_blank","question":"Type the root of ٱلظَّنِّ in Arabic (three letters).","correct":"ظنن","explanation":"ظنن. Diacritics are ignored when checking, so ظ ن ن is enough."}]', '["root-wkl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-skn', 'The root سكن (س ك ن)', 'grammar', 4, '{"explanation":"The root سكن occurs 69 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 41 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَسَـٰكِنُهُمْ","transliteration":"","meaning":"(are) their dwellings","rule":"28:58"},{"arabic":"وَٱلْمِسْكِينَ","transliteration":"","meaning":"and the needy","rule":"17:26"},{"arabic":"مَسَـٰكِنِ","transliteration":"","meaning":"the dwellings","rule":"14:45"},{"arabic":"سَكَنَ","transliteration":"","meaning":"dwells","rule":"6:13"},{"arabic":"وَمَسَـٰكِنِكُمْ","transliteration":"","meaning":"and to your homes","rule":"21:13"},{"arabic":"وَٱلْمَسَـٰكِينَ","transliteration":"","meaning":"and the needy","rule":"2:177"}],"rules":[{"name":"Words on سكن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَسَـٰكِنُهُمْ","وَٱلْمِسْكِينَ","مَسَـٰكِنِ","سَكَنَ","وَمَسَـٰكِنِكُمْ","وَٱلْمَسَـٰكِينَ","لِيَسْكُنُوا۟","سَكِينَةٌۭ"]},{"name":"Parts of speech attested for سكن","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 41 glossed words attested.","examples":["مَسَـٰكِنُهُمْ","وَٱلْمِسْكِينَ","مَسَـٰكِنِ","سَكَنَ","وَمَسَـٰكِنِكُمْ","وَٱلْمَسَـٰكِينَ"]},{"name":"Verb forms attested for سكن","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["مَسَـٰكِنُهُمْ","وَٱلْمِسْكِينَ","مَسَـٰكِنِ","سَكَنَ","وَمَسَـٰكِنِكُمْ","وَٱلْمَسَـٰكِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سكن?","options":["أَحَدُكُمْ","مُّشْرِكَةٍۢ","فَأَجْرُهُۥ","مَسَـٰكِنُهُمْ"],"correct":3,"explanation":"مَسَـٰكِنُهُمْ — glossed \"(are) their dwellings\" at 28:58 — carries the root سكن. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْمِسْكِينَ mean?","options":["(is) the Mother (of) the Book","and remembered","and the needy","any god"],"correct":2,"explanation":"\"and the needy\", from the word-by-word gloss at 17:26."},{"type":"fill_blank","question":"Type the root of مَسَـٰكِنِ in Arabic (three letters).","correct":"سكن","explanation":"سكن. Diacritics are ignored when checking, so س ك ن is enough."}]', '["root-Znn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-hlk', 'The root هلك (ه ل ك)', 'grammar', 4, '{"explanation":"The root هلك occurs 68 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُهْلِكَ","transliteration":"","meaning":"destroy","rule":"5:17"},{"arabic":"أَهْلَكْتَهُم","transliteration":"","meaning":"You (could) have destroyed them","rule":"7:155"},{"arabic":"أَهْلَكْنَـٰهَا","transliteration":"","meaning":"We destroyed it","rule":"7:4"},{"arabic":"لِيُهْلِكَ","transliteration":"","meaning":"destroy","rule":"11:117"},{"arabic":"فَأَهْلَكَتْهُ","transliteration":"","meaning":"then destroyed it","rule":"3:117"},{"arabic":"وَيُهْلِكَ","transliteration":"","meaning":"and destroys","rule":"2:205"}],"rules":[{"name":"Words on هلك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُهْلِكَ","أَهْلَكْتَهُم","أَهْلَكْنَـٰهَا","لِيُهْلِكَ","فَأَهْلَكَتْهُ","وَيُهْلِكَ","مُهْلِكُهُمْ","هَالِكٌ"]},{"name":"Parts of speech attested for هلك","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 35 glossed words attested.","examples":["يُهْلِكَ","أَهْلَكْتَهُم","أَهْلَكْنَـٰهَا","لِيُهْلِكَ","فَأَهْلَكَتْهُ","وَيُهْلِكَ"]},{"name":"Verb forms attested for هلك","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["يُهْلِكَ","أَهْلَكْتَهُم","أَهْلَكْنَـٰهَا","لِيُهْلِكَ","فَأَهْلَكَتْهُ","وَيُهْلِكَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root هلك?","options":["أَهْلَكَ","وَءَاتَيْنَـٰهُمَا","يُهْلِكَ","فَلِلَّهِ"],"correct":2,"explanation":"يُهْلِكَ — glossed \"destroy\" at 5:17 — carries the root هلك. The others come from different roots."},{"type":"multiple_choice","question":"What does أَهْلَكْتَهُم mean?","options":["the last","Allah accepts repentance","So go both of you","You (could) have destroyed them"],"correct":3,"explanation":"\"You (could) have destroyed them\", from the word-by-word gloss at 7:155."},{"type":"fill_blank","question":"Type the root of أَهْلَكْنَـٰهَا in Arabic (three letters).","correct":"هلك","explanation":"هلك. Diacritics are ignored when checking, so ه ل ك is enough."}]', '["root-skn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wHd', 'The root وحد (و ح د)', 'grammar', 4, '{"explanation":"The root وحد occurs 68 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as ADJ, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَحْدَهُ","transliteration":"","meaning":"Alone","rule":"39:45"},{"arabic":"فَوَٰحِدَةً","transliteration":"","meaning":"then (marry) one","rule":"4:3"},{"arabic":"وَٰحِدٌۭ","transliteration":"","meaning":"one (only)","rule":"2:163"},{"arabic":"وَٰحِدًا","transliteration":"","meaning":"(into) one god","rule":"38:5"},{"arabic":"وَٰحِدَةًۭ","transliteration":"","meaning":"single","rule":"2:213"},{"arabic":"وَٰحِدٍۢ","transliteration":"","meaning":"(of) one (kind)","rule":"2:61"}],"rules":[{"name":"Words on وحد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَحْدَهُ","فَوَٰحِدَةً","وَٰحِدٌۭ","وَٰحِدًا","وَٰحِدَةًۭ","وَٰحِدٍۢ","ٱلْوَٰحِدِ","ٱلْوَٰحِدُ"]},{"name":"Parts of speech attested for وحد","description":"The morphology corpus tags words on this root as ADJ, N — 2 distinct parts of speech across the 15 glossed words attested.","examples":["وَحْدَهُ","فَوَٰحِدَةً","وَٰحِدٌۭ","وَٰحِدًا","وَٰحِدَةًۭ","وَٰحِدٍۢ"]},{"name":"Where وحد occurs","description":"The 15 glossed words on this root are attested across 10 distinct surahs.","examples":["وَحْدَهُ (39:45)","فَوَٰحِدَةً (4:3)","وَٰحِدٌۭ (2:163)","وَٰحِدًا (38:5)","وَٰحِدَةًۭ (2:213)","وَٰحِدٍۢ (2:61)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وحد?","options":["وَحْدَهُ","ٱذْكُرْ","وَذِكْرَىٰ","أَهْلِهِۦ"],"correct":0,"explanation":"وَحْدَهُ — glossed \"Alone\" at 39:45 — carries the root وحد. The others come from different roots."},{"type":"multiple_choice","question":"What does فَوَٰحِدَةً mean?","options":["then give permission","and the witnesses","then (marry) one","(of) Abu"],"correct":2,"explanation":"\"then (marry) one\", from the word-by-word gloss at 4:3."},{"type":"fill_blank","question":"Type the root of وَٰحِدٌۭ in Arabic (three letters).","correct":"وحد","explanation":"وحد. Diacritics are ignored when checking, so و ح د is enough."}]', '["root-hlk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bEv', 'The root بعث (ب ع ث)', 'grammar', 4, '{"explanation":"The root بعث occurs 67 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, in verb form VII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُبْعَثُ","transliteration":"","meaning":"he will be raised","rule":"19:15"},{"arabic":"وَبَعَثْنَا","transliteration":"","meaning":"and We appointed","rule":"5:12"},{"arabic":"تُبْعَثُونَ","transliteration":"","meaning":"will be resurrected","rule":"23:16"},{"arabic":"ٱنۢبِعَاثَهُمْ","transliteration":"","meaning":"their being sent","rule":"9:46"},{"arabic":"أُبْعَثُ","transliteration":"","meaning":"I will be raised","rule":"19:33"},{"arabic":"لَيَبْعَثَنَّ","transliteration":"","meaning":"that He would surely send","rule":"7:167"}],"rules":[{"name":"Words on بعث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُبْعَثُ","وَبَعَثْنَا","تُبْعَثُونَ","ٱنۢبِعَاثَهُمْ","أُبْعَثُ","لَيَبْعَثَنَّ","فَٱبْعَثُوا۟","بَعَثْنَا"]},{"name":"Parts of speech attested for بعث","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 32 glossed words attested.","examples":["يُبْعَثُ","وَبَعَثْنَا","تُبْعَثُونَ","ٱنۢبِعَاثَهُمْ","أُبْعَثُ","لَيَبْعَثَنَّ"]},{"name":"Verb forms attested for بعث","description":"Where this root is tagged as a verb, the corpus attests derived Form VII.","examples":["يُبْعَثُ","وَبَعَثْنَا","تُبْعَثُونَ","ٱنۢبِعَاثَهُمْ","أُبْعَثُ","لَيَبْعَثَنَّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بعث?","options":["ٱلشَّيَـٰطِينِ","ٱلْمُؤْمِنُ","شَاكِلَتِهِۦ","يُبْعَثُ"],"correct":3,"explanation":"يُبْعَثُ — glossed \"he will be raised\" at 19:15 — carries the root بعث. The others come from different roots."},{"type":"multiple_choice","question":"What does وَبَعَثْنَا mean?","options":["gods","Then go","(are) brothers","and We appointed"],"correct":3,"explanation":"\"and We appointed\", from the word-by-word gloss at 5:12."},{"type":"fill_blank","question":"Type the root of تُبْعَثُونَ in Arabic (three letters).","correct":"بعث","explanation":"بعث. Diacritics are ignored when checking, so ب ع ث is enough."}]', '["root-wHd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ksb', 'The root كسب (ك س ب)', 'grammar', 4, '{"explanation":"The root كسب occurs 67 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَكْسِبُ","transliteration":"","meaning":"earns","rule":"6:164"},{"arabic":"كَسَبُوا۟","transliteration":"","meaning":"they earned","rule":"2:202"},{"arabic":"كَسَبَ","transliteration":"","meaning":"earned","rule":"2:81"},{"arabic":"ٱكْتَسَبْنَ","transliteration":"","meaning":"they earned","rule":"4:32"},{"arabic":"ٱكْتَسَبَ","transliteration":"","meaning":"he earned","rule":"24:11"},{"arabic":"يَكْسِبْ","transliteration":"","meaning":"earns","rule":"4:111"}],"rules":[{"name":"Words on كسب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَكْسِبُ","كَسَبُوا۟","كَسَبَ","ٱكْتَسَبْنَ","ٱكْتَسَبَ","يَكْسِبْ","كَسَبُوٓا۟","كَسَبَا"]},{"name":"Parts of speech attested for كسب","description":"The morphology corpus tags words on this root as V — one part of speech across the 15 glossed words attested.","examples":["تَكْسِبُ","كَسَبُوا۟","كَسَبَ","ٱكْتَسَبْنَ","ٱكْتَسَبَ","يَكْسِبْ"]},{"name":"Verb forms attested for كسب","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["تَكْسِبُ","كَسَبُوا۟","كَسَبَ","ٱكْتَسَبْنَ","ٱكْتَسَبَ","يَكْسِبْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كسب?","options":["شَرِّ","تَكْسِبُ","لِأَهْلِهِۦٓ","خُذُوا۟"],"correct":1,"explanation":"تَكْسِبُ — glossed \"earns\" at 6:164 — carries the root كسب. The others come from different roots."},{"type":"multiple_choice","question":"What does كَسَبُوا۟ mean?","options":["(is) surely a thing","(of) his brother","so We seized him","they earned"],"correct":3,"explanation":"\"they earned\", from the word-by-word gloss at 2:202."},{"type":"fill_blank","question":"Type the root of كَسَبَ in Arabic (three letters).","correct":"كسب","explanation":"كسب. Diacritics are ignored when checking, so ك س ب is enough."}]', '["root-bEv"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jrm', 'The root جرم (ج ر م)', 'grammar', 4, '{"explanation":"The root جرم occurs 66 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُّجْرِمُونَ","transliteration":"","meaning":"criminals","rule":"44:22"},{"arabic":"ٱلْمُجْرِمِينَ","transliteration":"","meaning":"(of) the criminals","rule":"6:55"},{"arabic":"مُّجْرِمِينَ","transliteration":"","meaning":"criminal","rule":"7:133"},{"arabic":"بِٱلْمُجْرِمِينَ","transliteration":"","meaning":"with the criminals","rule":"37:34"},{"arabic":"أَجْرَمُوا۟","transliteration":"","meaning":"committed crimes","rule":"6:124"},{"arabic":"لِّلْمُجْرِمِينَ","transliteration":"","meaning":"for the criminals","rule":"25:22"}],"rules":[{"name":"Words on جرم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُّجْرِمُونَ","ٱلْمُجْرِمِينَ","مُّجْرِمِينَ","بِٱلْمُجْرِمِينَ","أَجْرَمُوا۟","لِّلْمُجْرِمِينَ","مُجْرِمِيهَا","جَرَمَ"]},{"name":"Parts of speech attested for جرم","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 15 glossed words attested.","examples":["مُّجْرِمُونَ","ٱلْمُجْرِمِينَ","مُّجْرِمِينَ","بِٱلْمُجْرِمِينَ","أَجْرَمُوا۟","لِّلْمُجْرِمِينَ"]},{"name":"Verb forms attested for جرم","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["مُّجْرِمُونَ","ٱلْمُجْرِمِينَ","مُّجْرِمِينَ","بِٱلْمُجْرِمِينَ","أَجْرَمُوا۟","لِّلْمُجْرِمِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جرم?","options":["ءَالِهَةٌ","أَلَّفْتَ","مُّجْرِمُونَ","وَأَصِيلًا"],"correct":2,"explanation":"مُّجْرِمُونَ — glossed \"criminals\" at 44:22 — carries the root جرم. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُجْرِمِينَ mean?","options":["O you who believe","He (has) given you","(of) the criminals","any intercessor"],"correct":2,"explanation":"\"(of) the criminals\", from the word-by-word gloss at 6:55."},{"type":"fill_blank","question":"Type the root of مُّجْرِمِينَ in Arabic (three letters).","correct":"جرم","explanation":"جرم. Diacritics are ignored when checking, so ج ر م is enough."}]', '["root-ksb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wfy', 'The root وفي (و ف ي)', 'grammar', 4, '{"explanation":"The root وفي occurs 66 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 40 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, V, II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَيُوَفِّيهِمْ","transliteration":"","meaning":"then He will grant them in full","rule":"3:57"},{"arabic":"يُتَوَفَّوْنَ","transliteration":"","meaning":"pass away","rule":"2:234"},{"arabic":"فَأَوْفُوا۟","transliteration":"","meaning":"So give full","rule":"7:85"},{"arabic":"أَوْفُوا۟","transliteration":"","meaning":"Fulfil","rule":"5:1"},{"arabic":"لَمُوَفُّوهُمْ","transliteration":"","meaning":"will surely pay them in full","rule":"11:109"},{"arabic":"وَتُوَفَّىٰ","transliteration":"","meaning":"and will be paid in full","rule":"16:111"}],"rules":[{"name":"Words on وفي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَيُوَفِّيهِمْ","يُتَوَفَّوْنَ","فَأَوْفُوا۟","أَوْفُوا۟","لَمُوَفُّوهُمْ","وَتُوَفَّىٰ","وَٱلْمُوفُونَ","وَأَوْفُوا۟"]},{"name":"Parts of speech attested for وفي","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 40 glossed words attested.","examples":["فَيُوَفِّيهِمْ","يُتَوَفَّوْنَ","فَأَوْفُوا۟","أَوْفُوا۟","لَمُوَفُّوهُمْ","وَتُوَفَّىٰ"]},{"name":"Verb forms attested for وفي","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, V, II, X.","examples":["فَيُوَفِّيهِمْ","يُتَوَفَّوْنَ","فَأَوْفُوا۟","أَوْفُوا۟","لَمُوَفُّوهُمْ","وَتُوَفَّىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وفي?","options":["فَيُوَفِّيهِمْ","ءَايَـٰتِنَا","وَلِلَّهِ","ٱلْأُنثَىٰ"],"correct":0,"explanation":"فَيُوَفِّيهِمْ — glossed \"then He will grant them in full\" at 3:57 — carries the root وفي. The others come from different roots."},{"type":"multiple_choice","question":"What does يُتَوَفَّوْنَ mean?","options":["And Allah makes clear","pass away","(are the) worst","grateful"],"correct":1,"explanation":"\"pass away\", from the word-by-word gloss at 2:234."},{"type":"fill_blank","question":"Type the root of فَأَوْفُوا۟ in Arabic (three letters).","correct":"وفي","explanation":"وفي. Diacritics are ignored when checking, so و ف ي is enough."}]', '["root-jrm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Eyn', 'The root عين (ع ي ن)', 'grammar', 4, '{"explanation":"The root عين occurs 65 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 36 distinct glossed words, tagged in the corpus as N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَعْيُنُكُمْ","transliteration":"","meaning":"your eyes","rule":"11:31"},{"arabic":"ٱلْأَعْيُنِ","transliteration":"","meaning":"(the) stealthy glance","rule":"40:19"},{"arabic":"عُيُونًۭا","transliteration":"","meaning":"(with) springs","rule":"54:12"},{"arabic":"وَعُيُونٍۢ","transliteration":"","meaning":"and springs","rule":"26:57"},{"arabic":"عَيْنَيْكَ","transliteration":"","meaning":"your eyes","rule":"15:88"},{"arabic":"مَّعِينٍۭ","transliteration":"","meaning":"a flowing spring","rule":"37:45"}],"rules":[{"name":"Words on عين","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَعْيُنُكُمْ","ٱلْأَعْيُنِ","عُيُونًۭا","وَعُيُونٍۢ","عَيْنَيْكَ","مَّعِينٍۭ","عَيْنِىٓ","أَعْيُنَ"]},{"name":"Parts of speech attested for عين","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 36 glossed words attested.","examples":["أَعْيُنُكُمْ","ٱلْأَعْيُنِ","عُيُونًۭا","وَعُيُونٍۢ","عَيْنَيْكَ","مَّعِينٍۭ"]},{"name":"Where عين occurs","description":"The 36 glossed words on this root are attested across 26 distinct surahs.","examples":["أَعْيُنُكُمْ (11:31)","ٱلْأَعْيُنِ (40:19)","عُيُونًۭا (54:12)","وَعُيُونٍۢ (26:57)","عَيْنَيْكَ (15:88)","مَّعِينٍۭ (37:45)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عين?","options":["شَطْرَهُۥ","وَٱلْأَذَىٰ","أَعْيُنُكُمْ","إِخْوَةًۭ"],"correct":2,"explanation":"أَعْيُنُكُمْ — glossed \"your eyes\" at 11:31 — carries the root عين. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْأَعْيُنِ mean?","options":["(will) come (for) them","We took","(the) stealthy glance","An ear"],"correct":2,"explanation":"\"(the) stealthy glance\", from the word-by-word gloss at 40:19."},{"type":"fill_blank","question":"Type the root of عُيُونًۭا in Arabic (three letters).","correct":"عين","explanation":"عين. Diacritics are ignored when checking, so ع ي ن is enough."}]', '["root-wfy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xsr', 'The root خسر (خ س ر)', 'grammar', 4, '{"explanation":"The root خسر occurs 65 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْخَـٰسِرُونَ","transliteration":"","meaning":"(are) the losers","rule":"2:27"},{"arabic":"تُخْسِرُوا۟","transliteration":"","meaning":"make deficient","rule":"55:9"},{"arabic":"خُسْرَانًۭا","transliteration":"","meaning":"a loss","rule":"4:119"},{"arabic":"لَّخَـٰسِرُونَ","transliteration":"","meaning":"(will be) certainly losers","rule":"7:90"},{"arabic":"ٱلْخَـٰسِرِينَ","transliteration":"","meaning":"the losers","rule":"2:64"},{"arabic":"خَسِرُوٓا۟","transliteration":"","meaning":"have lost","rule":"6:12"}],"rules":[{"name":"Words on خسر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْخَـٰسِرُونَ","تُخْسِرُوا۟","خُسْرَانًۭا","لَّخَـٰسِرُونَ","ٱلْخَـٰسِرِينَ","خَسِرُوٓا۟","بِٱلْأَخْسَرِينَ","تَخْسِيرٍۢ"]},{"name":"Parts of speech attested for خسر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 17 glossed words attested.","examples":["ٱلْخَـٰسِرُونَ","تُخْسِرُوا۟","خُسْرَانًۭا","لَّخَـٰسِرُونَ","ٱلْخَـٰسِرِينَ","خَسِرُوٓا۟"]},{"name":"Verb forms attested for خسر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV.","examples":["ٱلْخَـٰسِرُونَ","تُخْسِرُوا۟","خُسْرَانًۭا","لَّخَـٰسِرُونَ","ٱلْخَـٰسِرِينَ","خَسِرُوٓا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خسر?","options":["وَذِكْرًۭا","يَشْفَعْ","ٱلْخَـٰسِرُونَ","مُؤْمِنٍ"],"correct":2,"explanation":"ٱلْخَـٰسِرُونَ — glossed \"(are) the losers\" at 2:27 — carries the root خسر. The others come from different roots."},{"type":"multiple_choice","question":"What does تُخْسِرُوا۟ mean?","options":["they (can) delay (it)","and the god","make deficient","(to) Allah"],"correct":2,"explanation":"\"make deficient\", from the word-by-word gloss at 55:9."},{"type":"fill_blank","question":"Type the root of خُسْرَانًۭا in Arabic (three letters).","correct":"خسر","explanation":"خسر. Diacritics are ignored when checking, so خ س ر is enough."}]', '["root-Eyn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hml', 'The root حمل (ح م ل)', 'grammar', 4, '{"explanation":"The root حمل occurs 64 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 48 distinct glossed words, tagged in the corpus as V, N, in verb forms II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُحْمَلْ","transliteration":"","meaning":"will be carried","rule":"35:18"},{"arabic":"حَمَلَتْهُ","transliteration":"","meaning":"carried him","rule":"31:14"},{"arabic":"وَلَيَحْمِلُنَّ","transliteration":"","meaning":"But surely they will carry","rule":"29:13"},{"arabic":"لِتَحْمِلَهُمْ","transliteration":"","meaning":"that you provide them with mounts","rule":"9:92"},{"arabic":"فَٱحْتَمَلَ","transliteration":"","meaning":"and carries","rule":"13:17"},{"arabic":"ٱحْتَمَلَ","transliteration":"","meaning":"he (has) burdened (himself)","rule":"4:112"}],"rules":[{"name":"Words on حمل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُحْمَلْ","حَمَلَتْهُ","وَلَيَحْمِلُنَّ","لِتَحْمِلَهُمْ","فَٱحْتَمَلَ","ٱحْتَمَلَ","حُمِّلْنَآ","يَحْمِلُ"]},{"name":"Parts of speech attested for حمل","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 48 glossed words attested.","examples":["يُحْمَلْ","حَمَلَتْهُ","وَلَيَحْمِلُنَّ","لِتَحْمِلَهُمْ","فَٱحْتَمَلَ","ٱحْتَمَلَ"]},{"name":"Verb forms attested for حمل","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VIII.","examples":["يُحْمَلْ","حَمَلَتْهُ","وَلَيَحْمِلُنَّ","لِتَحْمِلَهُمْ","فَٱحْتَمَلَ","ٱحْتَمَلَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حمل?","options":["يَشَآءُ","يُحْمَلْ","وَلِلْمُؤْمِنِينَ","أَتَيْنَا"],"correct":1,"explanation":"يُحْمَلْ — glossed \"will be carried\" at 35:18 — carries the root حمل. The others come from different roots."},{"type":"multiple_choice","question":"What does حَمَلَتْهُ mean?","options":["(the) command","carried him","you give to me","(is) a hurt"],"correct":1,"explanation":"\"carried him\", from the word-by-word gloss at 31:14."},{"type":"fill_blank","question":"Type the root of وَلَيَحْمِلُنَّ in Arabic (three letters).","correct":"حمل","explanation":"حمل. Diacritics are ignored when checking, so ح م ل is enough."}]', '["root-xsr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jry', 'The root جري (ج ر ي)', 'grammar', 4, '{"explanation":"The root جري occurs 64 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَٱلْجَـٰرِيَـٰتِ","transliteration":"","meaning":"And those sailing","rule":"51:3"},{"arabic":"لِتَجْرِىَ","transliteration":"","meaning":"so that they may sail","rule":"14:32"},{"arabic":"يَجْرِىٓ","transliteration":"","meaning":"moving","rule":"31:29"},{"arabic":"تَجْرِيَانِ","transliteration":"","meaning":"flowing","rule":"55:50"},{"arabic":"يَجْرِى","transliteration":"","meaning":"running","rule":"13:2"},{"arabic":"مَجْر۪ىٰهَا","transliteration":"","meaning":"(is) its course","rule":"11:41"}],"rules":[{"name":"Words on جري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَٱلْجَـٰرِيَـٰتِ","لِتَجْرِىَ","يَجْرِىٓ","تَجْرِيَانِ","يَجْرِى","مَجْر۪ىٰهَا","ٱلْجَارِيَةِ","وَجَرَيْنَ"]},{"name":"Parts of speech attested for جري","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 11 glossed words attested.","examples":["فَٱلْجَـٰرِيَـٰتِ","لِتَجْرِىَ","يَجْرِىٓ","تَجْرِيَانِ","يَجْرِى","مَجْر۪ىٰهَا"]},{"name":"Where جري occurs","description":"The 11 glossed words on this root are attested across 11 distinct surahs.","examples":["فَٱلْجَـٰرِيَـٰتِ (51:3)","لِتَجْرِىَ (14:32)","يَجْرِىٓ (31:29)","تَجْرِيَانِ (55:50)","يَجْرِى (13:2)","مَجْر۪ىٰهَا (11:41)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جري?","options":["أُجِّلَتْ","يَأْتِيَهُم","ٱللَّهُ","فَٱلْجَـٰرِيَـٰتِ"],"correct":3,"explanation":"فَٱلْجَـٰرِيَـٰتِ — glossed \"And those sailing\" at 51:3 — carries the root جري. The others come from different roots."},{"type":"multiple_choice","question":"What does لِتَجْرِىَ mean?","options":["Allah will raise them","so that they may sail","any drink","but Allah came"],"correct":1,"explanation":"\"so that they may sail\", from the word-by-word gloss at 14:32."},{"type":"fill_blank","question":"Type the root of يَجْرِىٓ in Arabic (three letters).","correct":"جري","explanation":"جري. Diacritics are ignored when checking, so ج ر ي is enough."}]', '["root-Hml"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*wq', 'The root ذوق (ذ و ق)', 'grammar', 4, '{"explanation":"The root ذوق occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَذُوقُوا۟","transliteration":"","meaning":"Taste","rule":"8:50"},{"arabic":"لَّأَذَقْنَـٰكَ","transliteration":"","meaning":"We (would) have made you taste","rule":"17:75"},{"arabic":"لِّنُذِيقَهُمْ","transliteration":"","meaning":"that We may make them taste","rule":"41:16"},{"arabic":"يَذُوقُونَ","transliteration":"","meaning":"they will taste","rule":"44:56"},{"arabic":"نُذِقْهُ","transliteration":"","meaning":"We will make him taste","rule":"25:19"},{"arabic":"ذَآئِقَةُ","transliteration":"","meaning":"(will) taste","rule":"3:185"}],"rules":[{"name":"Words on ذوق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَذُوقُوا۟","لَّأَذَقْنَـٰكَ","لِّنُذِيقَهُمْ","يَذُوقُونَ","نُذِقْهُ","ذَآئِقَةُ","ذَاقُوا۟","وَتَذُوقُوا۟"]},{"name":"Parts of speech attested for ذوق","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 33 glossed words attested.","examples":["وَذُوقُوا۟","لَّأَذَقْنَـٰكَ","لِّنُذِيقَهُمْ","يَذُوقُونَ","نُذِقْهُ","ذَآئِقَةُ"]},{"name":"Verb forms attested for ذوق","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَذُوقُوا۟","لَّأَذَقْنَـٰكَ","لِّنُذِيقَهُمْ","يَذُوقُونَ","نُذِقْهُ","ذَآئِقَةُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذوق?","options":["شَـٰهِدِينَ","وَءَاتَىٰكُم","وَذُوقُوا۟","ٱلْأَرْضِ"],"correct":2,"explanation":"وَذُوقُوا۟ — glossed \"Taste\" at 8:50 — carries the root ذوق. The others come from different roots."},{"type":"multiple_choice","question":"What does لَّأَذَقْنَـٰكَ mean?","options":["So Allah seized them","(is) a good reward","We (would) have made you taste","(as) a witness"],"correct":2,"explanation":"\"We (would) have made you taste\", from the word-by-word gloss at 17:75."},{"type":"fill_blank","question":"Type the root of لِّنُذِيقَهُمْ in Arabic (three letters).","correct":"ذوق","explanation":"ذوق. Diacritics are ignored when checking, so ذ و ق is enough."}]', '["root-jry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ewd', 'The root عود (ع و د)', 'grammar', 4, '{"explanation":"The root عود occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 36 distinct glossed words, tagged in the corpus as V, N, PN, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَادًا","transliteration":"","meaning":"Aad","rule":"53:50"},{"arabic":"أُعِيدُوا۟","transliteration":"","meaning":"they will be returned","rule":"22:22"},{"arabic":"سَنُعِيدُهَا","transliteration":"","meaning":"We will return it","rule":"20:21"},{"arabic":"عَادٌ","transliteration":"","meaning":"(the people) of Aad","rule":"26:123"},{"arabic":"عُدتُّمْ","transliteration":"","meaning":"you return","rule":"17:8"},{"arabic":"عَادَ","transliteration":"","meaning":"repeated","rule":"2:275"}],"rules":[{"name":"Words on عود","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَادًا","أُعِيدُوا۟","سَنُعِيدُهَا","عَادٌ","عُدتُّمْ","عَادَ","عُدْنَا","عَادٍۢ"]},{"name":"Parts of speech attested for عود","description":"The morphology corpus tags words on this root as V, N, PN — 3 distinct parts of speech across the 36 glossed words attested.","examples":["عَادًا","أُعِيدُوا۟","سَنُعِيدُهَا","عَادٌ","عُدتُّمْ","عَادَ"]},{"name":"Verb forms attested for عود","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["عَادًا","أُعِيدُوا۟","سَنُعِيدُهَا","عَادٌ","عُدتُّمْ","عَادَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عود?","options":["عَادًا","فَخُذُوهُ","ٱلشَّهَوَٰتِ","أُذُنُ"],"correct":0,"explanation":"عَادًا — glossed \"Aad\" at 53:50 — carries the root عود. The others come from different roots."},{"type":"multiple_choice","question":"What does أُعِيدُوا۟ mean?","options":["(from) his father","they will be returned","to the believers","remember"],"correct":1,"explanation":"\"they will be returned\", from the word-by-word gloss at 22:22."},{"type":"fill_blank","question":"Type the root of سَنُعِيدُهَا in Arabic (three letters).","correct":"عود","explanation":"عود. Diacritics are ignored when checking, so ع و د is enough."}]', '["root-*wq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hmd', 'The root حمد (ح م د)', 'grammar', 4, '{"explanation":"The root حمد occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, ADJ, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْحَمْدُ","transliteration":"","meaning":"All praises and thanks","rule":"1:2"},{"arabic":"ٱلْحَمِيدُ","transliteration":"","meaning":"the Praiseworthy","rule":"22:64"},{"arabic":"بِحَمْدِهِۦ","transliteration":"","meaning":"with his praise","rule":"13:13"},{"arabic":"وَٱلْحَمْدُ","transliteration":"","meaning":"And all praises and thanks","rule":"6:45"},{"arabic":"بِحَمْدِ","transliteration":"","meaning":"with the praise","rule":"15:98"},{"arabic":"ٱلْحَـٰمِدُونَ","transliteration":"","meaning":"those who praise","rule":"9:112"}],"rules":[{"name":"Words on حمد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْحَمْدُ","ٱلْحَمِيدُ","بِحَمْدِهِۦ","وَٱلْحَمْدُ","بِحَمْدِ","ٱلْحَـٰمِدُونَ","بِحَمْدِكَ","ٱلْحَمِيدِ"]},{"name":"Parts of speech attested for حمد","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 14 glossed words attested.","examples":["ٱلْحَمْدُ","ٱلْحَمِيدُ","بِحَمْدِهِۦ","وَٱلْحَمْدُ","بِحَمْدِ","ٱلْحَـٰمِدُونَ"]},{"name":"Where حمد occurs","description":"The 14 glossed words on this root are attested across 13 distinct surahs.","examples":["ٱلْحَمْدُ (1:2)","ٱلْحَمِيدُ (22:64)","بِحَمْدِهِۦ (13:13)","وَٱلْحَمْدُ (6:45)","بِحَمْدِ (15:98)","ٱلْحَـٰمِدُونَ (9:112)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حمد?","options":["ٱلْحَمْدُ","ءَاذَانَ","شِرْبٍۢ","ذَهَابٍۭ"],"correct":0,"explanation":"ٱلْحَمْدُ — glossed \"All praises and thanks\" at 1:2 — carries the root حمد. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْحَمِيدُ mean?","options":["and believes","and orders you","the Praiseworthy","associate partners"],"correct":2,"explanation":"\"the Praiseworthy\", from the word-by-word gloss at 22:64."},{"type":"fill_blank","question":"Type the root of بِحَمْدِهِۦ in Arabic (three letters).","correct":"حمد","explanation":"حمد. Diacritics are ignored when checking, so ح م د is enough."}]', '["root-Ewd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mwh', 'The root موه (م و ه)', 'grammar', 4, '{"explanation":"The root موه occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمَآءَ","transliteration":"","meaning":"the water","rule":"7:57"},{"arabic":"مَآءَ","transliteration":"","meaning":"(to the) water","rule":"28:23"},{"arabic":"مَآؤُهَا","transliteration":"","meaning":"its water","rule":"18:41"},{"arabic":"مَّآءٍ","transliteration":"","meaning":"water","rule":"47:15"},{"arabic":"كَمَآءٍ","transliteration":"","meaning":"(is) like (the) water","rule":"10:24"},{"arabic":"مَآءًۭ","transliteration":"","meaning":"water","rule":"2:22"}],"rules":[{"name":"Words on موه","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمَآءَ","مَآءَ","مَآؤُهَا","مَّآءٍ","كَمَآءٍ","مَآءًۭ","مَآءً","مَآؤُكُمْ"]},{"name":"Parts of speech attested for موه","description":"The morphology corpus tags words on this root as N — one part of speech across the 17 glossed words attested.","examples":["ٱلْمَآءَ","مَآءَ","مَآؤُهَا","مَّآءٍ","كَمَآءٍ","مَآءًۭ"]},{"name":"Where موه occurs","description":"The 17 glossed words on this root are attested across 14 distinct surahs.","examples":["ٱلْمَآءَ (7:57)","مَآءَ (28:23)","مَآؤُهَا (18:41)","مَّآءٍ (47:15)","كَمَآءٍ (10:24)","مَآءًۭ (2:22)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root موه?","options":["ٱلْمَآءَ","ٱئْتِنَا","لِّلَّهِ","إِثْمًۭا"],"correct":0,"explanation":"ٱلْمَآءَ — glossed \"the water\" at 7:57 — carries the root موه. The others come from different roots."},{"type":"multiple_choice","question":"What does مَآءَ mean?","options":["(to the) water","our forefathers","Allah has given","(to) their forefathers"],"correct":0,"explanation":"\"(to the) water\", from the word-by-word gloss at 28:23."},{"type":"fill_blank","question":"Type the root of مَآؤُهَا in Arabic (three letters).","correct":"موه","explanation":"موه. Diacritics are ignored when checking, so م و ه is enough."}]', '["root-Hmd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qDy', 'The root قضي (ق ض ي)', 'grammar', 4, '{"explanation":"The root قضي occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, ADJ, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَاضٍ","transliteration":"","meaning":"(are) decreeing","rule":"20:72"},{"arabic":"قَضَيْنَا","transliteration":"","meaning":"We decreed","rule":"34:14"},{"arabic":"فَقَضَىٰ","transliteration":"","meaning":"and killed him","rule":"28:15"},{"arabic":"يُقْضَىٰ","transliteration":"","meaning":"is decreed","rule":"35:36"},{"arabic":"لْيَقْضُوا۟","transliteration":"","meaning":"let them end","rule":"22:29"},{"arabic":"قَضَىٰ","transliteration":"","meaning":"Musa fulfilled","rule":"28:29"}],"rules":[{"name":"Words on قضي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَاضٍ","قَضَيْنَا","فَقَضَىٰ","يُقْضَىٰ","لْيَقْضُوا۟","قَضَىٰ","وَقَضَيْنَآ","يَقْضُونَ"]},{"name":"Parts of speech attested for قضي","description":"The morphology corpus tags words on this root as V, ADJ, N — 3 distinct parts of speech across the 33 glossed words attested.","examples":["قَاضٍ","قَضَيْنَا","فَقَضَىٰ","يُقْضَىٰ","لْيَقْضُوا۟","قَضَىٰ"]},{"name":"Where قضي occurs","description":"The 33 glossed words on this root are attested across 18 distinct surahs.","examples":["قَاضٍ (20:72)","قَضَيْنَا (34:14)","فَقَضَىٰ (28:15)","يُقْضَىٰ (35:36)","لْيَقْضُوا۟ (22:29)","قَضَىٰ (28:29)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قضي?","options":["وَلِلَّهِ","قَاضٍ","أُذِنَ","أَبِيهِمْ"],"correct":1,"explanation":"قَاضٍ — glossed \"(are) decreeing\" at 20:72 — carries the root قضي. The others come from different roots."},{"type":"multiple_choice","question":"What does قَضَيْنَا mean?","options":["We decreed","the earth","and will hang low","(to) a matter"],"correct":0,"explanation":"\"We decreed\", from the word-by-word gloss at 34:14."},{"type":"fill_blank","question":"Type the root of فَقَضَىٰ in Arabic (three letters).","correct":"قضي","explanation":"قضي. Diacritics are ignored when checking, so ق ض ي is enough."}]', '["root-mwh"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sHr', 'The root سحر (س ح ر)', 'grammar', 4, '{"explanation":"The root سحر occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 36 distinct glossed words, tagged in the corpus as N, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَاحِرٌ","transliteration":"","meaning":"A magician","rule":"51:52"},{"arabic":"لِّتَسْحَرَنَا","transliteration":"","meaning":"so that you bewitch us","rule":"7:132"},{"arabic":"مَسْحُورًۭا","transliteration":"","meaning":"(you are) bewitched","rule":"17:101"},{"arabic":"بِسِحْرِهِمَا","transliteration":"","meaning":"with their magic","rule":"20:63"},{"arabic":"سَـٰحِرٌ","transliteration":"","meaning":"A magician","rule":"51:39"},{"arabic":"ٱلسَّحَرَةُ","transliteration":"","meaning":"the magicians","rule":"7:113"}],"rules":[{"name":"Words on سحر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَاحِرٌ","لِّتَسْحَرَنَا","مَسْحُورًۭا","بِسِحْرِهِمَا","سَـٰحِرٌ","ٱلسَّحَرَةُ","ٱلسَّاحِرُ","سِحْرٌۭ"]},{"name":"Parts of speech attested for سحر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 36 glossed words attested.","examples":["سَاحِرٌ","لِّتَسْحَرَنَا","مَسْحُورًۭا","بِسِحْرِهِمَا","سَـٰحِرٌ","ٱلسَّحَرَةُ"]},{"name":"Verb forms attested for سحر","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["سَاحِرٌ","لِّتَسْحَرَنَا","مَسْحُورًۭا","بِسِحْرِهِمَا","سَـٰحِرٌ","ٱلسَّحَرَةُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سحر?","options":["وَأَصِيلًۭا","بِـَٔايَـٰتِنَا","وَمَشْهُودٍۢ","سَاحِرٌ"],"correct":3,"explanation":"سَاحِرٌ — glossed \"A magician\" at 51:52 — carries the root سحر. The others come from different roots."},{"type":"multiple_choice","question":"What does لِّتَسْحَرَنَا mean?","options":["the secure","so that you bewitch us","any intercessors","their fathers"],"correct":1,"explanation":"\"so that you bewitch us\", from the word-by-word gloss at 7:132."},{"type":"fill_blank","question":"Type the root of مَسْحُورًۭا in Arabic (three letters).","correct":"سحر","explanation":"سحر. Diacritics are ignored when checking, so س ح ر is enough."}]', '["root-qDy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-tlw', 'The root تلو (ت ل و)', 'grammar', 4, '{"explanation":"The root تلو occurs 63 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَتْلُوا۟","transliteration":"","meaning":"(who) will recite","rule":"2:129"},{"arabic":"تُلِيَتْ","transliteration":"","meaning":"are recited","rule":"8:2"},{"arabic":"نَتْلُوهُ","transliteration":"","meaning":"(is what) We recite [it]","rule":"3:58"},{"arabic":"ٱتْلُ","transliteration":"","meaning":"Recite","rule":"29:45"},{"arabic":"نَتْلُوهَا","transliteration":"","meaning":"We recite them","rule":"2:252"},{"arabic":"تَتْلُوا۟","transliteration":"","meaning":"recite(d)","rule":"2:102"}],"rules":[{"name":"Words on تلو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَتْلُوا۟","تُلِيَتْ","نَتْلُوهُ","ٱتْلُ","نَتْلُوهَا","تَتْلُوا۟","أَتْلُ","سَأَتْلُوا۟"]},{"name":"Parts of speech attested for تلو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 23 glossed words attested.","examples":["يَتْلُوا۟","تُلِيَتْ","نَتْلُوهُ","ٱتْلُ","نَتْلُوهَا","تَتْلُوا۟"]},{"name":"Where تلو occurs","description":"The 23 glossed words on this root are attested across 15 distinct surahs.","examples":["يَتْلُوا۟ (2:129)","تُلِيَتْ (8:2)","نَتْلُوهُ (3:58)","ٱتْلُ (29:45)","نَتْلُوهَا (2:252)","تَتْلُوا۟ (2:102)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root تلو?","options":["يُذْكَرُ","شُهَدَآءَكُم","يَتْلُوا۟","ءَايَـٰتُ"],"correct":2,"explanation":"يَتْلُوا۟ — glossed \"(who) will recite\" at 2:129 — carries the root تلو. The others come from different roots."},{"type":"multiple_choice","question":"What does تُلِيَتْ mean?","options":["(is) God","at (the) mention","any one of them","are recited"],"correct":3,"explanation":"\"are recited\", from the word-by-word gloss at 8:2."},{"type":"fill_blank","question":"Type the root of نَتْلُوهُ in Arabic (three letters).","correct":"تلو","explanation":"تلو. Diacritics are ignored when checking, so ت ل و is enough."}]', '["root-sHr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mss', 'The root مسس (م س س)', 'grammar', 4, '{"explanation":"The root مسس occurs 61 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, N, IMPN, in verb form VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَمْسَسْهُ","transliteration":"","meaning":"touched it","rule":"24:35"},{"arabic":"مَّسَّتْهُمُ","transliteration":"","meaning":"Touched them","rule":"2:214"},{"arabic":"مَسَّنَا","transliteration":"","meaning":"Has touched us","rule":"12:88"},{"arabic":"لَيَمَسَّنَّ","transliteration":"","meaning":"surely will afflict","rule":"5:73"},{"arabic":"يَمَسُّهُمُ","transliteration":"","meaning":"will touch them","rule":"6:49"},{"arabic":"مَسَّ","transliteration":"","meaning":"(has) touched","rule":"3:140"}],"rules":[{"name":"Words on مسس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَمْسَسْهُ","مَّسَّتْهُمُ","مَسَّنَا","لَيَمَسَّنَّ","يَمَسُّهُمُ","مَسَّ","يَمَسُّهُم","مِسَاسَ"]},{"name":"Parts of speech attested for مسس","description":"The morphology corpus tags words on this root as V, N, IMPN — 3 distinct parts of speech across the 35 glossed words attested.","examples":["تَمْسَسْهُ","مَّسَّتْهُمُ","مَسَّنَا","لَيَمَسَّنَّ","يَمَسُّهُمُ","مَسَّ"]},{"name":"Verb forms attested for مسس","description":"Where this root is tagged as a verb, the corpus attests derived Form VI.","examples":["تَمْسَسْهُ","مَّسَّتْهُمُ","مَسَّنَا","لَيَمَسَّنَّ","يَمَسُّهُمُ","مَسَّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مسس?","options":["فَلِلَّهِ","يَشْكُرْ","يَأْذَنَ","تَمْسَسْهُ"],"correct":3,"explanation":"تَمْسَسْهُ — glossed \"touched it\" at 24:35 — carries the root مسس. The others come from different roots."},{"type":"multiple_choice","question":"What does مَّسَّتْهُمُ mean?","options":["You appointed","(for) reminder","Touched them","strong"],"correct":2,"explanation":"\"Touched them\", from the word-by-word gloss at 2:214."},{"type":"fill_blank","question":"Type the root of مَسَّنَا in Arabic (three letters).","correct":"مسس","explanation":"مسس. Diacritics are ignored when checking, so م س س is enough."}]', '["root-tlw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-zyd', 'The root زيد (ز ي د)', 'grammar', 4, '{"explanation":"The root زيد occurs 61 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 47 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَزِدْهُ","transliteration":"","meaning":"increase for him","rule":"38:61"},{"arabic":"وَيَزِيدُهُم","transliteration":"","meaning":"and give them more","rule":"4:173"},{"arabic":"نَّزِيدَكُمْ","transliteration":"","meaning":"We will increase you","rule":"78:30"},{"arabic":"وَزَادَكُمْ","transliteration":"","meaning":"and increased you","rule":"7:69"},{"arabic":"سَنَزِيدُ","transliteration":"","meaning":"We will increase (reward)","rule":"7:161"},{"arabic":"فَزَادَتْهُمْ","transliteration":"","meaning":"then it has increased them","rule":"9:124"}],"rules":[{"name":"Words on زيد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَزِدْهُ","وَيَزِيدُهُم","نَّزِيدَكُمْ","وَزَادَكُمْ","سَنَزِيدُ","فَزَادَتْهُمْ","زَادُوكُمْ","يَزِدْهُمْ"]},{"name":"Parts of speech attested for زيد","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 47 glossed words attested.","examples":["فَزِدْهُ","وَيَزِيدُهُم","نَّزِيدَكُمْ","وَزَادَكُمْ","سَنَزِيدُ","فَزَادَتْهُمْ"]},{"name":"Verb forms attested for زيد","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["فَزِدْهُ","وَيَزِيدُهُم","نَّزِيدَكُمْ","وَزَادَكُمْ","سَنَزِيدُ","فَزَادَتْهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root زيد?","options":["وَٱلْأُنثَىٰٓ","فَزِدْهُ","ءَاتَيْنَـٰهُمْ","شَهِيدًا"],"correct":1,"explanation":"فَزِدْهُ — glossed \"increase for him\" at 38:61 — carries the root زيد. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَزِيدُهُم mean?","options":["Allah has been good","weak","permission has been given","and give them more"],"correct":3,"explanation":"\"and give them more\", from the word-by-word gloss at 4:173."},{"type":"fill_blank","question":"Type the root of نَّزِيدَكُمْ in Arabic (three letters).","correct":"زيد","explanation":"زيد. Diacritics are ignored when checking, so ز ي د is enough."}]', '["root-mss"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fry', 'The root فري (ف ر ي)', 'grammar', 4, '{"explanation":"The root فري occurs 60 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَفْتَرِينَهُۥ","transliteration":"","meaning":"they invent it","rule":"60:12"},{"arabic":"ٱفْتَرَيْنَا","transliteration":"","meaning":"we would have fabricated","rule":"7:89"},{"arabic":"ٱفْتَرَىٰٓ","transliteration":"","meaning":"he has fabricated","rule":"4:48"},{"arabic":"يَفْتَرِى","transliteration":"","meaning":"they invent","rule":"16:105"},{"arabic":"تَفْتَرُوا۟","transliteration":"","meaning":"invent","rule":"20:61"},{"arabic":"مُفْتَرُونَ","transliteration":"","meaning":"inventors","rule":"11:50"}],"rules":[{"name":"Words on فري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَفْتَرِينَهُۥ","ٱفْتَرَيْنَا","ٱفْتَرَىٰٓ","يَفْتَرِى","تَفْتَرُوا۟","مُفْتَرُونَ","مُفْتَرٍۭ","تَفْتَرُونَ"]},{"name":"Parts of speech attested for فري","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 22 glossed words attested.","examples":["يَفْتَرِينَهُۥ","ٱفْتَرَيْنَا","ٱفْتَرَىٰٓ","يَفْتَرِى","تَفْتَرُوا۟","مُفْتَرُونَ"]},{"name":"Verb forms attested for فري","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["يَفْتَرِينَهُۥ","ٱفْتَرَيْنَا","ٱفْتَرَىٰٓ","يَفْتَرِى","تَفْتَرُوا۟","مُفْتَرُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فري?","options":["أَفَتَأْتُونَ","يَفْتَرِينَهُۥ","ءَايَةٍۭ","أَيَّدتُّكَ"],"correct":1,"explanation":"يَفْتَرِينَهُۥ — glossed \"they invent it\" at 60:12 — carries the root فري. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱفْتَرَيْنَا mean?","options":["Taste","we would have fabricated","your God","ask your permission"],"correct":1,"explanation":"\"we would have fabricated\", from the word-by-word gloss at 7:89."},{"type":"fill_blank","question":"Type the root of ٱفْتَرَىٰٓ in Arabic (three letters).","correct":"فري","explanation":"فري. Diacritics are ignored when checking, so ف ر ي is enough."}]', '["root-zyd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ftn', 'The root فتن (ف ت ن)', 'grammar', 4, '{"explanation":"The root فتن occurs 60 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فُتُونًۭا","transliteration":"","meaning":"(with) a trial","rule":"20:40"},{"arabic":"بِفَـٰتِنِينَ","transliteration":"","meaning":"can tempt away (anyone)","rule":"37:162"},{"arabic":"فِتْنَتَهُۥ","transliteration":"","meaning":"his trial","rule":"5:41"},{"arabic":"يَفْتِنُوكَ","transliteration":"","meaning":"they tempt you away","rule":"5:49"},{"arabic":"فَتَنُوا۟","transliteration":"","meaning":"persecuted","rule":"85:10"},{"arabic":"فِتْنَةَ","transliteration":"","meaning":"(the) trial","rule":"29:10"}],"rules":[{"name":"Words on فتن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فُتُونًۭا","بِفَـٰتِنِينَ","فِتْنَتَهُۥ","يَفْتِنُوكَ","فَتَنُوا۟","فِتْنَةَ","فِتْنَةٌۭ","ٱلْمَفْتُونُ"]},{"name":"Parts of speech attested for فتن","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 32 glossed words attested.","examples":["فُتُونًۭا","بِفَـٰتِنِينَ","فِتْنَتَهُۥ","يَفْتِنُوكَ","فَتَنُوا۟","فِتْنَةَ"]},{"name":"Where فتن occurs","description":"The 32 glossed words on this root are attested across 23 distinct surahs.","examples":["فُتُونًۭا (20:40)","بِفَـٰتِنِينَ (37:162)","فِتْنَتَهُۥ (5:41)","يَفْتِنُوكَ (5:49)","فَتَنُوا۟ (85:10)","فِتْنَةَ (29:10)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فتن?","options":["فُتُونًۭا","وَشَآقُّوا۟","أُمِرُوٓا۟","لِلْإِنسَـٰنِ"],"correct":0,"explanation":"فُتُونًۭا — glossed \"(with) a trial\" at 20:40 — carries the root فتن. The others come from different roots."},{"type":"multiple_choice","question":"What does بِفَـٰتِنِينَ mean?","options":["And drink","they give thanks","can tempt away (anyone)","(for) the believers"],"correct":2,"explanation":"\"can tempt away (anyone)\", from the word-by-word gloss at 37:162."},{"type":"fill_blank","question":"Type the root of فِتْنَتَهُۥ in Arabic (three letters).","correct":"فتن","explanation":"فتن. Diacritics are ignored when checking, so ف ت ن is enough."}]', '["root-fry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gyb', 'The root غيب (غ ي ب)', 'grammar', 4, '{"explanation":"The root غيب occurs 60 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"غَيَـٰبَتِ","transliteration":"","meaning":"the bottom","rule":"12:10"},{"arabic":"غَآئِبِينَ","transliteration":"","meaning":"absent","rule":"7:7"},{"arabic":"بِغَآئِبِينَ","transliteration":"","meaning":"(will be) absent","rule":"82:16"},{"arabic":"ٱلْغَيْبُ","transliteration":"","meaning":"the unseen","rule":"10:20"},{"arabic":"غَيْبِ","transliteration":"","meaning":"(of the) unseen","rule":"35:38"},{"arabic":"غَيْبُ","transliteration":"","meaning":"(is the) unseen","rule":"11:123"}],"rules":[{"name":"Words on غيب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["غَيَـٰبَتِ","غَآئِبِينَ","بِغَآئِبِينَ","ٱلْغَيْبُ","غَيْبِ","غَيْبُ","بِٱلْغَيْبِ","لِّلْغَيْبِ"]},{"name":"Parts of speech attested for غيب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["غَيَـٰبَتِ","غَآئِبِينَ","بِغَآئِبِينَ","ٱلْغَيْبُ","غَيْبِ","غَيْبُ"]},{"name":"Verb forms attested for غيب","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["غَيَـٰبَتِ","غَآئِبِينَ","بِغَآئِبِينَ","ٱلْغَيْبُ","غَيْبِ","غَيْبُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غيب?","options":["غَيَـٰبَتِ","أَحَدَكُم","وَٱلشُّهَدَآءُ","لِلَّهِ"],"correct":0,"explanation":"غَيَـٰبَتِ — glossed \"the bottom\" at 12:10 — carries the root غيب. The others come from different roots."},{"type":"multiple_choice","question":"What does غَآئِبِينَ mean?","options":["And enjoin","they brought","(into) sects","absent"],"correct":3,"explanation":"\"absent\", from the word-by-word gloss at 7:7."},{"type":"fill_blank","question":"Type the root of بِغَآئِبِينَ in Arabic (three letters).","correct":"غيب","explanation":"غيب. Diacritics are ignored when checking, so غ ي ب is enough."}]', '["root-ftn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Zhr', 'The root ظهر (ظ ه ر)', 'grammar', 4, '{"explanation":"The root ظهر occurs 59 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 40 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VI, III, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ظَهْرِهِۦٓ","transliteration":"","meaning":"its back","rule":"42:33"},{"arabic":"يَظْهَرُوا۟","transliteration":"","meaning":"they gain dominance","rule":"9:8"},{"arabic":"ظَهِيرٍۢ","transliteration":"","meaning":"supporter","rule":"34:22"},{"arabic":"ظُهُورِهِۦ","transliteration":"","meaning":"their backs","rule":"43:13"},{"arabic":"ٱلظَّهِيرَةِ","transliteration":"","meaning":"noon","rule":"24:58"},{"arabic":"وَظَهَرَ","transliteration":"","meaning":"and became manifest","rule":"9:48"}],"rules":[{"name":"Words on ظهر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ظَهْرِهِۦٓ","يَظْهَرُوا۟","ظَهِيرٍۢ","ظُهُورِهِۦ","ٱلظَّهِيرَةِ","وَظَهَرَ","يُظَـٰهِرُونَ","يُظْهِرُ"]},{"name":"Parts of speech attested for ظهر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 40 glossed words attested.","examples":["ظَهْرِهِۦٓ","يَظْهَرُوا۟","ظَهِيرٍۢ","ظُهُورِهِۦ","ٱلظَّهِيرَةِ","وَظَهَرَ"]},{"name":"Verb forms attested for ظهر","description":"Where this root is tagged as a verb, the corpus attests derived Forms VI, III, IV.","examples":["ظَهْرِهِۦٓ","يَظْهَرُوا۟","ظَهِيرٍۢ","ظُهُورِهِۦ","ٱلظَّهِيرَةِ","وَظَهَرَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ظهر?","options":["أَتَّخِذُ","يَذْكُرُ","وَيَأْكُلُونَ","ظَهْ