INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nsw', 'The root نسو (ن س و)', 'grammar', 4, '{"explanation":"The root نسو occurs 59 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نِسَآءِ","transliteration":"","meaning":"(the) women","rule":"3:42"},{"arabic":"وَنِسَآءٌۭ","transliteration":"","meaning":"and women","rule":"48:25"},{"arabic":"وَلِلنِّسَآءِ","transliteration":"","meaning":"and for the women","rule":"4:7"},{"arabic":"وَنِسَآءِ","transliteration":"","meaning":"and (the) women","rule":"33:59"},{"arabic":"نِّسَآئِهِم","transliteration":"","meaning":"(to) their wives","rule":"58:2"},{"arabic":"وَنِسَآءًۭ","transliteration":"","meaning":"and women","rule":"4:1"}],"rules":[{"name":"Words on نسو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نِسَآءِ","وَنِسَآءٌۭ","وَلِلنِّسَآءِ","وَنِسَآءِ","نِّسَآئِهِم","وَنِسَآءًۭ","وَٱلنِّسَآءِ","نِسَآئِكُمْ"]},{"name":"Parts of speech attested for نسو","description":"The morphology corpus tags words on this root as N — one part of speech across the 26 glossed words attested.","examples":["نِسَآءِ","وَنِسَآءٌۭ","وَلِلنِّسَآءِ","وَنِسَآءِ","نِّسَآئِهِم","وَنِسَآءًۭ"]},{"name":"Where نسو occurs","description":"The 26 glossed words on this root are attested across 10 distinct surahs.","examples":["نِسَآءِ (3:42)","وَنِسَآءٌۭ (48:25)","وَلِلنِّسَآءِ (4:7)","وَنِسَآءِ (33:59)","نِّسَآئِهِم (58:2)","وَنِسَآءًۭ (4:1)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نسو?","options":["بِٱلْأَنفِ","نِسَآءِ","بِمُؤْمِنِينَ","وَٱلْـَٔاصَالِ"],"correct":1,"explanation":"نِسَآءِ — glossed \"(the) women\" at 3:42 — carries the root نسو. The others come from different roots."},{"type":"multiple_choice","question":"What does وَنِسَآءٌۭ mean?","options":["He will pay heed","and women","(with) a reward","partners (were) associated (with Allah)"],"correct":1,"explanation":"\"and women\", from the word-by-word gloss at 48:25."},{"type":"fill_blank","question":"Type the root of وَلِلنِّسَآءِ in Arabic (three letters).","correct":"نسو","explanation":"نسو. Diacritics are ignored when checking, so ن س و is enough."}]', '["root-Zhr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rdd', 'The root ردد (ر د د)', 'grammar', 4, '{"explanation":"The root ردد occurs 59 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 45 distinct glossed words, tagged in the corpus as V, N, in verb forms VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَرَدَّ","transliteration":"","meaning":"turning away","rule":"13:11"},{"arabic":"بِرَدِّهِنَّ","transliteration":"","meaning":"to take them back","rule":"2:228"},{"arabic":"ٱرْتَدُّوا۟","transliteration":"","meaning":"return","rule":"47:25"},{"arabic":"فَنَرُدَّهَا","transliteration":"","meaning":"and turn them","rule":"4:47"},{"arabic":"رَدُّوهُ","transliteration":"","meaning":"they (had) referred it","rule":"4:83"},{"arabic":"نُرَدُّ","transliteration":"","meaning":"were sent back","rule":"6:27"}],"rules":[{"name":"Words on ردد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَرَدَّ","بِرَدِّهِنَّ","ٱرْتَدُّوا۟","فَنَرُدَّهَا","رَدُّوهُ","نُرَدُّ","يَتَرَدَّدُونَ","لَمَرْدُودُونَ"]},{"name":"Parts of speech attested for ردد","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 45 glossed words attested.","examples":["مَرَدَّ","بِرَدِّهِنَّ","ٱرْتَدُّوا۟","فَنَرُدَّهَا","رَدُّوهُ","نُرَدُّ"]},{"name":"Verb forms attested for ردد","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, V.","examples":["مَرَدَّ","بِرَدِّهِنَّ","ٱرْتَدُّوا۟","فَنَرُدَّهَا","رَدُّوهُ","نُرَدُّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ردد?","options":["ٱلْمَشْرِقِ","خُذُوا۟","مَرَدَّ","تَأْسَ"],"correct":2,"explanation":"مَرَدَّ — glossed \"turning away\" at 13:11 — carries the root ردد. The others come from different roots."},{"type":"multiple_choice","question":"What does بِرَدِّهِنَّ mean?","options":["to take them back","your reputation","but take","take"],"correct":0,"explanation":"\"to take them back\", from the word-by-word gloss at 2:228."},{"type":"fill_blank","question":"Type the root of ٱرْتَدُّوا۟ in Arabic (three letters).","correct":"ردد","explanation":"ردد. Diacritics are ignored when checking, so ر د د is enough."}]', '["root-nsw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-zkw', 'The root زكو (ز ك و)', 'grammar', 4, '{"explanation":"The root زكو occurs 59 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلزَّكَوٰةِ","transliteration":"","meaning":"and zakah","rule":"19:31"},{"arabic":"يُزَكِّيهِمْ","transliteration":"","meaning":"will He purify them","rule":"2:174"},{"arabic":"زَكَوٰةٍۢ","transliteration":"","meaning":"zakah","rule":"30:39"},{"arabic":"زَكَّىٰهَا","transliteration":"","meaning":"purifies it","rule":"91:9"},{"arabic":"زَكَوٰةًۭ","transliteration":"","meaning":"(in) purity","rule":"18:81"},{"arabic":"وَتُزَكِّيهِم","transliteration":"","meaning":"and cause them increase","rule":"9:103"}],"rules":[{"name":"Words on زكو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلزَّكَوٰةِ","يُزَكِّيهِمْ","زَكَوٰةٍۢ","زَكَّىٰهَا","زَكَوٰةًۭ","وَتُزَكِّيهِم","يَتَزَكَّىٰ","ٱلزَّكَوٰةَ"]},{"name":"Parts of speech attested for زكو","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 23 glossed words attested.","examples":["وَٱلزَّكَوٰةِ","يُزَكِّيهِمْ","زَكَوٰةٍۢ","زَكَّىٰهَا","زَكَوٰةًۭ","وَتُزَكِّيهِم"]},{"name":"Verb forms attested for زكو","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["وَٱلزَّكَوٰةِ","يُزَكِّيهِمْ","زَكَوٰةٍۢ","زَكَّىٰهَا","زَكَوٰةًۭ","وَتُزَكِّيهِم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root زكو?","options":["لِأَحَدٍۢ","فَسَ