INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Drb', 'The root ضرب (ض ر ب)', 'grammar', 4, '{"explanation":"The root ضرب occurs 58 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَضَرَبَ","transliteration":"","meaning":"And Allah sets forth","rule":"16:76"},{"arabic":"ضَرَبْنَا","transliteration":"","meaning":"We have set forth","rule":"25:39"},{"arabic":"وَٱضْرِبْ","transliteration":"","meaning":"And present","rule":"18:45"},{"arabic":"فَضُرِبَ","transliteration":"","meaning":"Then will be put up","rule":"57:13"},{"arabic":"يَضْرِبْنَ","transliteration":"","meaning":"let them stamp","rule":"24:31"},{"arabic":"ٱضْرِبُوهُ","transliteration":"","meaning":"Strike him","rule":"2:73"}],"rules":[{"name":"Words on ضرب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَضَرَبَ","ضَرَبْنَا","وَٱضْرِبْ","فَضُرِبَ","يَضْرِبْنَ","ٱضْرِبُوهُ","ضُرِبَتْ","وَٱضْرِبُوا۟"]},{"name":"Parts of speech attested for ضرب","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 34 glossed words attested.","examples":["وَضَرَبَ","ضَرَبْنَا","وَٱضْرِبْ","فَضُرِبَ","يَضْرِبْنَ","ٱضْرِبُوهُ"]},{"name":"Where ضرب occurs","description":"The 34 glossed words on this root are attested across 18 distinct surahs.","examples":["وَضَرَبَ (16:76)","ضَرَبْنَا (25:39)","وَٱضْرِبْ (18:45)","فَضُرِبَ (57:13)","يَضْرِبْنَ (24:31)","ٱضْرِبُوهُ (2:73)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ضرب?","options":["شَطْرَهُۥ","وَضَرَبَ","تَأْمُرُهُمْ","ٱلْأَرْضُ"],"correct":1,"explanation":"وَضَرَبَ — glossed \"And Allah sets forth\" at 16:76 — carries the root ضرب. The others come from different roots."},{"type":"multiple_choice","question":"What does ضَرَبْنَا mean?","options":["(the) mother","We have set forth","[the] former","(as) a witness"],"correct":1,"explanation":"\"We have set forth\", from the word-by-word gloss at 25:39."},{"type":"fill_blank","question":"Type the root of وَٱضْرِبْ in Arabic (three letters).","correct":"ضرب","explanation":"ضرب. Diacritics are ignored when checking, so ض ر ب is enough."}]', '["root-zkw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Edd', 'The root عدد (ع د د)', 'grammar', 4, '{"explanation":"The root عدد occurs 57 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as V, ADJ, N, in verb forms IV, VIII, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَعَدَّدَهُۥ","transliteration":"","meaning":"and counts it","rule":"104:2"},{"arabic":"مَّعْدُودَةًۭ","transliteration":"","meaning":"numbered","rule":"2:80"},{"arabic":"عُدَّةًۭ","transliteration":"","meaning":"(some) preparation","rule":"9:46"},{"arabic":"عَدًّۭا","transliteration":"","meaning":"a number","rule":"19:84"},{"arabic":"مَعْدُودَةٍۢ","transliteration":"","meaning":"few","rule":"12:20"},{"arabic":"لَأَعَدُّوا۟","transliteration":"","meaning":"surely they (would) have prepared","rule":"9:46"}],"rules":[{"name":"Words on عدد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَعَدَّدَهُۥ","مَّعْدُودَةًۭ","عُدَّةًۭ","عَدًّۭا","مَعْدُودَةٍۢ","لَأَعَدُّوا۟","تَعْتَدُّونَهَا","أَعَدَّ"]},{"name":"Parts of speech attested for عدد","description":"The morphology corpus tags words on this root as V, ADJ, N — 3 distinct parts of speech across the 31 glossed words attested.","examples":["وَعَدَّدَهُۥ","مَّعْدُودَةًۭ","عُدَّةًۭ","عَدًّۭا","مَعْدُودَةٍۢ","لَأَعَدُّوا۟"]},{"name":"Verb forms attested for عدد","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII, II.","examples":["وَعَدَّدَهُۥ","مَّعْدُودَةًۭ","عُدَّةًۭ","عَدًّۭا","مَعْدُودَةٍۢ","لَأَعَدُّوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عدد?","options":["وَأَبِيهِ","أَمْرُ","وَعَدَّدَهُۥ","شَيْـًٔا"],"correct":2,"explanation":"وَعَدَّدَهُۥ — glossed \"and counts it\" at 104:2 — carries the root عدد. The others come from different roots."},{"type":"multiple_choice","question":"What does مَّعْدُودَةًۭ mean?","options":["they remember (Allah)","they ask your permission","an announcer","numbered"],"correct":3,"explanation":"\"numbered\", from the word-by-word gloss at 2:80."},{"type":"fill_blank","question":"Type the root of عُدَّةًۭ in Arabic (three letters).","correct":"عدد","explanation":"عدد. Diacritics are ignored when checking, so ع د د is enough."}]', '["root-Drb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qry', 'The root قري (ق ر ي)', 'grammar', 4, '{"explanation":"The root قري occurs 57 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَرْيَةًۭ","transliteration":"","meaning":"(of) a town","rule":"16:112"},{"arabic":"ٱلْقَرْيَةَ","transliteration":"","meaning":"town","rule":"2:58"},{"arabic":"قَرْيَتِكُمْ","transliteration":"","meaning":"your town","rule":"7:82"},{"arabic":"قَرْيَتِنَآ","transliteration":"","meaning":"our city","rule":"7:88"},{"arabic":"قَرْيَةٍۢ","transliteration":"","meaning":"a township","rule":"2:259"},{"arabic":"ٱلْقُرَى","transliteration":"","meaning":"the towns","rule":"34:18"}],"rules":[{"name":"Words on قري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَرْيَةًۭ","ٱلْقَرْيَةَ","قَرْيَتِكُمْ","قَرْيَتِنَآ","قَرْيَةٍۢ","ٱلْقُرَى","ٱلْقَرْيَةِ","ٱلْقُرَىٰٓ"]},{"name":"Parts of speech attested for قري","description":"The morphology corpus tags words on this root as N — one part of speech across the 16 glossed words attested.","examples":["قَرْيَةًۭ","ٱلْقَرْيَةَ","قَرْيَتِكُمْ","قَرْيَتِنَآ","قَرْيَةٍۢ","ٱلْقُرَى"]},{"name":"Where قري occurs","description":"The 16 glossed words on this root are attested across 11 distinct surahs.","examples":["قَرْيَةًۭ (16:112)","ٱلْقَرْيَةَ (2:58)","قَرْيَتِكُمْ (7:82)","قَرْيَتِنَآ (7:88)","قَرْيَةٍۢ (2:259)","ٱلْقُرَى (34:18)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قري?","options":["قَرْيَةًۭ","أَمِنتُكُمْ","وَٱلشُّهَدَآءِ","أَمْرٌۭ"],"correct":0,"explanation":"قَرْيَةًۭ — glossed \"(of) a town\" at 16:112 — carries the root قري. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْقَرْيَةَ mean?","options":["town","trained","to sin","the human kind"],"correct":0,"explanation":"\"town\", from the word-by-word gloss at 2:58."},{"type":"fill_blank","question":"Type the root of قَرْيَتِكُمْ in Arabic (three letters).","correct":"قري","explanation":"قري. Diacritics are ignored when checking, so ق ر ي is enough."}]', '["root-Edd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rwH', 'The root روح (ر و ح)', 'grammar', 4, '{"explanation":"The root روح occurs 57 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَرَوْحٌۭ","transliteration":"","meaning":"Then rest","rule":"56:89"},{"arabic":"ٱلرِّيَـٰحِ","transliteration":"","meaning":"(of) the winds","rule":"2:164"},{"arabic":"ٱلرُّوحُ","transliteration":"","meaning":"The soul","rule":"17:85"},{"arabic":"ٱلرُّوحِ","transliteration":"","meaning":"the soul","rule":"17:85"},{"arabic":"ٱلرِّيَاحَ","transliteration":"","meaning":"the winds","rule":"30:46"},{"arabic":"وَٱلرُّوحُ","transliteration":"","meaning":"and the Spirit","rule":"70:4"}],"rules":[{"name":"Words on روح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَرَوْحٌۭ","ٱلرِّيَـٰحِ","ٱلرُّوحُ","ٱلرُّوحِ","ٱلرِّيَاحَ","وَٱلرُّوحُ","رِيحٍۢ","رِيحٌۭ"]},{"name":"Parts of speech attested for روح","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 34 glossed words attested.","examples":["فَرَوْحٌۭ","ٱلرِّيَـٰحِ","ٱلرُّوحُ","ٱلرُّوحِ","ٱلرِّيَاحَ","وَٱلرُّوحُ"]},{"name":"Verb forms attested for روح","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["فَرَوْحٌۭ","ٱلرِّيَـٰحِ","ٱلرُّوحُ","ٱلرُّوحِ","ٱلرِّيَاحَ","وَٱلرُّوحُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root روح?","options":["فَرَوْحٌۭ","مُّؤْمِنِينَ","أُجُورَهُمْ","أَحَدًا"],"correct":0,"explanation":"فَرَوْحٌۭ — glossed \"Then rest\" at 56:89 — carries the root روح. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلرِّيَـٰحِ mean?","options":["(the) masajid of Allah","one community","(of) the winds","an ailment"],"correct":2,"explanation":"\"(of) the winds\", from the word-by-word gloss at 2:164."},{"type":"fill_blank","question":"Type the root of ٱلرُّوحُ in Arabic (three letters).","correct":"روح","explanation":"روح. Diacritics are ignored when checking, so ر و ح is enough."}]', '["root-qry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*hb', 'The root ذهب (ذ ه ب)', 'grammar', 4, '{"explanation":"The root ذهب occurs 56 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِيُذْهِبَ","transliteration":"","meaning":"to remove","rule":"33:33"},{"arabic":"ذَهَبٍۢ","transliteration":"","meaning":"gold","rule":"18:31"},{"arabic":"فَٱذْهَبْ","transliteration":"","meaning":"So go","rule":"5:24"},{"arabic":"يُذْهِبْكُمْ","transliteration":"","meaning":"He can take you away","rule":"4:133"},{"arabic":"وَيُذْهِبَ","transliteration":"","meaning":"and take away","rule":"8:11"},{"arabic":"ٱلذَّهَبِ","transliteration":"","meaning":"[the] gold","rule":"3:14"}],"rules":[{"name":"Words on ذهب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِيُذْهِبَ","ذَهَبٍۢ","فَٱذْهَبْ","يُذْهِبْكُمْ","وَيُذْهِبَ","ٱلذَّهَبِ","لَنَذْهَبَنَّ","أَذْهَبَ"]},{"name":"Parts of speech attested for ذهب","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 39 glossed words attested.","examples":["لِيُذْهِبَ","ذَهَبٍۢ","فَٱذْهَبْ","يُذْهِبْكُمْ","وَيُذْهِبَ","ٱلذَّهَبِ"]},{"name":"Verb forms attested for ذهب","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["لِيُذْهِبَ","ذَهَبٍۢ","فَٱذْهَبْ","يُذْهِبْكُمْ","وَيُذْهِبَ","ٱلذَّهَبِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذهب?","options":["لِيُذْهِبَ","وَمَأْوَىٰهُمُ","ٱللَّهِ","إِلَـٰهِ"],"correct":0,"explanation":"لِيُذْهِبَ — glossed \"to remove\" at 33:33 — carries the root ذهب. The others come from different roots."},{"type":"multiple_choice","question":"What does ذَهَبٍۢ mean?","options":["then will come to them","another","people","gold"],"correct":3,"explanation":"\"gold\", from the word-by-word gloss at 18:31."},{"type":"fill_blank","question":"Type the root of فَٱذْهَبْ in Arabic (three letters).","correct":"ذهب","explanation":"ذهب. Diacritics are ignored when checking, so ذ ه ب is enough."}]', '["root-rwH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ajl', 'The root اجل (ا ج ل)', 'grammar', 4, '{"explanation":"The root اجل occurs 56 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَأَجَلٍۢ","transliteration":"","meaning":"and (for) a term","rule":"30:8"},{"arabic":"أَجَلَنَا","transliteration":"","meaning":"our term","rule":"6:128"},{"arabic":"أَجَلِهِۦ","transliteration":"","meaning":"its term","rule":"2:282"},{"arabic":"ٱلْأَجَلَيْنِ","transliteration":"","meaning":"(of) the two terms","rule":"28:28"},{"arabic":"أَجْلِ","transliteration":"","meaning":"time","rule":"5:32"},{"arabic":"أَجَلُهُمْ","transliteration":"","meaning":"their term","rule":"7:34"}],"rules":[{"name":"Words on اجل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَأَجَلٍۢ","أَجَلَنَا","أَجَلِهِۦ","ٱلْأَجَلَيْنِ","أَجْلِ","أَجَلُهُمْ","أَجَلَهَا","أَجَلُهُنَّ"]},{"name":"Parts of speech attested for اجل","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 23 glossed words attested.","examples":["وَأَجَلٍۢ","أَجَلَنَا","أَجَلِهِۦ","ٱلْأَجَلَيْنِ","أَجْلِ","أَجَلُهُمْ"]},{"name":"Verb forms attested for اجل","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["وَأَجَلٍۢ","أَجَلَنَا","أَجَلِهِۦ","ٱلْأَجَلَيْنِ","أَجْلِ","أَجَلُهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اجل?","options":["شَـٰمِخَـٰتٍۢ","أَبَقَ","ٱلْأُنثَىٰ","وَأَجَلٍۢ"],"correct":3,"explanation":"وَأَجَلٍۢ — glossed \"and (for) a term\" at 30:8 — carries the root اجل. The others come from different roots."},{"type":"multiple_choice","question":"What does أَجَلَنَا mean?","options":["our term","He has taken","their mother (town)","My Message"],"correct":0,"explanation":"\"our term\", from the word-by-word gloss at 6:128."},{"type":"fill_blank","question":"Type the root of أَجَلِهِۦ in Arabic (three letters).","correct":"اجل","explanation":"اجل. Diacritics are ignored when checking, so ا ج ل is enough."}]', '["root-*hb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nhy', 'The root نهي (ن ه ي)', 'grammar', 4, '{"explanation":"The root نهي occurs 56 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 36 distinct glossed words, tagged in the corpus as V, N, in verb forms VIII, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَهَىٰكُمْ","transliteration":"","meaning":"he forbids you","rule":"59:7"},{"arabic":"يَنْهَىٰهُمُ","transliteration":"","meaning":"forbid them","rule":"5:63"},{"arabic":"فَٱنتَهَىٰ","transliteration":"","meaning":"and he refrained","rule":"2:275"},{"arabic":"أَنْهَكُمَا","transliteration":"","meaning":"I forbid you both","rule":"7:22"},{"arabic":"ٱنتَهَوْا۟","transliteration":"","meaning":"they cease","rule":"2:192"},{"arabic":"نَهَىٰكُمَا","transliteration":"","meaning":"forbid you both","rule":"7:20"}],"rules":[{"name":"Words on نهي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَهَىٰكُمْ","يَنْهَىٰهُمُ","فَٱنتَهَىٰ","أَنْهَكُمَا","ٱنتَهَوْا۟","نَهَىٰكُمَا","يَنْهَوْنَ","أَتَنْهَىٰنَآ"]},{"name":"Parts of speech attested for نهي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 36 glossed words attested.","examples":["نَهَىٰكُمْ","يَنْهَىٰهُمُ","فَٱنتَهَىٰ","أَنْهَكُمَا","ٱنتَهَوْا۟","نَهَىٰكُمَا"]},{"name":"Verb forms attested for نهي","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, VI.","examples":["نَهَىٰكُمْ","يَنْهَىٰهُمُ","فَٱنتَهَىٰ","أَنْهَكُمَا","ٱنتَهَوْا۟","نَهَىٰكُمَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نهي?","options":["ٱللَّهُ","يَشْرَحْ","نَهَىٰكُمْ","يَشْفِينِ"],"correct":2,"explanation":"نَهَىٰكُمْ — glossed \"he forbids you\" at 59:7 — carries the root نهي. The others come from different roots."},{"type":"multiple_choice","question":"What does يَنْهَىٰهُمُ mean?","options":["(will be) for Allah","forbid them","they are reminded","for possessors"],"correct":1,"explanation":"\"forbid them\", from the word-by-word gloss at 5:63."},{"type":"fill_blank","question":"Type the root of فَٱنتَهَىٰ in Arabic (three letters).","correct":"نهي","explanation":"نهي. Diacritics are ignored when checking, so ن ه ي is enough."}]', '["root-Ajl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dwr', 'The root دور (د و ر)', 'grammar', 4, '{"explanation":"The root دور occurs 55 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلدَّارُ","transliteration":"","meaning":"And the home","rule":"7:169"},{"arabic":"ٱلدَّارَ","transliteration":"","meaning":"the home","rule":"28:77"},{"arabic":"دَارِكُمْ","transliteration":"","meaning":"your home(s)","rule":"11:65"},{"arabic":"ٱلدِّيَارِ","transliteration":"","meaning":"(of) the homes","rule":"17:5"},{"arabic":"دَارَ","transliteration":"","meaning":"(the) home","rule":"7:145"},{"arabic":"ٱلدَّارِ","transliteration":"","meaning":"(a good) home","rule":"6:135"}],"rules":[{"name":"Words on دور","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلدَّارُ","ٱلدَّارَ","دَارِكُمْ","ٱلدِّيَارِ","دَارَ","ٱلدَّارِ","دِيَـٰرِكُمْ","ٱلدَّوَآئِرَ"]},{"name":"Parts of speech attested for دور","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 26 glossed words attested.","examples":["وَٱلدَّارُ","ٱلدَّارَ","دَارِكُمْ","ٱلدِّيَارِ","دَارَ","ٱلدَّارِ"]},{"name":"Verb forms attested for دور","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَٱلدَّارُ","ٱلدَّارَ","دَارِكُمْ","ٱلدِّيَارِ","دَارَ","ٱلدَّارِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دور?","options":["وَٱلدَّارُ","مَذْءُومًۭا","إِخْوَٰنِكُمْ","تُؤَدُّوا۟"],"correct":0,"explanation":"وَٱلدَّارُ — glossed 