INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-tHt', 'The root تحت (ت ح ت)', 'grammar', 4, '{"explanation":"The root تحت occurs 51 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as N, LOC. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَحْتِ","transliteration":"","meaning":"beneath","rule":"5:66"},{"arabic":"تَحْتِهَا","transliteration":"","meaning":"under them","rule":"2:25"},{"arabic":"تَحْتَهَا","transliteration":"","meaning":"underneath it","rule":"9:100"},{"arabic":"تَحْتِىٓ","transliteration":"","meaning":"underneath me","rule":"43:51"},{"arabic":"تَحْتِهِمْ","transliteration":"","meaning":"underneath them","rule":"6:6"},{"arabic":"تَحْتِهِمُ","transliteration":"","meaning":"underneath them","rule":"7:43"}],"rules":[{"name":"Words on تحت","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَحْتِ","تَحْتِهَا","تَحْتَهَا","تَحْتِىٓ","تَحْتِهِمْ","تَحْتِهِمُ","تَحْتَهُۥ","تَحْتِهَآ"]},{"name":"Parts of speech attested for تحت","description":"The morphology corpus tags words on this root as N, LOC — 2 distinct parts of speech across the 10 glossed words attested.","examples":["تَحْتِ","تَحْتِهَا","تَحْتَهَا","تَحْتِىٓ","تَحْتِهِمْ","تَحْتِهِمُ"]},{"name":"Where تحت occurs","description":"The 10 glossed words on this root are attested across 9 distinct surahs.","examples":["تَحْتِ (5:66)","تَحْتِهَا (2:25)","تَحْتَهَا (9:100)","تَحْتِىٓ (43:51)","تَحْتِهِمْ (6:6)","تَحْتِهِمُ (7:43)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root تحت?","options":["وَأَهْلَهُۥ","تَحْتِ","تُؤْتَوْهُ","ءَايَـٰتِنَا"],"correct":1,"explanation":"تَحْتِ — glossed \"beneath\" at 5:66 — carries the root تحت. The others come from different roots."},{"type":"multiple_choice","question":"What does تَحْتِهَا mean?","options":["surely (are) Signs","under them","their sins","you (are) grateful"],"correct":1,"explanation":"\"under them\", from the word-by-word gloss at 2:25."},{"type":"fill_blank","question":"Type the root of تَحْتَهَا in Arabic (three letters).","correct":"تحت","explanation":"تحت. Diacritics are ignored when checking, so ت ح ت is enough."}]', '["root-Hll"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Tyb', 'The root طيب (ط ي ب)', 'grammar', 4, '{"explanation":"The root طيب occurs 50 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, ADJ, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"طُوبَىٰ","transliteration":"","meaning":"blessedness","rule":"13:29"},{"arabic":"ٱلطَّيِّبَـٰتِ","transliteration":"","meaning":"the pure things","rule":"7:157"},{"arabic":"طَيِّبَـٰتِكُمْ","transliteration":"","meaning":"your good things","rule":"46:20"},{"arabic":"طَيِّبَةً","transliteration":"","meaning":"pure","rule":"3:38"},{"arabic":"وَٱلطَّيِّبُ","transliteration":"","meaning":"and the good","rule":"5:100"},{"arabic":"طِبْتُمْ","transliteration":"","meaning":"you have done well","rule":"39:73"}],"rules":[{"name":"Words on طيب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["طُوبَىٰ","ٱلطَّيِّبَـٰتِ","طَيِّبَـٰتِكُمْ","طَيِّبَةً","وَٱلطَّيِّبُ","طِبْتُمْ","طَيِّبَةٌۭ","طَيِّبَـٰتِ"]},{"name":"Parts of speech attested for طيب","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 25 glossed words attested.","examples":["طُوبَىٰ","ٱلطَّيِّبَـٰتِ","طَيِّبَـٰتِكُمْ","طَيِّبَةً","وَٱلطَّيِّبُ","طِبْتُمْ"]},{"name":"Where طيب occurs","description":"The 25 glossed words on this root are attested across 14 distinct surahs.","examples":["طُوبَىٰ (13:29)","ٱلطَّيِّبَـٰتِ (7:157)","طَيِّبَـٰتِكُمْ (46:20)","طَيِّبَةً (3:38)","وَٱلطَّيِّبُ (5:100)","طِبْتُمْ (39:73)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طيب?","options":["طُوبَىٰ","بِإِذْنِى","أَمَدًۭا","وَأَهْلُهَا"],"correct":0,"explanation":"طُوبَىٰ — glossed \"blessedness\" at 13:29 — carries the root طيب. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلطَّيِّبَـٰتِ mean?","options":["could you take it","the pure things","you are commanded","the reward"],"correct":1,"explanation":"\"the pure things\", from the word-by-word gloss at 7:157."},{"type":"fill_blank","question":"Type the root of طَيِّبَـٰتِكُمْ in Arabic (three letters).","correct":"طيب","explanation":"طيب. Diacritics are ignored when checking, so ط ي ب is enough."}]', '["root-tHt"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fsd', 'The root فسد (ف س د)', 'grammar', 4, '{"explanation":"The root فسد occurs 50 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِيُفْسِدَ","transliteration":"","meaning":"to spread corruption","rule":"2:205"},{"arabic":"كَٱلْمُفْسِدِينَ","transliteration":"","meaning":"like those who spread corruption","rule":"38:28"},{"arabic":"فَسَادٍۢ","transliteration":"","meaning":"(for) spreading corruption","rule":"5:32"},{"arabic":"أَفْسَدُوهَا","transliteration":"","meaning":"they ruin it","rule":"27:34"},{"arabic":"ٱلْمُفْسِدُونَ","transliteration":"","meaning":"(are) the ones who spread corruption","rule":"2:12"},{"arabic":"لَّفَسَدَتِ","transliteration":"","meaning":"certainly (would have) corrupted","rule":"2:251"}],"rules":[{"name":"Words on فسد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِيُفْسِدَ","كَٱلْمُفْسِدِينَ","فَسَادٍۢ","أَفْسَدُوهَا","ٱلْمُفْسِدُونَ","لَّفَسَدَتِ","بِٱلْمُفْسِدِينَ","ٱلْمُفْسِدَ"]},{"name":"Parts of speech attested for فسد","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 26 glossed words attested.","examples":["لِيُفْسِدَ","كَٱلْمُفْسِدِينَ","فَسَادٍۢ","أَفْسَدُوهَا","ٱلْمُفْسِدُونَ","لَّفَسَدَتِ"]},{"name":"Verb forms attested for فسد","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["لِيُفْسِدَ","كَٱلْمُفْسِدِينَ","فَسَادٍۢ","أَفْسَدُوهَا","ٱلْمُفْسِدُونَ","لَّفَسَدَتِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فسد?","options":["يَأْتِىَ","ءَامَنُوا۟","أَشْكُوا۟","لِيُفْسِدَ"],"correct":3,"explanation":"لِيُفْسِدَ — glossed \"to spread corruption\" at 2:205 — carries the root فسد. The others come from different roots."},{"type":"multiple_choice","question":"What does كَٱلْمُفْسِدِينَ mean?","options":["like those who spread corruption","Shaitaan","his reward","Certainly Allah''s hatred"],"correct":0,"explanation":"\"like those who spread corruption\", from the word-by-word gloss at 38:28."},{"type":"fill_blank","question":"Type the root of فَسَادٍۢ in Arabic (three letters).","correct":"فسد","explanation":"فسد. Diacritics are ignored when checking, so ف س د is enough."}]', '["root-Tyb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nfE', 'The root نفع (ن ف ع)', 'grammar', 4, '{"explanation":"The root نفع occurs 50 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَنَـٰفِعَ","transliteration":"","meaning":"benefits","rule":"22:28"},{"arabic":"نَفْعًۭا","transliteration":"","meaning":"(in) benefit","rule":"4:11"},{"arabic":"يَنفَعُونَكُمْ","transliteration":"","meaning":"(do) they benefit you","rule":"26:73"},{"arabic":"نَفْعًا","transliteration":"","meaning":"(for) any profit","rule":"10:49"},{"arabic":"نَّفْعًۭا","transliteration":"","meaning":"to benefit","rule":"34:42"},{"arabic":"يَنفَعُ","transliteration":"","meaning":"benefits","rule":"2:164"}],"rules":[{"name":"Words on نفع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَنَـٰفِعَ","نَفْعًۭا","يَنفَعُونَكُمْ","نَفْعًا","نَّفْعًۭا","يَنفَعُ","يَنفَعُكُمْ","تَنفَعُهُمْ"]},{"name":"Parts of speech attested for نفع","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 25 glossed words attested.","examples":["مَنَـٰفِعَ","نَفْعًۭا","يَنفَعُونَكُمْ","نَفْعًا","نَّفْعًۭا","يَنفَعُ"]},{"name":"Where نفع occurs","description":"The 25 glossed words on this root are attested across 16 distinct surahs.","examples":["مَنَـٰفِعَ (22:28)","نَفْعًۭا (4:11)","يَنفَعُونَكُمْ (26:73)","نَفْعًا (10:49)","نَّفْعًۭا (34:42)","يَنفَعُ (2:164)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نفع?","options":["ٱلْأُنثَيَيْنِ","مَنَـٰفِعَ","مُتَشَـٰبِهٍ","وَأَكْلِهِمُ"],"correct":1,"explanation":"مَنَـٰفِعَ — glossed \"benefits\" at 22:28 — carries the root نفع. The others come from different roots."},{"type":"multiple_choice","question":"What does نَفْعًۭا mean?","options":["(in) benefit","for your wife","you believe","you have given them"],"correct":0,"explanation":"\"(in) benefit\", from the word-by-word gloss at 4:11."},{"type":"fill_blank","question":"Type the root of يَنفَعُونَكُمْ in Arabic (three letters).","correct":"نفع","explanation":"نفع. Diacritics are ignored when checking, so ن ف ع is enough."}]', '["root-fsd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Eql', 'The root عقل (ع ق ل)', 'grammar', 4, '{"explanation":"The root عقل occurs 49 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 5 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَعْقِلُونَ","transliteration":"","meaning":"you use reason","rule":"2:44"},{"arabic":"يَعْقِلُهَآ","transliteration":"","meaning":"will understand them","rule":"29:43"},{"arabic":"نَعْقِلُ","transliteration":"","meaning":"reasoned","rule":"67:10"},{"arabic":"عَقَلُوهُ","transliteration":"","meaning":"they understood it","rule":"2:75"},{"arabic":"يَعْقِلُونَ","transliteration":"","meaning":"who use their intellect","rule":"2:164"}],"rules":[{"name":"Words on عقل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَعْقِلُونَ","يَعْقِلُهَآ","نَعْقِلُ","عَقَلُوهُ","يَعْقِلُونَ"]},{"name":"Parts of speech attested for عقل","description":"The morphology corpus tags words on this root as V — one part of speech across the 5 glossed words attested.","examples":["تَعْقِلُونَ","يَعْقِلُهَآ","نَعْقِلُ","عَقَلُوهُ","يَعْقِلُونَ"]},{"name":"Where عقل occurs","description":"The 5 glossed words on this root are attested across 3 distinct surahs.","examples":["تَعْقِلُونَ (2:44)","يَعْقِلُهَآ (29:43)","نَعْقِلُ (67:10)","عَقَلُوهُ (2:75)","يَعْقِلُونَ (2:164)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عقل?","options":["فَـَٔامَنُوا۟","بِـَٔايَـٰتِنَا","تَعْقِلُونَ","مَذْءُومًۭا"],"correct":2,"explanation":"تَعْقِلُونَ — glossed \"you use reason\" at 2:44 — carries the root عقل. The others come from different roots."},{"type":"multiple_choice","question":"What does يَعْقِلُهَآ mean?","options":["Allah has guided them","and the sun","will understand them","to (the) last of them"],"correct":2,"explanation":"\"will understand them\", from the word-by-word gloss at 29:43."},{"type":"fill_blank","question":"Type the root of نَعْقِلُ in Arabic (three letters).","correct":"عقل","explanation":"عقل. Diacritics are ignored when checking, so ع ق ل is enough."}]', '["root-nfE"]', 29, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-swE', 'The root سوع (س و ع)', 'grammar', 4, '{"explanation":"The root سوع occurs 49 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, T, PN. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلسَّاعَةُ","transliteration":"","meaning":"and the Hour","rule":"45:32"},{"arabic":"ٱلسَّاعَةُ","transliteration":"","meaning":"the Hour","rule":"54:1"},{"arabic":"سُوَاعًۭا","transliteration":"","meaning":"Suwa","rule":"71:23"},{"arabic":"بِٱلسَّاعَةِ","transliteration":"","meaning":"the Hour","rule":"25:11"},{"arabic":"لِّلسَّاعَةِ","transliteration":"","meaning":"of the Hour","rule":"43:61"},{"arabic":"سَاعَةٍۢ","transliteration":"","meaning":"an hour","rule":"30:55"}],"rules":[{"name":"Words on سوع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلسَّاعَةُ","ٱلسَّاعَةُ","سُوَاعًۭا","بِٱلسَّاعَةِ","لِّلسَّاعَةِ","سَاعَةٍۢ","سَاعَةًۭ","ٱلسَّاعَةِ"]},{"name":"Parts of speech attested for سوع","description":"The morphology corpus tags words on this root as N, T, PN — 3 distinct parts of speech across the 11 glossed words attested.","examples":["وَٱلسَّاعَةُ","ٱلسَّاعَةُ","سُوَاعًۭا","بِٱلسَّاعَةِ","لِّلسَّاعَةِ","سَاعَةٍۢ"]},{"name":"Where سوع occurs","description":"The 11 glossed words on this root are attested across 10 distinct surahs.","examples":["وَٱلسَّاعَةُ (45:32)","ٱلسَّاعَةُ (54:1)","سُوَاعًۭا (71:23)","بِٱلسَّاعَةِ (25:11)","لِّلسَّاعَةِ (43:61)","سَاعَةٍۢ (30:55)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سوع?","options":["وَٱلسَّاعَةُ","أَخَذَ","يَتَذَكَّرُ","وَٱلْإِنسِ"],"correct":0,"explanation":"وَٱلسَّاعَةُ — glossed \"and the Hour\" at 45:32 — carries the root سوع. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلسَّاعَةُ mean?","options":["the Hour","anything","Came to them","will forget"],"correct":0,"explanation":"\"the Hour\", from the word-by-word gloss at 54:1."},{"type":"fill_blank","question":"Type the root of سُوَاعًۭا in Arabic (three letters).","correct":"سوع","explanation":"سوع. Diacritics are ignored when checking, so س و ع is enough."}]', '["root-Eql"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Avm', 'The root اثم (ا ث م)', 'grammar', 4, '{"explanation":"The root اثم occurs 48 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْإِثْمِ","transliteration":"","meaning":"[the] sin","rule":"5:2"},{"arabic":"أَثِيمٍ","transliteration":"","meaning":"sinner","rule":"2:276"},{"arabic":"ءَاثِمٌۭ","transliteration":"","meaning":"(is) sinful","rule":"2:283"},{"arabic":"بِإِثْمِى","transliteration":"","meaning":"with my sin","rule":"5:29"},{"arabic":"إِثْمَ","transliteration":"","meaning":"sin","rule":"2:173"},{"arabic":"أَثِيمًۭا","transliteration":"","meaning":"(and) sinful","rule":"4:107"}],"rules":[{"name":"Words on اثم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْإِثْمِ","أَثِيمٍ","ءَاثِمٌۭ","بِإِثْمِى","إِثْمَ","أَثِيمًۭا","وَإِثْمُهُمَآ","ٱلْـَٔاثِمِينَ"]},{"name":"Parts of speech attested for اثم","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 24 glossed words attested.","examples":["ٱلْإِثْمِ","أَثِيمٍ","ءَاثِمٌۭ","بِإِثْمِى","إِثْمَ","أَثِيمًۭا"]},{"name":"Verb forms attested for اثم","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["ٱلْإِثْمِ","أَثِيمٍ","ءَاثِمٌۭ","بِإِثْمِى","إِثْمَ","أَثِيمًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اثم?","options":["فَٱذْهَبْ","تُشْرِكْ","ٱلْإِنسَـٰنَ","ٱلْإِثْمِ"],"correct":3,"explanation":"ٱلْإِثْمِ — glossed \"[the] sin\" at 5:2 — carries the root اثم. The others come from different roots."},{"type":"multiple_choice","question":"What does أَثِيمٍ mean?","options":["so (that) they intercede","will bear witness","sinner","I am commanded"],"correct":2,"explanation":"\"sinner\", from the word-by-word gloss at 2:276."},{"type":"fill_blank","question":"Type the root of ءَاثِمٌۭ in Arabic (three letters).","correct":"اثم","explanation":"اثم. Diacritics are ignored when checking, so ا ث م is enough."}]', '["root-swE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-TEm', 'The root طعم (ط ع م)', 'grammar', 4, '{"explanation":"The root طعم occurs 48 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُطْعِمُونَ","transliteration":"","meaning":"you feed","rule":"5:89"},{"arabic":"ٱلطَّعَامَ","transliteration":"","meaning":"[the] food","rule":"5:75"},{"arabic":"أَنُطْعِمُ","transliteration":"","meaning":"Should we feed","rule":"36:47"},{"arabic":"نُطْعِمُكُمْ","transliteration":"","meaning":"we feed you","rule":"76:9"},{"arabic":"وَطَعَامُهُۥ","transliteration":"","meaning":"and its food","rule":"5:96"},{"arabic":"نُطْعِمُ","transliteration":"","meaning":"feed","rule":"74:44"}],"rules":[{"name":"Words on طعم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُطْعِمُونَ","ٱلطَّعَامَ","أَنُطْعِمُ","نُطْعِمُكُمْ","وَطَعَامُهُۥ","نُطْعِمُ","أَطْعَمَهُۥٓ","وَطَعَامُ"]},{"name":"Parts of speech attested for طعم","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 38 glossed words attested.","examples":["تُطْعِمُونَ","ٱلطَّعَامَ","أَنُطْعِمُ","نُطْعِمُكُمْ","وَطَعَامُهُۥ","نُطْعِمُ"]},{"name":"Verb forms attested for طعم","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["تُطْعِمُونَ","ٱلطَّعَامَ","أَنُطْعِمُ","نُطْعِمُكُمْ","وَطَعَامُهُۥ","نُطْعِمُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طعم?","options":["وَإِخْوَٰنُهُمْ","يَأْخُذُوهُ","تُطْعِمُونَ","ٱلشَّوْكَةِ"],"correct":2,"explanation":"تُطْعِمُونَ — glossed \"you feed\" at 5:89 — carries the root طعم. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلطَّعَامَ mean?","options":["(is) Allah","they purchase","[the] food","We will"],"correct":2,"explanation":"\"[the] food\", from the word-by-word gloss at 5:75."},{"type":"fill_blank","question":"Type the root of أَنُطْعِمُ in Arabic (three letters).","correct":"طعم","explanation":"طعم. Diacritics are ignored when checking, so ط ع م is enough."}]', '["root-Avm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qdm', 'The root قدم (ق د م)', 'grammar', 4, '{"explanation":"The root قدم occurs 48 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, X, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمُسْتَقْدِمِينَ","transliteration":"","meaning":"the preceding ones","rule":"15:24"},{"arabic":"فَقَدِّمُوا۟","transliteration":"","meaning":"then offer","rule":"58:12"},{"arabic":"أَقْدَامَنَا","transliteration":"","meaning":"our feet","rule":"2:250"},{"arabic":"وَقَدِمْنَآ","transliteration":"","meaning":"And We will proceed","rule":"25:23"},{"arabic":"قَدَّمْتُ","transliteration":"","meaning":"I sent forth","rule":"50:28"},{"arabic":"يَقْدُمُ","transliteration":"","meaning":"He will precede","rule":"11:98"}],"rules":[{"name":"Words on قدم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمُسْتَقْدِمِينَ","فَقَدِّمُوا۟","أَقْدَامَنَا","وَقَدِمْنَآ","قَدَّمْتُ","يَقْدُمُ","قَدَّمَ","وَٱلْأَقْدَامِ"]},{"name":"Parts of speech attested for قدم","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 26 glossed words attested.","examples":["ٱلْمُسْتَقْدِمِينَ","فَقَدِّمُوا۟","أَقْدَامَنَا","وَقَدِمْنَآ","قَدَّمْتُ","يَقْدُمُ"]},{"name":"Verb forms attested for قدم","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, X, V.","examples":["ٱلْمُسْتَقْدِمِينَ","فَقَدِّمُوا۟","أَقْدَامَنَا","وَقَدِمْنَآ","قَدَّمْتُ","يَقْدُمُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قدم?","options":["ٱلْمُسْتَقْدِمِينَ","وَيَذْهَبَا","أَسِفًۭا","وَٱلشَّمْسَ"],"correct":0,"explanation":"ٱلْمُسْتَقْدِمِينَ — glossed \"the preceding ones\" at 15:24 — carries the root قدم. The others come from different roots."},{"type":"multiple_choice","question":"What does فَقَدِّمُوا۟ mean?","options":["(will) come","painful","(the) People","then offer"],"correct":3,"explanation":"\"then offer\", from the word-by-word gloss at 58:12."},{"type":"fill_blank","question":"Type the root of أَقْدَامَنَا in Arabic (three letters).","correct":"قدم","explanation":"قدم. Diacritics are ignored when checking, so ق د م is enough."}]', '["root-TEm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-x$y', 'The root خشي (خ ش ي)', 'grammar', 4, '{"explanation":"The root خشي occurs 48 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"خَشْيَةِ","transliteration":"","meaning":"fear","rule":"2:74"},{"arabic":"وَتَخْشَى","transliteration":"","meaning":"And you fear","rule":"33:37"},{"arabic":"فَتَخْشَىٰ","transliteration":"","meaning":"so you would fear","rule":"79:19"},{"arabic":"تَخْشَىٰهُ","transliteration":"","meaning":"you (should) fear Him","rule":"33:37"},{"arabic":"يَخْشَىٰٓ","transliteration":"","meaning":"fears","rule":"79:26"},{"arabic":"يَخْشَوْنَ","transliteration":"","meaning":"[they] fear","rule":"4:77"}],"rules":[{"name":"Words on خشي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["خَشْيَةِ","وَتَخْشَى","فَتَخْشَىٰ","تَخْشَىٰهُ","يَخْشَىٰٓ","يَخْشَوْنَ","تَخْشَوْنَ","تَخْشَوُا۟"]},{"name":"Parts of speech attested for خشي","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 33 glossed words attested.","examples":["خَشْيَةِ","وَتَخْشَى","فَتَخْشَىٰ","تَخْشَىٰهُ","يَخْشَىٰٓ","يَخْشَوْنَ"]},{"name":"Where خشي occurs","description":"The 33 glossed words on this root are attested across 16 distinct surahs.","examples":["خَشْيَةِ (2:74)","وَتَخْشَى (33:37)","فَتَخْشَىٰ (79:19)","تَخْشَىٰهُ (33:37)","يَخْشَىٰٓ (79:26)","يَخْشَوْنَ (4:77)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خشي?","options":["وَءَالُ","مُؤْمِنٌۭ","خَشْيَةِ","تَأْكُلُوٓا۟"],"correct":2,"explanation":"خَشْيَةِ — glossed \"fear\" at 2:74 — carries the root خشي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَتَخْشَى mean?","options":["And you fear","they (can) intercede","So bring us","then let discharge"],"correct":0,"explanation":"\"And you fear\", from the word-by-word gloss at 33:37."},{"type":"fill_blank","question":"Type the root of فَتَخْشَىٰ in Arabic (three letters).","correct":"خشي","explanation":"خشي. Diacritics are ignored when checking, so خ ش ي is enough."}]', '["root-qdm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ejl', 'The root عجل (ع ج ل)', 'grammar', 4, '{"explanation":"The root عجل occurs 47 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms V, X, II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَسْتَعْجِلُونَ","transliteration":"","meaning":"you seek to hasten","rule":"6:57"},{"arabic":"عِجْلًۭا","transliteration":"","meaning":"a calf","rule":"7:148"},{"arabic":"لِتَعْجَلَ","transliteration":"","meaning":"to hasten","rule":"75:16"},{"arabic":"ٱسْتَعْجَلْتُم","transliteration":"","meaning":"you were asking it to be hastened","rule":"46:24"},{"arabic":"يُعَجِّلُ","transliteration":"","meaning":"hastens","rule":"10:11"},{"arabic":"ٱلْعَاجِلَةَ","transliteration":"","meaning":"the immediate","rule":"17:18"}],"rules":[{"name":"Words on عجل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَسْتَعْجِلُونَ","عِجْلًۭا","لِتَعْجَلَ","ٱسْتَعْجَلْتُم","يُعَجِّلُ","ٱلْعَاجِلَةَ","عَجِّل","عَجَّلْنَا"]},{"name":"Parts of speech attested for عجل","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["تَسْتَعْجِلُونَ","عِجْلًۭا","لِتَعْجَلَ","ٱسْتَعْجَلْتُم","يُعَجِّلُ","ٱلْعَاجِلَةَ"]},{"name":"Verb forms attested for عجل","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, X, II, IV.","examples":["تَسْتَعْجِلُونَ","عِجْلًۭا","لِتَعْجَلَ","ٱسْتَعْجَلْتُم","يُعَجِّلُ","ٱلْعَاجِلَةَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عجل?","options":["أُمُّكِ","وَتَنشَقُّ","تَسْتَعْجِلُونَ","شِقَاقَ"],"correct":2,"explanation":"تَسْتَعْجِلُونَ — glossed \"you seek to hasten\" at 6:57 — carries the root عجل. The others come from different roots."},{"type":"multiple_choice","question":"What does عِجْلًۭا mean?","options":["(are) grateful","a calf","(the) command","the human kind"],"correct":1,"explanation":"\"a calf\", from the word-by-word gloss at 7:148."},{"type":"fill_blank","question":"Type the root of لِتَعْجَلَ in Arabic (three letters).","correct":"عجل","explanation":"عجل. Diacritics are ignored when checking, so ع ج ل is enough."}]', '["root-x$y"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-krm', 'The root كرم (ك ر م)', 'grammar', 4, '{"explanation":"The root كرم occurs 47 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَرِيمٌۭ","transliteration":"","meaning":"noble","rule":"8:4"},{"arabic":"كَرِيمًۭا","transliteration":"","meaning":"noble","rule":"4:31"},{"arabic":"كِرَامًۭا","transliteration":"","meaning":"(as) dignified ones","rule":"25:72"},{"arabic":"ٱلْكَرِيمِ","transliteration":"","meaning":"Honorable","rule":"23:116"},{"arabic":"كِرَامٍۭ","transliteration":"","meaning":"Noble","rule":"80:16"},{"arabic":"أَكْرَمَنِ","transliteration":"","meaning":"has honored me","rule":"89:15"}],"rules":[{"name":"Words on كرم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَرِيمٌۭ","كَرِيمًۭا","كِرَامًۭا","ٱلْكَرِيمِ","كِرَامٍۭ","أَكْرَمَنِ","ٱلْأَكْرَمُ","كَرِيمٍۢ"]},{"name":"Parts of speech attested for كرم","description":"The morphology corpus tags words on this root as ADJ, V, N — 3 distinct parts of speech across the 22 glossed words attested.","examples":["كَرِيمٌۭ","كَرِيمًۭا","كِرَامًۭا","ٱلْكَرِيمِ","كِرَامٍۭ","أَكْرَمَنِ"]},{"name":"Verb forms attested for كرم","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["كَرِيمٌۭ","كَرِيمًۭا","كِرَامًۭا","ٱلْكَرِيمِ","كِرَامٍۭ","أَكْرَمَنِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كرم?","options":["كَرِيمٌۭ","وَأَيَّدَهُۥ","وَأْتَمِرُوا۟","إِمَامًۭا"],"correct":0,"explanation":"كَرِيمٌۭ — glossed \"noble\" at 8:4 — carries the root كرم. The others come from different roots."},{"type":"multiple_choice","question":"What does كَرِيمًۭا mean?","options":["the fly","I made them witness","noble","in faith"],"correct":2,"explanation":"\"noble\", from the word-by-word gloss at 4:31."},{"type":"fill_blank","question":"Type the root of كِرَامًۭا in Arabic (three letters).","correct":"كرم","explanation":"كرم. Diacritics are ignored when checking, so ك ر م is enough."}]', '["root-Ejl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ehd', 'The root عهد (ع ه د)', 'grammar', 4, '{"explanation":"The root عهد occurs 46 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N, V, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَـٰهَدُوا۟","transliteration":"","meaning":"they took","rule":"2:100"},{"arabic":"عَهْدِى","transliteration":"","meaning":"My Covenant","rule":"2:124"},{"arabic":"ٱلْعَهْدُ","transliteration":"","meaning":"the promise","rule":"20:86"},{"arabic":"عَهْدُ","transliteration":"","meaning":"(the) promise","rule":"33:15"},{"arabic":"عَهْدًۭا","transliteration":"","meaning":"a covenant","rule":"2:80"},{"arabic":"عَهْدٌ","transliteration":"","meaning":"a covenant","rule":"9:7"}],"rules":[{"name":"Words on عهد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَـٰهَدُوا۟","عَهْدِى","ٱلْعَهْدُ","عَهْدُ","عَهْدًۭا","عَهْدٌ","عَـٰهَدتُّمْ","بِعَهْدِ"]},{"name":"Parts of speech attested for عهد","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 28 glossed words attested.","examples":["عَـٰهَدُوا۟","عَهْدِى","ٱلْعَهْدُ","عَهْدُ","عَهْدًۭا","عَهْدٌ"]},{"name":"Verb forms attested for عهد","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["عَـٰهَدُوا۟","عَهْدِى","ٱلْعَهْدُ","عَهْدُ","عَهْدًۭا","عَهْدٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عهد?","options":["أَثِيمٍۢ","أُمَّ","بِأَمْرِهِۦٓ","عَـٰهَدُوا۟"],"correct":3,"explanation":"عَـٰهَدُوا۟ — glossed \"they took\" at 2:100 — carries the root عهد. The others come from different roots."},{"type":"multiple_choice","question":"What does عَهْدِى mean?","options":["We gave [them]","My Covenant","to our gods","(is) One God"],"correct":1,"explanation":"\"My Covenant\", from the word-by-word gloss at 2:124."},{"type":"fill_blank","question":"Type the root of ٱلْعَهْدُ in Arabic (three letters).","correct":"عهد","explanation":"عهد. Diacritics are ignored when checking, so ع ه د is enough."}]', '["root-krm"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Sdr', 'The root صدر (ص د ر)', 'grammar', 4, '{"explanation":"The root صدر occurs 46 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صَدْرَهُۥ","transliteration":"","meaning":"his breast","rule":"6:125"},{"arabic":"صُدُورَ","transliteration":"","meaning":"(the) breasts","rule":"9:14"},{"arabic":"ٱلصُّدُورِ","transliteration":"","meaning":"(is in) the breasts","rule":"3:119"},{"arabic":"صُدُورِكُمْ","transliteration":"","meaning":"your breasts","rule":"3:29"},{"arabic":"ٱلصُّدُورُ","transliteration":"","meaning":"the breasts","rule":"40:19"},{"arabic":"صُدُورُهُمْ","transliteration":"","meaning":"their breasts","rule":"3:118"}],"rules":[{"name":"Words on صدر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صَدْرَهُۥ","صُدُورَ","ٱلصُّدُورِ","صُدُورِكُمْ","ٱلصُّدُورُ","صُدُورُهُمْ","صَدْرُكَ","صُدُورَهُمْ"]},{"name":"Parts of speech attested for صدر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["صَدْرَهُۥ","صُدُورَ","ٱلصُّدُورِ","صُدُورِكُمْ","ٱلصُّدُورُ","صُدُورُهُمْ"]},{"name":"Verb forms attested for صدر","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["صَدْرَهُۥ","صُدُورَ","ٱلصُّدُورِ","صُدُورِكُمْ","ٱلصُّدُورُ","صُدُورُهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صدر?","options":["بِذُنُوبِهِمْ","ٱللَّهُ","صَدْرَهُۥ","فَلْيَأْتُوا۟"],"correct":2,"explanation":"صَدْرَهُۥ — glossed \"his breast\" at 6:125 — carries the root صدر. The others come from different roots."},{"type":"multiple_choice","question":"What does صُدُورَ mean?","options":["the Remembrance","intercessor","(the) brink","(the) breasts"],"correct":3,"explanation":"\"(the) breasts\", from the word-by-word gloss at 9:14."},{"type":"fill_blank","question":"Type the root of ٱلصُّدُورِ in Arabic (three letters).","correct":"صدر","explanation":"صدر. Diacritics are ignored when checking, so ص د ر is enough."}]', '["root-Ehd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-zyn', 'The root زين (ز ي ن)', 'grammar', 4, '{"explanation":"The root زين occurs 46 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as V, N, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَزِينَتُهَا","transliteration":"","meaning":"and its adornment","rule":"28:60"},{"arabic":"فَزَيَّنُوا۟","transliteration":"","meaning":"(who) made fair-seeming","rule":"41:25"},{"arabic":"زِينَتِهِۦ","transliteration":"","meaning":"his adornment","rule":"28:79"},{"arabic":"ٱلزِّينَةِ","transliteration":"","meaning":"(of) the festival","rule":"20:59"},{"arabic":"وَزَيَّنَّا","transliteration":"","meaning":"And We adorned","rule":"41:12"},{"arabic":"زُيِّنَ","transliteration":"","meaning":"Beautified","rule":"2:212"}],"rules":[{"name":"Words on زين","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَزِينَتُهَا","فَزَيَّنُوا۟","زِينَتِهِۦ","ٱلزِّينَةِ","وَزَيَّنَّا","زُيِّنَ","زِينَتِهِنَّ","وَٱزَّيَّنَتْ"]},{"name":"Parts of speech attested for زين","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 27 glossed words attested.","examples":["وَزِينَتُهَا","فَزَيَّنُوا۟","زِينَتِهِۦ","ٱلزِّينَةِ","وَزَيَّنَّا","زُيِّنَ"]},{"name":"Verb forms attested for زين","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["وَزِينَتُهَا","فَزَيَّنُوا۟","زِينَتِهِۦ","ٱلزِّينَةِ","وَزَيَّنَّا","زُيِّنَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root زين?","options":["وَلْيُؤْمِنُوا۟","أَخَاهُمْ","وَزِينَتُهَا","ٱللَّهُ"],"correct":2,"explanation":"وَزِينَتُهَا — glossed \"and its adornment\" at 28:60 — carries the root زين. The others come from different roots."},{"type":"multiple_choice","question":"What does فَزَيَّنُوا۟ mean?","options":["he may eat","the Signs of Allah","(who) made fair-seeming","(for final) determination"],"correct":2,"explanation":"\"(who) made fair-seeming\", from the word-by-word gloss at 41:25."},{"type":"fill_blank","question":"Type the root of زِينَتِهِۦ in Arabic (three letters).","correct":"زين","explanation":"زين. Diacritics are ignored when checking, so ز ي ن is enough."}]', '["root-Sdr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-SbH', 'The root صبح (ص ب ح)', 'grammar', 4, '{"explanation":"The root صبح occurs 45 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, T, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِمَصَـٰبِيحَ","transliteration":"","meaning":"with lamps","rule":"41:12"},{"arabic":"مُصْبِحِينَ","transliteration":"","meaning":"(at) early morning","rule":"15:83"},{"arabic":"فَتُصْبِحُ","transliteration":"","meaning":"then becomes","rule":"22:63"},{"arabic":"يُصْبِحَ","transliteration":"","meaning":"will become","rule":"18:41"},{"arabic":"مِصْبَاحٌ","transliteration":"","meaning":"(is) a lamp","rule":"24:35"},{"arabic":"لَّيُصْبِحُنَّ","transliteration":"","meaning":"surely they will become","rule":"23:40"}],"rules":[{"name":"Words on صبح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِمَصَـٰبِيحَ","مُصْبِحِينَ","فَتُصْبِحُ","يُصْبِحَ","مِصْبَاحٌ","لَّيُصْبِحُنَّ","فَتُصْبِحَ","صَبَاحُ"]},{"name":"Parts of speech attested for صبح","description":"The morphology corpus tags words on this root as V, N, T — 3 distinct parts of speech across the 25 glossed words attested.","examples":["بِمَصَـٰبِيحَ","مُصْبِحِينَ","فَتُصْبِحُ","يُصْبِحَ","مِصْبَاحٌ","لَّيُصْبِحُنَّ"]},{"name":"Verb forms attested for صبح","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["بِمَصَـٰبِيحَ","مُصْبِحِينَ","فَتُصْبِحُ","يُصْبِحَ","مِصْبَاحٌ","لَّيُصْبِحُنَّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صبح?","options":["بِمَصَـٰبِيحَ","إِيمَـٰنَكُمْ","ٱللَّهُ","وَأَخَذْنَ"],"correct":0,"explanation":"بِمَصَـٰبِيحَ — glossed \"with lamps\" at 41:12 — carries the root صبح. The others come from different roots."},{"type":"multiple_choice","question":"What does مُصْبِحِينَ mean?","options":["(at) early morning","come to you","And seized","one of you"],"correct":0,"explanation":"\"(at) early morning\", from the word-by-word gloss at 15:83."},{"type":"fill_blank","question":"Type the root of فَتُصْبِحُ in Arabic (three letters).","correct":"صبح","explanation":"صبح. Diacritics are ignored when checking, so ص ب ح is enough."}]', '["root-zyn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-SrT', 'The root صرط (ص ر ط)', 'grammar', 4, '{"explanation":"The root صرط occurs 45 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صِرَٰطُ","transliteration":"","meaning":"(is the) way","rule":"6:126"},{"arabic":"صِرَٰطِى","transliteration":"","meaning":"(is) My path","rule":"6:153"},{"arabic":"صِرَٰطَكَ","transliteration":"","meaning":"(on) Your path","rule":"7:16"},{"arabic":"صِرَٰطٌ","transliteration":"","meaning":"(is) the way","rule":"15:41"},{"arabic":"ٱلصِّرَٰطِ","transliteration":"","meaning":"(of) the way","rule":"20:135"},{"arabic":"صِرَٰطٌۭ","transliteration":"","meaning":"(is) the path","rule":"3:51"}],"rules":[{"name":"Words on صرط","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صِرَٰطُ","صِرَٰطِى","صِرَٰطَكَ","صِرَٰطٌ","ٱلصِّرَٰطِ","صِرَٰطٌۭ","صِرَٰطَ","صِرَٰطٍۢ"]},{"name":"Parts of speech attested for صرط","description":"The morphology corpus tags words on this root as N — one part of speech across the 11 glossed words attested.","examples":["صِرَٰطُ","صِرَٰطِى","صِرَٰطَكَ","صِرَٰطٌ","ٱلصِّرَٰطِ","صِرَٰطٌۭ"]},{"name":"Where صرط occurs","description":"The 11 glossed words on this root are attested across 9 distinct surahs.","examples":["صِرَٰطُ (6:126)","صِرَٰطِى (6:153)","صِرَٰطَكَ (7:16)","صِرَٰطٌ (15:41)","ٱلصِّرَٰطِ (20:135)","صِرَٰطٌۭ (3:51)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صرط?","options":["ٱلْإِثْمَ","أُمَّةٍۢ","أَهْلِيكُمْ","صِرَٰطُ"],"correct":3,"explanation":"صِرَٰطُ — glossed \"(is the) way\" at 6:126 — carries the root صرط. The others come from different roots."},{"type":"multiple_choice","question":"What does صِرَٰطِى mean?","options":["that he may taste","And give","(is) My path","(are) certainly a band"],"correct":2,"explanation":"\"(is) My path\", from the word-by-word gloss at 6:153."},{"type":"fill_blank","question":"Type the root of صِرَٰطَكَ in Arabic (three letters).","correct":"صرط","explanation":"صرط. Diacritics are ignored when checking, so ص ر ط is enough."}]', '["root-SbH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nsy', 'The root نسي (ن س ي)', 'grammar', 4, '{"explanation":"The root نسي occurs 45 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُنسَىٰ","transliteration":"","meaning":"you will be forgotten","rule":"20:126"},{"arabic":"نَسْيًۭا","transliteration":"","meaning":"(in) oblivion","rule":"19:23"},{"arabic":"أَنسَىٰنِيهُ","transliteration":"","meaning":"made me forget it","rule":"18:63"},{"arabic":"نَسُوا۟","transliteration":"","meaning":"they forgot","rule":"6:44"},{"arabic":"وَتَنسَوْنَ","transliteration":"","meaning":"and you forget","rule":"2:44"},{"arabic":"نَسِيَا","transliteration":"","meaning":"they forgot","rule":"18:61"}],"rules":[{"name":"Words on نسي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُنسَىٰ","نَسْيًۭا","أَنسَىٰنِيهُ","نَسُوا۟","وَتَنسَوْنَ","نَسِيَا","تَنسَىٰٓ","نَسِىَ"]},{"name":"Parts of speech attested for نسي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 33 glossed words attested.","examples":["تُنسَىٰ","نَسْيًۭا","أَنسَىٰنِيهُ","نَسُوا۟","وَتَنسَوْنَ","نَسِيَا"]},{"name":"Verb forms attested for نسي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تُنسَىٰ","نَسْيًۭا","أَنسَىٰنِيهُ","نَسُوا۟","وَتَنسَوْنَ","نَسِيَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نسي?","options":["يَسْتَـْٔذِنُكَ","فَإِخْوَٰنُكُمْ","يُؤَاخِذُكُمُ","تُنسَىٰ"],"correct":3,"explanation":"تُنسَىٰ — glossed \"you will be forgotten\" at 20:126 — carries the root نسي. The others come from different roots."},{"type":"multiple_choice","question":"What does نَسْيًۭا mean?","options":["(in) oblivion","his faith","witnesses","those who enjoin"],"correct":0,"explanation":"\"(in) oblivion\", from the word-by-word gloss at 19:23."},{"type":"fill_blank","question":"Type the root of أَنسَىٰنِيهُ in Arabic (three letters).","correct":"نسي","explanation":"نسي. Diacritics are ignored when checking, so ن س ي is enough."}]', '["root-SrT"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-w*r', 'The root وذر (و ذ ر)', 'grammar', 4, '{"explanation":"The root وذر occurs 45 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَذَرُ","transliteration":"","meaning":"it left","rule":"51:42"},{"arabic":"وَّنَذَرُ","transliteration":"","meaning":"and We will leave","rule":"19:72"},{"arabic":"وَيَذَرُونَ","transliteration":"","meaning":"and leave behind","rule":"2:234"},{"arabic":"فَيَذَرُهَا","transliteration":"","meaning":"Then He will leave it","rule":"20:106"},{"arabic":"فَتَذَرُوهَا","transliteration":"","meaning":"and leave her (the other)","rule":"4:129"},{"arabic":"تَذَرْ","transliteration":"","meaning":"leave","rule":"71:26"}],"rules":[{"name":"Words on وذر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَذَرُ","وَّنَذَرُ","وَيَذَرُونَ","فَيَذَرُهَا","فَتَذَرُوهَا","تَذَرْ","فَذَرُوهُ","تَذَرُنَّ"]},{"name":"Parts of speech attested for وذر","description":"The morphology corpus tags words on this root as V — one part of speech across the 29 glossed words attested.","examples":["تَذَرُ","وَّنَذَرُ","وَيَذَرُونَ","فَيَذَرُهَا","فَتَذَرُوهَا","تَذَرْ"]},{"name":"Where وذر occurs","description":"The 29 glossed words on this root are attested across 19 distinct surahs.","examples":["تَذَرُ (51:42)","وَّنَذَرُ (19:72)","وَيَذَرُونَ (2:234)","فَيَذَرُهَا (20:106)","فَتَذَرُوهَا (4:129)","تَذَرْ (71:26)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وذر?","options":["أَنُؤْمِنُ","وَٱلْمُؤْتَفِكَـٰتِ","وَإِخْوَٰنِهِمْ","تَذَرُ"],"correct":3,"explanation":"تَذَرُ — glossed \"it left\" at 51:42 — carries the root وذر. The others come from different roots."},{"type":"multiple_choice","question":"What does وَّنَذَرُ mean?","options":["We will","his brother","[the] poetry","and We will leave"],"correct":3,"explanation":"\"and We will leave\", from the word-by-word gloss at 19:72."},{"type":"fill_blank","question":"Type the root of وَيَذَرُونَ in Arabic (three letters).","correct":"وذر","explanation":"وذر. Diacritics are ignored when checking, so و ذ ر is enough."}]', '["root-nsy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-HfZ', 'The root حفظ (ح ف ظ)', 'grammar', 4, '{"explanation":"The root حفظ occurs 44 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms III, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْحَـٰفِظَـٰتِ","transliteration":"","meaning":"and the women who guard (it)","rule":"33:35"},{"arabic":"وَيَحْفَظْنَ","transliteration":"","meaning":"and they should guard","rule":"24:31"},{"arabic":"وَيَحْفَظُوا۟","transliteration":"","meaning":"and they should guard","rule":"24:30"},{"arabic":"مَّحْفُوظٍۭ","transliteration":"","meaning":"Guarded","rule":"85:22"},{"arabic":"حَـٰفِظًۭا","transliteration":"","meaning":"Guardian","rule":"12:64"},{"arabic":"حِفْظُهُمَا","transliteration":"","meaning":"(the) guarding of both of them","rule":"2:255"}],"rules":[{"name":"Words on حفظ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْحَـٰفِظَـٰتِ","وَيَحْفَظْنَ","وَيَحْفَظُوا۟","مَّحْفُوظٍۭ","حَـٰفِظًۭا","حِفْظُهُمَا","وَٱلْحَـٰفِظِينَ","وَحَفِظْنَـٰهَا"]},{"name":"Parts of speech attested for حفظ","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 32 glossed words attested.","examples":["وَٱلْحَـٰفِظَـٰتِ","وَيَحْفَظْنَ","وَيَحْفَظُوا۟","مَّحْفُوظٍۭ","حَـٰفِظًۭا","حِفْظُهُمَا"]},{"name":"Verb forms attested for حفظ","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, X.","examples":["وَٱلْحَـٰفِظَـٰتِ","وَيَحْفَظْنَ","وَيَحْفَظُوا۟","مَّحْفُوظٍۭ","حَـٰفِظًۭا","حِفْظُهُمَا"]}]}', '[{"type":"multiple_choice","questi