INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fSl', 'The root فصل (ف ص ل)', 'grammar', 4, '{"explanation":"The root فصل occurs 43 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فُصِّلَتْ","transliteration":"","meaning":"explained in detail","rule":"11:1"},{"arabic":"وَفَصِيلَتِهِ","transliteration":"","meaning":"And his nearest kindred","rule":"70:13"},{"arabic":"وَفَصْلَ","transliteration":"","meaning":"and decisive","rule":"38:20"},{"arabic":"وَنُفَصِّلُ","transliteration":"","meaning":"And We explain in detail","rule":"9:11"},{"arabic":"وَتَفْصِيلَ","transliteration":"","meaning":"and a detailed explanation","rule":"10:37"},{"arabic":"فَصَلَ","transliteration":"","meaning":"set out","rule":"2:249"}],"rules":[{"name":"Words on فصل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فُصِّلَتْ","وَفَصِيلَتِهِ","وَفَصْلَ","وَنُفَصِّلُ","وَتَفْصِيلَ","فَصَلَ","فَصَلَتِ","فَصَّلْنَـٰهُ"]},{"name":"Parts of speech attested for فصل","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 22 glossed words attested.","examples":["فُصِّلَتْ","وَفَصِيلَتِهِ","وَفَصْلَ","وَنُفَصِّلُ","وَتَفْصِيلَ","فَصَلَ"]},{"name":"Verb forms attested for فصل","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["فُصِّلَتْ","وَفَصِيلَتِهِ","وَفَصْلَ","وَنُفَصِّلُ","وَتَفْصِيلَ","فَصَلَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فصل?","options":["أُذُنٌۭ","يُؤَاخِذُ","ٱللَّهِ","فُصِّلَتْ"],"correct":3,"explanation":"فُصِّلَتْ — glossed \"explained in detail\" at 11:1 — carries the root فصل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَفَصِيلَتِهِ mean?","options":["for men","are you deluded","And his nearest kindred","(the) mention"],"correct":2,"explanation":"\"And his nearest kindred\", from the word-by-word gloss at 70:13."},{"type":"fill_blank","question":"Type the root of وَفَصْلَ in Arabic (three letters).","correct":"فصل","explanation":"فصل. Diacritics are ignored when checking, so ف ص ل is enough."}]', '["root-H$r"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fwq', 'The root فوق (ف و ق)', 'grammar', 4, '{"explanation":"The root فوق occurs 43 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as LOC, N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَوْقَ","transliteration":"","meaning":"superior","rule":"3:55"},{"arabic":"فَوْقَكُمْ","transliteration":"","meaning":"above you","rule":"23:17"},{"arabic":"فَوْقِهِنَّ","transliteration":"","meaning":"above them","rule":"42:5"},{"arabic":"فَوْقِهَا","transliteration":"","meaning":"above them","rule":"39:20"},{"arabic":"فَوْقَهُمُ","transliteration":"","meaning":"over them","rule":"4:154"},{"arabic":"أَفَاقَ","transliteration":"","meaning":"he recovered","rule":"7:143"}],"rules":[{"name":"Words on فوق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَوْقَ","فَوْقَكُمْ","فَوْقِهِنَّ","فَوْقِهَا","فَوْقَهُمُ","أَفَاقَ","فَوْقِكُمْ","فَوْقَكُمُ"]},{"name":"Parts of speech attested for فوق","description":"The morphology corpus tags words on this root as LOC, N, V — 3 distinct parts of speech across the 15 glossed words attested.","examples":["فَوْقَ","فَوْقَكُمْ","فَوْقِهِنَّ","فَوْقِهَا","فَوْقَهُمُ","أَفَاقَ"]},{"name":"Verb forms attested for فوق","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["فَوْقَ","فَوْقَكُمْ","فَوْقِهِنَّ","فَوْقِهَا","فَوْقَهُمُ","أَفَاقَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فوق?","options":["لِلْإِيمَـٰنِ","كَمِشْكَوٰةٍۢ","فَوْقَ","تَذْرُوهُ"],"correct":2,"explanation":"فَوْقَ — glossed \"superior\" at 3:55 — carries the root فوق. The others come from different roots."},{"type":"multiple_choice","question":"What does فَوْقَكُمْ mean?","options":["had willed","Is it falsehood","(do) I testify","above you"],"correct":3,"explanation":"\"above you\", from the word-by-word gloss at 23:17."},{"type":"fill_blank","question":"Type the root of فَوْقِهِنَّ in Arabic (three letters).","correct":"فوق","explanation":"فوق. Diacritics are ignored when checking, so ف و ق is enough."}]', '["root-fSl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jwb', 'The root جوب (ج و ب)', 'grammar', 4, '{"explanation":"The root جوب occurs 43 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَيَسْتَجِيبُ","transliteration":"","meaning":"And He answers","rule":"42:26"},{"arabic":"فَٱسْتَجَبْتُمْ","transliteration":"","meaning":"and you responded","rule":"14:22"},{"arabic":"أَجِيبُوا۟","transliteration":"","meaning":"Respond","rule":"46:31"},{"arabic":"يُجِبْ","transliteration":"","meaning":"respond","rule":"46:32"},{"arabic":"فَٱسْتَجَبْنَا","transliteration":"","meaning":"so We responded","rule":"21:76"},{"arabic":"أُجِيبَت","transliteration":"","meaning":"has been answered","rule":"10:89"}],"rules":[{"name":"Words on جوب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَيَسْتَجِيبُ","فَٱسْتَجَبْتُمْ","أَجِيبُوا۟","يُجِبْ","فَٱسْتَجَبْنَا","أُجِيبَت","فَٱسْتَجَابَ","يَسْتَجِيبُوا۟"]},{"name":"Parts of speech attested for جوب","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 25 glossed words attested.","examples":["وَيَسْتَجِيبُ","فَٱسْتَجَبْتُمْ","أَجِيبُوا۟","يُجِبْ","فَٱسْتَجَبْنَا","أُجِيبَت"]},{"name":"Verb forms attested for جوب","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["وَيَسْتَجِيبُ","فَٱسْتَجَبْتُمْ","أَجِيبُوا۟","يُجِبْ","فَٱسْتَجَبْنَا","أُجِيبَت"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جوب?","options":["إِنَىٰهُ","وَأَبُونَا","أُشْرِكْ","وَيَسْتَجِيبُ"],"correct":3,"explanation":"وَيَسْتَجِيبُ — glossed \"And He answers\" at 42:26 — carries the root جوب. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱسْتَجَبْتُمْ mean?","options":["and you responded","another people","eat","And give"],"correct":0,"explanation":"\"and you responded\", from the word-by-word gloss at 14:22."},{"type":"fill_blank","question":"Type the root of أَجِيبُوا۟ in Arabic (three letters).","correct":"جوب","explanation":"جوب. Diacritics are ignored when checking, so ج و ب is enough."}]', '["root-fwq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mkr', 'The root مكر (م ك ر)', 'grammar', 4, '{"explanation":"The root مكر occurs 43 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَمْكُرُونَ","transliteration":"","meaning":"they plot","rule":"6:123"},{"arabic":"وَيَمْكُرُ","transliteration":"","meaning":"and (also) was planning","rule":"8:30"},{"arabic":"وَيَمْكُرُونَ","transliteration":"","meaning":"And they were planning","rule":"8:30"},{"arabic":"وَمَكْرَ","transliteration":"","meaning":"and plotting","rule":"35:43"},{"arabic":"مَّكَرْتُمُوهُ","transliteration":"","meaning":"you have plotted it","rule":"7:123"},{"arabic":"وَمَكْرُ","transliteration":"","meaning":"and (the) plotting","rule":"35:10"}],"rules":[{"name":"Words on مكر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَمْكُرُونَ","وَيَمْكُرُ","وَيَمْكُرُونَ","وَمَكْرَ","مَّكَرْتُمُوهُ","وَمَكْرُ","تَمْكُرُونَ","لَمَكْرٌۭ"]},{"name":"Parts of speech attested for مكر","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 26 glossed words attested.","examples":["يَمْكُرُونَ","وَيَمْكُرُ","وَيَمْكُرُونَ","وَمَكْرَ","مَّكَرْتُمُوهُ","وَمَكْرُ"]},{"name":"Where مكر occurs","description":"The 26 glossed words on this root are attested across 11 distinct surahs.","examples":["يَمْكُرُونَ (6:123)","وَيَمْكُرُ (8:30)","وَيَمْكُرُونَ (8:30)","وَمَكْرَ (35:43)","مَّكَرْتُمُوهُ (7:123)","وَمَكْرُ (35:10)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مكر?","options":["ءَاتَىٰهُمُ","شَقُوا۟","يَمْكُرُونَ","شَكَرْتُمْ"],"correct":2,"explanation":"يَمْكُرُونَ — glossed \"they plot\" at 6:123 — carries the root مكر. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَمْكُرُ mean?","options":["so Allah made it taste","in Our Signs","(to) anyone","and (also) was planning"],"correct":3,"explanation":"\"and (also) was planning\", from the word-by-word gloss at 8:30."},{"type":"fill_blank","question":"Type the root of وَيَمْكُرُونَ in Arabic (three letters).","correct":"مكر","explanation":"مكر. Diacritics are ignored when checking, so م ك ر is enough."}]', '["root-jwb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-trk', 'The root ترك (ت ر ك)', 'grammar', 4, '{"explanation":"The root ترك occurs 43 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَتَرَكُوكَ","transliteration":"","meaning":"and left you","rule":"62:11"},{"arabic":"تَّرَكْنَا","transliteration":"","meaning":"We have left","rule":"29:35"},{"arabic":"تَرَكَ","transliteration":"","meaning":"he leaves","rule":"2:180"},{"arabic":"يُتْرَكَ","transliteration":"","meaning":"he will be left","rule":"75:36"},{"arabic":"تَرَكْتُمْ","transliteration":"","meaning":"you left","rule":"4:12"},{"arabic":"فَتَرَكَهُۥ","transliteration":"","meaning":"then left it","rule":"2:264"}],"rules":[{"name":"Words on ترك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَتَرَكُوكَ","تَّرَكْنَا","تَرَكَ","يُتْرَكَ","تَرَكْتُمْ","فَتَرَكَهُۥ","تَرَكْتُم","بِتَارِكِىٓ"]},{"name":"Parts of speech attested for ترك","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 25 glossed words attested.","examples":["وَتَرَكُوكَ","تَّرَكْنَا","تَرَكَ","يُتْرَكَ","تَرَكْتُمْ","فَتَرَكَهُۥ"]},{"name":"Where ترك occurs","description":"The 25 glossed words on this root are attested across 16 distinct surahs.","examples":["وَتَرَكُوكَ (62:11)","تَّرَكْنَا (29:35)","تَرَكَ (2:180)","يُتْرَكَ (75:36)","تَرَكْتُمْ (4:12)","فَتَرَكَهُۥ (2:264)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ترك?","options":["شِيعَةٍ","وَتَرَكُوكَ","يَأْتِيَـٰنِهَا","ٱللَّهِ"],"correct":1,"explanation":"وَتَرَكُوكَ — glossed \"and left you\" at 62:11 — carries the root ترك. The others come from different roots."},{"type":"multiple_choice","question":"What does تَّرَكْنَا mean?","options":["any intercession","We have left","(the) Favor of Allah","and family"],"correct":1,"explanation":"\"We have left\", from the word-by-word gloss at 29:35."},{"type":"fill_blank","question":"Type the root of تَرَكَ in Arabic (three letters).","correct":"ترك","explanation":"ترك. Diacritics are ignored when checking, so ت ر ك is enough."}]', '["root-mkr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hzn', 'The root حزن (ح ز ن)', 'grammar', 4, '{"explanation":"The root حزن occurs 42 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَحْزَنْ","transliteration":"","meaning":"grieve","rule":"9:40"},{"arabic":"ٱلْحُزْنِ","transliteration":"","meaning":"the grief","rule":"12:84"},{"arabic":"يَحْزُنُهُمُ","transliteration":"","meaning":"will grieve them","rule":"21:103"},{"arabic":"تَحْزَنِى","transliteration":"","meaning":"grieve","rule":"19:24"},{"arabic":"تَحْزَنَ","transliteration":"","meaning":"she grieves","rule":"20:40"},{"arabic":"يَحْزَنُونَ","transliteration":"","meaning":"will grieve","rule":"2:38"}],"rules":[{"name":"Words on حزن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَحْزَنْ","ٱلْحُزْنِ","يَحْزُنُهُمُ","تَحْزَنِى","تَحْزَنَ","يَحْزَنُونَ","حَزَنًا","تَحْزَنُونَ"]},{"name":"Parts of speech attested for حزن","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 18 glossed words attested.","examples":["تَحْزَنْ","ٱلْحُزْنِ","يَحْزُنُهُمُ","تَحْزَنِى","تَحْزَنَ","يَحْزَنُونَ"]},{"name":"Where حزن occurs","description":"The 18 glossed words on this root are attested across 13 distinct surahs.","examples":["تَحْزَنْ (9:40)","ٱلْحُزْنِ (12:84)","يَحْزُنُهُمُ (21:103)","تَحْزَنِى (19:24)","تَحْزَنَ (20:40)","يَحْزَنُونَ (2:38)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حزن?","options":["ٱللَّهُ","ٱللَّهُ","تَحْزَنْ","ءَالَـٰفٍۢ"],"correct":2,"explanation":"تَحْزَنْ — glossed \"grieve\" at 9:40 — carries the root حزن. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْحُزْنِ mean?","options":["we bring you","(the) God","the grief","they give"],"correct":2,"explanation":"\"the grief\", from the word-by-word gloss at 12:84."},{"type":"fill_blank","question":"Type the root of يَحْزُنُهُمُ in Arabic (three letters).","correct":"حزن","explanation":"حزن. Diacritics are ignored when checking, so ح ز ن is enough."}]', '["root-trk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Sdd', 'The root صدد (ص د د)', 'grammar', 4, '{"explanation":"The root صدد occurs 42 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَصُدُّونَ","transliteration":"","meaning":"turning away","rule":"4:61"},{"arabic":"يَصُدَّنَّكُمُ","transliteration":"","meaning":"avert you","rule":"43:62"},{"arabic":"لِيَصُدُّوا۟","transliteration":"","meaning":"to hinder (people)","rule":"8:36"},{"arabic":"وَيَصُدُّونَ","transliteration":"","meaning":"and hinder (them)","rule":"8:47"},{"arabic":"وَبِصَدِّهِمْ","transliteration":"","meaning":"and for their hindering","rule":"4:160"},{"arabic":"وَصَدُّوكُمْ","transliteration":"","meaning":"and hindered you","rule":"48:25"}],"rules":[{"name":"Words on صدد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَصُدُّونَ","يَصُدَّنَّكُمُ","لِيَصُدُّوا۟","وَيَصُدُّونَ","وَبِصَدِّهِمْ","وَصَدُّوكُمْ","فَصَدَّهُمْ","يَصُدَّكُمْ"]},{"name":"Parts of speech attested for صدد","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 28 glossed words attested.","examples":["يَصُدُّونَ","يَصُدَّنَّكُمُ","لِيَصُدُّوا۟","وَيَصُدُّونَ","وَبِصَدِّهِمْ","وَصَدُّوكُمْ"]},{"name":"Verb forms attested for صدد","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["يَصُدُّونَ","يَصُدَّنَّكُمُ","لِيَصُدُّوا۟","وَيَصُدُّونَ","وَبِصَدِّهِمْ","وَصَدُّوكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صدد?","options":["بِذَنۢبِهِمْ","تَذَكَّرُونَ","يَشْهَدُهُ","يَصُدُّونَ"],"correct":3,"explanation":"يَصُدُّونَ — glossed \"turning away\" at 4:61 — carries the root صدد. The others come from different roots."},{"type":"multiple_choice","question":"What does يَصُدَّنَّكُمُ mean?","options":["(is a share of) drink","avert you","he has been given","(is) more severe"],"correct":1,"explanation":"\"avert you\", from the word-by-word gloss at 43:62."},{"type":"fill_blank","question":"Type the root of لِيَصُدُّوا۟ in Arabic (three letters).","correct":"صدد","explanation":"صدد. Diacritics are ignored when checking, so ص د د is enough."}]', '["root-Hzn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bHr', 'The root بحر (ب ح ر)', 'grammar', 4, '{"explanation":"The root بحر occurs 42 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْبَحْرَيْنِ","transliteration":"","meaning":"(of) the two seas","rule":"18:60"},{"arabic":"وَٱلْبَحْرِ","transliteration":"","meaning":"and in the sea","rule":"6:59"},{"arabic":"ٱلْبَحْرَ","transliteration":"","meaning":"the sea","rule":"2:50"},{"arabic":"وَٱلْبَحْرُ","transliteration":"","meaning":"and the sea","rule":"31:27"},{"arabic":"ٱلْبَحْرُ","transliteration":"","meaning":"the sea","rule":"18:109"},{"arabic":"بَحِيرَةٍۢ","transliteration":"","meaning":"a Bahirah","rule":"5:103"}],"rules":[{"name":"Words on بحر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْبَحْرَيْنِ","وَٱلْبَحْرِ","ٱلْبَحْرَ","وَٱلْبَحْرُ","ٱلْبَحْرُ","بَحِيرَةٍۢ","أَبْحُرٍۢ","بَحْرٍۢ"]},{"name":"Parts of speech attested for بحر","description":"The morphology corpus tags words on this root as N — one part of speech across the 11 glossed words attested.","examples":["ٱلْبَحْرَيْنِ","وَٱلْبَحْرِ","ٱلْبَحْرَ","وَٱلْبَحْرُ","ٱلْبَحْرُ","بَحِيرَةٍۢ"]},{"name":"Where بحر occurs","description":"The 11 glossed words on this root are attested across 8 distinct surahs.","examples":["ٱلْبَحْرَيْنِ (18:60)","وَٱلْبَحْرِ (6:59)","ٱلْبَحْرَ (2:50)","وَٱلْبَحْرُ (31:27)","ٱلْبَحْرُ (18:109)","بَحِيرَةٍۢ (5:103)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بحر?","options":["۞ وَٱذْكُرْ","تُشْرِكُونَ","شَيْـًۭٔا","ٱلْبَحْرَيْنِ"],"correct":3,"explanation":"ٱلْبَحْرَيْنِ — glossed \"(of) the two seas\" at 18:60 — carries the root بحر. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْبَحْرِ mean?","options":["and grieved","and in the sea","Allah has expanded","its shoot"],"correct":1,"explanation":"\"and in the sea\", from the word-by-word gloss at 6:59."},{"type":"fill_blank","question":"Type the root of ٱلْبَحْرَ in Arabic (three letters).","correct":"بحر","explanation":"بحر. Diacritics are ignored when checking, so ب ح ر is enough."}]', '["root-Sdd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qwy', 'The root قوي (ق و ي)', 'grammar', 4, '{"explanation":"The root قوي occurs 42 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِّلْمُقْوِينَ","transliteration":"","meaning":"for the wayfarers in the desert","rule":"56:73"},{"arabic":"قَوِىٌّۭ","transliteration":"","meaning":"(is) All-Strong","rule":"8:52"},{"arabic":"ٱلْقُوَّةِ","transliteration":"","meaning":"possessors of great strength","rule":"28:76"},{"arabic":"قَوِيًّا","transliteration":"","meaning":"All-Strong","rule":"33:25"},{"arabic":"ٱلْقُوَّةَ","transliteration":"","meaning":"the power","rule":"2:165"},{"arabic":"قَوِىٌّ","transliteration":"","meaning":"(is) All-Strong","rule":"57:25"}],"rules":[{"name":"Words on قوي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِّلْمُقْوِينَ","قَوِىٌّۭ","ٱلْقُوَّةِ","قَوِيًّا","ٱلْقُوَّةَ","قَوِىٌّ","بِقُوَّةٍۢ","ٱلْقَوِىُّ"]},{"name":"Parts of speech attested for قوي","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 17 glossed words attested.","examples":["لِّلْمُقْوِينَ","قَوِىٌّۭ","ٱلْقُوَّةِ","قَوِيًّا","ٱلْقُوَّةَ","قَوِىٌّ"]},{"name":"Verb forms attested for قوي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["لِّلْمُقْوِينَ","قَوِىٌّۭ","ٱلْقُوَّةِ","قَوِيًّا","ٱلْقُوَّةَ","قَوِىٌّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قوي?","options":["لِّلْمُقْوِينَ","وَءَاتُوا۟","أَشَدَّ","ءَامَنَّا"],"correct":0,"explanation":"لِّلْمُقْوِينَ — glossed \"for the wayfarers in the desert\" at 56:73 — carries the root قوي. The others come from different roots."},{"type":"multiple_choice","question":"What does قَوِىٌّۭ mean?","options":["Our Verses","your God","(is) All-Strong","And the earth"],"correct":2,"explanation":"\"(is) All-Strong\", from the word-by-word gloss at 8:52."},{"type":"fill_blank","question":"Type the root of ٱلْقُوَّةِ in Arabic (three letters).","correct":"قوي","explanation":"قوي. Diacritics are ignored when checking, so ق و ي is enough."}]', '["root-bHr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sxr', 'The root سخر (س خ ر)', 'grammar', 4, '{"explanation":"The root سخر occurs 42 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَسْخَرُونَ","transliteration":"","meaning":"you ridicule","rule":"11:38"},{"arabic":"يَسْتَسْخِرُونَ","transliteration":"","meaning":"they mock","rule":"37:14"},{"arabic":"سُخْرِيًّۭا","transliteration":"","meaning":"(for) service","rule":"43:32"},{"arabic":"نَسْخَرُ","transliteration":"","meaning":"can ridicule","rule":"11:38"},{"arabic":"فَسَخَّرْنَا","transliteration":"","meaning":"Then We subjected","rule":"38:36"},{"arabic":"سَخَّرْنَا","transliteration":"","meaning":"subjected","rule":"38:18"}],"rules":[{"name":"Words on سخر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَسْخَرُونَ","يَسْتَسْخِرُونَ","سُخْرِيًّۭا","نَسْخَرُ","فَسَخَّرْنَا","سَخَّرْنَا","وَيَسْخَرُونَ","فَيَسْخَرُونَ"]},{"name":"Parts of speech attested for سخر","description":"The morphology corpus tags words on this root as ADJ, V, N — 3 distinct parts of speech across the 23 glossed words attested.","examples":["تَسْخَرُونَ","يَسْتَسْخِرُونَ","سُخْرِيًّۭا","نَسْخَرُ","فَسَخَّرْنَا","سَخَّرْنَا"]},{"name":"Verb forms attested for سخر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, X.","examples":["تَسْخَرُونَ","يَسْتَسْخِرُونَ","سُخْرِيًّۭا","نَسْخَرُ","فَسَخَّرْنَا","سَخَّرْنَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سخر?","options":["لَـَٔايَةًۭ","ٱللَّهِ","تَسْخَرُونَ","يُؤَاخِذُكُمُ"],"correct":2,"explanation":"تَسْخَرُونَ — glossed \"you ridicule\" at 11:38 — carries the root سخر. The others come from different roots."},{"type":"multiple_choice","question":"What does يَسْتَسْخِرُونَ mean?","options":["(of) sin","Allah intends","they mock","in the horizon"],"correct":2,"explanation":"\"they mock\", from the word-by-word gloss at 37:14."},{"type":"fill_blank","question":"Type the root of سُخْرِيًّۭا in Arabic (three letters).","correct":"سخر","explanation":"سخر. Diacritics are ignored when checking, so س خ ر is enough."}]', '["root-qwy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Twf', 'The root طوف (ط و ف)', 'grammar', 4, '{"explanation":"The root طوف occurs 41 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"طَّآئِفَةٌۭ","transliteration":"","meaning":"a group","rule":"3:69"},{"arabic":"طَوَّٰفُونَ","transliteration":"","meaning":"(as) moving about","rule":"24:58"},{"arabic":"يَطُوفُ","transliteration":"","meaning":"Will circulate","rule":"56:17"},{"arabic":"ٱلطُّوفَانَ","transliteration":"","meaning":"the flood","rule":"7:133"},{"arabic":"طَآئِفَتَيْنِ","transliteration":"","meaning":"the two groups","rule":"6:156"},{"arabic":"طَـٰٓئِفٌۭ","transliteration":"","meaning":"an evil thought","rule":"7:201"}],"rules":[{"name":"Words on طوف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["طَّآئِفَةٌۭ","طَوَّٰفُونَ","يَطُوفُ","ٱلطُّوفَانَ","طَآئِفَتَيْنِ","طَـٰٓئِفٌۭ","يَطَّوَّفَ","يَطُوفُونَ"]},{"name":"Parts of speech attested for طوف","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 25 glossed words attested.","examples":["طَّآئِفَةٌۭ","طَوَّٰفُونَ","يَطُوفُ","ٱلطُّوفَانَ","طَآئِفَتَيْنِ","طَـٰٓئِفٌۭ"]},{"name":"Verb forms attested for طوف","description":"Where this root is tagged as a verb, the corpus attests derived Form V.","examples":["طَّآئِفَةٌۭ","طَوَّٰفُونَ","يَطُوفُ","ٱلطُّوفَانَ","طَآئِفَتَيْنِ","طَـٰٓئِفٌۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طوف?","options":["ٱلْأُخْرَىٰ","وَذُوقُوا۟","ٱللَّهُ","طَّآئِفَةٌۭ"],"correct":3,"explanation":"طَّآئِفَةٌۭ — glossed \"a group\" at 3:69 — carries the root طوف. The others come from different roots."},{"type":"multiple_choice","question":"What does طَوَّٰفُونَ mean?","options":["and they purchase","(as) moving about","to the Shaitaan","He has given you"],"correct":1,"explanation":"\"(as) moving about\", from the word-by-word gloss at 24:58."},{"type":"fill_blank","question":"Type the root of يَطُوفُ in Arabic (three letters).","correct":"طوف","explanation":"طوف. Diacritics are ignored when checking, so ط و ف is enough."}]', '["root-sxr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jbl', 'The root جبل (ج ب ل)', 'grammar', 4, '{"explanation":"The root جبل occurs 41 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْجِبَالُ","transliteration":"","meaning":"and the mountains","rule":"22:18"},{"arabic":"جِبَالٍۢ","transliteration":"","meaning":"mountains","rule":"24:43"},{"arabic":"جِبِلًّۭا","transliteration":"","meaning":"a multitude","rule":"36:62"},{"arabic":"لِلْجَبَلِ","transliteration":"","meaning":"to the mountain","rule":"7:143"},{"arabic":"ٱلْجِبَالَ","transliteration":"","meaning":"the mountains","rule":"7:74"},{"arabic":"ٱلْجِبَالُ","transliteration":"","meaning":"the mountains","rule":"13:31"}],"rules":[{"name":"Words on جبل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْجِبَالُ","جِبَالٍۢ","جِبِلًّۭا","لِلْجَبَلِ","ٱلْجِبَالَ","ٱلْجِبَالُ","وَٱلْجِبِلَّةَ","ٱلْجَبَلِ"]},{"name":"Parts of speech attested for جبل","description":"The morphology corpus tags words on this root as N — one part of speech across the 15 glossed words attested.","examples":["وَٱلْجِبَالُ","جِبَالٍۢ","جِبِلًّۭا","لِلْجَبَلِ","ٱلْجِبَالَ","ٱلْجِبَالُ"]},{"name":"Where جبل occurs","description":"The 15 glossed words on this root are attested across 12 distinct surahs.","examples":["وَٱلْجِبَالُ (22:18)","جِبَالٍۢ (24:43)","جِبِلًّۭا (36:62)","لِلْجَبَلِ (7:143)","ٱلْجِبَالَ (7:74)","ٱلْجِبَالُ (13:31)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جبل?","options":["بِذُنُوبِكُم","سَيَذَّكَّرُ","أَجَلُهُنَّ","وَٱلْجِبَالُ"],"correct":3,"explanation":"وَٱلْجِبَالُ — glossed \"and the mountains\" at 22:18 — carries the root جبل. The others come from different roots."},{"type":"multiple_choice","question":"What does جِبَالٍۢ mean?","options":["you entrust him","(are) a reminder","mountains","Allah intends"],"correct":2,"explanation":"\"mountains\", from the word-by-word gloss at 24:43."},{"type":"fill_blank","question":"Type the root of جِبِلًّۭا in Arabic (three letters).","correct":"جبل","explanation":"جبل. Diacritics are ignored when checking, so ج ب ل is enough."}]', '["root-Twf"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jhd', 'The root جهد (ج ه د)', 'grammar', 4, '{"explanation":"The root جهد occurs 41 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as V, N, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَجَـٰهَدَ","transliteration":"","meaning":"and strives","rule":"9:19"},{"arabic":"جَهْدَ","transliteration":"","meaning":"strongest","rule":"5:53"},{"arabic":"جِهَادًۭا","transliteration":"","meaning":"a striving","rule":"25:52"},{"arabic":"وَٱلْمُجَـٰهِدُونَ","transliteration":"","meaning":"and the ones who strive","rule":"4:95"},{"arabic":"جَـٰهَدُوا۟","transliteration":"","meaning":"strove hard","rule":"3:142"},{"arabic":"جَـٰهَدَ","transliteration":"","meaning":"strives","rule":"29:6"}],"rules":[{"name":"Words on جهد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَجَـٰهَدَ","جَهْدَ","جِهَادًۭا","وَٱلْمُجَـٰهِدُونَ","جَـٰهَدُوا۟","جَـٰهَدَ","وَجَـٰهِدْهُم","وَجِهَادٍۢ"]},{"name":"Parts of speech attested for جهد","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 20 glossed words attested.","examples":["وَجَـٰهَدَ","جَهْدَ","جِهَادًۭا","وَٱلْمُجَـٰهِدُونَ","جَـٰهَدُوا۟","جَـٰهَدَ"]},{"name":"Verb forms attested for جهد","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["وَجَـٰهَدَ","جَهْدَ","جِهَادًۭا","وَٱلْمُجَـٰهِدُونَ","جَـٰهَدُوا۟","جَـٰهَدَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جهد?","options":["ٱلْمَشْـَٔمَةِ","ٱلشَّيْطَـٰنَ","ٱتَّخَذْتُ","وَجَـٰهَدَ"],"correct":3,"explanation":"وَجَـٰهَدَ — glossed \"and strives\" at 9:19 — carries the root جهد. The others come from different roots."},{"type":"multiple_choice","question":"What does جَهْدَ mean?","options":["strongest","his family","Bring us","its inhabitants"],"correct":0,"explanation":"\"strongest\", from the word-by-word gloss at 5:53."},{"type":"fill_blank","question":"Type the root of جِهَادًۭا in Arabic (three letters).","correct":"جهد","explanation":"جهد. Diacritics are ignored when checking, so ج ه د is enough."}]', '["root-jbl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-krh', 'The root كره (ك ر ه)', 'grammar', 4, '{"explanation":"The root كره occurs 41 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَكْرَهُوا۟","transliteration":"","meaning":"you dislike","rule":"2:216"},{"arabic":"كَرِهَ","transliteration":"","meaning":"disliked (it)","rule":"8:8"},{"arabic":"يُكْرِههُّنَّ","transliteration":"","meaning":"compels them","rule":"24:33"},{"arabic":"وَكَرَّهَ","transliteration":"","meaning":"and has made hateful","rule":"49:7"},{"arabic":"كَرْهًۭا","transliteration":"","meaning":"(by) force","rule":"4:19"},{"arabic":"فَكَرِهْتُمُوهُ","transliteration":"","meaning":"Nay, you would hate it","rule":"49:12"}],"rules":[{"name":"Words on كره","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَكْرَهُوا۟","كَرِهَ","يُكْرِههُّنَّ","وَكَرَّهَ","كَرْهًۭا","فَكَرِهْتُمُوهُ","كُرْهٌۭ","أَكْرَهْتَنَا"]},{"name":"Parts of speech attested for كره","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 24 glossed words attested.","examples":["تَكْرَهُوا۟","كَرِهَ","يُكْرِههُّنَّ","وَكَرَّهَ","كَرْهًۭا","فَكَرِهْتُمُوهُ"]},{"name":"Verb forms attested for كره","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["تَكْرَهُوا۟","كَرِهَ","يُكْرِههُّنَّ","وَكَرَّهَ","كَرْهًۭا","فَكَرِهْتُمُوهُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كره?","options":["أَمْرُنَا","ٱلْمُؤْمِنُونَ","تَكْرَهُوا۟","ٱلذَّكَرَ"],"correct":2,"explanation":"تَكْرَهُوا۟ — glossed \"you dislike\" at 2:216 — carries the root كره. The others come from different roots."},{"type":"multiple_choice","question":"What does كَرِهَ mean?","options":["You postpone (it for) us","(do) you instruct","disliked (it)","testify"],"correct":2,"explanation":"\"disliked (it)\", from the word-by-word gloss at 8:8."},{"type":"fill_blank","question":"Type the root of يُكْرِههُّنَّ in Arabic (three letters).","correct":"كره","explanation":"كره. Diacritics are ignored when checking, so ك ر ه is enough."}]', '["root-jhd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lEn', 'The root لعن (ل ع ن)', 'grammar', 4, '{"explanation":"The root لعن occurs 41 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱللَّعْنَةُ","transliteration":"","meaning":"(is) the curse","rule":"13:25"},{"arabic":"مَّلْعُونِينَ","transliteration":"","meaning":"Accursed","rule":"33:61"},{"arabic":"وَيَلْعَنُهُمُ","transliteration":"","meaning":"and curse them","rule":"2:159"},{"arabic":"لَعَنَ","transliteration":"","meaning":"has cursed","rule":"33:64"},{"arabic":"لَّعَنَتْ","transliteration":"","meaning":"it cursed","rule":"7:38"},{"arabic":"لَعَنَّآ","transliteration":"","meaning":"We cursed","rule":"4:47"}],"rules":[{"name":"Words on لعن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱللَّعْنَةُ","مَّلْعُونِينَ","وَيَلْعَنُهُمُ","لَعَنَ","لَّعَنَتْ","لَعَنَّآ","لَّعَنَهُ","لُعِنُوا۟"]},{"name":"Parts of speech attested for لعن","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 33 glossed words attested.","examples":["ٱللَّعْنَةُ","مَّلْعُونِينَ","وَيَلْعَنُهُمُ","لَعَنَ","لَّعَنَتْ","لَعَنَّآ"]},{"name":"Where لعن occurs","description":"The 33 glossed words on this root are attested across 15 distinct surahs.","examples":["ٱللَّعْنَةُ (13:25)","مَّلْعُونِينَ (33:61)","وَيَلْعَنُهُمُ (2:159)","لَعَنَ (33:64)","لَّعَنَتْ (7:38)","لَعَنَّآ (4:47)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لعن?","options":["أَتَىٰكُمْ","ٱللَّعْنَةُ","أُمَمًۭا","يُؤْخَذُ"],"correct":1,"explanation":"ٱللَّعْنَةُ — glossed \"(is) the curse\" at 13:25 — carries the root لعن. The others come from different roots."},{"type":"multiple_choice","question":"What does مَّلْعُونِينَ mean?","options":["Accursed","We (had) given them","you (will) eat","Should I take"],"correct":0,"explanation":"\"Accursed\", from the word-by-word gloss at 33:61."},{"type":"fill_blank","question":"Type the root of وَيَلْعَنُهُمُ in Arabic (three letters).","correct":"لعن","explanation":"لعن. Diacritics are ignored when checking, so ل ع ن is enough."}]', '["root-krh"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$Er', 'The root شعر (ش ع ر)', 'grammar', 4, '{"explanation":"The root شعر occurs 40 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as V, N, PN, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَاعِرٍۢ","transliteration":"","meaning":"(of) a poet","rule":"69:41"},{"arabic":"شَاعِرٌۭ","transliteration":"","meaning":"(is) a poet","rule":"21:5"},{"arabic":"وَٱلشُّعَرَآءُ","transliteration":"","meaning":"And the poets","rule":"26:224"},{"arabic":"شَعَآئِرِ","transliteration":"","meaning":"(the) symbols","rule":"2:158"},{"arabic":"يُشْعِرَنَّ","transliteration":"","meaning":"And let not be aware","rule":"18:19"},{"arabic":"شَعَـٰٓئِرِ","transliteration":"","meaning":"(the) Symbols","rule":"22:36"}],"rules":[{"name":"Words on شعر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَاعِرٍۢ","شَاعِرٌۭ","وَٱلشُّعَرَآءُ","شَعَآئِرِ","يُشْعِرَنَّ","شَعَـٰٓئِرِ","ٱلشِّعْرَ","ٱلشِّعْرَىٰ"]},{"name":"Parts of speech attested for شعر","description":"The morphology corpus tags words on this root as V, N, PN — 3 distinct parts of speech across the 15 glossed words attested.","examples":["شَاعِرٍۢ","شَاعِرٌۭ","وَٱلشُّعَرَآءُ","شَعَآئِرِ","يُشْعِرَنَّ","شَعَـٰٓئِرِ"]},{"name":"Verb forms attested for شعر","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["شَاعِرٍۢ","شَاعِرٌۭ","وَٱلشُّعَرَآءُ","شَعَآئِرِ","يُشْعِرَنَّ","شَعَـٰٓئِرِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شعر?","options":["لَأَجْرًا","ٱللَّهِ","أَتَوْكَ","شَاعِرٍۢ"],"correct":3,"explanation":"شَاعِرٍۢ — glossed \"(of) a poet\" at 69:41 — carries the root شعر. The others come from different roots."},{"type":"multiple_choice","question":"What does شَاعِرٌۭ mean?","options":["(have) they taken","(is) a poet","and take","[in] the Signs"],"correct":1,"explanation":"\"(is) a poet\", from the word-by-word gloss at 21:5."},{"type":"fill_blank","question":"Type the root of وَٱلشُّعَرَآءُ in Arabic (three letters).","correct":"شعر","explanation":"شعر. Diacritics are ignored when checking, so ش ع ر is enough."}]', '["root-lEn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-flH', 'The root فلح (ف ل ح)', 'grammar', 4, '{"explanation":"The root فلح occurs 40 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُفْلِحُونَ","transliteration":"","meaning":"they will not succeed","rule":"10:69"},{"arabic":"أَفْلَحَ","transliteration":"","meaning":"(will be) successful","rule":"20:64"},{"arabic":"ٱلْمُفْلِحِينَ","transliteration":"","meaning":"the successful ones","rule":"28:67"},{"arabic":"تُفْلِحُوٓا۟","transliteration":"","meaning":"will you succeed","rule":"18:20"},{"arabic":"ٱلْمُفْلِحُونَ","transliteration":"","meaning":"(are) the successful ones","rule":"2:5"},{"arabic":"يُفْلِحُ","transliteration":"","meaning":"will be successful","rule":"6:21"}],"rules":[{"name":"Words on فلح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُفْلِحُونَ","أَفْلَحَ","ٱلْمُفْلِحِينَ","تُفْلِحُوٓا۟","ٱلْمُفْلِحُونَ","يُفْلِحُ","تُفْلِحُونَ"]},{"name":"Parts of speech attested for فلح","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 7 glossed words attested.","examples":["يُفْلِحُونَ","أَفْلَحَ","ٱلْمُفْلِحِينَ","تُفْلِحُوٓا۟","ٱلْمُفْلِحُونَ","يُفْلِحُ"]},{"name":"Verb forms attested for فلح","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["يُفْلِحُونَ","أَفْلَحَ","ٱلْمُفْلِحِينَ","تُفْلِحُوٓا۟","ٱلْمُفْلِحُونَ","يُفْلِحُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فلح?","options":["يُفْلِحُونَ","وَٱلْـَٔاخِرَةُ","أَشْتَاتًۭا","وَٱلْمُؤْتَفِكَةَ"],"correct":0,"explanation":"يُفْلِحُونَ — glossed \"they will not succeed\" at 10:69 — carries the root فلح. The others come from different roots."},{"type":"multiple_choice","question":"What does أَفْلَحَ mean?","options":["and his family","and the former (people)","harm you may cause us","(will be) successful"],"correct":3,"explanation":"\"(will be) successful\", from the word-by-word gloss at 20:64."},{"type":"fill_blank","question":"Type the root of ٱلْمُفْلِحِينَ in Arabic (three letters).","correct":"فلح","explanation":"فلح. Diacritics are ignored when checking, so ف ل ح is enough."}]', '["root-$Er"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mlA', 'The root ملا (م ل ا)', 'grammar', 4, '{"explanation":"The root ملا occurs 40 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمَلَؤُا۟","transliteration":"","meaning":"the chiefs","rule":"23:24"},{"arabic":"بِٱلْمَلَإِ","transliteration":"","meaning":"(of) the chiefs","rule":"38:69"},{"arabic":"ٱلْمَلَأَ","transliteration":"","meaning":"the chiefs","rule":"28:20"},{"arabic":"وَمَلَأَهُۥ","transliteration":"","meaning":"and his chiefs","rule":"10:88"},{"arabic":"لِلْمَلَإِ","transliteration":"","meaning":"to the chiefs","rule":"26:34"},{"arabic":"ٱلْمَلَأُ","transliteration":"","meaning":"the chiefs","rule":"7:60"}],"rules":[{"name":"Words on ملا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمَلَؤُا۟","بِٱلْمَلَإِ","ٱلْمَلَأَ","وَمَلَأَهُۥ","لِلْمَلَإِ","ٱلْمَلَأُ","مِّلْءُ","فَمَالِـُٔونَ"]},{"name":"Parts of speech attested for ملا","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["ٱلْمَلَؤُا۟","بِٱلْمَلَإِ","ٱلْمَلَأَ","وَمَلَأَهُۥ","لِلْمَلَإِ","ٱلْمَلَأُ"]},{"name":"Verb forms attested for ملا","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["ٱلْمَلَؤُا۟","بِٱلْمَلَإِ","ٱلْمَلَأَ","وَمَلَأَهُۥ","لِلْمَلَإِ","ٱلْمَلَأُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ملا?","options":["ءَايَةٍۢ","ٱلْمَلَؤُا۟","ءَابَآؤُنَا","كَشَجَرَةٍ"],"correct":1,"explanation":"ٱلْمَلَؤُا۟ — glossed \"the chiefs\" at 23:24 — carries the root ملا. The others come from different roots."},{"type":"multiple_choice","question":"What does بِٱلْمَلَإِ mean?","options":["(of) the chiefs","That Allah may reward them","for sin","a Message"],"correct":0,"explanation":"\"(of) the chiefs\", from the word-by-word gloss at 38:69."},{"type":"fill_blank","question":"Type the root of ٱلْمَلَأَ in Arabic (three letters).","correct":"ملا","explanation":"ملا. Diacritics are ignored when checking, so م ل ا is enough."}]', '["root-flH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$rb', 'The root شرب (ش ر ب)', 'grammar', 4, '{"explanation":"The root شرب occurs 39 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلشَّرَابُ","transliteration":"","meaning":"(is) the drink","rule":"18:29"},{"arabic":"شَرَابُهُۥ","transliteration":"","meaning":"its drink","rule":"35:12"},{"arabic":"تَشْرَبُونَ","transliteration":"","meaning":"you drink","rule":"23:33"},{"arabic":"فَشَـٰرِبُونَ","transliteration":"","meaning":"And drink","rule":"56:54"},{"arabic":"شُرْبَ","transliteration":"","meaning":"(as) drinking","rule":"56:55"},{"arabic":"شَرَابًۭا","transliteration":"","meaning":"a drink","rule":"76:21"}],"rules":[{"name":"Words on شرب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلشَّرَابُ","شَرَابُهُۥ","تَشْرَبُونَ","فَشَـٰرِبُونَ","شُرْبَ","شَرَابًۭا","لِّلشَّـٰرِبِينَ","وَيَشْرَبُ"]},{"name":"Parts of speech attested for شرب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 25 glossed words attested.","examples":["ٱلشَّرَابُ","شَرَابُهُۥ","تَشْرَبُونَ","فَشَـٰرِبُونَ","شُرْبَ","شَرَابًۭا"]},{"name":"Verb forms attested for شرب","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["ٱلشَّرَابُ","شَرَابُهُۥ","تَشْرَبُونَ","فَشَـٰرِبُونَ","شُرْبَ","شَرَابًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شرب?","options":["أَخَذَتِ","ٱلشَّرَابُ","أَرْضِكُمْ","أُذُنٌۭ"],"correct":1,"explanation":"ٱلشَّرَابُ — glossed \"(is) the drink\" at 18:29 — carries the root شرب. The others come from different roots."},{"type":"multiple_choice","question":"What does شَرَابُهُۥ mean?","options":["(is) the security","its drink","(set by) Allah","(is) like a niche"],"correct":1,"explanation":"\"its drink\", from the word-by-word gloss at 35:12."},{"type":"fill_blank","question":"Type the root of تَشْرَبُونَ in Arabic (three letters).","correct":"شرب","explanation":"شرب. Diacritics are ignored when checking, so ش ر ب is enough."}]', '["root-mlA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*nb', 'The root ذنب (ذ ن ب)', 'grammar', 4, '{"explanation":"The root ذنب occurs 39 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِذُنُوبِ","transliteration":"","meaning":"concerning the sins","rule":"17:17"},{"arabic":"ذَنۢبٍۢ","transliteration":"","meaning":"sin","rule":"81:9"},{"arabic":"لِذَنۢبِكِ","transliteration":"","meaning":"for your sin","rule":"12:29"},{"arabic":"ٱلذَّنۢبِ","transliteration":"","meaning":"(of) the sin","rule":"40:3"},{"arabic":"ذُنُوبِهِمْ","transliteration":"","meaning":"(of) their sins","rule":"5:49"},{"arabic":"بِذُنُوبِكُم","transliteration":"","meaning":"for your sins","rule":"5:18"}],"rules":[{"name":"Words on ذنب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِذُنُوبِ","ذَنۢبٍۢ","لِذَنۢبِكِ","ٱلذَّنۢبِ","ذُنُوبِهِمْ","بِذُنُوبِكُم","ذَنۢبِهِۦٓ","ٱلذُّنُوبَ"]},{"name":"Parts of speech attested for ذنب","description":"The morphology corpus tags words on this root as N — one part of speech across the 23 glossed words attested.","examples":["بِذُنُوبِ","ذَنۢبٍۢ","لِذَنۢبِكِ","ٱلذَّنۢبِ","ذُنُوبِهِمْ","بِذُنُوبِكُم"]},{"name":"Where ذنب occurs","description":"The 23 glossed words on this root are attested across 14 distinct surahs.","examples":["بِذُنُوبِ (17:17)","ذَنۢبٍۢ (81:9)","لِذَنۢبِكِ (12:29)","ٱلذَّنۢبِ (40:3)","ذُنُوبِهِمْ (5:49)","بِذُنُوبِكُم (5:18)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذنب?","options":["شَيْـًۭٔا","بِذُنُوبِ","ءَاخَرَ","يُشْرِكُونَ"],"correct":1,"explanation":"بِذُنُوبِ — glossed \"concerning the sins\" at 17:17 — carries the root ذنب. The others come from different roots."},{"type":"multiple_choice","question":"What does ذَنۢبٍۢ mean?","options":["sin","(is) any share","And our God","those of understanding"],"correct":0,"explanation":"\"sin\", from the word-by-word gloss at 81:9."},{"type":"fill_blank","question":"Type the root of لِذَنۢبِكِ in Arabic (three letters).","correct":"ذنب","explanation":"ذنب. Diacritics are ignored when checking, so ذ ن ب is enough."}]', '["root-$rb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Tgy', 'The root طغي (ط غ ي)', 'grammar', 4, '{"explanation":"The root طغي occurs 39 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلطَّـٰغُوتِ","transliteration":"","meaning":"and the false deities","rule":"4:51"},{"arabic":"طَغَا","transliteration":"","meaning":"overflowed","rule":"69:11"},{"arabic":"لِّلطَّـٰغِينَ","transliteration":"","meaning":"For the transgressors","rule":"78:22"},{"arabic":"ٱلطَّـٰغُوتَ","transliteration":"","meaning":"the false deities","rule":"5:60"},{"arabic":"بِطَغْوَىٰهَآ","transliteration":"","meaning":"by their transgression","rule":"91:11"},{"arabic":"طَاغُونَ","transliteration":"","meaning":"transgressing","rule":"51:53"}],"rules":[{"name":"Words on طغي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلطَّـٰغُوتِ","طَغَا","لِّلطَّـٰغِينَ","ٱلطَّـٰغُوتَ","بِطَغْوَىٰهَآ","طَاغُونَ","لَيَطْغَىٰٓ","طَغَىٰ"]},{"name":"Parts of speech attested for طغي","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 21 glossed words attested.","examples":["وَٱلطَّـٰغُوتِ","طَغَا","لِّلطَّـٰغِينَ","ٱلطَّـٰغُوتَ","بِطَغْوَىٰهَآ","طَاغُونَ"]},{"name":"Verb forms attested for طغي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَٱلطَّـٰغُوتِ","طَغَا","لِّلطَّـٰغِينَ","ٱلطَّـٰغُوتَ","بِطَغْوَىٰهَآ","طَاغُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طغي?","options":["وَأَكْلِهِمُ","إِلَـٰهُكُمُ","وَٱلطَّـٰغُوتِ","وَتَأْبَىٰ"],"correct":2,"explanation":"وَٱلطَّـٰغُوتِ — glossed \"and the false deities\" at 4:51 — carries the root طغي. The others come from different roots."},{"type":"multiple_choice","question":"What does طَغَا mean?","options":["consume","his family","tires Him","overflowed"],"correct":3,"explanation":"\"overflowed\", from the word-by-word gloss at 69:11."},{"type":"fill_blank","question":"Type the root of لِّلطَّـٰغِينَ in Arabic (three letters).","correct":"طغي","explanation":"طغي. Diacritics are ignored when checking, so ط غ ي is enough."}]', '["root-*nb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-slT', 'The root سلط (س ل ط)', 'grammar', 4, '{"explanation":"The root سلط occurs 39 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سُلْطَـٰنٍۭ","transliteration":"","meaning":"authority","rule":"10:68"},{"arabic":"سُلْطَـٰنًۭا","transliteration":"","meaning":"any authority","rule":"3:151"},{"arabic":"سُلْطَـٰنُهُۥ","transliteration":"","meaning":"his authority","rule":"16:100"},{"arabic":"وَسُلْطَـٰنٍۢ","transliteration":"","meaning":"and an authority","rule":"11:96"},{"arabic":"سُلْطَـٰنٍۢ","transliteration":"","meaning":"authority","rule":"7:71"},{"arabic":"سُلْطَـٰنٌ","transliteration":"","meaning":"any authority","rule":"15:42"}],"rules":[{"name":"Words on سلط","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سُلْطَـٰنٍۭ","سُلْطَـٰنًۭا","سُلْطَـٰنُهُۥ","وَسُلْطَـٰنٍۢ","سُلْطَـٰنٍۢ","سُلْطَـٰنٌ","سُلْطَـٰنٌۭ","سُلْطَـٰنِيَهْ"]},{"name":"Parts of speech attested for سلط","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 14 glossed words attested.","examples":["سُلْطَـٰنٍۭ","سُلْطَـٰنًۭا","سُلْطَـٰنُهُۥ","وَسُلْطَـٰنٍۢ","سُلْطَـٰنٍۢ","سُلْطَـٰنٌ"]},{"name":"Verb forms attested for سلط","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["سُلْطَـٰنٍۭ","سُلْطَـٰنًۭا","سُلْطَـٰنُهُۥ","وَسُلْطَـٰنٍۢ","سُلْطَـٰنٍۢ","سُلْطَـٰنٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سلط?","options":["ذِكْرًۭا","وَلِإِخْوَٰنِنَا","وَتُؤْمِنُونَ","سُلْطَـٰنٍۭ"],"correct":3,"explanation":"سُلْطَـٰنٍۭ — glossed \"authority\" at 10:68 — carries the root سلط. The others come from different roots."},{"type":"multiple_choice","question":"What does سُلْطَـٰنًۭا mean?","options":["any authority","but Allah refuses","the other","surely they (would have) eaten"],"correct":0,"explanation":"\"any authority\", from the word-by-word gloss at 3:151."},{"type":"fill_blank","question":"Type the root of سُلْطَـٰنُهُۥ in Arabic (three letters).","correct":"سلط","explanation":"سلط. Diacritics are ignored when checking, so س ل ط is enough."}]', '["root-Tgy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*rr', 'The root ذرر (ذ ر ر)', 'grammar', 4, '{"explanation":"The root ذرر occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ذُرِّيَّةِ","transliteration":"","meaning":"the descendants","rule":"6:133"},{"arabic":"ذُرِّيَّتِىٓ","transliteration":"","meaning":"my offspring","rule":"46:15"},{"arabic":"ذُرِّيَّتِهِمَا","transliteration":"","meaning":"their offspring","rule":"37:113"},{"arabic":"ذَرَّةٍۢ","transliteration":"","meaning":"(of) an atom","rule":"4:40"},{"arabic":"ذُرِّيَّتِى","transliteration":"","meaning":"my offspring","rule":"2:124"},{"arabic":"وَذُرِّيَّتَهُۥٓ","transliteration":"","meaning":"and his offspring","rule":"18:50"}],"rules":[{"name":"Words on ذرر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ذُرِّيَّةِ","ذُرِّيَّتِىٓ","ذُرِّيَّتِهِمَا","ذَرَّةٍۢ","ذُرِّيَّتِى","وَذُرِّيَّتَهُۥٓ","ذُرِّيَّةَ","ذُرِّيَّتِهِ"]},{"name":"Parts of speech attested for ذرر","description":"The morphology corpus tags words on this root as N — one part of speech across the 22 glossed words attested.","examples":["ذُرِّيَّةِ","ذُرِّيَّتِىٓ","ذُرِّيَّتِهِمَا","ذَرَّةٍۢ","ذُرِّيَّتِى","وَذُرِّيَّتَهُۥٓ"]},{"name":"Where ذرر occurs","description":"The 22 glossed words on this root are attested across 14 distinct surahs.","examples":["ذُرِّيَّةِ (6:133)","ذُرِّيَّتِىٓ (46:15)","ذُرِّيَّتِهِمَا (37:113)","ذَرَّةٍۢ (4:40)","ذُرِّيَّتِى (2:124)","وَذُرِّيَّتَهُۥٓ (18:50)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذرر?","options":["وَءَاخَرَ","ءَالَ","وَأَبًّۭا","ذُرِّيَّةِ"],"correct":3,"explanation":"ذُرِّيَّةِ — glossed \"the descendants\" at 6:133 — carries the root ذرر. The others come from different roots."},{"type":"multiple_choice","question":"What does ذُرِّيَّتِىٓ mean?","options":["my offspring","(are) you deluded","we will take him","(the) earth"],"correct":0,"explanation":"\"my offspring\", from the word-by-word gloss at 46:15."},{"type":"fill_blank","question":"Type the root of ذُرِّيَّتِهِمَا in Arabic (three letters).","correct":"ذرر","explanation":"ذرر. Diacritics are ignored when checking, so ذ ر ر is enough."}]', '["root-slT"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-blw', 'The root بلو (ب ل و)', 'grammar', 4, '{"explanation":"The root بلو occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, V, in verb forms VIII, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْبَلَـٰٓؤُا۟","transliteration":"","meaning":"the trial","rule":"37:106"},{"arabic":"يَبْلَىٰ","transliteration":"","meaning":"(that will) deteriorate","rule":"20:120"},{"arabic":"لَمُبْتَلِينَ","transliteration":"","meaning":"surely testing","rule":"23:30"},{"arabic":"وَنَبْلُوَا۟","transliteration":"","meaning":"and We will test","rule":"47:31"},{"arabic":"وَلِيَبْتَلِىَ","transliteration":"","meaning":"And that might test","rule":"3:154"},{"arabic":"لِيَبْلُوَنِىٓ","transliteration":"","meaning":"to test me","rule":"27:40"}],"rules":[{"name":"Words on بلو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْبَلَـٰٓؤُا۟","يَبْلَىٰ","لَمُبْتَلِينَ","وَنَبْلُوَا۟","وَلِيَبْتَلِىَ","لِيَبْلُوَنِىٓ","ٱبْتُلِىَ","بَلَآءٌۭ"]},{"name":"Parts of speech attested for بلو","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 33 glossed words attested.","examples":["ٱلْبَلَـٰٓؤُا۟","يَبْلَىٰ","لَمُبْتَلِينَ","وَنَبْلُوَا۟","وَلِيَبْتَلِىَ","لِيَبْلُوَنِىٓ"]},{"name":"Verb forms attested for بلو","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, IV.","examples":["ٱلْبَلَـٰٓؤُا۟","يَبْلَىٰ","لَمُبْتَلِينَ","وَنَبْلُوَا۟","وَلِيَبْتَلِىَ","لِيَبْلُوَنِىٓ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بلو?","options":["ٱلْبَلَـٰٓؤُا۟","ٱلْأَمَدُ","بِـَٔايَـٰتِنَا","شَجَرَةٌۭ"],"correct":0,"explanation":"ٱلْبَلَـٰٓؤُا۟ — glossed \"the trial\" at 37:106 — carries the root بلو. The others come from different roots."},{"type":"multiple_choice","question":"What does يَبْلَىٰ mean?","options":["a believer","has come to them","and mention","(that will) deteriorate"],"correct":3,"explanation":"\"(that will) deteriorate\", from the word-by-word gloss at 20:120."},{"type":"fill_blank","question":"Type the root of لَمُبْتَلِينَ in Arabic (three letters).","correct":"بلو","explanation":"بلو. Diacritics are ignored when checking, so ب ل و is enough."}]', '["root-*rr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ftH', 'The root فتح (ف ت ح)', 'grammar', 4, '{"explanation":"The root فتح occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, in verb forms X, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْفَتْحِ","transliteration":"","meaning":"(of) the Decision","rule":"32:29"},{"arabic":"وَٱسْتَفْتَحُوا۟","transliteration":"","meaning":"And they sought victory","rule":"14:15"},{"arabic":"وَٱلْفَتْحُ","transliteration":"","meaning":"and the Victory","rule":"110:1"},{"arabic":"تَسْتَفْتِحُوا۟","transliteration":"","meaning":"you ask for victory","rule":"8:19"},{"arabic":"ٱلْفَـٰتِحِينَ","transliteration":"","meaning":"(of) those who Decide","rule":"7:89"},{"arabic":"يَفْتَحِ","transliteration":"","meaning":"Allah grants","rule":"35:2"}],"rules":[{"name":"Words on فتح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْفَتْحِ","وَٱسْتَفْتَحُوا۟","وَٱلْفَتْحُ","تَسْتَفْتِحُوا۟","ٱلْفَـٰتِحِينَ","يَفْتَحِ","وَفَتْحٌۭ","ٱلْفَتْحُ"]},{"name":"Parts of speech attested for فتح","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 29 glossed words attested.","examples":["ٱلْفَتْحِ","وَٱسْتَفْتَحُوا۟","وَٱلْفَتْحُ","تَسْتَفْتِحُوا۟","ٱلْفَـٰتِحِينَ","يَفْتَحِ"]},{"name":"Verb forms attested for فتح","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, II.","examples":["ٱلْفَتْحِ","وَٱسْتَفْتَحُوا۟","وَٱلْفَتْحُ","تَسْتَفْتِحُوا۟","ٱلْفَـٰتِحِينَ","يَفْتَحِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فتح?","options":["يَتَّخِذِ","ٱللَّهُ","ٱلْفَتْحِ","شَىْءٍ"],"correct":2,"explanation":"ٱلْفَتْحِ — glossed \"(of) the Decision\" at 32:29 — carries the root فتح. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱسْتَفْتَحُوا۟ mean?","options":["and We seized them","we eat","And they sought victory","Then she took"],"correct":2,"explanation":"\"And they sought victory\", from the word-by-word gloss at 14:15."},{"type":"fill_blank","question":"Type the root of وَٱلْفَتْحُ in Arabic (three letters).","correct":"فتح","explanation":"فتح. Diacritics are ignored when checking, so ف ت ح is enough."}]', '["root-blw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-hwy', 'The root هوي (ه و ي)', 'grammar', 4, '{"explanation":"The root هوي occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as V, N, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِأَهْوَآئِهِم","transliteration":"","meaning":"by their (vain) desires","rule":"6:119"},{"arabic":"أَهْوَآءَهُم","transliteration":"","meaning":"their desires","rule":"2:120"},{"arabic":"تَهْوَى","transliteration":"","meaning":"desire","rule":"53:23"},{"arabic":"تَهْوِىٓ","transliteration":"","meaning":"incline","rule":"14:37"},{"arabic":"تَهْوِى","transliteration":"","meaning":"had blown","rule":"22:31"},{"arabic":"ٱلْهَوَىٰٓ","transliteration":"","meaning":"the desire","rule":"4:135"}],"rules":[{"name":"Words on هوي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِأَهْوَآئِهِم","أَهْوَآءَهُم","تَهْوَى","تَهْوِىٓ","تَهْوِى","ٱلْهَوَىٰٓ","أَهْوَآءَهُمْ","أَهْوَىٰ"]},{"name":"Parts of speech attested for هوي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 17 glossed words attested.","examples":["بِأَهْوَآئِهِم","أَهْوَآءَهُم","تَهْوَى","تَهْوِىٓ","تَهْوِى","ٱلْهَوَىٰٓ"]},{"name":"Verb forms attested for هوي","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["بِأَهْوَآئِهِم","أَهْوَآءَهُم","تَهْوَى","تَهْوِىٓ","تَهْوِى","ٱلْهَوَىٰٓ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root هوي?","options":["وَٱللَّهُ","شَىْءٍۭ","وَٱلشَّفْعِ","بِأَهْوَآئِهِم"],"correct":3,"explanation":"بِأَهْوَآئِهِم — glossed \"by their (vain) desires\" at 6:119 — carries the root هوي. The others come from different roots."},{"type":"multiple_choice","question":"What does أَهْوَآءَهُم mean?","options":["they come to me","and Allah has forgiven","their desires","her family"],"correct":2,"explanation":"\"their desires\", from the word-by-word gloss at 2:120."},{"type":"fill_blank","question":"Type the root of تَهْوَى in Arabic (three letters).","correct":"هوي","explanation":"هوي. Diacritics are ignored when checking, so ه و ي is enough."}]', '["root-ftH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mrA', 'The root مرا (م ر ا)', 'grammar', 4, '{"explanation":"The root مرا occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمَرْءُ","transliteration":"","meaning":"the man","rule":"78:40"},{"arabic":"وَٱمْرَأَةًۭ","transliteration":"","meaning":"and a woman","rule":"33:50"},{"arabic":"ٱمْرَأَتِى","transliteration":"","meaning":"my wife","rule":"19:5"},{"arabic":"ٱمْرِئٍۢ","transliteration":"","meaning":"person","rule":"24:11"},{"arabic":"ٱمْرُؤٌا۟","transliteration":"","meaning":"a man","rule":"4:176"},{"arabic":"لِٱمْرَأَتِهِۦٓ","transliteration":"","meaning":"to his wife","rule":"12:21"}],"rules":[{"name":"Words on مرا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمَرْءُ","وَٱمْرَأَةًۭ","ٱمْرَأَتِى","ٱمْرِئٍۢ","ٱمْرُؤٌا۟","لِٱمْرَأَتِهِۦٓ","ٱمْرِئٍۭ","ٱمْرَأَةٌ"]},{"name":"Parts of speech attested for مرا","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 23 glossed words attested.","examples":["ٱلْمَرْءُ","وَٱمْرَأَةًۭ","ٱمْرَأَتِى","ٱمْرِئٍۢ","ٱمْرُؤٌا۟","لِٱمْرَأَتِهِۦٓ"]},{"name":"Where مرا occurs","description":"The 23 glossed words on this root are attested across 15 distinct surahs.","examples":["ٱلْمَرْءُ (78:40)","وَٱمْرَأَةًۭ (33:50)","ٱمْرَأَتِى (19:5)","ٱمْرِئٍۢ (24:11)","ٱمْرُؤٌا۟ (4:176)","لِٱمْرَأَتِهِۦٓ (12:21)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مرا?","options":["يَأْتِى","ٱتَّخَذُوا۟","ٱلْمَرْءُ","وَيَتَّخِذَهَا"],"correct":2,"explanation":"ٱلْمَرْءُ — glossed \"the man\" at 78:40 — carries the root مرا. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱمْرَأَةًۭ mean?","options":["and their affairs","and a woman","their forms","and his mother"],"correct":1,"explanation":"\"and a woman\", from the word-by-word gloss at 33:50."},{"type":"fill_blank","question":"Type the root of ٱمْرَأَتِى in Arabic (three letters).","correct":"مرا","explanation":"مرا. Diacritics are ignored when checking, so م ر ا is enough."}]', '["root-hwy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qrr', 'The root قرر (ق ر ر)', 'grammar', 4, '{"explanation":"The root قرر occurs 38 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N, V, in verb forms X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُّسْتَقَرٌّۭ","transliteration":"","meaning":"(is) a fixed time","rule":"6:67"},{"arabic":"ٱسْتَقَرَّ","transliteration":"","meaning":"it remains","rule":"7:143"},{"arabic":"ءَأَقْرَرْتُمْ","transliteration":"","meaning":"Do you affirm","rule":"3:81"},{"arabic":"ٱلْقَرَارُ","transliteration":"","meaning":"place to settle","rule":"14:29"},{"arabic":"تَقَرَّ","transliteration":"","meaning":"may be cooled","rule":"20:40"},{"arabic":"مُسْتَقَرٌّۭ","transliteration":"","meaning":"(is) a dwelling place","rule":"2:36"}],"rules":[{"name":"Words on قرر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُّسْتَقَرٌّۭ","ٱسْتَقَرَّ","ءَأَقْرَرْتُمْ","ٱلْقَرَارُ","تَقَرَّ","مُسْتَقَرٌّۭ","قَوَارِيرَا۠","أَقْرَرْنَا"]},{"name":"Parts of speech attested for قرر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 28 glossed words attested.","examples":["مُّسْتَقَرٌّۭ","ٱسْتَقَرَّ","ءَأَقْرَرْتُمْ","ٱلْقَرَارُ","تَقَرَّ","مُسْتَقَرٌّۭ"]},{"name":"Verb forms attested for قرر","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, IV.","examples":["مُّسْتَقَرٌّۭ","ٱسْتَقَرَّ","ءَأَقْرَرْتُمْ","ٱلْقَرَارُ","تَقَرَّ","مُسْتَقَرٌّۭ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قرر?","options":["شَطْرَ","مُّسْتَقَرٌّۭ","ٱللَّهُ","لِتَأْخُذُوهَا"],"correct":1,"explanation":"مُّسْتَقَرٌّۭ — glossed \"(is) a fixed time\" at 6:67 — carries the root قرر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱسْتَقَرَّ mean?","options":["Allah wills","then eat","in the Verses","it remains"],"correct":3,"explanation":"\"it remains\", from the word-by-word gloss at 7:143."},{"type":"fill_blank","question":"Type the root of ءَأَقْرَرْتُمْ in Arabic (three letters).","correct":"قرر","explanation":"قرر. Diacritics are ignored when checking, so ق ر ر is enough."}]', '["root-mrA"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Alw', 'The root الو (ا ل و)', 'grammar', 4, '{"explanation":"The root الو occurs 37 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 5 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ءَالَآءِ","transliteration":"","meaning":"the Favors","rule":"53:55"},{"arabic":"يَأْتَلِ","transliteration":"","meaning":"let swear","rule":"24:22"},{"arabic":"يُؤْلُونَ","transliteration":"","meaning":"swear (off)","rule":"2:226"},{"arabic":"يَأْلُونَكُمْ","transliteration":"","meaning":"they will spare you","rule":"3:118"},{"arabic":"ءَالَآءَ","transliteration":"","meaning":"(the) Bounties","rule":"7:69"}],"rules":[{"name":"Words on الو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ءَالَآءِ","يَأْتَلِ","يُؤْلُونَ","يَأْلُونَكُمْ","ءَالَآءَ"]},{"name":"Parts of speech attested for الو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 5 glossed words attested.","examples":["ءَالَآءِ","يَأْتَلِ","يُؤْلُونَ","يَأْلُونَكُمْ","ءَالَآءَ"]},{"name":"Verb forms attested for الو","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VIII.","examples":["ءَالَآءِ","يَأْتَلِ","يُؤْلُونَ","يَأْلُونَكُمْ","ءَالَآءَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root الو?","options":["شُعَبٍۢ","ءَاتَىٰهُ","ءَالَآءِ","ذِكْرَىٰهَآ"],"correct":2,"explanation":"ءَالَآءِ — glossed \"the Favors\" at 53:55 — carries the root الو. The others come from different roots."},{"type":"multiple_choice","question":"What does يَأْتَلِ mean?","options":["(of) its affair","they remain behind","let swear","more intense"],"correct":2,"explanation":"\"let swear\", from the word-by-word gloss at 24:22."},{"type":"fill_blank","question":"Type the root of يُؤْلُونَ in Arabic (three letters).","correct":"الو","explanation":"الو. Diacritics are ignored when checking, so ا ل و is enough."}]', '["root-qrr"]', 29, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nkr', 'The root نكر (ن ك ر)', 'grammar', 4, '{"explanation":"The root نكر occurs 37 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنكَرَ","transliteration":"","meaning":"(the) harshest","rule":"31:19"},{"arabic":"بِٱلْمُنكَرِ","transliteration":"","meaning":"the wrong","rule":"9:67"},{"arabic":"نُّكُرٍ","transliteration":"","meaning":"terrible","rule":"54:6"},{"arabic":"ٱلْمُنكَرِ","transliteration":"","meaning":"the wrong","rule":"3:104"},{"arabic":"نَكِيرِ","transliteration":"","meaning":"My punishment","rule":"22:44"},{"arabic":"وَٱلْمُنكَرِ","transliteration":"","meaning":"and the bad","rule":"16:90"}],"rules":[{"name":"Words on نكر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنكَرَ","بِٱلْمُنكَرِ","نُّكُرٍ","ٱلْمُنكَرِ","نَكِيرِ","وَٱلْمُنكَرِ","مُّنكَرُونَ","تُنكِرُونَ"]},{"name":"Parts of speech attested for نكر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 19 glossed words attested.","examples":["أَنكَرَ","بِٱلْمُنكَرِ","نُّكُرٍ","ٱلْمُنكَرِ","نَكِيرِ","وَٱلْمُنكَرِ"]},{"name":"Verb forms attested for نكر","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["أَنكَرَ","بِٱلْمُنكَرِ","نُّكُرٍ","ٱلْمُنكَرِ","نَكِيرِ","وَٱلْمُنكَرِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نكر?","options":["ٱللَّهُ","أَنكَرَ","مُؤْمِنُونَ","أَفَّاكٍ"],"correct":1,"explanation":"أَنكَرَ — glossed \"(the) harshest\" at 31:19 — carries the root نكر. The others come from different roots."},{"type":"multiple_choice","question":"What does بِٱلْمُنكَرِ mean?","options":["the wrong","the sins","[the] gold","believing"],"correct":0,"explanation":"\"the wrong\", from the word-by-word gloss at 9:67."},{"type":"fill_blank","question":"Type the root of نُّكُرٍ in Arabic (three letters).","correct":"نكر","explanation":"نكر. Diacritics are ignored when checking, so ن ك ر is enough."}]', '["root-Alw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sbq', 'The root سبق (س ب ق)', 'grammar', 4, '{"explanation":"The root سبق occurs 37 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as V, N, in verb forms VIII, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَبْقًۭا","transliteration":"","meaning":"(in) a race","rule":"79:4"},{"arabic":"سَبَقُونَآ","transliteration":"","meaning":"they (would) have preceded us","rule":"46:11"},{"arabic":"سَبَقَكُم","transliteration":"","meaning":"has preceded you","rule":"7:80"},{"arabic":"وَٱلسَّـٰبِقُونَ","transliteration":"","meaning":"And the forerunners","rule":"9:100"},{"arabic":"بِمَسْبُوقِينَ","transliteration":"","meaning":"(are) outrun","rule":"56:60"},{"arabic":"نَسْتَبِقُ","transliteration":"","meaning":"racing each other","rule":"12:17"}],"rules":[{"name":"Words on سبق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَبْقًۭا","سَبَقُونَآ","سَبَقَكُم","وَٱلسَّـٰبِقُونَ","بِمَسْبُوقِينَ","نَسْتَبِقُ","سَبَقُوٓا۟","سَابِقُ"]},{"name":"Parts of speech attested for سبق","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 23 glossed words attested.","examples":["سَبْقًۭا","سَبَقُونَآ","سَبَقَكُم","وَٱلسَّـٰبِقُونَ","بِمَسْبُوقِينَ","نَسْتَبِقُ"]},{"name":"Verb forms attested for سبق","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, III.","examples":["سَبْقًۭا","سَبَقُونَآ","سَبَقَكُم","وَٱلسَّـٰبِقُونَ","بِمَسْبُوقِينَ","نَسْتَبِقُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سبق?","options":["أُو۟لِى","يَتَّخِذُوهُ","سَبْقًۭا","أَمْرًۭا"],"correct":2,"explanation":"سَبْقًۭا — glossed \"(in) a race\" at 79:4 — carries the root سبق. The others come from different roots."},{"type":"multiple_choice","question":"What does سَبَقُونَآ mean?","options":["bought","they (would) have preceded us","(to) the land","So remind"],"correct":1,"explanation":"\"they (would) have preceded us\", from the word-by-word gloss at 46:11."},{"type":"fill_blank","question":"Type the root of سَبَقَكُم in Arabic (three letters).","correct":"سبق","explanation":"سبق. Diacritics are ignored when checking, so س ب ق is enough."}]', '["root-nkr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Any', 'The root اني (ا ن ي)', 'grammar', 4, '{"explanation":"The root اني occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as INTG, T, N, V, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ءَانَآءَ","transliteration":"","meaning":"(in the) hours","rule":"3:113"},{"arabic":"ءَانِيَةٍۢ","transliteration":"","meaning":"boiling","rule":"88:5"},{"arabic":"بِـَٔانِيَةٍۢ","transliteration":"","meaning":"vessels","rule":"76:15"},{"arabic":"أَنَّىٰ","transliteration":"","meaning":"when","rule":"2:223"},{"arabic":"ءَانَآئِ","transliteration":"","meaning":"(the) hours","rule":"20:130"},{"arabic":"ءَانٍۢ","transliteration":"","meaning":"heated","rule":"55:44"}],"rules":[{"name":"Words on اني","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ءَانَآءَ","ءَانِيَةٍۢ","بِـَٔانِيَةٍۢ","أَنَّىٰ","ءَانَآئِ","ءَانٍۢ","إِنَىٰهُ","فَأَنَّىٰ"]},{"name":"Parts of speech attested for اني","description":"The morphology corpus tags words on this root as INTG, T, N, V, ADJ — 5 distinct parts of speech across the 10 glossed words attested.","examples":["ءَانَآءَ","ءَانِيَةٍۢ","بِـَٔانِيَةٍۢ","أَنَّىٰ","ءَانَآئِ","ءَانٍۢ"]},{"name":"Where اني occurs","description":"The 10 glossed words on this root are attested across 10 distinct surahs.","examples":["ءَانَآءَ (3:113)","ءَانِيَةٍۢ (88:5)","بِـَٔانِيَةٍۢ (76:15)","أَنَّىٰ (2:223)","ءَانَآئِ (20:130)","ءَانٍۢ (55:44)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اني?","options":["شَيَـٰطِينِهِمْ","ءَانَآءَ","فَأْتُوا۟","وَٱذْكُرُوهُ"],"correct":1,"explanation":"ءَانَآءَ — glossed \"(in the) hours\" at 3:113 — carries the root اني. The others come from different roots."},{"type":"multiple_choice","question":"What does ءَانِيَةٍۢ mean?","options":["O you who believe","boiling","remember","and you will come forth"],"correct":1,"explanation":"\"boiling\", from the word-by-word gloss at 88:5."},{"type":"fill_blank","question":"Type the root of بِـَٔانِيَةٍۢ in Arabic (three letters).","correct":"اني","explanation":"اني. Diacritics are ignored when checking, so ا ن ي is enough."}]', '["root-sbq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Awy', 'The root اوي (ا و ي)', 'grammar', 4, '{"explanation":"The root اوي occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَوَيْنَآ","transliteration":"","meaning":"we retired","rule":"18:63"},{"arabic":"وَمَأْوَىٰهُمْ","transliteration":"","meaning":"And their abode","rule":"9:73"},{"arabic":"وَمَأْوَىٰهُمُ","transliteration":"","meaning":"and their refuge","rule":"3:151"},{"arabic":"وَمَأْوَىٰهُ","transliteration":"","meaning":"and his abode","rule":"3:162"},{"arabic":"ءَاوِىٓ","transliteration":"","meaning":"I could take refuge","rule":"11:80"},{"arabic":"سَـَٔاوِىٓ","transliteration":"","meaning":"I will betake myself","rule":"11:43"}],"rules":[{"name":"Words on اوي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَوَيْنَآ","وَمَأْوَىٰهُمْ","وَمَأْوَىٰهُمُ","وَمَأْوَىٰهُ","ءَاوِىٓ","سَـَٔاوِىٓ","مَأْوَىٰهُمُ","ٱلْمَأْوَىٰ"]},{"name":"Parts of speech attested for اوي","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 23 glossed words attested.","examples":["أَوَيْنَآ","وَمَأْوَىٰهُمْ","وَمَأْوَىٰهُمُ","وَمَأْوَىٰهُ","ءَاوِىٓ","سَـَٔاوِىٓ"]},{"name":"Verb forms attested for اوي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["أَوَيْنَآ","وَمَأْوَىٰهُمْ","وَمَأْوَىٰهُمُ","وَمَأْوَىٰهُ","ءَاوِىٓ","سَـَٔاوِىٓ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اوي?","options":["أَوَيْنَآ","ٱللَّهِ","فَأَتَىٰهُمُ","وَإِخْوَٰنُهُمْ"],"correct":0,"explanation":"أَوَيْنَآ — glossed \"we retired\" at 18:63 — carries the root اوي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَمَأْوَىٰهُمْ mean?","options":["And their abode","And drink","their offspring","a Sign"],"correct":0,"explanation":"\"And their abode\", from the word-by-word gloss at 9:73."},{"type":"fill_blank","question":"Type the root of وَمَأْوَىٰهُمُ in Arabic (three letters).","correct":"اوي","explanation":"اوي. Diacritics are ignored when checking, so ا و ي is enough."}]', '["root-Any"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hdv', 'The root حدث (ح د ث)', 'grammar', 4, '{"explanation":"The root حدث occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as V, N, in verb forms II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْأَحَادِيثِ","transliteration":"","meaning":"(of) the narratives","rule":"12:6"},{"arabic":"ٱلْحَدِيثِ","transliteration":"","meaning":"[the] narration","rule":"18:6"},{"arabic":"أَتُحَدِّثُونَهُم","transliteration":"","meaning":"Do you tell them","rule":"2:76"},{"arabic":"يُحْدِثُ","transliteration":"","meaning":"it may cause","rule":"20:113"},{"arabic":"حَدِيثٍ","transliteration":"","meaning":"a conversation","rule":"4:140"},{"arabic":"أُحْدِثَ","transliteration":"","meaning":"I present","rule":"18:70"}],"rules":[{"name":"Words on حدث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْأَحَادِيثِ","ٱلْحَدِيثِ","أَتُحَدِّثُونَهُم","يُحْدِثُ","حَدِيثٍ","أُحْدِثَ","أَحَادِيثَ","مُّحْدَثٍ"]},{"name":"Parts of speech attested for حدث","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 16 glossed words attested.","examples":["ٱلْأَحَادِيثِ","ٱلْحَدِيثِ","أَتُحَدِّثُونَهُم","يُحْدِثُ","حَدِيثٍ","أُحْدِثَ"]},{"name":"Verb forms attested for حدث","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV.","examples":["ٱلْأَحَادِيثِ","ٱلْحَدِيثِ","أَتُحَدِّثُونَهُم","يُحْدِثُ","حَدِيثٍ","أُحْدِثَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حدث?","options":["ٱلْمَشَـٰرِقِ","إِثْمًۭا","ٱلْأَحَادِيثِ","ٱللَّهِ"],"correct":2,"explanation":"ٱلْأَحَادِيثِ — glossed \"(of) the narratives\" at 12:6 — carries the root حدث. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْحَدِيثِ mean?","options":["[the] narration","will bring it to you","a tree","their forefathers"],"correct":0,"explanation":"\"[the] narration\", from the word-by-word gloss at 18:6."},{"type":"fill_blank","question":"Type the root of أَتُحَدِّثُونَهُم in Arabic (three letters).","correct":"حدث","explanation":"حدث. Diacritics are ignored when checking, so ح د ث is enough."}]', '["root-Awy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bTl', 'The root بطل (ب ط ل)', 'grammar', 4, '{"explanation":"The root بطل occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَفَبِٱلْبَـٰطِلِ","transliteration":"","meaning":"Then in falsehood do","rule":"16:72"},{"arabic":"وَيُبْطِلَ","transliteration":"","meaning":"and prove false","rule":"8:8"},{"arabic":"تُبْطِلُوا۟","transliteration":"","meaning":"render in vain","rule":"2:264"},{"arabic":"وَبَـٰطِلٌۭ","transliteration":"","meaning":"and vain","rule":"7:139"},{"arabic":"ٱلْبَـٰطِلَ","transliteration":"","meaning":"the falsehood","rule":"8:8"},{"arabic":"بِٱلْبَـٰطِلِ","transliteration":"","meaning":"with [the] falsehood","rule":"2:42"}],"rules":[{"name":"Words on بطل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَفَبِٱلْبَـٰطِلِ","وَيُبْطِلَ","تُبْطِلُوا۟","وَبَـٰطِلٌۭ","ٱلْبَـٰطِلَ","بِٱلْبَـٰطِلِ","وَٱلْبَـٰطِلَ","سَيُبْطِلُهُۥٓ"]},{"name":"Parts of speech attested for بطل","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 15 glossed words attested.","examples":["أَفَبِٱلْبَـٰطِلِ","وَيُبْطِلَ","تُبْطِلُوا۟","وَبَـٰطِلٌۭ","ٱلْبَـٰطِلَ","بِٱلْبَـٰطِلِ"]},{"name":"Verb forms attested for بطل","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["أَفَبِٱلْبَـٰطِلِ","وَيُبْطِلَ","تُبْطِلُوا۟","وَبَـٰطِلٌۭ","ٱلْبَـٰطِلَ","بِٱلْبَـٰطِلِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بطل?","options":["تَشْكُرُونَ","فَـَٔامِنُوا۟","لِّأَوَّلِنَا","أَفَبِٱلْبَـٰطِلِ"],"correct":3,"explanation":"أَفَبِٱلْبَـٰطِلِ — glossed \"Then in falsehood do\" at 16:72 — carries the root بطل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيُبْطِلَ mean?","options":["and prove false","(of) its affair","to his father","or [the] hurt"],"correct":0,"explanation":"\"and prove false\", from the word-by-word gloss at 8:8."},{"type":"fill_blank","question":"Type the root of تُبْطِلُوا۟ in Arabic (three letters).","correct":"بطل","explanation":"بطل. Diacritics are ignored when checking, so ب ط ل is enough."}]', '["root-Hdv"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qTE', 'The root قطع (ق ط ع)', 'grammar', 4, '{"explanation":"The root قطع occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, in verb forms V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَقَطَّعَ","transliteration":"","meaning":"so it cuts into pieces","rule":"47:15"},{"arabic":"وَيَقْطَعَ","transliteration":"","meaning":"and cut off","rule":"8:7"},{"arabic":"بِقِطْعٍۢ","transliteration":"","meaning":"in a part","rule":"11:81"},{"arabic":"وَتَقَطَّعُوٓا۟","transliteration":"","meaning":"But they cut off","rule":"21:93"},{"arabic":"وَيَقْطَعُونَ","transliteration":"","meaning":"and [they] cut","rule":"2:27"},{"arabic":"قَاطِعَةً","transliteration":"","meaning":"the one to decide","rule":"27:32"}],"rules":[{"name":"Words on قطع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَقَطَّعَ","وَيَقْطَعَ","بِقِطْعٍۢ","وَتَقَطَّعُوٓا۟","وَيَقْطَعُونَ","قَاطِعَةً","قُطِّعَتْ","وَتَقَطَّعَتْ"]},{"name":"Parts of speech attested for قطع","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 32 glossed words attested.","examples":["فَقَطَّعَ","وَيَقْطَعَ","بِقِطْعٍۢ","وَتَقَطَّعُوٓا۟","وَيَقْطَعُونَ","قَاطِعَةً"]},{"name":"Verb forms attested for قطع","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, II.","examples":["فَقَطَّعَ","وَيَقْطَعَ","بِقِطْعٍۢ","وَتَقَطَّعُوٓا۟","وَيَقْطَعُونَ","قَاطِعَةً"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قطع?","options":["فَقَطَّعَ","ٱللَّهُ","يَشَإِ","لِّلَّهِ"],"correct":0,"explanation":"فَقَطَّعَ — glossed \"so it cuts into pieces\" at 47:15 — carries the root قطع. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَقْطَعَ mean?","options":["(of the) people","covenant of protection","and cut off","[the] witnesses"],"correct":2,"explanation":"\"and cut off\", from the word-by-word gloss at 8:7."},{"type":"fill_blank","question":"Type the root of بِقِطْعٍۢ in Arabic (three letters).","correct":"قطع","explanation":"قطع. Diacritics are ignored when checking, so ق ط ع is enough."}]', '["root-bTl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qrn', 'The root قرن (ق ر ن)', 'grammar', 4, '{"explanation":"The root قرن occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, ADJ, in verb forms II, IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَقُرُونًۢا","transliteration":"","meaning":"and generations","rule":"25:38"},{"arabic":"قَرِينُهُۥ","transliteration":"","meaning":"his companion","rule":"50:23"},{"arabic":"قَرِينٌۭ","transliteration":"","meaning":"a companion","rule":"37:51"},{"arabic":"ٱلْقَرْنَيْنِ","transliteration":"","meaning":"Dhul-qarnain","rule":"18:83"},{"arabic":"قَرْنٍ","transliteration":"","meaning":"a generation","rule":"19:74"},{"arabic":"قَرْنٍۢ","transliteration":"","meaning":"generations","rule":"6:6"}],"rules":[{"name":"Words on قرن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَقُرُونًۢا","قَرِينُهُۥ","قَرِينٌۭ","ٱلْقَرْنَيْنِ","قَرْنٍ","قَرْنٍۢ","قُرَنَآءَ","مُقْتَرِنِينَ"]},{"name":"Parts of speech attested for قرن","description":"The morphology corpus tags words on this root as N, ADJ — 2 distinct parts of speech across the 19 glossed words attested.","examples":["وَقُرُونًۢا","قَرِينُهُۥ","قَرِينٌۭ","ٱلْقَرْنَيْنِ","قَرْنٍ","قَرْنٍۢ"]},{"name":"Verb forms attested for قرن","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV, VIII.","examples":["وَقُرُونًۢا","قَرِينُهُۥ","قَرِينٌۭ","ٱلْقَرْنَيْنِ","قَرْنٍ","قَرْنٍۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قرن?","options":["ٱلْمُشْرِكِينَ","ٱللَّهُ","وَقُرُونًۢا","بِـَٔايَـٰتِنَآ"],"correct":2,"explanation":"وَقُرُونًۢا — glossed \"and generations\" at 25:38 — carries the root قرن. The others come from different roots."},{"type":"multiple_choice","question":"What does قَرِينُهُۥ mean?","options":["something","his companion","(is) sinful","and Allah has forgiven"],"correct":1,"explanation":"\"his companion\", from the word-by-word gloss at 50:23."},{"type":"fill_blank","question":"Type the root of قَرِينٌۭ in Arabic (three letters).","correct":"قرن","explanation":"قرن. Diacritics are ignored when checking, so ق ر ن is enough."}]', '["root-qTE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ryb', 'The root ريب (ر ي ب)', 'grammar', 4, '{"explanation":"The root ريب occurs 36 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms VIII, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَرْتَابُوا۟","transliteration":"","meaning":"doubt","rule":"49:15"},{"arabic":"وَٱرْتَابَتْ","transliteration":"","meaning":"and (are in) doubts","rule":"9:45"},{"arabic":"مُّرِيبٍۭ","transliteration":"","meaning":"disquieting","rule":"34:54"},{"arabic":"يَرْتَابَ","transliteration":"","meaning":"may doubt","rule":"74:31"},{"arabic":"رَيْبِهِمْ","transliteration":"","meaning":"their doubts","rule":"9:45"},{"arabic":"مُّرِيبٍ","transliteration":"","meaning":"doubter","rule":"50:25"}],"rules":[{"name":"Words on ريب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَرْتَابُوا۟","وَٱرْتَابَتْ","مُّرِيبٍۭ","يَرْتَابَ","رَيْبِهِمْ","مُّرِيبٍ","لَّٱرْتَابَ","مُّرْتَابٌ"]},{"name":"Parts of speech attested for ريب","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 16 glossed words attested.","examples":["يَرْتَابُوا۟","وَٱرْتَابَتْ","مُّرِيبٍۭ","يَرْتَابَ","رَيْبِهِمْ","مُّرِيبٍ"]},{"name":"Verb forms attested for ريب","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, IV.","examples":["يَرْتَابُوا۟","وَٱرْتَابَتْ","مُّرِيبٍۭ","يَرْتَابَ","رَيْبِهِمْ","مُّرِيبٍ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ريب?","options":["يَرْتَابُوا۟","نُؤْتِيهِ","تَأْمُرِينَ","ٱللَّهُ"],"correct":0,"explanation":"يَرْتَابُوا۟ — glossed \"doubt\" at 49:15 — carries the root ريب. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱرْتَابَتْ mean?","options":["(will) come to both of you","And taste","with [the] bad","and (are in) doubts"],"correct":3,"explanation":"\"and (are in) doubts\", from the word-by-word gloss at 9:45."},{"type":"fill_blank","question":"Type the root of مُّرِيبٍۭ in Arabic (three letters).","correct":"ريب","explanation":"ريب. Diacritics are ignored when checking, so ر ي ب is enough."}]', '["root-qrn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Efw', 'The root عفو (ع ف و)', 'grammar', 4, '{"explanation":"The root عفو occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَفَوا۟","transliteration":"","meaning":"they increased","rule":"7:95"},{"arabic":"وَٱلْعَافِينَ","transliteration":"","meaning":"and those who pardon","rule":"3:134"},{"arabic":"وَيَعْفُ","transliteration":"","meaning":"but He pardons","rule":"42:34"},{"arabic":"ٱلْعَفْوَ","transliteration":"","meaning":"The surplus","rule":"2:219"},{"arabic":"فَٱعْفُوا۟","transliteration":"","meaning":"So forgive","rule":"2:109"},{"arabic":"تَعْفُوا۟","transliteration":"","meaning":"pardon","rule":"4:149"}],"rules":[{"name":"Words on عفو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَفَوا۟","وَٱلْعَافِينَ","وَيَعْفُ","ٱلْعَفْوَ","فَٱعْفُوا۟","تَعْفُوا۟","عَفُوًّا","نَّعْفُ"]},{"name":"Parts of speech attested for عفو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 23 glossed words attested.","examples":["عَفَوا۟","وَٱلْعَافِينَ","وَيَعْفُ","ٱلْعَفْوَ","فَٱعْفُوا۟","تَعْفُوا۟"]},{"name":"Where عفو occurs","description":"The 23 glossed words on this root are attested across 9 distinct surahs.","examples":["عَفَوا۟ (7:95)","وَٱلْعَافِينَ (3:134)","وَيَعْفُ (42:34)","ٱلْعَفْوَ (2:219)","فَٱعْفُوا۟ (2:109)","تَعْفُوا۟ (4:149)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عفو?","options":["تَأْتِى","شِقْوَتُنَا","عَفَوا۟","ٱلشُّحَّ"],"correct":2,"explanation":"عَفَوا۟ — glossed \"they increased\" at 7:95 — carries the root عفو. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْعَافِينَ mean?","options":["secure","a Verse","and those who pardon","(are) communities"],"correct":2,"explanation":"\"and those who pardon\", from the word-by-word gloss at 3:134."},{"type":"fill_blank","question":"Type the root of وَيَعْفُ in Arabic (three letters).","correct":"عفو","explanation":"عفو. Diacritics are ignored when checking, so ع ف و is enough."}]', '["root-ryb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hyn', 'The root حين (ح ي ن)', 'grammar', 4, '{"explanation":"The root حين occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 8 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"حِينَ","transliteration":"","meaning":"when","rule":"5:101"},{"arabic":"حِينِ","transliteration":"","meaning":"a time","rule":"28:15"},{"arabic":"حِينٌۭ","transliteration":"","meaning":"a period","rule":"76:1"},{"arabic":"حِينٍۭ","transliteration":"","meaning":"time","rule":"14:25"},{"arabic":"حِينٍ","transliteration":"","meaning":"a time","rule":"23:54"},{"arabic":"وَحِينَ","transliteration":"","meaning":"and (the) time","rule":"2:177"}],"rules":[{"name":"Words on حين","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["حِينَ","حِينِ","حِينٌۭ","حِينٍۭ","حِينٍ","وَحِينَ","حِينَئِذٍۢ","حِينٍۢ"]},{"name":"Parts of speech attested for حين","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 8 glossed words attested.","examples":["حِينَ","حِينِ","حِينٌۭ","حِينٍۭ","حِينٍ","وَحِينَ"]},{"name":"Where حين occurs","description":"The 8 glossed words on this root are attested across 7 distinct surahs.","examples":["حِينَ (5:101)","حِينِ (28:15)","حِينٌۭ (76:1)","حِينٍۭ (14:25)","حِينٍ (23:54)","وَحِينَ (2:177)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حين?","options":["حِينَ","يَـٰٓأُو۟لِى","يَأْذَنَ","يَأْتِ"],"correct":0,"explanation":"حِينَ — glossed \"when\" at 5:101 — carries the root حين. The others come from different roots."},{"type":"multiple_choice","question":"What does حِينِ mean?","options":["a time","martyrs","Allah intended for me","its Verses"],"correct":0,"explanation":"\"a time\", from the word-by-word gloss at 28:15."},{"type":"fill_blank","question":"Type the root of حِينٌۭ in Arabic (three letters).","correct":"حين","explanation":"حين. Diacritics are ignored when checking, so ح ي ن is enough."}]', '["root-Efw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gfl', 'The root غفل (غ ف ل)', 'grammar', 4, '{"explanation":"The root غفل occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"غَـٰفِلِينَ","transliteration":"","meaning":"heedless","rule":"7:136"},{"arabic":"تَغْفُلُونَ","transliteration":"","meaning":"you neglect","rule":"4:102"},{"arabic":"أَغْفَلْنَا","transliteration":"","meaning":"We have made heedless","rule":"18:28"},{"arabic":"لَغَـٰفِلِينَ","transliteration":"","meaning":"certainly unaware","rule":"6:156"},{"arabic":"غَـٰفِلًا","transliteration":"","meaning":"(is) unaware","rule":"14:42"},{"arabic":"ٱلْغَـٰفِلِينَ","transliteration":"","meaning":"the heedless","rule":"7:205"}],"rules":[{"name":"Words on غفل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["غَـٰفِلِينَ","تَغْفُلُونَ","أَغْفَلْنَا","لَغَـٰفِلِينَ","غَـٰفِلًا","ٱلْغَـٰفِلِينَ","ٱلْغَـٰفِلُونَ","بِغَـٰفِلٍ"]},{"name":"Parts of speech attested for غفل","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 12 glossed words attested.","examples":["غَـٰفِلِينَ","تَغْفُلُونَ","أَغْفَلْنَا","لَغَـٰفِلِينَ","غَـٰفِلًا","ٱلْغَـٰفِلِينَ"]},{"name":"Verb forms attested for غفل","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["غَـٰفِلِينَ","تَغْفُلُونَ","أَغْفَلْنَا","لَغَـٰفِلِينَ","غَـٰفِلًا","ٱلْغَـٰفِلِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غفل?","options":["غَـٰفِلِينَ","ٱلذِّكْرَىٰ","فَأْذَن","أُجُورَهُمْ"],"correct":0,"explanation":"غَـٰفِلِينَ — glossed \"heedless\" at 7:136 — carries the root غفل. The others come from different roots."},{"type":"multiple_choice","question":"What does تَغْفُلُونَ mean?","options":["you neglect","And remind","(to) Allah","contains"],"correct":0,"explanation":"\"you neglect\", from the word-by-word gloss at 4:102."},{"type":"fill_blank","question":"Type the root of أَغْفَلْنَا in Arabic (three letters).","correct":"غفل","explanation":"غفل. Diacritics are ignored when checking, so غ ف ل is enough."}]', '["root-Hyn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kyd', 'The root كيد (ك ي د)', 'grammar', 4, '{"explanation":"The root كيد occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَيْدِى","transliteration":"","meaning":"My plan","rule":"7:183"},{"arabic":"لَأَكِيدَنَّ","transliteration":"","meaning":"surely, I will plan","rule":"21:57"},{"arabic":"كَيْدَهُمْ","transliteration":"","meaning":"their plan","rule":"105:2"},{"arabic":"كَيْدًۭا","transliteration":"","meaning":"a plan","rule":"21:70"},{"arabic":"كَيْدَكُنَّ","transliteration":"","meaning":"your plot","rule":"12:28"},{"arabic":"يَكِيدُونَ","transliteration":"","meaning":"are plotting","rule":"86:15"}],"rules":[{"name":"Words on كيد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَيْدِى","لَأَكِيدَنَّ","كَيْدَهُمْ","كَيْدًۭا","كَيْدَكُنَّ","يَكِيدُونَ","فَكِيدُونِى","ٱلْمَكِيدُونَ"]},{"name":"Parts of speech attested for كيد","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 25 glossed words attested.","examples":["كَيْدِى","لَأَكِيدَنَّ","كَيْدَهُمْ","كَيْدًۭا","كَيْدَكُنَّ","يَكِيدُونَ"]},{"name":"Where كيد occurs","description":"The 25 glossed words on this root are attested across 13 distinct surahs.","examples":["كَيْدِى (7:183)","لَأَكِيدَنَّ (21:57)","كَيْدَهُمْ (105:2)","كَيْدًۭا (21:70)","كَيْدَكُنَّ (12:28)","يَكِيدُونَ (86:15)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كيد?","options":["لِّلشَّـٰرِبِينَ","ٱللَّهُ","كَيْدِى","وَتَأْسِرُونَ"],"correct":2,"explanation":"كَيْدِى — glossed \"My plan\" at 7:183 — carries the root كيد. The others come from different roots."},{"type":"multiple_choice","question":"What does لَأَكِيدَنَّ mean?","options":["a term","the later ones","will bring","surely, I will plan"],"correct":3,"explanation":"\"surely, I will plan\", from the word-by-word gloss at 21:57."},{"type":"fill_blank","question":"Type the root of كَيْدَهُمْ in Arabic (three letters).","correct":"كيد","explanation":"كيد. Diacritics are ignored when checking, so ك ي د is enough."}]', '["root-gfl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mrr', 'The root مرر (م ر ر)', 'grammar', 4, '{"explanation":"The root مرر occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَمَرَّتْ","transliteration":"","meaning":"and continues","rule":"7:189"},{"arabic":"مَرَّةٍۭ","transliteration":"","meaning":"time","rule":"18:48"},{"arabic":"لَتَمُرُّونَ","transliteration":"","meaning":"surely pass","rule":"37:137"},{"arabic":"مَرَّتَانِ","transliteration":"","meaning":"(is) twice","rule":"2:229"},{"arabic":"مُّسْتَمِرٍّۢ","transliteration":"","meaning":"continuous","rule":"54:19"},{"arabic":"يَمُرُّونَ","transliteration":"","meaning":"they pass","rule":"12:105"}],"rules":[{"name":"Words on مرر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَمَرَّتْ","مَرَّةٍۭ","لَتَمُرُّونَ","مَرَّتَانِ","مُّسْتَمِرٍّۢ","يَمُرُّونَ","مَرَّ","مَرَّةٍ"]},{"name":"Parts of speech attested for مرر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 20 glossed words attested.","examples":["فَمَرَّتْ","مَرَّةٍۭ","لَتَمُرُّونَ","مَرَّتَانِ","مُّسْتَمِرٍّۢ","يَمُرُّونَ"]},{"name":"Verb forms attested for مرر","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["فَمَرَّتْ","مَرَّةٍۭ","لَتَمُرُّونَ","مَرَّتَانِ","مُّسْتَمِرٍّۢ","يَمُرُّونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مرر?","options":["فَمَرَّتْ","شُرَكَآءَكُمْ","لِلْأَنَامِ","يَذْكُرُونَ"],"correct":0,"explanation":"فَمَرَّتْ — glossed \"and continues\" at 7:189 — carries the root مرر. The others come from different roots."},{"type":"multiple_choice","question":"What does مَرَّةٍۭ mean?","options":["Do you take us","(is) mightier","you mention","time"],"correct":3,"explanation":"\"time\", from the word-by-word gloss at 18:48."},{"type":"fill_blank","question":"Type the root of لَتَمُرُّونَ in Arabic (three letters).","correct":"مرر","explanation":"مرر. Diacritics are ignored when checking, so م ر ر is enough."}]', '["root-kyd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wrv', 'The root ورث (و ر ث)', 'grammar', 4, '{"explanation":"The root ورث occurs 35 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَرِثُوا۟","transliteration":"","meaning":"(who) inherited","rule":"7:169"},{"arabic":"أُورِثْتُمُوهَا","transliteration":"","meaning":"you have been made to inherit it","rule":"7:43"},{"arabic":"وَأَوْرَثَنَا","transliteration":"","meaning":"and has made us inherit","rule":"39:74"},{"arabic":"وَأَوْرَثْنَا","transliteration":"","meaning":"And We made inheritors","rule":"7:137"},{"arabic":"وَأَوْرَثْنَـٰهَا","transliteration":"","meaning":"And We caused to inherit them","rule":"26:59"},{"arabic":"يُورِثُهَا","transliteration":"","meaning":"He causes to inherit it","rule":"7:128"}],"rules":[{"name":"Words on ورث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَرِثُوا۟","أُورِثْتُمُوهَا","وَأَوْرَثَنَا","وَأَوْرَثْنَا","وَأَوْرَثْنَـٰهَا","يُورِثُهَا","وَرَثَةِ","وَنَرِثُهُۥ"]},{"name":"Parts of speech attested for ورث","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 27 glossed words attested.","examples":["وَرِثُوا۟","أُورِثْتُمُوهَا","وَأَوْرَثَنَا","وَأَوْرَثْنَا","وَأَوْرَثْنَـٰهَا","يُورِثُهَا"]},{"name":"Verb forms attested for ورث","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَرِثُوا۟","أُورِثْتُمُوهَا","وَأَوْرَثَنَا","وَأَوْرَثْنَا","وَأَوْرَثْنَـٰهَا","يُورِثُهَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ورث?","options":["لِّلَّهِ","أُكُلَهَا","وَرِثُوا۟","بِأَمْرِهِۦٓ"],"correct":2,"explanation":"وَرِثُوا۟ — glossed \"(who) inherited\" at 7:169 — carries the root ورث. The others come from different roots."},{"type":"multiple_choice","question":"What does أُورِثْتُمُوهَا mean?","options":["the most wretched","you have been made to inherit it","Most Appreciative","any drink"],"correct":1,"explanation":"\"you have been made to inherit it\", from the word-by-word gloss at 7:43."},{"type":"fill_blank","question":"Type the root of وَأَوْرَثَنَا in Arabic (three letters).","correct":"ورث","explanation":"ورث. Diacritics are ignored when checking, so و ر ث is enough."}]', '["root-mrr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-hzA', 'The root هزا (ه ز ا)', 'grammar', 4, '{"explanation":"The root هزا occurs 34 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as N, V, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"هُزُوًۭا","transliteration":"","meaning":"(in) ridicule","rule":"2:67"},{"arabic":"ٱسْتَهْزِءُوٓا۟","transliteration":"","meaning":"Mock","rule":"9:64"},{"arabic":"مُسْتَهْزِءُونَ","transliteration":"","meaning":"(are) mockers","rule":"2:14"},{"arabic":"يَسْتَهْزِئُ","transliteration":"","meaning":"mocks","rule":"2:15"},{"arabic":"ٱلْمُسْتَهْزِءِينَ","transliteration":"","meaning":"(against) the mockers","rule":"15:95"},{"arabic":"ٱسْتُهْزِئَ","transliteration":"","meaning":"were mocked","rule":"6:10"}],"rules":[{"name":"Words on هزا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["هُزُوًۭا","ٱسْتَهْزِءُوٓا۟","مُسْتَهْزِءُونَ","يَسْتَهْزِئُ","ٱلْمُسْتَهْزِءِينَ","ٱسْتُهْزِئَ","وَيُسْتَهْزَأُ","هُزُوًا"]},{"name":"Parts of speech attested for هزا","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 10 glossed words attested.","examples":["هُزُوًۭا","ٱسْتَهْزِءُوٓا۟","مُسْتَهْزِءُونَ","يَسْتَهْزِئُ","ٱلْمُسْتَهْزِءِينَ","ٱسْتُهْزِئَ"]},{"name":"Verb forms attested for هزا","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["هُزُوًۭا","ٱسْتَهْزِءُوٓا۟","مُسْتَهْزِءُونَ","يَسْتَهْزِئُ","ٱلْمُسْتَهْزِءِينَ","ٱسْتُهْزِئَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root هزا?","options":["