INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wvq', 'The root وثق (و ث ق)', 'grammar', 4, '{"explanation":"The root وثق occurs 34 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms III, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مِيثَـٰقِهِۦ","transliteration":"","meaning":"its ratification","rule":"2:27"},{"arabic":"ٱلْوُثْقَىٰ","transliteration":"","meaning":"[the] firm","rule":"2:256"},{"arabic":"يُوثِقُ","transliteration":"","meaning":"will bind","rule":"89:26"},{"arabic":"وَثَاقَهُۥٓ","transliteration":"","meaning":"(as) His binding","rule":"89:26"},{"arabic":"مَوْثِقَهُمْ","transliteration":"","meaning":"their promise","rule":"12:66"},{"arabic":"مِيثَـٰقَكُمْ","transliteration":"","meaning":"your covenant","rule":"2:63"}],"rules":[{"name":"Words on وثق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مِيثَـٰقِهِۦ","ٱلْوُثْقَىٰ","يُوثِقُ","وَثَاقَهُۥٓ","مَوْثِقَهُمْ","مِيثَـٰقَكُمْ","مَوْثِقًۭا","مِيثَـٰقَهُمْ"]},{"name":"Parts of speech attested for وثق","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 20 glossed words attested.","examples":["مِيثَـٰقِهِۦ","ٱلْوُثْقَىٰ","يُوثِقُ","وَثَاقَهُۥٓ","مَوْثِقَهُمْ","مِيثَـٰقَكُمْ"]},{"name":"Verb forms attested for وثق","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, IV.","examples":["مِيثَـٰقِهِۦ","ٱلْوُثْقَىٰ","يُوثِقُ","وَثَاقَهُۥٓ","مَوْثِقَهُمْ","مِيثَـٰقَكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وثق?","options":["وَأَصِيلًا","ٱللَّهُ","مِيثَـٰقِهِۦ","يَشْرَبُ"],"correct":2,"explanation":"مِيثَـٰقِهِۦ — glossed \"its ratification\" at 2:27 — carries the root وثق. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْوُثْقَىٰ mean?","options":["[the] firm","(is the) Command","and their hair","But for Allah"],"correct":0,"explanation":"\"[the] firm\", from the word-by-word gloss at 2:256."},{"type":"fill_blank","question":"Type the root of يُوثِقُ in Arabic (three letters).","correct":"وثق","explanation":"وثق. Diacritics are ignored when checking, so و ث ق is enough."}]', '["root-jnH"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xfy', 'The root خفي (خ ف ي)', 'grammar', 4, '{"explanation":"The root خفي occurs 34 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَخْفَيْتُمْ","transliteration":"","meaning":"you conceal","rule":"60:1"},{"arabic":"مُسْتَخْفٍۭ","transliteration":"","meaning":"(is) hidden","rule":"13:10"},{"arabic":"وَخُفْيَةًۭ","transliteration":"","meaning":"and secretly","rule":"6:63"},{"arabic":"وَتُخْفُونَ","transliteration":"","meaning":"and you conceal","rule":"6:91"},{"arabic":"يُخْفُونَ","transliteration":"","meaning":"They hide","rule":"3:154"},{"arabic":"لِيَسْتَخْفُوا۟","transliteration":"","meaning":"that they may hide","rule":"11:5"}],"rules":[{"name":"Words on خفي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَخْفَيْتُمْ","مُسْتَخْفٍۭ","وَخُفْيَةًۭ","وَتُخْفُونَ","يُخْفُونَ","لِيَسْتَخْفُوا۟","يُخْفِينَ","وَخُفْيَةً"]},{"name":"Parts of speech attested for خفي","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 25 glossed words attested.","examples":["أَخْفَيْتُمْ","مُسْتَخْفٍۭ","وَخُفْيَةًۭ","وَتُخْفُونَ","يُخْفُونَ","لِيَسْتَخْفُوا۟"]},{"name":"Verb forms attested for خفي","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["أَخْفَيْتُمْ","مُسْتَخْفٍۭ","وَخُفْيَةًۭ","وَتُخْفُونَ","يُخْفُونَ","لِيَسْتَخْفُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خفي?","options":["أَخْفَيْتُمْ