INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$ms', 'The root شمس (ش م س)', 'grammar', 4, '{"explanation":"The root شمس occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَمْسًۭا","transliteration":"","meaning":"sun","rule":"76:13"},{"arabic":"بِٱلشَّمْسِ","transliteration":"","meaning":"the sun","rule":"2:258"},{"arabic":"وَٱلشَّمْسِ","transliteration":"","meaning":"By the sun","rule":"91:1"},{"arabic":"ٱلشَّمْسُ","transliteration":"","meaning":"the sun","rule":"36:40"},{"arabic":"لِلشَّمْسِ","transliteration":"","meaning":"to the sun","rule":"27:24"},{"arabic":"ٱلشَّمْسِ","transliteration":"","meaning":"(of) the sun","rule":"17:78"}],"rules":[{"name":"Words on شمس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَمْسًۭا","بِٱلشَّمْسِ","وَٱلشَّمْسِ","ٱلشَّمْسُ","لِلشَّمْسِ","ٱلشَّمْسِ","وَٱلشَّمْسُ","ٱلشَّمْسُ"]},{"name":"Parts of speech attested for شمس","description":"The morphology corpus tags words on this root as N — one part of speech across the 10 glossed words attested.","examples":["شَمْسًۭا","بِٱلشَّمْسِ","وَٱلشَّمْسِ","ٱلشَّمْسُ","لِلشَّمْسِ","ٱلشَّمْسِ"]},{"name":"Where شمس occurs","description":"The 10 glossed words on this root are attested across 9 distinct surahs.","examples":["شَمْسًۭا (76:13)","بِٱلشَّمْسِ (2:258)","وَٱلشَّمْسِ (91:1)","ٱلشَّمْسُ (36:40)","لِلشَّمْسِ (27:24)","ٱلشَّمْسِ (17:78)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شمس?","options":["يَأْتِيهِ","إِيمَـٰنًۭا","شَمْسًۭا","وَءَامَنتُمْ"],"correct":2,"explanation":"شَمْسًۭا — glossed \"sun\" at 76:13 — carries the root شمس. The others come from different roots."},{"type":"multiple_choice","question":"What does بِٱلشَّمْسِ mean?","options":["were given","the first","the sun","and We seized them"],"correct":2,"explanation":"\"the sun\", from the word-by-word gloss at 2:258."},{"type":"fill_blank","question":"Type the root of وَٱلشَّمْسِ in Arabic (three letters).","correct":"شمس","explanation":"شمس. Diacritics are ignored when checking, so ش م س is enough."}]', '["root-xfy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Emy', 'The root عمي (ع م ي)', 'grammar', 4, '{"explanation":"The root عمي occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعُمْىِ","transliteration":"","meaning":"the blind","rule":"27:81"},{"arabic":"تَعْمَى","transliteration":"","meaning":"(are) blinded","rule":"22:46"},{"arabic":"عُمْيًۭا","transliteration":"","meaning":"blind","rule":"17:97"},{"arabic":"فَعَمِيَتْ","transliteration":"","meaning":"But (will) be obscure","rule":"28:66"},{"arabic":"وَأَعْمَىٰٓ","transliteration":"","meaning":"and blinded","rule":"47:23"},{"arabic":"فَعَمُوا۟","transliteration":"","meaning":"so they became blind","rule":"5:71"}],"rules":[{"name":"Words on عمي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعُمْىِ","تَعْمَى","عُمْيًۭا","فَعَمِيَتْ","وَأَعْمَىٰٓ","فَعَمُوا۟","عَمًى","عَمُوا۟"]},{"name":"Parts of speech attested for عمي","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 20 glossed words attested.","examples":["ٱلْعُمْىِ","تَعْمَى","عُمْيًۭا","فَعَمِيَتْ","وَأَعْمَىٰٓ","فَعَمُوا۟"]},{"name":"Verb forms attested for عمي","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["ٱلْعُمْىِ","تَعْمَى","عُمْيًۭا","فَعَمِيَتْ","وَأَعْمَىٰٓ","فَعَمُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عمي?","options":["كَشَجَرَةٍ","لِّلْمُؤْمِنَـٰتِ","ٱلْعُمْىِ","يَسْتَـْٔخِرُونَ"],"correct":2,"explanation":"ٱلْعُمْىِ — glossed \"the blind\" at 27:81 — carries the root عمي. The others come from different roots."},{"type":"multiple_choice","question":"What does تَعْمَى mean?","options":["you believe","we believe","(are) blinded","Offsprings"],"correct":2,"explanation":"\"(are) blinded\", from the word-by-word gloss at 22:46."},{"type":"fill_blank","question":"Type the root of عُمْيًۭا in Arabic (three letters).","correct":"عمي","explanation":"عمي. Diacritics are ignored when checking, so ع م ي is enough."}]', '["root-$ms"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Er$', 'The root عرش (ع ر ش)', 'grammar', 4, '{"explanation":"The root عرش occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, ADJ, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعَرْشِ","transliteration":"","meaning":"the Throne","rule":"7:54"},{"arabic":"يَعْرِشُونَ","transliteration":"","meaning":"erect","rule":"7:137"},{"arabic":"عَرْشٌ","transliteration":"","meaning":"(is) a throne","rule":"27:23"},{"arabic":"عَرْشُكِ","transliteration":"","meaning":"your throne","rule":"27:42"},{"arabic":"مَّعْرُوشَـٰتٍۢ","transliteration":"","meaning":"trellised","rule":"6:141"},{"arabic":"عَرْشَ","transliteration":"","meaning":"(the) Throne","rule":"69:17"}],"rules":[{"name":"Words on عرش","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعَرْشِ","يَعْرِشُونَ","عَرْشٌ","عَرْشُكِ","مَّعْرُوشَـٰتٍۢ","عَرْشَ","مَعْرُوشَـٰتٍۢ","بِعَرْشِهَا"]},{"name":"Parts of speech attested for عرش","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 12 glossed words attested.","examples":["ٱلْعَرْشِ","يَعْرِشُونَ","عَرْشٌ","عَرْشُكِ","مَّعْرُوشَـٰتٍۢ","عَرْشَ"]},{"name":"Where عرش occurs","description":"The 12 glossed words on this root are attested across 7 distinct surahs.","examples":["ٱلْعَرْشِ (7:54)","يَعْرِشُونَ (7:137)","عَرْشٌ (27:23)","عَرْشُكِ (27:42)","مَّعْرُوشَـٰتٍۢ (6:141)","عَرْشَ (69:17)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عرش?","options":["أُكُلُهُۥ","ٱللَّهُ","ٱلْعَرْشِ","فَأَذَاقَهُمُ"],"correct":2,"explanation":"ٱلْعَرْشِ — glossed \"the Throne\" at 7:54 — carries the root عرش. The others come from different roots."},{"type":"multiple_choice","question":"What does يَعْرِشُونَ mean?","options":["erect","Allah (had) willed","nothing","We willed"],"correct":0,"explanation":"\"erect\", from the word-by-word gloss at 7:137."},{"type":"fill_blank","question":"Type the root of عَرْشٌ in Arabic (three letters).","correct":"عرش","explanation":"عرش. Diacritics are ignored when checking, so ع ر ش is enough."}]', '["root-Emy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Hjj', 'The root حجج (ح ج ج)', 'grammar', 4, '{"explanation":"The root حجج occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as V, N, in verb forms III, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"حَآجَّ","transliteration":"","meaning":"argued","rule":"2:258"},{"arabic":"يَتَحَآجُّونَ","transliteration":"","meaning":"they will dispute","rule":"40:47"},{"arabic":"حَـٰجَجْتُمْ","transliteration":"","meaning":"argued","rule":"3:66"},{"arabic":"بِٱلْحَجِّ","transliteration":"","meaning":"[of] the Pilgrimage","rule":"22:27"},{"arabic":"حُجَّةٌۢ","transliteration":"","meaning":"any argument","rule":"4:165"},{"arabic":"حُجَّتُنَآ","transliteration":"","meaning":"(is) Our argument","rule":"6:83"}],"rules":[{"name":"Words on حجج","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["حَآجَّ","يَتَحَآجُّونَ","حَـٰجَجْتُمْ","بِٱلْحَجِّ","حُجَّةٌۢ","حُجَّتُنَآ","حُجَّتَهُمْ","أَتُحَآجُّونَنَا"]},{"name":"Parts of speech attested for حجج","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 28 glossed words attested.","examples":["حَآجَّ","يَتَحَآجُّونَ","حَـٰجَجْتُمْ","بِٱلْحَجِّ","حُجَّةٌۢ","حُجَّتُنَآ"]},{"name":"Verb forms attested for حجج","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VI.","examples":["حَآجَّ","يَتَحَآجُّونَ","حَـٰجَجْتُمْ","بِٱلْحَجِّ","حُجَّةٌۢ","حُجَّتُنَآ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حجج?","options":["بِشَىْءٍۢ","يَشْهَدُونَ","أَجْرًۭا","حَآجَّ"],"correct":3,"explanation":"حَآجَّ — glossed \"argued\" at 2:258 — carries the root حجج. The others come from different roots."},{"type":"multiple_choice","question":"What does يَتَحَآجُّونَ mean?","options":["And take","(is) with Allah","will stare","they will dispute"],"correct":3,"explanation":"\"they will dispute\", from the word-by-word gloss at 40:47."},{"type":"fill_blank","question":"Type the root of حَـٰجَجْتُمْ in Arabic (three letters).","correct":"حجج","explanation":"حجج. Diacritics are ignored when checking, so ح ج ج is enough."}]', '["root-Er$"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Zll', 'The root ظلل (ظ ل ل)', 'grammar', 4, '{"explanation":"The root ظلل occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ظَلْتَ","transliteration":"","meaning":"you have remained","rule":"20:97"},{"arabic":"ٱلظِّلَّ","transliteration":"","meaning":"the shadow","rule":"25:45"},{"arabic":"فَنَظَلُّ","transliteration":"","meaning":"so we will remain","rule":"26:71"},{"arabic":"وَظِلٍّۢ","transliteration":"","meaning":"And shade","rule":"56:30"},{"arabic":"ظِلٍّۢ","transliteration":"","meaning":"a shadow","rule":"77:30"},{"arabic":"ظِلَـٰلٍ","transliteration":"","meaning":"shades","rule":"36:56"}],"rules":[{"name":"Words on ظلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ظَلْتَ","ٱلظِّلَّ","فَنَظَلُّ","وَظِلٍّۢ","ظِلٍّۢ","ظِلَـٰلٍ","ظُلَّةٌۭ","ظُلَلٌۭ"]},{"name":"Parts of speech attested for ظلل","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 29 glossed words attested.","examples":["ظَلْتَ","ٱلظِّلَّ","فَنَظَلُّ","وَظِلٍّۢ","ظِلٍّۢ","ظِلَـٰلٍ"]},{"name":"Verb forms attested for ظلل","description":"Where this root is tagged as a verb, the corpus attests derived Form II.","examples":["ظَلْتَ","ٱلظِّلَّ","فَنَظَلُّ","وَظِلٍّۢ","ظِلٍّۢ","ظِلَـٰلٍ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ظلل?","options":["ٱتَّخِذُونِى","ظَلْتَ","شَهِيدًۢا","ٱللَّهُ"],"correct":1,"explanation":"ظَلْتَ — glossed \"you have remained\" at 20:97 — carries the root ظلل. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلظِّلَّ mean?","options":["the shadow","believe","And taste","So remember"],"correct":0,"explanation":"\"the shadow\", from the word-by-word gloss at 25:45."},{"type":"fill_blank","question":"Type the root of فَنَظَلُّ in Arabic (three letters).","correct":"ظلل","explanation":"ظلل. Diacritics are ignored when checking, so ظ ل ل is enough."}]', '["root-Hjj"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jnb', 'The root جنب (ج ن ب)', 'grammar', 4, '{"explanation":"The root جنب occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as N, V, ADJ, LOC, in verb forms VIII, V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"جُنُبًا","transliteration":"","meaning":"(when you are) impure","rule":"4:43"},{"arabic":"جَانِبٍۢ","transliteration":"","meaning":"side","rule":"37:8"},{"arabic":"جُنُوبِهِمْ","transliteration":"","meaning":"their sides","rule":"3:191"},{"arabic":"جُنُوبُهُمْ","transliteration":"","meaning":"their sides","rule":"32:16"},{"arabic":"جُنُوبِكُمْ","transliteration":"","meaning":"your sides","rule":"4:103"},{"arabic":"ٱجْتَنَبُوا۟","transliteration":"","meaning":"avoid","rule":"39:17"}],"rules":[{"name":"Words on جنب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["جُنُبًا","جَانِبٍۢ","جُنُوبِهِمْ","جُنُوبُهُمْ","جُنُوبِكُمْ","ٱجْتَنَبُوا۟","وَيَتَجَنَّبُهَا","بِٱلْجَنۢبِ"]},{"name":"Parts of speech attested for جنب","description":"The morphology corpus tags words on this root as N, V, ADJ, LOC — 4 distinct parts of speech across the 27 glossed words attested.","examples":["جُنُبًا","جَانِبٍۢ","جُنُوبِهِمْ","جُنُوبُهُمْ","جُنُوبِكُمْ","ٱجْتَنَبُوا۟"]},{"name":"Verb forms attested for جنب","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, V, II.","examples":["جُنُبًا","جَانِبٍۢ","جُنُوبِهِمْ","جُنُوبُهُمْ","جُنُوبِكُمْ","ٱجْتَنَبُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جنب?","options":["أَمِينٌ","جُنُبًا","أَمْرِهِۦ","ٱلذِّئْبُ"],"correct":1,"explanation":"جُنُبًا — glossed \"(when you are) impure\" at 4:43 — carries the root جنب. The others come from different roots."},{"type":"multiple_choice","question":"What does جَانِبٍۢ mean?","options":["they (did) not perceive","side","for the Hereafter","(is) a sin"],"correct":1,"explanation":"\"side\", from the word-by-word gloss at 37:8."},{"type":"fill_blank","question":"Type the root of جُنُوبِهِمْ in Arabic (three letters).","correct":"جنب","explanation":"جنب. Diacritics are ignored when checking, so ج ن ب is enough."}]', '["root-Zll"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kfy', 'The root كفي (ك ف ي)', 'grammar', 4, '{"explanation":"The root كفي occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَفَىٰ","transliteration":"","meaning":"Sufficient","rule":"13:43"},{"arabic":"وَكَفَىٰ","transliteration":"","meaning":"And is sufficient","rule":"4:6"},{"arabic":"يَكْفِهِمْ","transliteration":"","meaning":"sufficient for them","rule":"29:51"},{"arabic":"فَكَفَىٰ","transliteration":"","meaning":"So sufficient","rule":"10:29"},{"arabic":"وَكَفَى","transliteration":"","meaning":"And sufficient is","rule":"33:25"},{"arabic":"يَكْفِ","transliteration":"","meaning":"sufficient","rule":"41:53"}],"rules":[{"name":"Words on كفي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَفَىٰ","وَكَفَىٰ","يَكْفِهِمْ","فَكَفَىٰ","وَكَفَى","يَكْفِ","بِكَافٍ","كَفَيْنَـٰكَ"]},{"name":"Parts of speech attested for كفي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 10 glossed words attested.","examples":["كَفَىٰ","وَكَفَىٰ","يَكْفِهِمْ","فَكَفَىٰ","وَكَفَى","يَكْفِ"]},{"name":"Where كفي occurs","description":"The 10 glossed words on this root are attested across 10 distinct surahs.","examples":["كَفَىٰ (13:43)","وَكَفَىٰ (4:6)","يَكْفِهِمْ (29:51)","فَكَفَىٰ (10:29)","وَكَفَى (33:25)","يَكْفِ (41:53)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كفي?","options":["كَفَىٰ","لِأَحَدِهِمَا","ٱللَّهُ","شَرِيكٌۭ"],"correct":0,"explanation":"كَفَىٰ — glossed \"Sufficient\" at 13:43 — carries the root كفي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَكَفَىٰ mean?","options":["And is sufficient","I grieve","Thankful","withhold you"],"correct":0,"explanation":"\"And is sufficient\", from the word-by-word gloss at 4:6."},{"type":"fill_blank","question":"Type the root of يَكْفِهِمْ in Arabic (three letters).","correct":"كفي","explanation":"كفي. Diacritics are ignored when checking, so ك ف ي is enough."}]', '["root-jnb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qsm', 'The root قسم (ق س م)', 'grammar', 4, '{"explanation":"The root قسم occurs 33 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, V, in verb forms X, IV, III, VIII, VI, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَقَاسَمَهُمَآ","transliteration":"","meaning":"And he swore (to) both of them","rule":"7:21"},{"arabic":"تَقَاسَمُوا۟","transliteration":"","meaning":"Swear to each other","rule":"27:49"},{"arabic":"قِسْمَةٌۭ","transliteration":"","meaning":"(is) a division","rule":"53:22"},{"arabic":"ٱلْمُقْتَسِمِينَ","transliteration":"","meaning":"those who divided","rule":"15:90"},{"arabic":"أَقْسَمْتُمْ","transliteration":"","meaning":"you had sworn","rule":"7:49"},{"arabic":"۞ وَأَقْسَمُوا۟","transliteration":"","meaning":"And they swear","rule":"24:53"}],"rules":[{"name":"Words on قسم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَقَاسَمَهُمَآ","تَقَاسَمُوا۟","قِسْمَةٌۭ","ٱلْمُقْتَسِمِينَ","أَقْسَمْتُمْ","۞ وَأَقْسَمُوا۟","ٱلْقِسْمَةَ","أُقْسِمُ"]},{"name":"Parts of speech attested for قسم","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 22 glossed words attested.","examples":["وَقَاسَمَهُمَآ","تَقَاسَمُوا۟","قِسْمَةٌۭ","ٱلْمُقْتَسِمِينَ","أَقْسَمْتُمْ","۞ وَأَقْسَمُوا۟"]},{"name":"Verb forms attested for قسم","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, IV, III, VIII, VI, II.","examples":["وَقَاسَمَهُمَآ","تَقَاسَمُوا۟","قِسْمَةٌۭ","ٱلْمُقْتَسِمِينَ","أَقْسَمْتُمْ","۞ وَأَقْسَمُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قسم?","options":["ٱللَّهُ","بِٱلْإِثْمِ","أَحَدٍۢ","وَقَاسَمَهُمَآ"],"correct":3,"explanation":"وَقَاسَمَهُمَآ — glossed \"And he swore (to) both of them\" at 7:21 — carries the root قسم. The others come from different roots."},{"type":"multiple_choice","question":"What does تَقَاسَمُوا۟ mean?","options":["Swear to each other","eleven","their fathers","and Allah will see"],"correct":0,"explanation":"\"Swear to each other\", from the word-by-word gloss at 27:49."},{"type":"fill_blank","question":"Type the root of قِسْمَةٌۭ in Arabic (three letters).","correct":"قسم","explanation":"قسم. Diacritics are ignored when checking, so ق س م is enough."}]', '["root-kfy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-ESy', 'The root عصي (ع ص ي)', 'grammar', 4, '{"explanation":"The root عصي occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as V, ADJ, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَصَوْنِى","transliteration":"","meaning":"disobeyed me","rule":"71:21"},{"arabic":"وَعَصَوُا۟","transliteration":"","meaning":"and disobeyed","rule":"4:42"},{"arabic":"عَصَوا۟","transliteration":"","meaning":"they disobeyed","rule":"2:61"},{"arabic":"وَٱلْعِصْيَانَ","transliteration":"","meaning":"and disobedience","rule":"49:7"},{"arabic":"وَمَعْصِيَتِ","transliteration":"","meaning":"and disobedience","rule":"58:8"},{"arabic":"فَعَصَىٰ","transliteration":"","meaning":"But disobeyed","rule":"73:16"}],"rules":[{"name":"Words on عصي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَصَوْنِى","وَعَصَوُا۟","عَصَوا۟","وَٱلْعِصْيَانَ","وَمَعْصِيَتِ","فَعَصَىٰ","عَصِيًّۭا","يَعْصِينَكَ"]},{"name":"Parts of speech attested for عصي","description":"The morphology corpus tags words on this root as V, ADJ, N — 3 distinct parts of speech across the 23 glossed words attested.","examples":["عَصَوْنِى","وَعَصَوُا۟","عَصَوا۟","وَٱلْعِصْيَانَ","وَمَعْصِيَتِ","فَعَصَىٰ"]},{"name":"Where عصي occurs","description":"The 23 glossed words on this root are attested across 19 distinct surahs.","examples":["عَصَوْنِى (71:21)","وَعَصَوُا۟ (4:42)","عَصَوا۟ (2:61)","وَٱلْعِصْيَانَ (49:7)","وَمَعْصِيَتِ (58:8)","فَعَصَىٰ (73:16)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عصي?","options":["فَأْتُوهُنَّ","عَصَوْنِى","إِم