INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-brk', 'The root برك (ب ر ك)', 'grammar', 4, '{"explanation":"The root برك occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms III, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَبَـٰرَكَ","transliteration":"","meaning":"and He blessed","rule":"41:10"},{"arabic":"بُورِكَ","transliteration":"","meaning":"Blessed is","rule":"27:8"},{"arabic":"مُّبَارَكًۭا","transliteration":"","meaning":"blessed","rule":"23:29"},{"arabic":"بَرَكَـٰتٍۢ","transliteration":"","meaning":"blessings","rule":"7:96"},{"arabic":"مُبَـٰرَكٌۭ","transliteration":"","meaning":"blessed","rule":"38:29"},{"arabic":"مُّبَارَكٌ","transliteration":"","meaning":"blessed","rule":"21:50"}],"rules":[{"name":"Words on برك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَبَـٰرَكَ","بُورِكَ","مُّبَارَكًۭا","بَرَكَـٰتٍۢ","مُبَـٰرَكٌۭ","مُّبَارَكٌ","بَـٰرَكْنَا","فَتَبَارَكَ"]},{"name":"Parts of speech attested for برك","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 22 glossed words attested.","examples":["وَبَـٰرَكَ","بُورِكَ","مُّبَارَكًۭا","بَرَكَـٰتٍۢ","مُبَـٰرَكٌۭ","مُّبَارَكٌ"]},{"name":"Verb forms attested for برك","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VI.","examples":["وَبَـٰرَكَ","بُورِكَ","مُّبَارَكًۭا","بَرَكَـٰتٍۢ","مُبَـٰرَكٌۭ","مُّبَارَكٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root برك?","options":["ٱلذُّلِّ","وَبَـٰرَكَ","لِّلشَّوَىٰ","فَلِلَّهِ"],"correct":1,"explanation":"وَبَـٰرَكَ — glossed \"and He blessed\" at 41:10 — carries the root برك. The others come from different roots."},{"type":"multiple_choice","question":"What does بُورِكَ mean?","options":["So take them","schism","Blessed is","Allah has let go astray"],"correct":2,"explanation":"\"Blessed is\", from the word-by-word gloss at 27:8."},{"type":"fill_blank","question":"Type the root of مُّبَارَكًۭا in Arabic (three letters).","correct":"برك","explanation":"برك. Diacritics are ignored when checking, so ب ر ك is enough."}]', '["root-ESy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-brr', 'The root برر (ب ر ر)', 'grammar', 4, '{"explanation":"The root برر occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as N, V, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْبِرِّ","transliteration":"","meaning":"[the] righteousness","rule":"5:2"},{"arabic":"بِٱلْبِرِّ","transliteration":"","meaning":"[the] righteousness","rule":"2:44"},{"arabic":"ٱلْبِرُّ","transliteration":"","meaning":"[the] righteousness","rule":"2:189"},{"arabic":"ٱلْأَبْرَارِ","transliteration":"","meaning":"the righteous","rule":"3:193"},{"arabic":"ٱلْبَرِّ","transliteration":"","meaning":"(of) the land","rule":"5:96"},{"arabic":"ٱلْأَبْرَارَ","transliteration":"","meaning":"the righteous","rule":"76:5"}],"rules":[{"name":"Words on برر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْبِرِّ","بِٱلْبِرِّ","ٱلْبِرُّ","ٱلْأَبْرَارِ","ٱلْبَرِّ","ٱلْأَبْرَارَ","تَبَرُّوهُمْ","ٱلْبِرَّ"]},{"name":"Parts of speech attested for برر","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 13 glossed words attested.","examples":["ٱلْبِرِّ","بِٱلْبِرِّ","ٱلْبِرُّ","ٱلْأَبْرَارِ","ٱلْبَرِّ","ٱلْأَبْرَارَ"]},{"name":"Where برر occurs","description":"The 13 glossed words on this root are attested across 8 distinct surahs.","examples":["ٱلْبِرِّ (5:2)","بِٱلْبِرِّ (2:44)","ٱلْبِرُّ (2:189)","ٱلْأَبْرَارِ (3:193)","ٱلْبَرِّ (5:96)","ٱلْأَبْرَارَ (76:5)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root برر?","options":["ٱلْبِرِّ","وَكُلُوا۟","يَشْكُ