INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nSb', 'The root نصب (ن ص ب)', 'grammar', 4, '{"explanation":"The root نصب occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N, ADJ, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَصِيبُهُم","transliteration":"","meaning":"their portion","rule":"7:37"},{"arabic":"نَصِيبًۭا","transliteration":"","meaning":"a portion","rule":"3:23"},{"arabic":"نَّصِيبٍ","transliteration":"","meaning":"share","rule":"42:20"},{"arabic":"وَٱلْأَنصَابُ","transliteration":"","meaning":"and (sacrifices at) altars","rule":"5:90"},{"arabic":"نَّاصِبَةٌۭ","transliteration":"","meaning":"exhausted","rule":"88:3"},{"arabic":"نَصِيبَهُمْ","transliteration":"","meaning":"their share","rule":"4:33"}],"rules":[{"name":"Words on نصب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَصِيبُهُم","نَصِيبًۭا","نَّصِيبٍ","وَٱلْأَنصَابُ","نَّاصِبَةٌۭ","نَصِيبَهُمْ","ٱلنُّصُبِ","نَصَبٌۭ"]},{"name":"Parts of speech attested for نصب","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 15 glossed words attested.","examples":["نَصِيبُهُم","نَصِيبًۭا","نَّصِيبٍ","وَٱلْأَنصَابُ","نَّاصِبَةٌۭ","نَصِيبَهُمْ"]},{"name":"Where نصب occurs","description":"The 15 glossed words on this root are attested across 13 distinct surahs.","examples":["نَصِيبُهُم (7:37)","نَصِيبًۭا (3:23)","نَّصِيبٍ (42:20)","وَٱلْأَنصَابُ (5:90)","نَّاصِبَةٌۭ (88:3)","نَصِيبَهُمْ (4:33)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نصب?","options":["أَجْرَهُم","نَصِيبُهُم","أَخَذَتْهُ","ء