INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-vlv', 'The root ثلث (ث ل ث)', 'grammar', 4, '{"explanation":"The root ثلث occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ثَلَـٰثَةَ","transliteration":"","meaning":"(for) three","rule":"2:228"},{"arabic":"ثَلَـٰثٍۢ","transliteration":"","meaning":"three","rule":"39:6"},{"arabic":"ٱلثَّالِثَةَ","transliteration":"","meaning":"the third","rule":"53:20"},{"arabic":"بِثَلَـٰثَةِ","transliteration":"","meaning":"with three","rule":"3:124"},{"arabic":"ثَلَـٰثُونَ","transliteration":"","meaning":"(is) thirty","rule":"46:15"},{"arabic":"ثَلَـٰثَةًۭ","transliteration":"","meaning":"three","rule":"56:7"}],"rules":[{"name":"Words on ثلث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ثَلَـٰثَةَ","ثَلَـٰثٍۢ","ٱلثَّالِثَةَ","بِثَلَـٰثَةِ","ثَلَـٰثُونَ","ثَلَـٰثَةًۭ","وَثُلَـٰثَ","بِثَالِثٍۢ"]},{"name":"Parts of speech attested for ثلث","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 26 glossed words attested.","examples":["ثَلَـٰثَةَ","ثَلَـٰثٍۢ","ٱلثَّالِثَةَ","بِثَلَـٰثَةِ","ثَلَـٰثُونَ","ثَلَـٰثَةًۭ"]},{"name":"Where ثلث occurs","description":"The 26 glossed words on this root are attested across 17 distinct surahs.","examples":["ثَلَـٰثَةَ (2:228)","ثَلَـٰثٍۢ (39:6)","ٱلثَّالِثَةَ (53:20)","بِثَلَـٰثَةِ (3:124)","ثَلَـٰثُونَ (46:15)","ثَلَـٰثَةًۭ (56:7)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ثلث?","options":["ٱللَّهُ","بِذِكْرِ","ثَلَـٰثَةَ","أَهْلُ"],"corre