INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wSy', 'The root وصي (و ص ي)', 'grammar', 4, '{"explanation":"The root وصي occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as V, N, in verb forms II, IV, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُوصِيكُمُ","transliteration":"","meaning":"Instructs you","rule":"4:11"},{"arabic":"وَصِيَّةٍۢ","transliteration":"","meaning":"any will","rule":"4:11"},{"arabic":"أَتَوَاصَوْا۟","transliteration":"","meaning":"Have they transmitted it to them","rule":"51:53"},{"arabic":"وَصَّىٰكُمُ","transliteration":"","meaning":"enjoined you","rule":"6:144"},{"arabic":"وَصَّيْنَا","transliteration":"","meaning":"We have instructed","rule":"4:131"},{"arabic":"يُوصَىٰ","transliteration":"","meaning":"was made","rule":"4:12"}],"rules":[{"name":"Words on وصي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُوصِيكُمُ","وَصِيَّةٍۢ","أَتَوَاصَوْا۟","وَصَّىٰكُمُ","وَصَّيْنَا","يُوصَىٰ","يُوصِى","وَصَّىٰكُم"]},{"name":"Parts of speech attested for وصي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 20 glossed words attested.","examples":["يُوصِيكُمُ","وَصِيَّةٍۢ","أَتَوَاصَوْا۟","وَصَّىٰكُمُ","وَصَّيْنَا","يُوصَىٰ"]},{"name":"Verb forms attested for وصي","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, IV, VI.","examples":["يُوصِيكُمُ","وَصِيَّةٍۢ","أَتَوَاصَوْا۟","وَصَّىٰكُمُ","وَصَّيْنَا","يُوصَىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وصي?","options":["يُوصِيكُمُ","أُشْرِكْ","وَيَذْهَبَا","أَلِيمٌۭ"],"correct":0,"explanation":"يُوصِيكُمُ — glossed \"Instructs you\" at 4:11 — carries the root وصي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَصِيَّةٍۢ mean?","options":["To Allah (belongs)","any will","surely they (would have) eaten","eats him"],"correct":1,"explanation":"\"any will\", from the word-by-word gloss at 4:11."},{"type":"fill_blank","question":"Type the root of أَتَوَاصَوْا۟ in Arabic (three letters).","correct":"وصي","explanation":"وصي. Diacritics are ignored when checking, so و ص ي is enough."}]', '["root-vlv"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wry', 'The root وري (و ر ي)', 'grammar', 4, '{"explanation":"The root وري occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as LOC, N, V, in verb forms III, VI, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وُۥرِىَ","transliteration":"","meaning":"was concealed","rule":"7:20"},{"arabic":"وَرَآءَكُمْ","transliteration":"","meaning":"behind your","rule":"11:92"},{"arabic":"وَرَآئِ","transliteration":"","meaning":"behind","rule":"42:51"},{"arabic":"وَرَآءِ","transliteration":"","meaning":"and after","rule":"11:71"},{"arabic":"وَرَآئِكُمْ","transliteration":"","meaning":"behind you","rule":"4:102"},{"arabic":"وَرَآءَهُم","transliteration":"","meaning":"after them","rule":"18:79"}],"rules":[{"name":"Words on وري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وُۥرِىَ","وَرَآءَكُمْ","وَرَآئِ","وَرَآءِ","وَرَآئِكُمْ","وَرَآءَهُم","وَرَآءِى","يَتَوَٰرَىٰ"]},{"name":"Parts of speech attested for وري","description":"The morphology corpus tags words on this root as LOC, N, V — 3 distinct parts of speech across the 19 glossed words attested.","examples":["وُۥرِىَ","وَرَآءَكُمْ","وَرَآئِ","وَرَآءِ","وَرَآئِكُمْ","وَرَآءَهُم"]},{"name":"Verb forms attested for وري","description":"Where this root is tagged as a verb, the corpus attests derived Forms III, VI, IV.","examples":["وُۥرِىَ","وَرَآءَكُمْ","وَرَآئِ","وَرَآءِ","وَرَآئِكُمْ","وَرَآءَهُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وري?","options":["وَءَاتَى","لِتَأْفِكَنَا","وَٱدَّكَرَ","وُۥرِىَ"],"correct":3,"explanation":"وُۥرِىَ — glossed \"was concealed\" at 7:20 — carries the root وري. The others come from different roots."},{"type":"multiple_choice","question":"What does وَرَآءَكُمْ mean?","options":["associating partners","Our Signs","behind your","bring (upon) us"],"correct":2,"explanation":"\"behind your\", from the word-by-word gloss at 11:92."},{"type":"fill_blank","question":"Type the root of وَرَآئِ in Arabic (three letters).","correct":"وري","explanation":"وري. Diacritics are ignored when checking, so و ر ي is enough."}]', '["root-wSy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wsE', 'The root وسع (و س ع)', 'grammar', 4, '{"explanation":"The root وسع occurs 32 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٰسِعُ","transliteration":"","meaning":"(is) vast","rule":"53:32"},{"arabic":"وَٰسِعٌ","transliteration":"","meaning":"(is) All-Encompassing","rule":"2:115"},{"arabic":"وَٰسِعَةًۭ","transliteration":"","meaning":"spacious (enough)","rule":"4:97"},{"arabic":"وَسِعَ","transliteration":"","meaning":"Extends","rule":"2:255"},{"arabic":"وَسِعْتَ","transliteration":"","meaning":"You encompass","rule":"40:7"},{"arabic":"وَٰسِعَةٌ","transliteration":"","meaning":"(is) spacious","rule":"39:10"}],"rules":[{"name":"Words on وسع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٰسِعُ","وَٰسِعٌ","وَٰسِعَةًۭ","وَسِعَ","وَسِعْتَ","وَٰسِعَةٌ","لَمُوسِعُونَ","وَٱلسَّعَةِ"]},{"name":"Parts of speech attested for وسع","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 19 glossed words attested.","examples":["وَٰسِعُ","وَٰسِعٌ","وَٰسِعَةًۭ","وَسِعَ","وَسِعْتَ","وَٰسِعَةٌ"]},{"name":"Verb forms attested for وسع","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["وَٰسِعُ","وَٰسِعٌ","وَٰسِعَةًۭ","وَسِعَ","وَسِعْتَ","وَٰسِعَةٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وسع?","options":["أَشَدُّ","وَٰسِعُ","أَمْرًۭا","أَهْلِهَآ"],"correct":1,"explanation":"وَٰسِعُ — glossed \"(is) vast\" at 53:32 — carries the root وسع. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٰسِعٌ mean?","options":["And surely the Hereafter","will bring it (on) you","(is) All-Encompassing","(is) a sin"],"correct":2,"explanation":"\"(is) All-Encompassing\", from the word-by-word gloss at 2:115."},{"type":"fill_blank","question":"Type the root of وَٰسِعَةًۭ in Arabic (three letters).","correct":"وسع","explanation":"وسع. Diacritics are ignored when checking, so و س ع is enough."}]', '["root-wry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$fE', 'The root شفع (ش ف ع)', 'grammar', 4, '{"explanation":"The root شفع occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as N, V, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شُفَعَآءَ","transliteration":"","meaning":"intercessors","rule":"7:53"},{"arabic":"شَفَـٰعَةًۭ","transliteration":"","meaning":"an intercession","rule":"4:85"},{"arabic":"شَفَـٰعَةٌۭ","transliteration":"","meaning":"any intercession","rule":"2:48"},{"arabic":"يَشْفَعْ","transliteration":"","meaning":"intercedes","rule":"4:85"},{"arabic":"يَشْفَعُ","transliteration":"","meaning":"can intercede","rule":"2:255"},{"arabic":"شَفَـٰعَةُ","transliteration":"","meaning":"intercession","rule":"74:48"}],"rules":[{"name":"Words on شفع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شُفَعَآءَ","شَفَـٰعَةًۭ","شَفَـٰعَةٌۭ","يَشْفَعْ","يَشْفَعُ","شَفَـٰعَةُ","شُفَعَآءَكُمُ","ٱلشَّفَـٰعَةُ"]},{"name":"Parts of speech attested for شفع","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 21 glossed words attested.","examples":["شُفَعَآءَ","شَفَـٰعَةًۭ","شَفَـٰعَةٌۭ","يَشْفَعْ","يَشْفَعُ","شَفَـٰعَةُ"]},{"name":"Where شفع occurs","description":"The 21 glossed words on this root are attested across 14 distinct surahs.","examples":["شُفَعَآءَ (7:53)","شَفَـٰعَةًۭ (4:85)","شَفَـٰعَةٌۭ (2:48)","يَشْفَعْ (4:85)","يَشْفَعُ (2:255)","شَفَـٰعَةُ (74:48)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شفع?","options":["أُمِرْتُ","ٱلْـَٔايَـٰتِ","شُفَعَآءَ","ٱللَّهُ"],"correct":2,"explanation":"شُفَعَآءَ — glossed \"intercessors\" at 7:53 — carries the root شفع. The others come from different roots."},{"type":"multiple_choice","question":"What does شَفَـٰعَةًۭ mean?","options":["land","(is) painful","and mightier","an intercession"],"correct":3,"explanation":"\"an intercession\", from the word-by-word gloss at 4:85."},{"type":"fill_blank","question":"Type the root of شَفَـٰعَةٌۭ in Arabic (three letters).","correct":"شفع","explanation":"شفع. Diacritics are ignored when checking, so ش ف ع is enough."}]', '["root-wsE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$rr', 'The root شرر (ش ر ر)', 'grammar', 4, '{"explanation":"The root شرر occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَشَرَّ","transliteration":"","meaning":"surely (is) an evil","rule":"38:55"},{"arabic":"ٱلشَّرُّ","transliteration":"","meaning":"the evil","rule":"17:83"},{"arabic":"شَرًّۭا","transliteration":"","meaning":"bad","rule":"24:11"},{"arabic":"شَرُّهُۥ","transliteration":"","meaning":"its evil","rule":"76:7"},{"arabic":"شَرٌّۭ","transliteration":"","meaning":"(is) bad","rule":"2:216"},{"arabic":"بِشَرَرٍۢ","transliteration":"","meaning":"sparks","rule":"77:32"}],"rules":[{"name":"Words on شرر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَشَرَّ","ٱلشَّرُّ","شَرًّۭا","شَرُّهُۥ","شَرٌّۭ","بِشَرَرٍۢ","ٱلشَّرَّ","شَرِّ"]},{"name":"Parts of speech attested for شرر","description":"The morphology corpus tags words on this root as N — one part of speech across the 14 glossed words attested.","examples":["لَشَرَّ","ٱلشَّرُّ","شَرًّۭا","شَرُّهُۥ","شَرٌّۭ","بِشَرَرٍۢ"]},{"name":"Where شرر occurs","description":"The 14 glossed words on this root are attested across 12 distinct surahs.","examples":["لَشَرَّ (38:55)","ٱلشَّرُّ (17:83)","شَرًّۭا (24:11)","شَرُّهُۥ (76:7)","شَرٌّۭ (2:216)","بِشَرَرٍۢ (77:32)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شرر?","options":["مُشْفِقِينَ","شُبِّهَ","لَشَرَّ","ٱللَّهُ"],"correct":2,"explanation":"لَشَرَّ — glossed \"surely (is) an evil\" at 38:55 — carries the root شرر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلشَّرُّ mean?","options":["to barter","(of the) east","the evil","they would surely believe"],"correct":2,"explanation":"\"the evil\", from the word-by-word gloss at 17:83."},{"type":"fill_blank","question":"Type the root of شَرًّۭا in Arabic (three letters).","correct":"شرر","explanation":"شرر. Diacritics are ignored when checking, so ش ر ر is enough."}]', '["root-$fE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Thr', 'The root طهر (ط ه ر)', 'grammar', 4, '{"explanation":"The root طهر occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِّيُطَهِّرَكُم","transliteration":"","meaning":"so that He may purify you","rule":"8:11"},{"arabic":"ٱلْمُطَّهِّرِينَ","transliteration":"","meaning":"the ones who purify themselves","rule":"9:108"},{"arabic":"تَطَهَّرْنَ","transliteration":"","meaning":"they are purified","rule":"2:222"},{"arabic":"ٱلْمُطَهَّرُونَ","transliteration":"","meaning":"the purified","rule":"56:79"},{"arabic":"طَهِّرَا","transliteration":"","meaning":"[You both] purify","rule":"2:125"},{"arabic":"وَطَهَّرَكِ","transliteration":"","meaning":"and purified you","rule":"3:42"}],"rules":[{"name":"Words on طهر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِّيُطَهِّرَكُم","ٱلْمُطَّهِّرِينَ","تَطَهَّرْنَ","ٱلْمُطَهَّرُونَ","طَهِّرَا","وَطَهَّرَكِ","مُّطَهَّرَةًۭ","فَطَهِّرْ"]},{"name":"Parts of speech attested for طهر","description":"The morphology corpus tags words on this root as ADJ, V, N — 3 distinct parts of speech across the 26 glossed words attested.","examples":["لِّيُطَهِّرَكُم","ٱلْمُطَّهِّرِينَ","تَطَهَّرْنَ","ٱلْمُطَهَّرُونَ","طَهِّرَا","وَطَهَّرَكِ"]},{"name":"Verb forms attested for طهر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["لِّيُطَهِّرَكُم","ٱلْمُطَّهِّرِينَ","تَطَهَّرْنَ","ٱلْمُطَهَّرُونَ","طَهِّرَا","وَطَهَّرَكِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طهر?","options":["لِّلْمُؤْمِنِينَ","سَنَشُدُّ","ٱلْإِنسَـٰنَ","لِّيُطَهِّرَكُم"],"correct":3,"explanation":"لِّيُطَهِّرَكُم — glossed \"so that He may purify you\" at 8:11 — carries the root طهر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُطَّهِّرِينَ mean?","options":["the ones who purify themselves","(will be) coming","and your partners","he went"],"correct":0,"explanation":"\"the ones who purify themselves\", from the word-by-word gloss at 9:108."},{"type":"fill_blank","question":"Type the root of تَطَهَّرْنَ in Arabic (three letters).","correct":"طهر","explanation":"طهر. Diacritics are ignored when checking, so ط ه ر is enough."}]', '["root-$rr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bdw', 'The root بدو (ب د و)', 'grammar', 4, '{"explanation":"The root بدو occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُبْدُونَ","transliteration":"","meaning":"you reveal","rule":"2:33"},{"arabic":"بَدَا","transliteration":"","meaning":"became manifest","rule":"6:28"},{"arabic":"يُبْدُونَ","transliteration":"","meaning":"they reveal","rule":"3:154"},{"arabic":"تُبْدَ","transliteration":"","meaning":"made clear","rule":"5:101"},{"arabic":"فَبَدَتْ","transliteration":"","meaning":"so became apparent","rule":"20:121"},{"arabic":"يُبْدِهَا","transliteration":"","meaning":"reveal it","rule":"12:77"}],"rules":[{"name":"Words on بدو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُبْدُونَ","بَدَا","يُبْدُونَ","تُبْدَ","فَبَدَتْ","يُبْدِهَا","بَادِىَ","ٱلْبَدْوِ"]},{"name":"Parts of speech attested for بدو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 20 glossed words attested.","examples":["تُبْدُونَ","بَدَا","يُبْدُونَ","تُبْدَ","فَبَدَتْ","يُبْدِهَا"]},{"name":"Verb forms attested for بدو","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تُبْدُونَ","بَدَا","يُبْدُونَ","تُبْدَ","فَبَدَتْ","يُبْدِهَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بدو?","options":["فَأْتِيَاهُ","تُبْدُونَ","أُجُورَهُنَّ","يُؤْتُوٓا۟"],"correct":1,"explanation":"تُبْدُونَ — glossed \"you reveal\" at 2:33 — carries the root بدو. The others come from different roots."},{"type":"multiple_choice","question":"What does بَدَا mean?","options":["became manifest","any god","safe","He has ordained"],"correct":0,"explanation":"\"became manifest\", from the word-by-word gloss at 6:28."},{"type":"fill_blank","question":"Type the root of يُبْدُونَ in Arabic (three letters).","correct":"بدو","explanation":"بدو. Diacritics are ignored when checking, so ب د و is enough."}]', '["root-Thr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-brA', 'The root برا (ب ر ا)', 'grammar', 4, '{"explanation":"The root برا occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms V, IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَنَتَبَرَّأَ","transliteration":"","meaning":"then we will disown","rule":"2:167"},{"arabic":"ٱلْبَارِئُ","transliteration":"","meaning":"the Inventor","rule":"59:24"},{"arabic":"ٱلْبَرِيَّةِ","transliteration":"","meaning":"(of) the creatures","rule":"98:6"},{"arabic":"بَرِىٓءٌۭ","transliteration":"","meaning":"free","rule":"6:19"},{"arabic":"بَرِيٓـُٔونَ","transliteration":"","meaning":"(are) disassociated","rule":"10:41"},{"arabic":"وَتُبْرِئُ","transliteration":"","meaning":"and you heal","rule":"5:110"}],"rules":[{"name":"Words on برا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَنَتَبَرَّأَ","ٱلْبَارِئُ","ٱلْبَرِيَّةِ","بَرِىٓءٌۭ","بَرِيٓـُٔونَ","وَتُبْرِئُ","تَبَرَّءُوا۟","بُرَءَٰٓؤُا۟"]},{"name":"Parts of speech attested for برا","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 19 glossed words attested.","examples":["فَنَتَبَرَّأَ","ٱلْبَارِئُ","ٱلْبَرِيَّةِ","بَرِىٓءٌۭ","بَرِيٓـُٔونَ","وَتُبْرِئُ"]},{"name":"Verb forms attested for برا","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, IV, II.","examples":["فَنَتَبَرَّأَ","ٱلْبَارِئُ","ٱلْبَرِيَّةِ","بَرِىٓءٌۭ","بَرِيٓـُٔونَ","وَتُبْرِئُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root برا?","options":["ك