INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-glb', 'The root غلب (غ ل ب)', 'grammar', 4, '{"explanation":"The root غلب occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَتُغْلَبُونَ","transliteration":"","meaning":"You will be overcome","rule":"3:12"},{"arabic":"غَالِبٌ","transliteration":"","meaning":"(is) Predominant","rule":"12:21"},{"arabic":"غُلِبَتِ","transliteration":"","meaning":"Have been defeated","rule":"30:2"},{"arabic":"ٱلْغَـٰلِبُونَ","transliteration":"","meaning":"(are) the victorious","rule":"5:56"},{"arabic":"غُلْبًۭا","transliteration":"","meaning":"(of) thick foliage","rule":"80:30"},{"arabic":"غَالِبَ","transliteration":"","meaning":"(can) overcome","rule":"3:160"}],"rules":[{"name":"Words on غلب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَتُغْلَبُونَ","غَالِبٌ","غُلِبَتِ","ٱلْغَـٰلِبُونَ","غُلْبًۭا","غَالِبَ","فَغُلِبُوا۟","مَغْلُوبٌۭ"]},{"name":"Parts of speech attested for غلب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 20 glossed words attested.","examples":["سَتُغْلَبُونَ","غَالِبٌ","غُلِبَتِ","ٱلْغَـٰلِبُونَ","غُلْبًۭا","غَالِبَ"]},{"name":"Where غلب occurs","description":"The 20 glossed words on this root are attested across 13 distinct surahs.","examples":["سَتُغْلَبُونَ (3:12)","غَالِبٌ (12:21)","غُلِبَتِ (30:2)","ٱلْغَـٰلِبُونَ (5:56)","غُلْبًۭا (80:30)","غَالِبَ (3:160)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غلب?","options":["أُمَّةٍۢ","سَتُغْ