INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lbv', 'The root لبث (ل ب ث)', 'grammar', 4, '{"explanation":"The root لبث occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَلَبِثَ","transliteration":"","meaning":"Certainly, he (would have) remained","rule":"37:144"},{"arabic":"لَبِثْتَ","transliteration":"","meaning":"(have) you remained","rule":"2:259"},{"arabic":"يَلْبَثُونَ","transliteration":"","meaning":"they (would) have stayed","rule":"17:76"},{"arabic":"فَلَبِثْتَ","transliteration":"","meaning":"Then you remained","rule":"20:40"},{"arabic":"لَبِثَ","transliteration":"","meaning":"and not he delayed","rule":"11:69"},{"arabic":"وَلَبِثْتَ","transliteration":"","meaning":"and you remained","rule":"26:18"}],"rules":[{"name":"Words on لبث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَلَبِثَ","لَبِثْتَ","يَلْبَثُونَ","فَلَبِثْتَ","لَبِثَ","وَلَبِثْتَ","يَلْبَثُوٓا۟","لَبِثْنَا"]},{"name":"Parts of speech attested for لبث","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 18 glossed words attested.","examples":["لَلَبِثَ","لَبِثْتَ","يَلْبَثُونَ","فَلَبِثْتَ","لَبِثَ","وَلَبِثْتَ"]},{"name":"Where لبث occurs","description":"The 18 glossed words on this root are attested across 11 distinct surahs.","examples":["لَلَبِثَ (37:144)","لَبِثْتَ (2:259)","يَلْبَثُونَ (17:76)","فَلَبِثْتَ (20:40)","لَبِثَ (11:69)","وَلَبِثْتَ (26:18)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لبث?","options":["ءَأَشْفَقْتُ