INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xlS', 'The root خلص (خ ل ص)', 'grammar', 4, '{"explanation":"The root خلص occurs 31 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْمُخْلَصِينَ","transliteration":"","meaning":"the sincere","rule":"12:24"},{"arabic":"خَالِصًۭا","transliteration":"","meaning":"pure","rule":"16:66"},{"arabic":"مُخْلِصُونَ","transliteration":"","meaning":"(are) sincere","rule":"2:139"},{"arabic":"ٱلْخَالِصُ","transliteration":"","meaning":"the pure","rule":"39:3"},{"arabic":"وَأَخْلَصُوا۟","transliteration":"","meaning":"and are sincere","rule":"4:146"},{"arabic":"مُخْلَصًۭا","transliteration":"","meaning":"chosen","rule":"19:51"}],"rules":[{"name":"Words on خلص","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْمُخْلَصِينَ","خَالِصًۭا","مُخْلِصُونَ","ٱلْخَالِصُ","وَأَخْلَصُوا۟","مُخْلَصًۭا","خَالِصَةًۭ","أَسْتَخْلِصْهُ"]},{"name":"Parts of speech attested for خلص","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 14 glossed words attested.","examples":["ٱلْمُخْلَصِينَ","خَالِصًۭا","مُخْلِصُونَ","ٱلْخَالِصُ","وَأَخْلَصُوا۟","مُخْلَصًۭا"]},{"name":"Verb forms attested for خلص","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["ٱلْمُخْلَصِينَ","خَالِصًۭا","مُخْلِصُونَ","ٱلْخَالِصُ","وَأَخْلَصُوا۟","مُخْلَصًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلص?","options":["ٱلْمُخْلَصِينَ","وَتُؤْتُوهَا",