INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Afk', 'The root افك (ا ف ك)', 'grammar', 4, '{"explanation":"The root افك occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْمُؤْتَفِكَةَ","transliteration":"","meaning":"And the overturned cities","rule":"53:53"},{"arabic":"لِتَأْفِكَنَا","transliteration":"","meaning":"to turn us away","rule":"46:22"},{"arabic":"يُؤْفَكُ","transliteration":"","meaning":"were deluded","rule":"40:63"},{"arabic":"أَئِفْكًا","transliteration":"","meaning":"Is it falsehood","rule":"37:86"},{"arabic":"أُفِكَ","transliteration":"","meaning":"is deluded","rule":"51:9"},{"arabic":"إِفْكٌ","transliteration":"","meaning":"a lie","rule":"25:4"}],"rules":[{"name":"Words on افك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْمُؤْتَفِكَةَ","لِتَأْفِكَنَا","يُؤْفَكُ","أَئِفْكًا","أُفِكَ","إِفْكٌ","وَٱلْمُؤْتَفِكَـٰتُ","تُؤْفَكُونَ"]},{"name":"Parts of speech attested for افك","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 17 glossed words attested.","examples":["وَٱلْمُؤْتَفِكَةَ","لِتَأْفِكَنَا","يُؤْفَكُ","أَئِفْكًا","أُفِكَ","إِفْكٌ"]},{"name":"Verb forms attested for افك","description":"Where this root is tagged as a verb, the corpus attests derived Form VIII.","examples":["وَٱلْمُؤْتَفِكَةَ","لِتَأْفِكَنَا","يُؤْفَكُ","أَئِفْكًا","أُفِكَ","إِفْكٌ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root افك?","options":["تُشَـٰٓقُّونَ","بِٱلْأُذُنِ","وَٱلْمُؤْتَفِكَةَ","أَتَأْخُذُونَهُۥ"],"correct":2,"explanation":"وَٱلْمُؤْتَفِكَةَ — glossed \"And the overturned cities\" at 53:53 — carries the root افك. The others come from different roots."},{"type":"multiple_choice","question":"What does لِتَأْفِكَنَا mean?","options":["and others","(is) a hurt","to turn us away","our ears"],"correct":2,"explanation":"\"to turn us away\", from the word-by-word gloss at 46:22."},{"type":"fill_blank","question":"Type the root of يُؤْفَكُ in Arabic (three letters).","correct":"افك","explanation":"افك. Diacritics are ignored when checking, so ا ف ك is enough."}]', '["root-xlS"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Anv', 'The root انث (ا ن ث)', 'grammar', 4, '{"explanation":"The root انث occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أُنثَىٰ","transliteration":"","meaning":"a female","rule":"3:36"},{"arabic":"وَإِنَـٰثًۭا","transliteration":"","meaning":"and females","rule":"42:50"},{"arabic":"وَأُنثَىٰ","transliteration":"","meaning":"and a female","rule":"49:13"},{"arabic":"ٱلْأُنثَيَيْنِ","transliteration":"","meaning":"(of) two females","rule":"4:11"},{"arabic":"إِنَـٰثًا","transliteration":"","meaning":"daughters","rule":"17:40"},{"arabic":"إِنَـٰثًۭا","transliteration":"","meaning":"female (deities)","rule":"4:117"}],"rules":[{"name":"Words on انث","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أُنثَىٰ","وَإِنَـٰثًۭا","وَأُنثَىٰ","ٱلْأُنثَيَيْنِ","إِنَـٰثًا","إِنَـٰثًۭا","وَٱلْأُنثَىٰ","وَٱلْأُنثَىٰٓ"]},{"name":"Parts of speech attested for انث","description":"The morphology corpus tags words on this root as N — one part of speech across the 11 glossed words attested.","examples":["أُنثَىٰ","وَإِنَـٰثًۭا","وَأُنثَىٰ","ٱلْأُنثَيَيْنِ","إِنَـٰثًا","إِنَـٰثًۭا"]},{"name":"Where انث occurs","description":"The 11 glossed words on this root are attested across 8 distinct surahs.","examples":["أُنثَىٰ (3:36)","وَإِنَـٰثًۭا (42:50)","وَأُنثَىٰ (49:13)","ٱلْأُنثَيَيْنِ (4:11)","إِنَـٰثًا (17:40)","إِنَـٰثًۭا (4:117)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root انث?","options":["ٱللَّهُ","ٱلْـَٔاخِرِينَ","أُنثَىٰ","وَأُو۟لُوا۟"],"correct":2,"explanation":"أُنثَىٰ — glossed \"a female\" at 3:36 — carries the root انث. The others come from different roots."},{"type":"multiple_choice","question":"What does وَإِنَـٰثًۭا mean?","options":["Our Reminder","Do they then feel secure","and females","nothing"],"correct":2,"explanation":"\"and females\", from the word-by-word gloss at 42:50."},{"type":"fill_blank","question":"Type the root of وَأُنثَىٰ in Arabic (three letters).","correct":"انث","explanation":"انث. Diacritics are ignored when checking, so ا ن ث is enough."}]', '["root-Afk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Esy', 'The root عسي (ع س ي)', 'grammar', 4, '{"explanation":"The root عسي occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 9 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَعَسَى","transliteration":"","meaning":"But perhaps","rule":"5:52"},{"arabic":"فَعَسَىٰ","transliteration":"","meaning":"It may be","rule":"18:40"},{"arabic":"عَسَيْتُمْ","transliteration":"","meaning":"you perhaps","rule":"2:246"},{"arabic":"فَعَسَىٰٓ","transliteration":"","meaning":"then perhaps","rule":"4:19"},{"arabic":"عَسَىٰ","transliteration":"","meaning":"Perhaps","rule":"7:129"},{"arabic":"۞ عَسَى","transliteration":"","meaning":"Perhaps","rule":"60:7"}],"rules":[{"name":"Words on عسي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَعَسَى","فَعَسَىٰ","عَسَيْتُمْ","فَعَسَىٰٓ","عَسَىٰ","۞ عَسَى","وَعَسَىٰٓ","عَسَى"]},{"name":"Parts of speech attested for عسي","description":"The morphology corpus tags words on this root as V — one part of speech across the 9 glossed words attested.","examples":["فَعَسَى","فَعَسَىٰ","عَسَيْتُمْ","فَعَسَىٰٓ","عَسَىٰ","۞ عَسَى"]},{"name":"Where عسي occurs","description":"The 9 glossed words on this root are attested across 6 distinct surahs.","examples":["فَعَسَى (5:52)","فَعَسَىٰ (18:40)","عَسَيْتُمْ (2:246)","فَعَسَىٰٓ (4:19)","عَسَىٰ (7:129)","۞ عَسَى (60:7)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عسي?","options":["شَيْـًۭٔا","فَعَسَى","أَجْرُ","وَلْيُؤْمِنُوا۟"],"correct":1,"explanation":"فَعَسَى — glossed \"But perhaps\" at 5:52 — carries the root عسي. The others come from different roots."},{"type":"multiple_choice","question":"What does فَعَسَىٰ mean?","options":["We have brought them","It may be","(is) a sin","So, seized them"],"correct":1,"explanation":"\"It may be\", from the word-by-word gloss at 18:40."},{"type":"fill_blank","question":"Type the root of عَسَيْتُمْ in Arabic (three letters).","correct":"عسي","explanation":"عسي. Diacritics are ignored when checking, so ع س ي is enough."}]', '["root-Anv"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Srf', 'The root صرف (ص ر ف)', 'grammar', 4, '{"explanation":"The root صرف occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, V, in verb forms II, VII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"صَرَّفْنَـٰهُ","transliteration":"","meaning":"We have distributed it","rule":"25:50"},{"arabic":"ٱنصَرَفُوا۟","transliteration":"","meaning":"they turn away","rule":"9:127"},{"arabic":"صَرَفَ","transliteration":"","meaning":"Allah has turned away","rule":"9:127"},{"arabic":"فَصَرَفَ","transliteration":"","meaning":"and turned away","rule":"12:34"},{"arabic":"صَرْفًۭا","transliteration":"","meaning":"(to) avert","rule":"25:19"},{"arabic":"سَأَصْرِفُ","transliteration":"","meaning":"I will turn away","rule":"7:146"}],"rules":[{"name":"Words on صرف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["صَرَّفْنَـٰهُ","ٱنصَرَفُوا۟","صَرَفَ","فَصَرَفَ","صَرْفًۭا","سَأَصْرِفُ","وَتَصْرِيفِ","صَرَفَكُمْ"]},{"name":"Parts of speech attested for صرف","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 22 glossed words attested.","examples":["صَرَّفْنَـٰهُ","ٱنصَرَفُوا۟","صَرَفَ","فَصَرَفَ","صَرْفًۭا","سَأَصْرِفُ"]},{"name":"Verb forms attested for صرف","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VII.","examples":["صَرَّفْنَـٰهُ","ٱنصَرَفُوا۟","صَرَفَ","فَصَرَفَ","صَرْفًۭا","سَأَصْرِفُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صرف?","options":["ٱللَّهُ","صَرَّفْنَـٰهُ","شَهِيدَيْنِ","يَشْعُرُونَ"],"correct":1,"explanation":"صَرَّفْنَـٰهُ — glossed \"We have distributed it\" at 25:50 — carries the root صرف. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱنصَرَفُوا۟ mean?","options":["they turn away","you associate partners","and grieved","their footsteps"],"correct":0,"explanation":"\"they turn away\", from the word-by-word gloss at 9:127."},{"type":"fill_blank","question":"Type the root of صَرَفَ in Arabic (three letters).","correct":"صرف","explanation":"صرف. Diacritics are ignored when checking, so ص ر ف is enough."}]', '["root-Esy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qSS', 'The root قصص (ق ص ص)', 'grammar', 4, '{"explanation":"The root قصص occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَقْصُصْ","transliteration":"","meaning":"relate","rule":"12:5"},{"arabic":"فَٱقْصُصِ","transliteration":"","meaning":"So relate","rule":"7:176"},{"arabic":"ٱلْقَصَصَ","transliteration":"","meaning":"the story","rule":"7:176"},{"arabic":"فَلَنَقُصَّنَّ","transliteration":"","meaning":"Then surely We will narrate","rule":"7:7"},{"arabic":"وَقَصَّ","transliteration":"","meaning":"and narrated","rule":"28:25"},{"arabic":"قَصَصْنَا","transliteration":"","meaning":"We related","rule":"16:118"}],"rules":[{"name":"Words on قصص","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَقْصُصْ","فَٱقْصُصِ","ٱلْقَصَصَ","فَلَنَقُصَّنَّ","وَقَصَّ","قَصَصْنَا","نَّقُصُّ","نَقُصُّهُۥ"]},{"name":"Parts of speech attested for قصص","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 22 glossed words attested.","examples":["تَقْصُصْ","فَٱقْصُصِ","ٱلْقَصَصَ","فَلَنَقُصَّنَّ","وَقَصَّ","قَصَصْنَا"]},{"name":"Where قصص occurs","description":"The 22 glossed words on this root are attested across 11 distinct surahs.","examples":["تَقْصُصْ (12:5)","فَٱقْصُصِ (7:176)","ٱلْقَصَصَ (7:176)","فَلَنَقُصَّنَّ (7:7)","وَقَصَّ (28:25)","قَصَصْنَا (16:118)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قصص?","options":["ءَاخِذٌۢ","يُؤْمِنُونَ","أَخَذْتُمْ","تَقْصُصْ"],"correct":3,"explanation":"تَقْصُصْ — glossed \"relate\" at 12:5 — carries the root قصص. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱقْصُصِ mean?","options":["So relate","remember","splitting","and flared"],"correct":0,"explanation":"\"So relate\", from the word-by-word gloss at 7:176."},{"type":"fill_blank","question":"Type the root of ٱلْقَصَصَ in Arabic (three letters).","correct":"قصص","explanation":"قصص. Diacritics are ignored when checking, so ق ص ص is enough."}]', '["root-Srf"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sEy', 'The root سعي (س ع ي)', 'grammar', 4, '{"explanation":"The root سعي occurs 30 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَعْيُكُم","transliteration":"","meaning":"your effort","rule":"76:22"},{"arabic":"فَٱسْعَوْا۟","transliteration":"","meaning":"then hasten","rule":"62:9"},{"arabic":"سَعَوْ","transliteration":"","meaning":"strive","rule":"34:5"},{"arabic":"وَيَسْعَوْنَ","transliteration":"","meaning":"and strive","rule":"5:33"},{"arabic":"سَعْيَهَا","transliteration":"","meaning":"the effort","rule":"17:19"},{"arabic":"سَعْيُهُمْ","transliteration":"","meaning":"their effort","rule":"18:104"}],"rules":[{"name":"Words on سعي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَعْيُكُم","فَٱسْعَوْا۟","سَعَوْ","وَيَسْعَوْنَ","سَعْيَهَا","سَعْيُهُمْ","لِسَعْيِهِۦ","وَسَعَىٰ"]},{"name":"Parts of speech attested for سعي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 19 glossed words attested.","examples":["سَعْيُكُم","فَٱسْعَوْا۟","سَعَوْ","وَيَسْعَوْنَ","سَعْيَهَا","سَعْيُهُمْ"]},{"name":"Where سعي occurs","description":"The 19 glossed words on this root are attested across 15 distinct surahs.","examples":["سَعْيُكُم (76:22)","فَٱسْعَوْا۟ (62:9)","سَعَوْ (34:5)","وَيَسْعَوْنَ (5:33)","سَعْيَهَا (17:19)","سَعْيُهُمْ (18:104)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سعي?","options":["مَأْوَىٰهُمْ","يَأْتِ","سَعْيُكُم","ذُرِّيَّتِى"],"correct":2,"explanation":"سَعْيُكُم — glossed \"your effort\" at 76:22 — carries the root سعي. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱسْعَوْا۟ mean?","options":["is deluded","and He gave you","O men","then hasten"],"correct":3,"explanation":"\"then hasten\", from the word-by-word gloss at 62:9."},{"type":"fill_blank","question":"Type the root of سَعَوْ in Arabic (three letters).","correct":"سعي","explanation":"سعي. Diacritics are ignored when checking, so س ع ي is enough."}]', '["root-qSS"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Syr', 'The root صير (ص ي ر)', 'grammar', 4, '{"explanation":"The root صير occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 6 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَصِيرًۭا","transliteration":"","meaning":"(is the) destination","rule":"48:6"},{"arabic":"وَمَصِيرًۭا","transliteration":"","meaning":"and destination","rule":"25:15"},{"arabic":"مَصِيرَكُمْ","transliteration":"","meaning":"your destination","rule":"14:30"},{"arabic":"تَصِيرُ","transliteration":"","meaning":"reach","rule":"42:53"},{"arabic":"ٱلْمَصِيرُ","transliteration":"","meaning":"(is) the destination","rule":"2:126"},{"arabic":"مَصِيرًا","transliteration":"","meaning":"destination","rule":"4:97"}],"rules":[{"name":"Words on صير","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَصِيرًۭا","وَمَصِيرًۭا","مَصِيرَكُمْ","تَصِيرُ","ٱلْمَصِيرُ","مَصِيرًا"]},{"name":"Parts of speech attested for صير","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 6 glossed words attested.","examples":["مَصِيرًۭا","وَمَصِيرًۭا","مَصِيرَكُمْ","تَصِيرُ","ٱلْمَصِيرُ","مَصِيرًا"]},{"name":"Where صير occurs","description":"The 6 glossed words on this root are attested across 6 distinct surahs.","examples":["مَصِيرًۭا (48:6)","وَمَصِيرًۭا (25:15)","مَصِيرَكُمْ (14:30)","تَصِيرُ (42:53)","ٱلْمَصِيرُ (2:126)","مَصِيرًا (4:97)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صير?","options":["مَصِيرًۭا","أَكَلَهُ","لِتَأْخُذُوهَا","ءَالَآءِ"],"correct":0,"explanation":"مَصِيرًۭا — glossed \"(is the) destination\" at 48:6 — carries the root صير. The others come from different roots."},{"type":"multiple_choice","question":"What does وَمَصِيرًۭا mean?","options":["and destination","(are) worse","(from) behind you","a testimony"],"correct":0,"explanation":"\"and destination\", from the word-by-word gloss at 25:15."},{"type":"fill_blank","question":"Type the root of مَصِيرَكُمْ in Arabic (three letters).","correct":"صير","explanation":"صير. Diacritics are ignored when checking, so ص ي ر is enough."}]', '["root-sEy"]', 30, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Tyr', 'The root طير (ط ي ر)', 'grammar', 4, '{"explanation":"The root طير occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, in verb forms V, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلطَّيْرَ","transliteration":"","meaning":"the birds","rule":"27:20"},{"arabic":"يَطَّيَّرُوا۟","transliteration":"","meaning":"they ascribe evil omens","rule":"7:131"},{"arabic":"تَطَيَّرْنَا","transliteration":"","meaning":"[we] see an evil omen","rule":"36:18"},{"arabic":"وَٱلطَّيْرُ","transliteration":"","meaning":"and the birds","rule":"24:41"},{"arabic":"وَٱلطَّيْرَ","transliteration":"","meaning":"and the birds","rule":"21:79"},{"arabic":"وَٱلطَّيْرِ","transliteration":"","meaning":"and the birds","rule":"27:17"}],"rules":[{"name":"Words on طير","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلطَّيْرَ","يَطَّيَّرُوا۟","تَطَيَّرْنَا","وَٱلطَّيْرُ","وَٱلطَّيْرَ","وَٱلطَّيْرِ","ٱطَّيَّرْنَا","ٱلطَّيْرُ"]},{"name":"Parts of speech attested for طير","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 19 glossed words attested.","examples":["ٱلطَّيْرَ","يَطَّيَّرُوا۟","تَطَيَّرْنَا","وَٱلطَّيْرُ","وَٱلطَّيْرَ","وَٱلطَّيْرِ"]},{"name":"Verb forms attested for طير","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, X.","examples":["ٱلطَّيْرَ","يَطَّيَّرُوا۟","تَطَيَّرْنَا","وَٱلطَّيْرُ","وَٱلطَّيْرَ","وَٱلطَّيْرِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root طير?","options":["ٱلطَّيْرَ","يُؤْمِنُ","شَىْءٍ","لِلشَّهَـٰدَةِ"],"correct":0,"explanation":"ٱلطَّيْرَ — glossed \"the birds\" at 27:20 — carries the root طير. The others come from different roots."},{"type":"multiple_choice","question":"What does يَطَّيَّرُوا۟ mean?","options":["Allah (were to) punish","(is) the command","Allah punish us","they ascribe evil omens"],"correct":3,"explanation":"\"they ascribe evil omens\", from the word-by-word gloss at 7:131."},{"type":"fill_blank","question":"Type the root of تَطَيَّرْنَا in Arabic (three letters).","correct":"طير","explanation":"طير. Diacritics are ignored when checking, so ط ي ر is enough."}]', '["root-Syr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-dry', 'The root دري (د ر ي)', 'grammar', 4, '{"explanation":"The root دري occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَدْرِى","transliteration":"","meaning":"we know","rule":"45:32"},{"arabic":"تَدْرُونَ","transliteration":"","meaning":"you know","rule":"4:11"},{"arabic":"أَدْرِىٓ","transliteration":"","meaning":"I know","rule":"21:109"},{"arabic":"أَدْرَىٰكَ","transliteration":"","meaning":"will make you know","rule":"69:3"},{"arabic":"أَدْرِى","transliteration":"","meaning":"I know","rule":"21:111"},{"arabic":"يُدْرِيكَ","transliteration":"","meaning":"will make you know","rule":"33:63"}],"rules":[{"name":"Words on دري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَدْرِى","تَدْرُونَ","أَدْرِىٓ","أَدْرَىٰكَ","أَدْرِى","يُدْرِيكَ","أَدْرَىٰكُم","تَدْرِى"]},{"name":"Parts of speech attested for دري","description":"The morphology corpus tags words on this root as V — one part of speech across the 10 glossed words attested.","examples":["نَدْرِى","تَدْرُونَ","أَدْرِىٓ","أَدْرَىٰكَ","أَدْرِى","يُدْرِيكَ"]},{"name":"Verb forms attested for دري","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["نَدْرِى","تَدْرُونَ","أَدْرِىٓ","أَدْرَىٰكَ","أَدْرِى","يُدْرِيكَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دري?","options":["وَذُوقُوا۟","نَدْرِى","تَأْمُرُوٓنِّىٓ","لِّلْمُشْرِكِينَ"],"correct":1,"explanation":"نَدْرِى — glossed \"we know\" at 45:32 — carries the root دري. The others come from different roots."},{"type":"multiple_choice","question":"What does تَدْرُونَ mean?","options":["offspring","you know","(which) Allah ordered","(by) Allah"],"correct":1,"explanation":"\"you know\", from the word-by-word gloss at 4:11."},{"type":"fill_blank","question":"Type the root of أَدْرِىٓ in Arabic (three letters).","correct":"دري","explanation":"دري. Diacritics are ignored when checking, so د ر ي is enough."}]', '["root-Tyr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fwz', 'The root فوز (ف و ز)', 'grammar', 4, '{"explanation":"The root فوز occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 8 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْفَوْزُ","transliteration":"","meaning":"(is) the success","rule":"4:13"},{"arabic":"فَازَ","transliteration":"","meaning":"he is successful","rule":"3:185"},{"arabic":"فَوْزًا","transliteration":"","meaning":"a success","rule":"4:73"},{"arabic":"مَفَازًا","transliteration":"","meaning":"(is) success","rule":"78:31"},{"arabic":"بِمَفَازَتِهِمْ","transliteration":"","meaning":"to their place of salvation","rule":"39:61"},{"arabic":"بِمَفَازَةٍۢ","transliteration":"","meaning":"(will) escape","rule":"3:188"}],"rules":[{"name":"Words on فوز","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْفَوْزُ","فَازَ","فَوْزًا","مَفَازًا","بِمَفَازَتِهِمْ","بِمَفَازَةٍۢ","ٱلْفَآئِزُونَ","فَأَفُوزَ"]},{"name":"Parts of speech attested for فوز","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 8 glossed words attested.","examples":["ٱلْفَوْزُ","فَازَ","فَوْزًا","مَفَازًا","بِمَفَازَتِهِمْ","بِمَفَازَةٍۢ"]},{"name":"Where فوز occurs","description":"The 8 glossed words on this root are attested across 5 distinct surahs.","examples":["ٱلْفَوْزُ (4:13)","فَازَ (3:185)","فَوْزًا (4:73)","مَفَازًا (78:31)","بِمَفَازَتِهِمْ (39:61)","بِمَفَازَةٍۢ (3:188)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فوز?","options":["أَخْذَ","ٱلْـَٔاثِمِينَ","ٱلْفَوْزُ","أَمَدًۢا"],"correct":2,"explanation":"ٱلْفَوْزُ — glossed \"(is) the success\" at 4:13 — carries the root فوز. The others come from different roots."},{"type":"multiple_choice","question":"What does فَازَ mean?","options":["(will be) for Allah","their faith","a partner","he is successful"],"correct":3,"explanation":"\"he is successful\", from the word-by-word gloss at 3:185."},{"type":"fill_blank","question":"Type the root of فَوْزًا in Arabic (three letters).","correct":"فوز","explanation":"فوز. Diacritics are ignored when checking, so ف و ز is enough."}]', '["root-dry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-g$w', 'The root غشو (غ ش و)', 'grammar', 4, '{"explanation":"The root غشو occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, V, II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَغَشَّىٰهَا","transliteration":"","meaning":"he covers her","rule":"7:189"},{"arabic":"يُغَشِّيكُمُ","transliteration":"","meaning":"He covered you","rule":"8:11"},{"arabic":"غَشِيَهُمْ","transliteration":"","meaning":"covered them","rule":"20:78"},{"arabic":"فَغَشَّىٰهَا","transliteration":"","meaning":"So covered them","rule":"53:54"},{"arabic":"يَغْشَىٰهُمُ","transliteration":"","meaning":"will cover them","rule":"29:55"},{"arabic":"غَشَّىٰ","transliteration":"","meaning":"covered","rule":"53:54"}],"rules":[{"name":"Words on غشو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَغَشَّىٰهَا","يُغَشِّيكُمُ","غَشِيَهُمْ","فَغَشَّىٰهَا","يَغْشَىٰهُمُ","غَشَّىٰ","غَـٰشِيَةٌۭ","يَغْشَىٰهَا"]},{"name":"Parts of speech attested for غشو","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 25 glossed words attested.","examples":["تَغَشَّىٰهَا","يُغَشِّيكُمُ","غَشِيَهُمْ","فَغَشَّىٰهَا","يَغْشَىٰهُمُ","غَشَّىٰ"]},{"name":"Verb forms attested for غشو","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, V, II, X.","examples":["تَغَشَّىٰهَا","يُغَشِّيكُمُ","غَشِيَهُمْ","فَغَشَّىٰهَا","يَغْشَىٰهُمُ","غَشَّىٰ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غشو?","options":["تَغَشَّىٰهَا","ٱلْ