INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jdl', 'The root جدل (ج د ل)', 'grammar', 4, '{"explanation":"The root جدل occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَجَـٰدِلْهُم","transliteration":"","meaning":"and discuss with them","rule":"16:125"},{"arabic":"جِدَٰلَنَا","transliteration":"","meaning":"(in) dispute with us","rule":"11:32"},{"arabic":"وَجَـٰدَلُوا۟","transliteration":"","meaning":"and they disputed","rule":"40:5"},{"arabic":"تُجَـٰدِلْ","transliteration":"","meaning":"argue","rule":"4:107"},{"arabic":"يُجَـٰدِلُ","transliteration":"","meaning":"will argue","rule":"4:109"},{"arabic":"جَـٰدَلْتُمْ","transliteration":"","meaning":"[you] argue","rule":"4:109"}],"rules":[{"name":"Words on جدل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَجَـٰدِلْهُم","جِدَٰلَنَا","وَجَـٰدَلُوا۟","تُجَـٰدِلْ","يُجَـٰدِلُ","جَـٰدَلْتُمْ","وَيُجَـٰدِلُ","جَدَلًۢا"]},{"name":"Parts of speech attested for جدل","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 20 glossed words attested.","examples":["وَجَـٰدِلْهُم","جِدَٰلَنَا","وَجَـٰدَلُوا۟","تُجَـٰدِلْ","يُجَـٰدِلُ","جَـٰدَلْتُمْ"]},{"name":"Verb forms attested for جدل","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["وَجَـٰدِلْهُم","جِدَٰلَنَا","وَجَـٰدَلُوا۟","تُجَـٰدِلْ","يُجَـٰدِلُ","جَـٰدَلْتُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جدل?","options":["وَجَـٰدِلْهُم","أُم