INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jnd', 'The root جند (ج ن د)', 'grammar', 4, '{"explanation":"The root جند occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِٱلْجُنُودِ","transliteration":"","meaning":"with the forces","rule":"2:249"},{"arabic":"جُنُودَ","transliteration":"","meaning":"(the) hosts","rule":"74:31"},{"arabic":"جُندٌۭ","transliteration":"","meaning":"(are) hosts","rule":"36:75"},{"arabic":"جُنُودٌۭ","transliteration":"","meaning":"(the) hosts","rule":"33:9"},{"arabic":"بِجُنُودِهِۦ","transliteration":"","meaning":"with his forces","rule":"20:78"},{"arabic":"وَجُنُودِهِۦ","transliteration":"","meaning":"and his troops","rule":"2:249"}],"rules":[{"name":"Words on جند","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِٱلْجُنُودِ","جُنُودَ","جُندٌۭ","جُنُودٌۭ","بِجُنُودِهِۦ","وَجُنُودِهِۦ","وَجُنُودُ","جُندًۭا"]},{"name":"Parts of speech attested for جند","description":"The morphology corpus tags words on this root as N — one part of speech across the 19 glossed words attested.","examples":["بِٱلْجُنُودِ","جُنُودَ","جُندٌۭ","جُنُودٌۭ","بِجُنُودِهِۦ","وَجُنُودِهِۦ"]},{"name":"Where جند occurs","description":"The 19 glossed words on this root are attested across 14 distinct surahs.","examples":["بِٱلْجُنُودِ (2:249)","جُنُودَ (74:31)","جُندٌۭ (36:75)","جُنُودٌۭ (33:9)","بِجُنُودِهِۦ (20:78)","وَجُنُودِهِۦ (2:249)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جند?","options":["يَذُوقُوا۟","بِٱلْجُنُودِ","شَجَرَةٍ","وَذُرِّيَّـٰتِهِمْ"],"correct":1,"explanation":"بِٱلْجُنُودِ — glossed \"with the forces\" at 2:249 — carries the root جند. The others come from different roots."},{"type":"multiple_choice","question":"What does جُنُودَ mean?","options":["(the) hosts","so We seized him","the fly","(will be) a matter"],"correct":0,"explanation":"\"(the) hosts\", from the word-by-word gloss at 74:31."},{"type":"fill_blank","question":"Type the root of جُندٌۭ in Arabic (three letters).","correct":"جند","explanation":"جند. Diacritics are ignored when checking, so ج ن د is enough."}]', '["root-jdl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rfE', 'The root رفع (ر ف ع)', 'grammar', 4, '{"explanation":"The root رفع occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَرْفَعُ","transliteration":"","meaning":"We raise","rule":"6:83"},{"arabic":"وَرَفَعَ","transliteration":"","meaning":"and He raised","rule":"2:253"},{"arabic":"يَرْفَعِ","transliteration":"","meaning":"Allah will raise","rule":"58:11"},{"arabic":"وَرَافِعُكَ","transliteration":"","meaning":"and raise you","rule":"3:55"},{"arabic":"يَرْفَعُهُۥ","transliteration":"","meaning":"raises it","rule":"35:10"},{"arabic":"مَّرْفُوعَةٍ","transliteration":"","meaning":"raised","rule":"56:34"}],"rules":[{"name":"Words on رفع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَرْفَعُ","وَرَفَعَ","يَرْفَعِ","وَرَافِعُكَ","يَرْفَعُهُۥ","مَّرْفُوعَةٍ","رَفِيعُ","رَفَعَ"]},{"name":"Parts of speech attested for رفع","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 21 glossed words attested.","examples":["نَرْفَعُ","وَرَفَعَ","يَرْفَعِ","وَرَافِعُكَ","يَرْفَعُهُۥ","مَّرْفُوعَةٍ"]},{"name":"Where رفع occurs","description":"The 21 glossed words on this root are attested across 17 distinct surahs.","examples":["نَرْفَعُ (6:83)","وَرَفَعَ (2:253)","يَرْفَعِ (58:11)","وَرَافِعُكَ (3:55)","يَرْفَعُهُۥ (35:10)","مَّرْفُوعَةٍ (56:34)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رفع?","options":["وَيُشْهِدُ","نَرْفَعُ","فَلْيَأْتُوا۟","أَشْرَكْتُم"],"correct":1,"explanation":"نَرْفَعُ — glossed \"We raise\" at 6:83 — carries the root رفع. The others come from different roots."},{"type":"multiple_choice","question":"What does وَرَفَعَ mean?","options":["your association","we eat","and He raised","they believe"],"correct":2,"explanation":"\"and He raised\", from the word-by-word gloss at 2:253."},{"type":"fill_blank","question":"Type the root of يَرْفَعِ in Arabic (three letters).","correct":"رفع","explanation":"رفع. Diacritics are ignored when checking, so ر ف ع is enough."}]', '["root-jnd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-vny', 'The root ثني (ث ن ي)', 'grammar', 4, '{"explanation":"The root ثني occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَسْتَثْنُونَ","transliteration":"","meaning":"making exception","rule":"68:18"},{"arabic":"مَثْنَىٰ","transliteration":"","meaning":"two","rule":"4:3"},{"arabic":"ٱثْنَيْنِ","transliteration":"","meaning":"two","rule":"6:143"},{"arabic":"مَّثَانِىَ","transliteration":"","meaning":"oft-repeated","rule":"39:23"},{"arabic":"ٱلْمَثَانِى","transliteration":"","meaning":"the oft-repeated","rule":"15:87"},{"arabic":"ٱثْنَتَا","transliteration":"","meaning":"(of)","rule":"2:60"}],"rules":[{"name":"Words on ثني","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَسْتَثْنُونَ","مَثْنَىٰ","ٱثْنَيْنِ","مَّثَانِىَ","ٱلْمَثَانِى","ٱثْنَتَا","ٱثْنَانِ","ٱثْنَتَىْ"]},{"name":"Parts of speech attested for ثني","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 14 glossed words attested.","examples":["يَسْتَثْنُونَ","مَثْنَىٰ","ٱثْنَيْنِ","مَّثَانِىَ","ٱلْمَثَانِى","ٱثْنَتَا"]},{"name":"Verb forms attested for ثني","description":"Where this root is tagged as a verb, the corpus attests derived Form X.","examples":["يَسْتَثْنُونَ","مَثْنَىٰ","ٱثْنَيْنِ","مَّثَانِىَ","ٱلْمَثَانِى","ٱثْنَتَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ثني?","options":["لِيُذِيقَهُم","يَسْتَثْنُونَ","يَشْكُرُونَ","ٱلْإِنسَـٰنَ"],"correct":1,"explanation":"يَسْتَثْنُونَ — glossed \"making exception\" at 68:18 — carries the root ثني. The others come from different roots."},{"type":"multiple_choice","question":"What does مَثْنَىٰ mean?","options":["two","Then, how","(is) painful","a Witness"],"correct":0,"explanation":"\"two\", from the word-by-word gloss at 4:3."},{"type":"fill_blank","question":"Type the root of ٱثْنَيْنِ in Arabic (three letters).","correct":"ثني","explanation":"ثني. Diacritics are ignored when checking, so ث ن ي is enough."}]', '["root-rfE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wdd', 'The root ودد (و د د)', 'grammar', 4, '{"explanation":"The root ودد occurs 29 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as V, N, ADJ, PN. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَيَوَدُّ","transliteration":"","meaning":"Would like","rule":"2:266"},{"arabic":"وُدًّۭا","transliteration":"","meaning":"affection","rule":"19:96"},{"arabic":"وَوَدُّوا۟","transliteration":"","meaning":"and they desire","rule":"60:2"},{"arabic":"وَتَوَدُّونَ","transliteration":"","meaning":"and you wished","rule":"8:7"},{"arabic":"تَوَدُّ","transliteration":"","meaning":"it will wish","rule":"3:30"},{"arabic":"مَوَدَّةٌۭ","transliteration":"","meaning":"any affection","rule":"4:73"}],"rules":[{"name":"Words on ودد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَيَوَدُّ","وُدًّۭا","وَوَدُّوا۟","وَتَوَدُّونَ","تَوَدُّ","مَوَدَّةٌۭ","وَدُودٌۭ","يُوَآدُّونَ"]},{"name":"Parts of speech attested for ودد","description":"The morphology corpus tags words on this root as V, N, ADJ, PN — 4 distinct parts of speech across the 19 glossed words attested.","examples":["أَيَوَدُّ","وُدًّۭا","وَوَدُّوا۟","وَتَوَدُّونَ","تَوَدُّ","مَوَدَّةٌۭ"]},{"name":"Where ودد occurs","description":"The 19 glossed words on this root are attested across 14 distinct surahs.","examples":["أَيَوَدُّ (2:266)","وُدًّۭا (19:96)","وَوَدُّوا۟ (60:2)","وَتَوَدُّونَ (8:7)","تَوَدُّ (3:30)","مَوَدَّةٌۭ (4:73)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ودد?","options":["أَيَوَدُّ","ٱلذُّنُوبَ","أَذْهَبْتُمْ","ٱلْأَوَّلُونَ"],"correct":0,"explanation":"أَيَوَدُّ — glossed \"Would like\" at 2:266 — carries the root ودد. The others come from different roots."},{"type":"multiple_choice","question":"What does وُدًّۭا mean?","options":["will call you to account","affection","That they may eat","as you remember"],"correct":1,"explanation":"\"affection\", from the word-by-word gloss at 19:96."},{"type":"fill_blank","question":"Type the root of وَوَدُّوا۟ in Arabic (three letters).","correct":"ودد","explanation":"ودد. Diacritics are ignored when checking, so و د د is enough."}]', '["root-vny"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$qq', 'The root شقق (ش ق ق)', 'grammar', 4, '{"explanation":"The root شقق occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, III, VII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱنشَقَّتِ","transliteration":"","meaning":"is split","rule":"55:37"},{"arabic":"شِقَاقٍۭ","transliteration":"","meaning":"schism","rule":"2:176"},{"arabic":"وَٱنشَقَّ","transliteration":"","meaning":"and has split","rule":"54:1"},{"arabic":"شِقَاقَ","transliteration":"","meaning":"a dissension","rule":"4:35"},{"arabic":"ٱنشَقَّتْ","transliteration":"","meaning":"is split asunder","rule":"84:1"},{"arabic":"تَشَقَّقُ","transliteration":"","meaning":"will split open","rule":"25:25"}],"rules":[{"name":"Words on شقق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱنشَقَّتِ","شِقَاقٍۭ","وَٱنشَقَّ","شِقَاقَ","ٱنشَقَّتْ","تَشَقَّقُ","شِقَاقٍۢ","وَتَنشَقُّ"]},{"name":"Parts of speech attested for شقق","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 23 glossed words attested.","examples":["ٱنشَقَّتِ","شِقَاقٍۭ","وَٱنشَقَّ","شِقَاقَ","ٱنشَقَّتْ","تَشَقَّقُ"]},{"name":"Verb forms attested for شقق","description":"Where this root is tagged as a verb, the corpus attests derived Forms V, III, VII.","examples":["ٱنشَقَّتِ","شِقَاقٍۭ","وَٱنشَقَّ","شِقَاقَ","ٱنشَقَّتْ","تَشَقَّقُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شقق?","options":["وَٱلشَّجَرُ","ٱنشَقَّتِ","لَنَتَّخِذَنَّ","وَلِلْمُؤْمِنِينَ"],"correct":1,"explanation":"ٱنشَقَّتِ — glossed \"is split\" at 55:37 — carries the root شقق. The others come from different roots."},{"type":"multiple_choice","question":"What does شِقَاقٍۭ mean?","options":["painful","schism","and will bear witness","The Mercy of Allah"],"correct":1,"explanation":"\"schism\", from the word-by-word gloss at 2:176."},{"type":"fill_blank","question":"Type the root of وَٱنشَقَّ in Arabic (three letters).","correct":"شقق","explanation":"شقق. Diacritics are ignored when checking, so ش ق ق is enough."}]', '["root-wdd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Edl', 'The root عدل (ع د ل)', 'grammar', 4, '{"explanation":"The root عدل occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَعَدْلًۭا","transliteration":"","meaning":"and justice","rule":"6:115"},{"arabic":"تَعْدِلْ","transliteration":"","meaning":"it offers ransom","rule":"6:70"},{"arabic":"عَدْلٍۢ","transliteration":"","meaning":"just","rule":"5:95"},{"arabic":"عَدْلٌۭ","transliteration":"","meaning":"a compensation","rule":"2:48"},{"arabic":"لِأَعْدِلَ","transliteration":"","meaning":"that I do justice","rule":"42:15"},{"arabic":"بِٱلْعَدْلِ","transliteration":"","meaning":"in justice","rule":"2:282"}],"rules":[{"name":"Words on عدل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَعَدْلًۭا","تَعْدِلْ","عَدْلٍۢ","عَدْلٌۭ","لِأَعْدِلَ","بِٱلْعَدْلِ","تَعْدِلُوا۟","يَعْدِلُونَ"]},{"name":"Parts of speech attested for عدل","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 12 glossed words attested.","examples":["وَعَدْلًۭا","تَعْدِلْ","عَدْلٍۢ","عَدْلٌۭ","لِأَعْدِلَ","بِٱلْعَدْلِ"]},{"name":"Where عدل occurs","description":"The 12 glossed words on this root are attested across 6 distinct surahs.","examples":["وَعَدْلًۭا (6:115)","تَعْدِلْ (6:70)","عَدْلٍۢ (5:95)","عَدْلٌۭ (2:48)","لِأَعْدِلَ (42:15)","بِٱلْعَدْلِ (2:282)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عدل?","options":["شَطَطًۭا","وَٱلشَّجَرُ","أَخِيهِ","وَعَدْلًۭا"],"correct":3,"explanation":"وَعَدْلًۭا — glossed \"and justice\" at 6:115 — carries the root عدل. The others come from different roots."},{"type":"multiple_choice","question":"What does تَعْدِلْ mean?","options":["it offers ransom","Has Allah sent","he will order you","(who) believe"],"correct":0,"explanation":"\"it offers ransom\", from the word-by-word gloss at 6:70."},{"type":"fill_blank","question":"Type the root of عَدْلٍۢ in Arabic (three letters).","correct":"عدل","explanation":"عدل. Diacritics are ignored when checking, so ع د ل is enough."}]', '["root-$qq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-HwT', 'The root حوط (ح و ط)', 'grammar', 4, '{"explanation":"The root حوط occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُحَاطَ","transliteration":"","meaning":"you are surrounded","rule":"12:66"},{"arabic":"أَحَاطَ","transliteration":"","meaning":"has encompassed","rule":"17:60"},{"arabic":"أَحَطْنَا","transliteration":"","meaning":"We encompassed","rule":"18:91"},{"arabic":"يُحِيطُوا۟","transliteration":"","meaning":"they could encompass","rule":"10:39"},{"arabic":"تُحِيطُوا۟","transliteration":"","meaning":"you encompassed","rule":"27:84"},{"arabic":"لَمُحِيطَةٌۢ","transliteration":"","meaning":"(will) surely surround","rule":"9:49"}],"rules":[{"name":"Words on حوط","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُحَاطَ","أَحَاطَ","أَحَطْنَا","يُحِيطُوا۟","تُحِيطُوا۟","لَمُحِيطَةٌۢ","أَحَطتُ","مُحِيطٌۢ"]},{"name":"Parts of speech attested for حوط","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 19 glossed words attested.","examples":["يُحَاطَ","أَحَاطَ","أَحَطْنَا","يُحِيطُوا۟","تُحِيطُوا۟","لَمُحِيطَةٌۢ"]},{"name":"Verb forms attested for حوط","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["يُحَاطَ","أَحَاطَ","أَحَطْنَا","يُحِيطُوا۟","تُحِيطُوا۟","لَمُحِيطَةٌۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حوط?","options":["ذُرِّيَّةًۭ","يُحَاطَ","أَفَأَمِنُوٓا۟","بِأَمْرِهِمْ"],"correct":1,"explanation":"يُحَاطَ — glossed \"you are surrounded\" at 12:66 — carries the root حوط. The others come from different roots."},{"type":"multiple_choice","question":"What does أَحَاطَ mean?","options":["has encompassed","(and) trusted","a matter","The Mercy of Allah"],"correct":0,"explanation":"\"has encompassed\", from the word-by-word gloss at 17:60."},{"type":"fill_blank","question":"Type the root of أَحَطْنَا in Arabic (three letters).","correct":"حوط","explanation":"حوط. Diacritics are ignored when checking, so ح و ط is enough."}]', '["root-Edl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-n$A', 'The root نشا (ن ش ا)', 'grammar', 4, '{"explanation":"The root نشا occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَأَنشَأْنَا","transliteration":"","meaning":"Then We produced","rule":"23:19"},{"arabic":"أَنشَأَ","transliteration":"","meaning":"produced","rule":"6:141"},{"arabic":"أَنشَأَكُمْ","transliteration":"","meaning":"produced you","rule":"67:23"},{"arabic":"وَيُنشِئُ","transliteration":"","meaning":"and brings up","rule":"13:12"},{"arabic":"أَنشَأْنَـٰهُ","transliteration":"","meaning":"We produce it","rule":"23:14"},{"arabic":"نَاشِئَةَ","transliteration":"","meaning":"(the) rising","rule":"73:6"}],"rules":[{"name":"Words on نشا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَأَنشَأْنَا","أَنشَأَ","أَنشَأَكُمْ","وَيُنشِئُ","أَنشَأْنَـٰهُ","نَاشِئَةَ","أَنشَأْنَا","يُنشِئُ"]},{"name":"Parts of speech attested for نشا","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 19 glossed words attested.","examples":["فَأَنشَأْنَا","أَنشَأَ","أَنشَأَكُمْ","وَيُنشِئُ","أَنشَأْنَـٰهُ","نَاشِئَةَ"]},{"name":"Verb forms attested for نشا","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["فَأَنشَأْنَا","أَنشَأَ","أَنشَأَكُمْ","وَيُنشِئُ","أَنشَأْنَـٰهُ","نَاشِئَةَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نشا?","options":["ٱلْمَأْوَىٰ","وَٱتَّخَذَ","فَأَنشَأْنَا","فَأَذَّنَ"],"correct":2,"explanation":"فَأَنشَأْنَا — glossed \"Then We produced\" at 23:19 — carries the root نشا. The others come from different roots."},{"type":"multiple_choice","question":"What does أَنشَأَ mean?","options":["produced","your (having) faith","(there) come","comes to them"],"correct":0,"explanation":"\"produced\", from the word-by-word gloss at 6:141."},{"type":"fill_blank","question":"Type the root of أَنشَأَكُمْ in Arabic (three letters).","correct":"نشا","explanation":"نشا. Diacritics are ignored when checking, so ن ش ا is enough."}]', '["root-HwT"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rjw', 'The root رجو (ر ج و)', 'grammar', 4, '{"explanation":"The root رجو occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَرْجُونَ","transliteration":"","meaning":"you attribute","rule":"71:13"},{"arabic":"يَرْجُوا۟","transliteration":"","meaning":"hoping","rule":"18:110"},{"arabic":"يَرْجُونَ","transliteration":"","meaning":"they hope","rule":"2:218"},{"arabic":"وَٱرْجُوا۟","transliteration":"","meaning":"and expect","rule":"29:36"},{"arabic":"تَرْجُوٓا۟","transliteration":"","meaning":"expecting","rule":"28:86"},{"arabic":"وَتَرْجُونَ","transliteration":"","meaning":"while you (have) hope","rule":"4:104"}],"rules":[{"name":"Words on رجو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَرْجُونَ","يَرْجُوا۟","يَرْجُونَ","وَٱرْجُوا۟","تَرْجُوٓا۟","وَتَرْجُونَ","وَيَرْجُوا۟","۞ تُرْجِى"]},{"name":"Parts of speech attested for رجو","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 14 glossed words attested.","examples":["تَرْجُونَ","يَرْجُوا۟","يَرْجُونَ","وَٱرْجُوا۟","تَرْجُوٓا۟","وَتَرْجُونَ"]},{"name":"Verb forms attested for رجو","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تَرْجُونَ","يَرْجُوا۟","يَرْجُونَ","وَٱرْجُوا۟","تَرْجُوٓا۟","وَتَرْجُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رجو?","options":["تَرْجُونَ","ٱتَّخَذَ","ءَايَـٰتُهُۥ","فَلْيَأْكُلْ"],"correct":0,"explanation":"تَرْجُونَ — glossed \"you attribute\" at 71:13 — carries the root رجو. The others come from different roots."},{"type":"multiple_choice","question":"What does يَرْجُوا۟ mean?","options":["that they may take heed","you have asked permission","entrusts","hoping"],"correct":3,"explanation":"\"hoping\", from the word-by-word gloss at 18:110."},{"type":"fill_blank","question":"Type the root of يَرْجُونَ in Arabic (three letters).","correct":"رجو","explanation":"رجو. Diacritics are ignored when checking, so ر ج و is enough."}]', '["root-n$A"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sbE', 'The root سبع (س ب ع)', 'grammar', 4, '{"explanation":"The root سبع occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَسَبْعِ","transliteration":"","meaning":"and seven","rule":"12:46"},{"arabic":"سَبْعِ","transliteration":"","meaning":"(the) seven","rule":"12:46"},{"arabic":"سَبْعًۭا","transliteration":"","meaning":"seven","rule":"15:87"},{"arabic":"وَسَبْعَةٍ","transliteration":"","meaning":"and seven (days)","rule":"2:196"},{"arabic":"ٱلسَّبُعُ","transliteration":"","meaning":"the wild animal","rule":"5:3"},{"arabic":"سَبْعَةٌۭ","transliteration":"","meaning":"(they were) seven","rule":"18:22"}],"rules":[{"name":"Words on سبع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَسَبْعِ","سَبْعِ","سَبْعًۭا","وَسَبْعَةٍ","ٱلسَّبُعُ","سَبْعَةٌۭ","سَبْعُونَ","سَبْعِينَ"]},{"name":"Parts of speech attested for سبع","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 15 glossed words attested.","examples":["وَسَبْعِ","سَبْعِ","سَبْعًۭا","وَسَبْعَةٍ","ٱلسَّبُعُ","سَبْعَةٌۭ"]},{"name":"Where سبع occurs","description":"The 15 glossed words on this root are attested across 9 distinct surahs.","examples":["وَسَبْعِ (12:46)","سَبْعِ (12:46)","سَبْعًۭا (15:87)","وَسَبْعَةٍ (2:196)","ٱلسَّبُعُ (5:3)","سَبْعَةٌۭ (18:22)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سبع?","options":["شُهَدَآءَ","وَسَبْعِ","ٱلْأَمْرَ","إِخْوَةُ"],"correct":1,"explanation":"وَسَبْعِ — glossed \"and seven\" at 12:46 — carries the root سبع. The others come from different roots."},{"type":"multiple_choice","question":"What does سَبْعِ mean?","options":["the Verses","Allah originates","(the) seven","[So] Allah"],"correct":2,"explanation":"\"(the) seven\", from the word-by-word gloss at 12:46."},{"type":"fill_blank","question":"Type the root of سَبْعًۭا in Arabic (three letters).","correct":"سبع","explanation":"سبع. Diacritics are ignored when checking, so س ب ع is enough."}]', '["root-rjw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-vql', 'The root ثقل (ث ق ل)', 'grammar', 4, '{"explanation":"The root ثقل occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مِثْقَالَ","transliteration":"","meaning":"(as much as) weight","rule":"4:40"},{"arabic":"ٱثَّاقَلْتُمْ","transliteration":"","meaning":"you cling heavily","rule":"9:38"},{"arabic":"مُّثْقَلُونَ","transliteration":"","meaning":"(are) overburdened","rule":"52:40"},{"arabic":"ثِقَالًۭا","transliteration":"","meaning":"heavy","rule":"7:57"},{"arabic":"وَأَثْقَالًۭا","transliteration":"","meaning":"and burdens","rule":"29:13"},{"arabic":"أَثْقَالَكُمْ","transliteration":"","meaning":"your loads","rule":"16:7"}],"rules":[{"name":"Words on ثقل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مِثْقَالَ","ٱثَّاقَلْتُمْ","مُّثْقَلُونَ","ثِقَالًۭا","وَأَثْقَالًۭا","أَثْقَالَكُمْ","ثَقِيلًا","مُثْقَلَةٌ"]},{"name":"Parts of speech attested for ثقل","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 19 glossed words attested.","examples":["مِثْقَالَ","ٱثَّاقَلْتُمْ","مُّثْقَلُونَ","ثِقَالًۭا","وَأَثْقَالًۭا","أَثْقَالَكُمْ"]},{"name":"Verb forms attested for ثقل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, VI.","examples":["مِثْقَالَ","ٱثَّاقَلْتُمْ","مُّثْقَلُونَ","ثِقَالًۭا","وَأَثْقَالًۭا","أَثْقَالَكُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ثقل?","options":["مِثْقَالَ","أَبِينَا","وَأُنثَىٰ","لِلْأَنَامِ"],"correct":0,"explanation":"مِثْقَالَ — glossed \"(as much as) weight\" at 4:40 — carries the root ثقل. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱثَّاقَلْتُمْ mean?","options":["a reminder","you cling heavily","and gives","are (also) suffering"],"correct":1,"explanation":"\"you cling heavily\", from the word-by-word gloss at 9:38."},{"type":"fill_blank","question":"Type the root of مُّثْقَلُونَ in Arabic (three letters).","correct":"ثقل","explanation":"ثقل. Diacritics are ignored when checking, so ث ق ل is enough."}]', '["root-sbE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-vwb', 'The root ثوب (ث و ب)', 'grammar', 4, '{"explanation":"The root ثوب occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ثِيَابَهُنَّ","transliteration":"","meaning":"their (outer) garments","rule":"24:60"},{"arabic":"فَأَثَـٰبَهُمُ","transliteration":"","meaning":"So rewarded them","rule":"5:85"},{"arabic":"ثَوَابُ","transliteration":"","meaning":"(is the) reward","rule":"4:134"},{"arabic":"ثِيَابُ","transliteration":"","meaning":"(will be) garments","rule":"76:21"},{"arabic":"وَأَثَـٰبَهُمْ","transliteration":"","meaning":"and rewarded them","rule":"48:18"},{"arabic":"ثَوَابًۭا","transliteration":"","meaning":"a reward","rule":"3:195"}],"rules":[{"name":"Words on ثوب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ثِيَابَهُنَّ","فَأَثَـٰبَهُمُ","ثَوَابُ","ثِيَابُ","وَأَثَـٰبَهُمْ","ثَوَابًۭا","ثَوَابِ","مَثُوبَةً"]},{"name":"Parts of speech attested for ثوب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 20 glossed words attested.","examples":["ثِيَابَهُنَّ","فَأَثَـٰبَهُمُ","ثَوَابُ","ثِيَابُ","وَأَثَـٰبَهُمْ","ثَوَابًۭا"]},{"name":"Verb forms attested for ثوب","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["ثِيَابَهُنَّ","فَأَثَـٰبَهُمُ","ثَوَابُ","ثِيَابُ","وَأَثَـٰبَهُمْ","ثَوَابًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ثوب?","options":["ثِيَابَهُنَّ","ٱشْتَرَىٰهُ","يَأْفِكُونَ","تَأْكُلُوٓا۟"],"correct":0,"explanation":"ثِيَابَهُنَّ — glossed \"their (outer) garments\" at 24:60 — carries the root ثوب. The others come from different roots."},{"type":"multiple_choice","question":"What does فَأَثَـٰبَهُمُ mean?","options":["Our Command","So rewarded them","he has impassioned her","ever"],"correct":1,"explanation":"\"So rewarded them\", from the word-by-word gloss at 5:85."},{"type":"fill_blank","question":"Type the root of ثَوَابُ in Arabic (three letters).","correct":"ثوب","explanation":"ثوب. Diacritics are ignored when checking, so ث و ب is enough."}]', '["root-vql"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-xlw', 'The root خلو (خ ل و)', 'grammar', 4, '{"explanation":"The root خلو occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 8 distinct glossed words, tagged in the corpus as V, ADJ, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَخَلُّوا۟","transliteration":"","meaning":"then leave","rule":"9:5"},{"arabic":"خَلَوْا۟","transliteration":"","meaning":"they are alone","rule":"2:14"},{"arabic":"خَلَتِ","transliteration":"","meaning":"and have already passed away","rule":"46:17"},{"arabic":"وَتَخَلَّتْ","transliteration":"","meaning":"and becomes empty","rule":"84:4"},{"arabic":"خَلَا","transliteration":"","meaning":"meet in private","rule":"2:76"},{"arabic":"يَخْلُ","transliteration":"","meaning":"so will be free","rule":"12:9"}],"rules":[{"name":"Words on خلو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَخَلُّوا۟","خَلَوْا۟","خَلَتِ","وَتَخَلَّتْ","خَلَا","يَخْلُ","خَلَتْ","ٱلْخَالِيَةِ"]},{"name":"Parts of speech attested for خلو","description":"The morphology corpus tags words on this root as V, ADJ — 2 distinct parts of speech across the 8 glossed words attested.","examples":["فَخَلُّوا۟","خَلَوْا۟","خَلَتِ","وَتَخَلَّتْ","خَلَا","يَخْلُ"]},{"name":"Verb forms attested for خلو","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, V.","examples":["فَخَلُّوا۟","خَلَوْا۟","خَلَتِ","وَتَخَلَّتْ","خَلَا","يَخْلُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلو?","options":["ٱللَّهِ","أَشَدُّ","أَتَتْكُمُ","فَخَلُّوا۟"],"correct":3,"explanation":"فَخَلُّوا۟ — glossed \"then leave\" at 9:5 — carries the root خلو. The others come from different roots."},{"type":"multiple_choice","question":"What does خَلَوْا۟ mean?","options":["a reminder","they had given him","they are alone","in Our Verses"],"correct":2,"explanation":"\"they are alone\", from the word-by-word gloss at 2:14."},{"type":"fill_blank","question":"Type the root of خَلَتِ in Arabic (three letters).","correct":"خلو","explanation":"خلو. Diacritics are ignored when checking, so خ ل و is enough."}]', '["root-vwb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-yqn', 'The root يقن (ي ق ن)', 'grammar', 4, '{"explanation":"The root يقن occurs 28 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱسْتَيْقَنَتْهَآ","transliteration":"","meaning":"though were convinced with them (signs)","rule":"27:14"},{"arabic":"يَقِينًۢا","transliteration":"","meaning":"certainly","rule":"4:157"},{"arabic":"ٱلْيَقِينُ","transliteration":"","meaning":"the certainty","rule":"15:99"},{"arabic":"مُّوقِنِينَ","transliteration":"","meaning":"convinced","rule":"26:24"},{"arabic":"يَقِينٍ","transliteration":"","meaning":"certain","rule":"27:22"},{"arabic":"ٱلْمُوقِنِينَ","transliteration":"","meaning":"the ones who are certain","rule":"6:75"}],"rules":[{"name":"Words on يقن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱسْتَيْقَنَتْهَآ","يَقِينًۢا","ٱلْيَقِينُ","مُّوقِنِينَ","يَقِينٍ","ٱلْمُوقِنِينَ","يُوقِنُونَ","تُوقِنُونَ"]},{"name":"Parts of speech attested for يقن","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 13 glossed words attested.","examples":["وَٱسْتَيْقَنَتْهَآ","يَقِينًۢا","ٱلْيَقِينُ","مُّوقِنِينَ","يَقِينٍ","ٱلْمُوقِنِينَ"]},{"name":"Verb forms attested for يقن","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X.","examples":["وَٱسْتَيْقَنَتْهَآ","يَقِينًۢا","ٱلْيَقِينُ","مُّوقِنِينَ","يَقِينٍ","ٱلْمُوقِنِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root يقن?","options":["يَسْتَـْٔذِنُكَ","أُمِرْتُ","وَٱسْتَيْقَنَتْهَآ","أَمِنتُمْ"],"correct":2,"explanation":"وَٱسْتَيْقَنَتْهَآ — glossed \"though were convinced with them (signs)\" at 27:14 — carries the root يقن. The others come from different roots."},{"type":"multiple_choice","question":"What does يَقِينًۢا mean?","options":["any matter","an intercession","they remember (Allah)","certainly"],"correct":3,"explanation":"\"certainly\", from the word-by-word gloss at 4:157."},{"type":"fill_blank","question":"Type the root of ٱلْيَقِينُ in Arabic (three letters).","correct":"يقن","explanation":"يقن. Diacritics are ignored when checking, so ي ق ن is enough."}]', '["root-xlw"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-$jr', 'The root شجر (ش ج ر)', 'grammar', 4, '{"explanation":"The root شجر occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلشَّجَرِ","transliteration":"","meaning":"the trees","rule":"16:68"},{"arabic":"شَجَرَةِ","transliteration":"","meaning":"(the) tree","rule":"20:120"},{"arabic":"شَجَرَهَآ","transliteration":"","meaning":"their trees","rule":"27:60"},{"arabic":"شَجَرَةٍ","transliteration":"","meaning":"(the) trees","rule":"31:27"},{"arabic":"شَجَرَةٍۢ","transliteration":"","meaning":"a tree","rule":"24:35"},{"arabic":"شَجَرَةًۭ","transliteration":"","meaning":"a plant","rule":"37:146"}],"rules":[{"name":"Words on شجر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلشَّجَرِ","شَجَرَةِ","شَجَرَهَآ","شَجَرَةٍ","شَجَرَةٍۢ","شَجَرَةًۭ","شَجَرٍۢ","وَٱلشَّجَرَةَ"]},{"name":"Parts of speech attested for شجر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 20 glossed words attested.","examples":["ٱلشَّجَرِ","شَجَرَةِ","شَجَرَهَآ","شَجَرَةٍ","شَجَرَةٍۢ","شَجَرَةًۭ"]},{"name":"Where شجر occurs","description":"The 20 glossed words on this root are attested across 15 distinct surahs.","examples":["ٱلشَّجَرِ (16:68)","شَجَرَةِ (20:120)","شَجَرَهَآ (27:60)","شَجَرَةٍ (31:27)","شَجَرَةٍۢ (24:35)","شَجَرَةًۭ (37:146)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شجر?","options":["فَيُؤْمِنُوا۟","ٱلشَّجَرِ","فَأَخَذْنَـٰهُ","وَءَاتَيْنَـٰهُمَا"],"correct":1,"explana