INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-E$r', 'The root عشر (ع ش ر)', 'grammar', 4, '{"explanation":"The root عشر occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, V, T, ADJ, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْعِشَارُ","transliteration":"","meaning":"the full-term she-camels","rule":"81:4"},{"arabic":"عَشَرَ","transliteration":"","meaning":"(and) ten","rule":"5:12"},{"arabic":"عَشَرَةٌۭ","transliteration":"","meaning":"(is) ten (days)","rule":"2:196"},{"arabic":"عَشِيرَتَكَ","transliteration":"","meaning":"your kindred","rule":"26:214"},{"arabic":"عَشْرًۭا","transliteration":"","meaning":"ten","rule":"20:103"},{"arabic":"مِعْشَارَ","transliteration":"","meaning":"a tenth","rule":"34:45"}],"rules":[{"name":"Words on عشر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْعِشَارُ","عَشَرَ","عَشَرَةٌۭ","عَشِيرَتَكَ","عَشْرًۭا","مِعْشَارَ","بِعَشْرٍۢ","عَشِيرَتَهُمْ"]},{"name":"Parts of speech attested for عشر","description":"The morphology corpus tags words on this root as N, V, T, ADJ — 4 distinct parts of speech across the 19 glossed words attested.","examples":["ٱلْعِشَارُ","عَشَرَ","عَشَرَةٌۭ","عَشِيرَتَكَ","عَشْرًۭا","مِعْشَارَ"]},{"name":"Verb forms attested for عشر","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["ٱلْعِشَارُ","عَشَرَ","عَشَرَةٌۭ","عَشِيرَتَكَ","عَشْرًۭا","مِعْشَارَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عشر?","options":["وَأُوتِينَا","ٱللَّهُ","بِأَخٍۢ","ٱلْعِشَارُ"],"correct":3,"explanation":"ٱلْعِشَارُ — glossed \"the full-term she-camels\" at 81:4 — carries the root عشر. The others come from different roots."},{"type":"multiple_choice","question":"What does عَشَرَ mean?","options":["(having) come to them","and orders you","(and) ten","they were given"],"correct":2,"explanation":"\"(and) ten\", from the word-by-word gloss at 5:12."},{"type":"fill_blank","question":"Type the root of عَشَرَةٌۭ in Arabic (three letters).","correct":"عشر","explanation":"عشر. Diacritics are ignored when checking, so ع ش ر is enough."}]', '["root-$jr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Ejb', 'The root عجب (ع ج ب)', 'grammar', 4, '{"explanation":"The root عجب occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُعْجِبْكَ","transliteration":"","meaning":"impress you","rule":"9:55"},{"arabic":"أَعْجَبَتْكُمْ","transliteration":"","meaning":"she pleases you","rule":"2:221"},{"arabic":"عَجِبْتَ","transliteration":"","meaning":"you wonder","rule":"37:12"},{"arabic":"عَجِيبٌۭ","transliteration":"","meaning":"amazing","rule":"11:72"},{"arabic":"أَعْجَبَ","transliteration":"","meaning":"pleases","rule":"57:20"},{"arabic":"عَجَبًا","transliteration":"","meaning":"a wonder","rule":"10:2"}],"rules":[{"name":"Words on عجب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُعْجِبْكَ","أَعْجَبَتْكُمْ","عَجِبْتَ","عَجِيبٌۭ","أَعْجَبَ","عَجَبًا","عَجِبُوٓا۟","فَعَجَبٌۭ"]},{"name":"Parts of speech attested for عجب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 21 glossed words attested.","examples":["تُعْجِبْكَ","أَعْجَبَتْكُمْ","عَجِبْتَ","عَجِيبٌۭ","أَعْجَبَ","عَجَبًا"]},{"name":"Verb forms attested for عجب","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تُعْجِبْكَ","أَعْجَبَتْكُمْ","عَجِبْتَ","عَجِيبٌۭ","أَعْجَبَ","عَجَبًا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عجب?","options":["تُعْجِبْكَ","ٱللَّهُ","شَجَرٍۢ","لِّيَذُوقَ"],"correct":0,"explanation":"تُعْجِبْكَ — glossed \"impress you\" at 9:55 — carries the root عجب. The others come from different roots."},{"type":"multiple_choice","question":"What does أَعْجَبَتْكُمْ mean?","options":["(will be) a drink","their father said","she pleases you","And they take"],"correct":2,"explanation":"\"she pleases you\", from the word-by-word gloss at 2:221."},{"type":"fill_blank","question":"Type the root of عَجِبْتَ in Arabic (three letters).","correct":"عجب","explanation":"عجب. Diacritics are ignored when checking, so ع ج ب is enough."}]', '["root-E$r"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bwb', 'The root بوب (ب و ب)', 'grammar', 4, '{"explanation":"The root بوب occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَابًۭا","transliteration":"","meaning":"a gate","rule":"15:14"},{"arabic":"أَبْوَٰبُ","transliteration":"","meaning":"(the) doors","rule":"7:40"},{"arabic":"أَبْوَٰبًۭا","transliteration":"","meaning":"doors","rule":"43:34"},{"arabic":"ٱلْبَابَ","transliteration":"","meaning":"the gate","rule":"2:58"},{"arabic":"ٱلْبَابِ","transliteration":"","meaning":"the door","rule":"12:25"},{"arabic":"أَبْوَٰبَ","transliteration":"","meaning":"gates","rule":"6:44"}],"rules":[{"name":"Words on بوب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَابًۭا","أَبْوَٰبُ","أَبْوَٰبًۭا","ٱلْبَابَ","ٱلْبَابِ","أَبْوَٰبَ","بَابٍۢ","أَبْوَٰبُهَا"]},{"name":"Parts of speech attested for بوب","description":"The morphology corpus tags words on this root as N — one part of speech across the 13 glossed words attested.","examples":["بَابًۭا","أَبْوَٰبُ","أَبْوَٰبًۭا","ٱلْبَابَ","ٱلْبَابِ","أَبْوَٰبَ"]},{"name":"Where بوب occurs","description":"The 13 glossed words on this root are attested across 9 distinct surahs.","examples":["بَابًۭا (15:14)","أَبْوَٰبُ (7:40)","أَبْوَٰبًۭا (43:34)","ٱلْبَابَ (2:58)","ٱلْبَابِ (12:25)","أَبْوَٰبَ (6:44)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بوب?","options":["أَتَىٰهَا","بَابًۭا","ءَايَـٰتُ","أَشَدُّ"],"correct":1,"explanation":"بَابًۭا — glossed \"a gate\" at 15:14 — carries the root بوب. The others come from different roots."},{"type":"multiple_choice","question":"What does أَبْوَٰبُ mean?","options":["will call you to account","His Command","(the) doors","anyone"],"correct":2,"explanation":"\"(the) doors\", from the word-by-word gloss at 7:40."},{"type":"fill_blank","question":"Type the root of أَبْوَٰبًۭا in Arabic (three letters).","correct":"بوب","explanation":"بوب. Diacritics are ignored when checking, so ب و ب is enough."}]', '["root-Ejb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-grr', 'The root غرر (غ ر ر)', 'grammar', 4, '{"explanation":"The root غرر occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَغَرَّتْهُمُ","transliteration":"","meaning":"and deluded them","rule":"6:70"},{"arabic":"ٱلْغُرُورِ","transliteration":"","meaning":"(of) delusion","rule":"3:185"},{"arabic":"وَغَرَّكُم","transliteration":"","meaning":"And deceived you","rule":"57:14"},{"arabic":"يَغْرُرْكَ","transliteration":"","meaning":"deceive you","rule":"40:4"},{"arabic":"غُرُورًۭا","transliteration":"","meaning":"(in) deception","rule":"6:112"},{"arabic":"يَغُرَّنَّكَ","transliteration":"","meaning":"deceive you","rule":"3:196"}],"rules":[{"name":"Words on غرر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَغَرَّتْهُمُ","ٱلْغُرُورِ","وَغَرَّكُم","يَغْرُرْكَ","غُرُورًۭا","يَغُرَّنَّكَ","تَغُرَّنَّكُمُ","غَرَّ"]},{"name":"Parts of speech attested for غرر","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 16 glossed words attested.","examples":["وَغَرَّتْهُمُ","ٱلْغُرُورِ","وَغَرَّكُم","يَغْرُرْكَ","غُرُورًۭا","يَغُرَّنَّكَ"]},{"name":"Where غرر occurs","description":"The 16 glossed words on this root are attested across 11 distinct surahs.","examples":["وَغَرَّتْهُمُ (6:70)","ٱلْغُرُورِ (3:185)","وَغَرَّكُم (57:14)","يَغْرُرْكَ (40:4)","غُرُورًۭا (6:112)","يَغُرَّنَّكَ (3:196)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غرر?","options":["ءَاتَيْتُكُم","وَغَرَّتْهُمُ","فَلِلَّهِ","لِّلْمُؤْمِنِينَ"],"correct":1,"explanation":"وَغَرَّتْهُمُ — glossed \"and deluded them\" at 6:70 — carries the root غرر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْغُرُورِ mean?","options":["(will) come to both of you","(of) delusion","(of) his family","His seizure"],"correct":1,"explanation":"\"(of) delusion\", from the word-by-word gloss at 3:185."},{"type":"fill_blank","question":"Type the root of وَغَرَّكُم in Arabic (three letters).","correct":"غرر","explanation":"غرر. Diacritics are ignored when checking, so غ ر ر is enough."}]', '["root-bwb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mnn', 'The root منن (م ن ن)', 'grammar', 4, '{"explanation":"The root منن occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَمَنَّ","transliteration":"","meaning":"then conferred favor","rule":"4:94"},{"arabic":"نَّمُنَّ","transliteration":"","meaning":"bestow a favor","rule":"28:5"},{"arabic":"تَمُنُّوا۟","transliteration":"","meaning":"consider a favor","rule":"49:17"},{"arabic":"مَمْنُونٍۢ","transliteration":"","meaning":"never ending","rule":"41:8"},{"arabic":"مَنًّۭا","transliteration":"","meaning":"(with) reminders of generosity","rule":"2:262"},{"arabic":"ٱلْمَنُونِ","transliteration":"","meaning":"a misfortune of time","rule":"52:30"}],"rules":[{"name":"Words on منن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَمَنَّ","نَّمُنَّ","تَمُنُّوا۟","مَمْنُونٍۢ","مَنًّۭا","ٱلْمَنُونِ","بِٱلْمَنِّ","فَٱمْنُنْ"]},{"name":"Parts of speech attested for منن","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 18 glossed words attested.","examples":["فَمَنَّ","نَّمُنَّ","تَمُنُّوا۟","مَمْنُونٍۢ","مَنًّۭا","ٱلْمَنُونِ"]},{"name":"Where منن occurs","description":"The 18 glossed words on this root are attested across 14 distinct surahs.","examples":["فَمَنَّ (4:94)","نَّمُنَّ (28:5)","تَمُنُّوا۟ (49:17)","مَمْنُونٍۢ (41:8)","مَنًّۭا (2:262)","ٱلْمَنُونِ (52:30)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root منن?","options":["شَفَا","ٱلْأَسْرَىٰٓ","فَمَنَّ","أَجَلَهُنّ