INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-msk', 'The root مسك (م س ك)', 'grammar', 4, '{"explanation":"The root مسك occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as N, V, in verb forms IV, X, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَمْسَكَ","transliteration":"","meaning":"He withheld","rule":"67:21"},{"arabic":"مِسْكٌۭ","transliteration":"","meaning":"(will be of) musk","rule":"83:26"},{"arabic":"مُسْتَمْسِكُونَ","transliteration":"","meaning":"(are) holding fast","rule":"43:21"},{"arabic":"مُمْسِكَـٰتُ","transliteration":"","meaning":"withholders","rule":"39:38"},{"arabic":"أَيُمْسِكُهُۥ","transliteration":"","meaning":"Should he keep it","rule":"16:59"},{"arabic":"ٱسْتَمْسَكَ","transliteration":"","meaning":"he grasped","rule":"2:256"}],"rules":[{"name":"Words on مسك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَمْسَكَ","مِسْكٌۭ","مُسْتَمْسِكُونَ","مُمْسِكَـٰتُ","أَيُمْسِكُهُۥ","ٱسْتَمْسَكَ","أَمْسِكْ","فَٱسْتَمْسِكْ"]},{"name":"Parts of speech attested for مسك","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 22 glossed words attested.","examples":["أَمْسَكَ","مِسْكٌۭ","مُسْتَمْسِكُونَ","مُمْسِكَـٰتُ","أَيُمْسِكُهُۥ","ٱسْتَمْسَكَ"]},{"name":"Verb forms attested for مسك","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, X, II.","examples":["أَمْسَكَ","مِسْكٌۭ","مُسْتَمْسِكُونَ","مُمْسِكَـٰتُ","أَيُمْسِكُهُۥ","ٱسْتَمْسَكَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مسك?","options":["فَـَٔامِنُوا۟","أَمْسَكَ","تَأْمَنْهُ","شَرَحَ"],"correct":1,"explanation":"أَمْسَكَ — glossed \"He withheld\" at 67:21 — carries the root مسك. The others come from different roots."},{"type":"multiple_choice","question":"What does مِسْكٌۭ mean?","options":["Allah will forgive","and order","are (these) postponed","(will be of) musk"],"correct":3,"explanation":"\"(will be of) musk\", from the word-by-word gloss at 83:26."},{"type":"fill_blank","question":"Type the root of مُسْتَمْسِكُونَ in Arabic (three letters).","correct":"مسك","explanation":"مسك. Diacritics are ignored when checking, so م س ك is enough."}]', '["root-mnn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qmr', 'The root قمر (ق م ر)', 'grammar', 4, '{"explanation":"The root قمر occurs 27 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْقَمَرَ","transliteration":"","meaning":"the moon","rule":"6:77"},{"arabic":"وَٱلْقَمَرِ","transliteration":"","meaning":"By the moon","rule":"74:32"},{"arabic":"وَٱلْقَمَرَ","transliteration":"","meaning":"and the moon","rule":"6:96"},{"arabic":"لِلْقَمَرِ","transliteration":"","meaning":"to the moon","rule":"41:37"},{"arabic":"وَٱلْقَمَرُ","transliteration":"","meaning":"and the moon","rule":"22:18"},{"arabic":"ٱلْقَمَرُ","transliteration":"","meaning":"the moon","rule":"54:1"}],"rules":[{"name":"Words on قمر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْقَمَرَ","وَٱلْقَمَرِ","وَٱلْقَمَرَ","لِلْقَمَرِ","وَٱلْقَمَرُ","ٱلْقَمَرُ","وَقَمَرًۭا"]},{"name":"Parts of speech attested for قمر","description":"The morphology corpus tags words on this root as N — one part of speech across the 7 glossed words attested.","examples":["ٱلْقَمَرَ","وَٱلْقَمَرِ","وَٱلْقَمَرَ","لِلْقَمَرِ","وَٱلْقَمَرُ","ٱلْقَمَرُ"]},{"name":"Where قمر occurs","description":"The 7 glossed words on this root are attested across 6 distinct surahs.","examples":["ٱلْقَمَرَ (6:77)","وَٱلْقَمَرِ (74:32)","وَٱلْقَمَرَ (6:96)","لِلْقَمَرِ (41:37)","وَٱلْقَمَرُ (22:18)","ٱلْقَمَرُ (54:1)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قمر?","options":["أَتَىٰهَا","شَدِيدُ","يَتَّخِذَ","ٱلْقَمَرَ"],"correct":3,"explanation":"ٱلْقَمَرَ — gl