INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bTn', 'The root بطن (ب ط ن)', 'grammar', 4, '{"explanation":"The root بطن occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِبَطْنِ","transliteration":"","meaning":"within","rule":"48:24"},{"arabic":"وَبَاطِنَهُۥٓ","transliteration":"","meaning":"and the secret","rule":"6:120"},{"arabic":"بَطَآئِنُهَا","transliteration":"","meaning":"(whose) inner linings","rule":"55:54"},{"arabic":"ٱلْبُطُونَ","transliteration":"","meaning":"(their) bellies","rule":"37:66"},{"arabic":"بُطُونِهِمْ","transliteration":"","meaning":"their bellies","rule":"2:174"},{"arabic":"بِطَانَةًۭ","transliteration":"","meaning":"(as) intimates","rule":"3:118"}],"rules":[{"name":"Words on بطن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِبَطْنِ","وَبَاطِنَهُۥٓ","بَطَآئِنُهَا","ٱلْبُطُونَ","بُطُونِهِمْ","بِطَانَةًۭ","بُطُونِهِۦ","وَبَاطِنَةًۭ"]},{"name":"Parts of speech attested for بطن","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 17 glossed words attested.","examples":["بِبَطْنِ","وَبَاطِنَهُۥٓ","بَطَآئِنُهَا","ٱلْبُطُونَ","بُطُونِهِمْ","بِطَانَةًۭ"]},{"name":"Where بطن occurs","description":"The 17 glossed words on this root are attested across 11 distinct surahs.","examples":["بِبَطْنِ (48:24)","وَبَاطِنَهُۥٓ (6:120)","بَطَآئِنُهَا (55:54)","ٱلْبُطُونَ (37:66)","بُطُونِهِمْ (2:174)","بِطَانَةًۭ (3:118)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بطن?","options":["فَأَتَىٰهُمُ","أَشَدَّ","ءَاتَىٰهُمْ","بِبَطْنِ"],"correct":3,"explanation":"بِبَطْنِ — glossed \"within\" at 48:24 — carries the root بطن. The others come from different roots."},{"type":"multiple_choice","question":"What does وَبَاطِنَهُۥٓ mean?","options":["Allah enriches them","and the secret","painful","has come (to) them"],"correct":1,"explanation":"\"and the secret\", from the word-by-word gloss at 6:120."},{"type":"fill_blank","question":"Type the root of بَطَآئِنُهَا in Arabic (three letters).","correct":"بطن","explanation":"بطن. Diacritics are ignored when checking, so ب ط ن is enough."}]', '["root-Sly"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-bsT', 'The root بسط (ب س ط)', 'grammar', 4, '{"explanation":"The root بسط occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَصْۜطَةًۭ","transliteration":"","meaning":"extensively","rule":"7:69"},{"arabic":"وَيَبْسُطُوٓا۟","transliteration":"","meaning":"and extend","rule":"60:2"},{"arabic":"تَبْسُطْهَا","transliteration":"","meaning":"extend it","rule":"17:29"},{"arabic":"ٱلْبَسْطِ","transliteration":"","meaning":"reach","rule":"17:29"},{"arabic":"كَبَـٰسِطِ","transliteration":"","meaning":"like one who stretches","rule":"13:14"},{"arabic":"مَبْسُوطَتَانِ","transliteration":"","meaning":"(are) stretched out","rule":"5:64"}],"rules":[{"name":"Words on بسط","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَصْۜطَةًۭ","وَيَبْسُطُوٓا۟","تَبْسُطْهَا","ٱلْبَسْطِ","كَبَـٰسِطِ","مَبْسُوطَتَانِ","بَـٰسِطٌۭ","يَبْسُطُ"]},{"name":"Parts of speech attested for بسط","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 17 glossed words attested.","examples":["بَصْۜطَةًۭ","وَيَبْسُطُوٓا۟","تَبْسُطْهَا","ٱلْبَسْطِ","كَبَـٰسِطِ","مَبْسُوطَتَانِ"]},{"name":"Where بسط occurs","description":"The 17 glossed words on this root are attested across 11 distinct surahs.","examples":["بَصْۜطَةًۭ (7:69)","وَيَبْسُطُوٓا۟ (60:2)","تَبْسُطْهَا (17:29)","ٱلْبَسْطِ (17:29)","كَبَـٰسِطِ (13:14)","مَبْسُوطَتَانِ (5:64)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بسط?","options":["وَٱلذَّٰكِرَٰتِ","بَصْۜطَةًۭ","شَكُورٌ","وَٱلْأَنفَ"],"correct":1,"explanation":"بَصْۜطَةًۭ — glossed \"extensively\" at 7:69 — carries the root بسط. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَبْسُطُوٓا۟ mean?","options":["and gray hair","and extend","for anyone","witnesses"],"correct":1,"explanation":"\"and extend\", from the word-by-word gloss at 60:2."},{"type":"fill_blank","question":"Type the root of تَبْسُطْهَا in Arabic (three letters).","correct":"بسط","explanation":"بسط. Diacritics are ignored when checking, so ب س ط is enough."}]', '["root-bTn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-flk', 'The root فلك (ف ل ك)', 'grammar', 4, '{"explanation":"The root فلك occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 6 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَلَكٍۢ","transliteration":"","meaning":"an orbit","rule":"21:33"},{"arabic":"وَٱلْفُلْكَ","transliteration":"","meaning":"and the ships","rule":"22:65"},{"arabic":"ٱلْفُلْكَ","transliteration":"","meaning":"the ship","rule":"11:37"},{"arabic":"ٱلْفُلْكِ","transliteration":"","meaning":"the ship","rule":"7:64"},{"arabic":"وَٱلْفُلْكِ","transliteration":"","meaning":"and the ships","rule":"2:164"},{"arabic":"ٱلْفُلْكُ","transliteration":"","meaning":"the ships","rule":"30:46"}],"rules":[{"name":"Words on فلك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَلَكٍۢ","وَٱلْفُلْكَ","ٱلْفُلْكَ","ٱلْفُلْكِ","وَٱلْفُلْكِ","ٱلْفُلْكُ"]},{"name":"Parts of speech attested for فلك","description":"The morphology corpus tags words on this root as N — one part of speech across the 6 glossed words attested.","examples":["فَلَكٍۢ","وَٱلْفُلْكَ","ٱلْفُلْكَ","ٱلْفُلْكِ","وَٱلْفُلْكِ","ٱلْفُلْكُ"]},{"name":"Where فلك occurs","description":"The 6 glossed words on this root are attested across 6 distinct surahs.","examples":["فَلَكٍۢ (21:33)","وَٱلْفُلْكَ (22:65)","ٱلْفُلْكَ (11:37)","ٱلْفُلْكِ (7:64)","وَٱلْفُلْكِ (2:164)","ٱلْفُلْكُ (30:46)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فلك?","options":["فَلَكٍۢ","تَذْلِيلًۭا","شَهَـٰدَةُ","شَىْءٍ"],"correct":0,"explanation":"فَلَكٍۢ — glossed \"an orbit\" at 21:33 — carries the root فلك. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْفُلْكَ mean?","options":["eating","(has been) commanded","and the ships","you are admonished"],"correct":2,"explanation":"\"and the ships\", from the word-by-word gloss at 22:65."},{"type":"fill_blank","question":"Type the root of ٱلْفُلْكَ in Arabic (three letters).","correct":"فلك","explanation":"فلك. Diacritics are ignored when checking, so ف ل ك is enough."}]', '["root-bsT"]', 30, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lsn', 'The root لسن (ل س ن)', 'grammar', 4, '{"explanation":"The root لسن occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَلِسَانًۭا","transliteration":"","meaning":"And a tongue","rule":"90:9"},{"arabic":"لِسَانَ","transliteration":"","meaning":"a truthful mention","rule":"19:50"},{"arabic":"لِسَانٌ","transliteration":"","meaning":"(is) a language","rule":"16:103"},{"arabic":"لِّسَانًا","transliteration":"","meaning":"(in) language","rule":"46:12"},{"arabic":"بِأَلْسِنَةٍ","transliteration":"","meaning":"with tongues","rule":"33:19"},{"arabic":"لِّسَانُ","transliteration":"","meaning":"(The) tongue","rule":"16:103"}],"rules":[{"name":"Words on لسن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَلِسَانًۭا","لِسَانَ","لِسَانٌ","لِّسَانًا","بِأَلْسِنَةٍ","لِّسَانُ","بِلِسَانِ","بِلِسَانِكَ"]},{"name":"Parts of speech attested for لسن","description":"The morphology corpus tags words on this root as N — one part of speech across the 23 glossed words attested.","examples":["وَلِسَانًۭا","لِسَانَ","لِسَانٌ","لِّسَانًا","بِأَلْسِنَةٍ","لِّسَانُ"]},{"name":"Where لسن occurs","description":"The 23 glossed words on this root are attested across 17 distinct surahs.","examples":["وَلِسَانًۭا (90:9)","لِسَانَ (19:50)","لِسَانٌ (16:103)","لِّسَانًا (46:12)","بِأَلْسِنَةٍ (33:19)","لِّسَانُ (16:103)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لسن?","options":["لِإِيلَـٰفِ","أَخِى","وَلِسَانًۭا","ٱللَّهِ"],"correct":2,"explanation":"وَلِسَانًۭا — glossed \"And a tongue\" at 90:9 — carries the root لسن. The others come from different roots."},{"type":"multiple_choice","question":"What does لِسَانَ mean?","options":["a truthful mention","Allah is mentioned","our term","he will return it"],"correct":0,"explanation":"\"a truthful mention\", from the word-by-word gloss at 19:50."},{"type":"fill_blank","question":"Type the root of لِسَانٌ in Arabic (three letters).","correct":"لسن","explanation":"لسن. Diacritics are ignored when checking, so ل س ن is enough."}]', '["root-flk"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-qsT', 'The root قسط (ق س ط)', 'grammar', 4, '{"explanation":"The root قسط occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 8 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُقْسِطُوا۟","transliteration":"","meaning":"you will be able to do justice","rule":"4:3"},{"arabic":"ٱلْقَـٰسِطُونَ","transliteration":"","meaning":"(are) unjust","rule":"72:14"},{"arabic":"ٱلْقِسْطَ","transliteration":"","meaning":"(of) the justice","rule":"21:47"},{"arabic":"ٱلْمُقْسِطِينَ","transliteration":"","meaning":"the ones who are just","rule":"5:42"},{"arabic":"وَأَقْسِطُوٓا۟","transliteration":"","meaning":"and act justly","rule":"49:9"},{"arabic":"أَقْسَطُ","transliteration":"","meaning":"(is) more just","rule":"2:282"}],"rules":[{"name":"Words on قسط","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُقْسِطُوا۟","ٱلْقَـٰسِطُونَ","ٱلْقِسْطَ","ٱلْمُقْسِطِينَ","وَأَقْسِطُوٓا۟","أَقْسَطُ","وَتُقْسِطُوٓا۟","بِٱلْقِسْطِ"]},{"name":"Parts of speech attested for قسط","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 8 glossed words attested.","examples":["تُقْسِطُوا۟","ٱلْقَـٰسِطُونَ","ٱلْقِسْطَ","ٱلْمُقْسِطِينَ","وَأَقْسِطُوٓا۟","أَقْسَطُ"]},{"name":"Verb forms attested for قسط","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["تُقْسِطُوا۟","ٱلْقَـٰسِطُونَ","ٱلْقِسْطَ","ٱلْمُقْسِطِينَ","وَأَقْسِطُوٓا۟","أَقْسَطُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قسط?","options":["مُؤَذِّنٌ","فَيُؤْمِنُوا۟","تُقْسِطُوا۟","وَيَتَّخِذُ"],"correct":2,"explanation":"تُقْسِطُوا۟ — glossed \"you will be able to do justice\" at 4:3 — carries the root قسط. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْقَـٰسِطُونَ mean?","options":["(by) hurt","(are) unjust","months","their reward"],"correct":1,"explanation":"\"(are) unjust\", from the word-by-word gloss at 72:14."},{"type":"fill_blank","question":"Type the root of ٱلْقِسْطَ in Arabic (three letters).","correct":"قسط","explanation":"قسط. Diacritics are ignored when checking, so ق س ط is enough."}]', '["root-lsn"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-sqy', 'The root سقي (س ق ي)', 'grammar', 4, '{"explanation":"The root سقي occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 24 distinct glossed words, tagged in the corpus as V, N, in verb forms X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَسُقْيَـٰهَا","transliteration":"","meaning":"and her drink","rule":"91:13"},{"arabic":"وَيَسْقِينِ","transliteration":"","meaning":"and gives me drink","rule":"26:79"},{"arabic":"وَيُسْقَىٰ","transliteration":"","meaning":"and he will be made to drink","rule":"14:16"},{"arabic":"لَأَسْقَيْنَـٰهُم","transliteration":"","meaning":"surely We (would) have given them to drink","rule":"72:16"},{"arabic":"تُسْقَىٰ","transliteration":"","meaning":"They will be given to drink","rule":"88:5"},{"arabic":"وَيُسْقَوْنَ","transliteration":"","meaning":"And they will be given to drink","rule":"76:17"}],"rules":[{"name":"Words on سقي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَسُقْيَـٰهَا","وَيَسْقِينِ","وَيُسْقَىٰ","لَأَسْقَيْنَـٰهُم","تُسْقَىٰ","وَيُسْقَوْنَ","وَسَقَىٰهُمْ","وَأَسْقَيْنَـٰكُم"]},{"name":"Parts of speech attested for سقي","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 24 glossed words attested.","examples":["وَسُقْيَـٰهَا","وَيَسْقِينِ","وَيُسْقَىٰ","لَأَسْقَيْنَـٰهُم","تُسْقَىٰ","وَيُسْقَوْنَ"]},{"name":"Verb forms attested for سقي","description":"Where this root is tagged as a verb, the corpus attests derived Forms X, IV.","examples":["وَسُقْيَـٰهَا","وَيَسْقِينِ","وَيُسْقَىٰ","لَأَسْقَيْنَـٰهُم","تُسْقَىٰ","وَيُسْقَوْنَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سقي?","options":["لِّلشَّـٰرِبِينَ","وَسُقْيَـٰهَا","أُو۟لُوا۟","فَذُوقُوا۟"],"correct":1,"explanation":"وَسُقْيَـٰهَا — glossed \"and her drink\" at 91:13 — carries the root سقي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَسْقِينِ mean?","options":["they give","desire","He gives us","and gives me drink"],"correct":3,"explanation":"\"and gives me drink\", from the word-by-word gloss at 26:79."},{"type":"fill_blank","question":"Type the root of وَيُسْقَىٰ in Arabic (three letters).","correct":"سقي","explanation":"سقي. Diacritics are ignored when checking, so س ق ي is enough."}]', '["root-qsT"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-wEZ', 'The root وعظ (و ع ظ)', 'grammar', 4, '{"explanation":"The root وعظ occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تُوعَظُونَ","transliteration":"","meaning":"you are admonished","rule":"58:3"},{"arabic":"مَوْعِظَةٌۭ","transliteration":"","meaning":"(the) admonition","rule":"2:275"},{"arabic":"أَوَعَظْتَ","transliteration":"","meaning":"whether you advise","rule":"26:136"},{"arabic":"وَٱلْمَوْعِظَةِ","transliteration":"","meaning":"and the instruction","rule":"16:125"},{"arabic":"يُوعَظُ","transliteration":"","meaning":"is admonished","rule":"2:232"},{"arabic":"مَّوْعِظَةٌۭ","transliteration":"","meaning":"an instruction","rule":"10:57"}],"rules":[{"name":"Words on وعظ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تُوعَظُونَ","مَوْعِظَةٌۭ","أَوَعَظْتَ","وَٱلْمَوْعِظَةِ","يُوعَظُ","مَّوْعِظَةٌۭ","وَمَوْعِظَةًۭ","تَعِظُونَ"]},{"name":"Parts of speech attested for وعظ","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 20 glossed words attested.","examples":["تُوعَظُونَ","مَوْعِظَةٌۭ","أَوَعَظْتَ","وَٱلْمَوْعِظَةِ","يُوعَظُ","مَّوْعِظَةٌۭ"]},{"name":"Where وعظ occurs","description":"The 20 glossed words on this root are attested across 12 distinct surahs.","examples":["تُوعَظُونَ (58:3)","مَوْعِظَةٌۭ (2:275)","أَوَعَظْتَ (26:136)","وَٱلْمَوْعِظَةِ (16:125)","يُوعَظُ (2:232)","مَّوْعِظَةٌۭ (10:57)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وعظ?","options":["تُوعَظُونَ","أَمْرَ","ٱلْأَشْقَى","شَهِيدٍۢ"],"correct":0,"explanation":"تُوعَظُونَ — glossed \"you are admonished\" at 58:3 — carries the root وعظ. The others come from different roots."},{"type":"multiple_choice","question":"What does مَوْعِظَةٌۭ mean?","options":["(the) admonition","mightier","the possessor of strength","Our Reminder"],"correct":0,"explanation":"\"(the) admonition\", from the word-by-word gloss at 2:275."},{"type":"fill_blank","question":"Type the root of أَوَعَظْتَ in Arabic (three letters).","correct":"وعظ","explanation":"وعظ. Diacritics are ignored when checking, so و ع ظ is enough."}]', '["root-sqy"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-whb', 'The root وهب (و ه ب)', 'grammar', 4, '{"explanation":"The root وهب occurs 25 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِأَهَبَ","transliteration":"","meaning":"that I (may) bestow","rule":"19:19"},{"arabic":"وَيَهَبُ","transliteration":"","meaning":"and He grants","rule":"42:49"},{"arabic":"ٱلْوَهَّابِ","transliteration":"","meaning":"the Bestower","rule":"38:9"},{"arabic":"وَهَبْنَا","transliteration":"","meaning":"[and] We bestowed","rule":"19:49"},{"arabic":"فَوَهَبَ","transliteration":"","meaning":"But granted","rule":"26:21"},{"arabic":"وَهَبَتْ","transliteration":"","meaning":"she gives","rule":"33:50"}],"rules":[{"name":"Words on وهب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِأَهَبَ","وَيَهَبُ","ٱلْوَهَّابِ","وَهَبْنَا","فَوَهَبَ","وَهَبَتْ","يَهَبُ","فَهَبْ"]},{"name":"Parts of speech attested for وهب","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 13 glossed words attested.","examples":["لِأَهَبَ","وَيَهَبُ","ٱلْوَهَّابِ","وَهَبْنَا","فَوَهَبَ","وَهَبَتْ"]},{"name":"Where وهب occurs","description":"The 13 glossed words on this root are attested across 8 distinct surahs.","examples":["لِأَهَبَ (19:19)","وَيَهَبُ (42:49)","ٱلْوَهَّابِ (38:9)","وَهَبْنَا (19:49)","فَوَهَبَ (26:21)","وَهَبَتْ (33:50)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وهب?","options":["ٱللَّهِ","لِأَهَبَ","ٱلْمُؤْمِنَـٰتِ","شِرْعَةًۭ"],"correct":1,"explanation":"لِأَهَبَ — glossed \"that I (may) bestow\" at 19:19 — carries the root وهب. The others come from different roots."},{"type":"multiple_choice","question":"What does وَيَهَبُ mean?","options":["its people","consume","its root","and He grants"],"correct":3,"explanation":"\"and He grants\", from the word-by-word gloss at 42:49."},{"type":"fill_blank","question":"Type the root of ٱلْوَهَّابِ in Arabic (three letters).","correct":"وهب","explanation":"وهب. Diacritics are ignored when checking, so و ه ب is enough."}]', '["root-wEZ"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-*ll', 'The root ذلل (ذ ل ل)', 'grammar', 4, '{"explanation":"The root ذلل occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ذِلَّةٌ","transliteration":"","meaning":"humiliation","rule":"10:26"},{"arabic":"وَذِلَّةٌۭ","transliteration":"","meaning":"and humiliation","rule":"7:152"},{"arabic":"أَذِلَّةٌۭ","transliteration":"","meaning":"weak","rule":"3:123"},{"arabic":"وَذَلَّلْنَـٰهَا","transliteration":"","meaning":"And We have tamed them","rule":"36:72"},{"arabic":"ٱلْأَذَلَّ","transliteration":"","meaning":"the more humble","rule":"63:8"},{"arabic":"ٱلذِّلَّةُ","transliteration":"","meaning":"the humiliation","rule":"2:61"}],"rules":[{"name":"Words on ذلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ذِلَّةٌ","وَذِلَّةٌۭ","أَذِلَّةٌۭ","وَذَلَّلْنَـٰهَا","ٱلْأَذَلَّ","ٱلذِّلَّةُ","ذُلُلًۭا","ذَلُولٌۭ"]},{"name":"Parts of speech attested for ذلل","description":"The morphology corpus tags words on this root as N, ADJ, V — 3 distinct parts of speech across the 18 glossed words attested.","examples":["ذِلَّةٌ","وَذِلَّةٌۭ","أَذِلَّةٌۭ","وَذَلَّلْنَـٰهَا","ٱلْأَذَلَّ","ٱلذِّلَّةُ"]},{"name":"Verb forms attested for ذلل","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["ذِلَّةٌ","وَذِلَّةٌۭ","أَذِلَّةٌۭ","وَذَلَّلْنَـٰهَا","ٱلْأَذَلَّ","ٱلذِّلَّةُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذلل?","options":["وَأُمَّهَـٰتُكُمُ","يُؤْفَكُ","تَشْكُرُونَ","ذِلَّةٌ"],"correct":3,"explanation":"ذِلَّةٌ — glossed \"humiliation\" at 10:26 — carries the root ذلل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَذِلَّةٌۭ mean?","options":["any intercession","and humiliation","in Our Verses","and (in) the Hereafter"],"correct":1,"explanation":"\"and humiliation\", from the word-by-word gloss at 7:152."},{"type":"fill_blank","question":"Type the root of أَذِلَّةٌۭ in Arabic (three letters).","correct":"ذلل","explanation":"ذلل. Diacritics are ignored when checking, so ذ ل ل is enough."}]', '["root-whb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-A*y', 'The root اذي (ا ذ ي)', 'grammar', 4, '{"explanation":"The root اذي occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ءَاذَوْا۟","transliteration":"","meaning":"abused","rule":"33:69"},{"arabic":"يُؤْذِى","transliteration":"","meaning":"troubling","rule":"33:53"},{"arabic":"وَأُوذُوا۟","transliteration":"","meaning":"and were harmed","rule":"3:195"},{"arabic":"يُؤْذَيْنَ","transliteration":"","meaning":"harmed","rule":"33:59"},{"arabic":"أُوذِىَ","transliteration":"","meaning":"he is harmed","rule":"29:10"},{"arabic":"تُؤْذُوا۟","transliteration":"","meaning":"you trouble","rule":"33:53"}],"rules":[{"name":"Words on اذي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ءَاذَوْا۟","يُؤْذِى","وَأُوذُوا۟","يُؤْذَيْنَ","أُوذِىَ","تُؤْذُوا۟","أَذَىٰهُمْ","فَـَٔاذُوهُمَا"]},{"name":"Parts of speech attested for اذي","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 14 glossed words attested.","examples":["ءَاذَوْا۟","يُؤْذِى","وَأُوذُوا۟","يُؤْذَيْنَ","أُوذِىَ","تُؤْذُوا۟"]},{"name":"Verb forms attested for اذي","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["ءَاذَوْا۟","يُؤْذِى","وَأُوذُوا۟","يُؤْذَيْنَ","أُوذِىَ","تُؤْذُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اذي?","options":["لِلْمُشْرِكِينَ","وَشُرَكَآؤُكُمْ","يُذَبِّحُونَ","ءَاذَوْا۟"],"correct":3,"explanation":"ءَاذَوْا۟ — glossed \"abused\" at 33:69 — carries the root اذي. The others come from different roots."},{"type":"multiple_choice","question":"What does يُؤْذِى mean?","options":["be grateful","troubling","his sin","Do you take"],"correct":1,"explanation":"\"troubling\", from the word-by-word gloss at 33:53."},{"type":"fill_blank","question":"Type the root of وَأُوذُوا۟ in Arabic (three letters).","correct":"اذي","explanation":"اذي. Diacritics are ignored when checking, so ا ذ ي is enough."}]', '["root-*ll"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-Emr', 'The root عمر (ع م ر)', 'grammar', 4, '{"explanation":"The root عمر occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 21 distinct glossed words, tagged in the corpus as V, N, in verb forms II, VIII, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَعْمُرُ","transliteration":"","meaning":"will maintain","rule":"9:18"},{"arabic":"يُعَمَّرُ","transliteration":"","meaning":"he could be granted a life","rule":"2:96"},{"arabic":"وَٱسْتَعْمَرَكُمْ","transliteration":"","meaning":"and settled you","rule":"11:61"},{"arabic":"بِٱلْعُمْرَةِ","transliteration":"","meaning":"of the Umrah","rule":"2:196"},{"arabic":"عُمُرِهِۦٓ","transliteration":"","meaning":"his life","rule":"35:11"},{"arabic":"وَعِمَارَةَ","transliteration":"","meaning":"and (the) maintenance","rule":"9:19"}],"rules":[{"name":"Words on عمر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَعْمُرُ","يُعَمَّرُ","وَٱسْتَعْمَرَكُمْ","بِٱلْعُمْرَةِ","عُمُرِهِۦٓ","وَعِمَارَةَ","نُعَمِّرْكُم","يَعْمُرُوا۟"]},{"name":"Parts of speech attested for عمر","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 21 glossed words attested.","examples":["يَعْمُرُ","يُعَمَّرُ","وَٱسْتَعْمَرَكُمْ","بِٱلْعُمْرَةِ","عُمُرِهِۦٓ","وَعِمَارَةَ"]},{"name":"Verb forms attested for عمر","description":"Where this root is tagged as a verb, the corpus attests derived Forms II, VIII, X.","examples":["يَعْمُرُ","يُعَمَّرُ","وَٱسْتَعْمَرَكُمْ","بِٱلْعُمْرَةِ","عُمُرِهِۦٓ","وَعِمَارَةَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عمر?","options":["ءَامَنَّا","يَعْمُرُ","شَهَـٰدَةً","أَتَتْكُمُ"],"correct":1,"explanation":"يَعْمُرُ — glossed \"will maintain\" at 9:18 — carries the root عمر. The others come from different roots."},{"type":"multiple_choice","question":"What does يُعَمَّرُ mean?","options":["(of) anyone","and the sin","he could be granted a life","Allah decides"],"correct":2,"explanation":"\"he could be granted a life\", from the word-by-word gloss at 2:96."},{"type":"fill_blank","question":"Type the root of وَٱسْتَعْمَرَكُمْ in Arabic (three letters).","correct":"عمر","explanation":"عمر. Diacritics are ignored when checking, so ع م ر is enough."}]', '["root-A*y"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fH$', 'The root فحش (ف ح ش)', 'grammar', 4, '{"explanation":"The root فحش occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَـٰحِشَةً","transliteration":"","meaning":"immorality","rule":"3:135"},{"arabic":"ٱلْفَـٰحِشَةَ","transliteration":"","meaning":"[the] immorality","rule":"4:15"},{"arabic":"بِفَـٰحِشَةٍۢ","transliteration":"","meaning":"immorality","rule":"4:19"},{"arabic":"وَٱلْفَحْشَآءِ","transliteration":"","meaning":"and the shameful","rule":"2:169"},{"arabic":"ٱلْفَوَٰحِشَ","transliteration":"","meaning":"[the] immoralities","rule":"6:151"},{"arabic":"فَـٰحِشَةًۭ","transliteration":"","meaning":"an immorality","rule":"4:22"}],"rules":[{"name":"Words on فحش","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَـٰحِشَةً","ٱلْفَـٰحِشَةَ","بِفَـٰحِشَةٍۢ","وَٱلْفَحْشَآءِ","ٱلْفَوَٰحِشَ","فَـٰحِشَةًۭ","وَٱلْفَوَٰحِشَ","بِٱلْفَحْشَآءِ"]},{"name":"Parts of speech attested for فحش","description":"The morphology corpus tags words on this root as N — one part of speech across the 11 glossed words attested.","examples":["فَـٰحِشَةً","ٱلْفَـٰحِشَةَ","بِفَـٰحِشَةٍۢ","وَٱلْفَحْشَآءِ","ٱلْفَوَٰحِشَ","فَـٰحِشَةًۭ"]},{"name":"Where فحش occurs","description":"The 11 glossed words on this root are attested across 8 distinct surahs.","examples":["فَـٰحِشَةً (3:135)","ٱلْفَـٰحِشَةَ (4:15)","بِفَـٰحِشَةٍۢ (4:19)","وَٱلْفَحْشَآءِ (2:169)","ٱلْفَوَٰحِشَ (6:151)","فَـٰحِشَةًۭ (4:22)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فحش?","options":["فَـٰحِشَةً","ٱللَّهُ","تَأْجُرَنِى","وَلَيَأْتِيَنَّهُم"],"correct":0,"explanation":"فَـٰحِشَةً — glossed \"immorality\" at 3:135 — carries the root فحش. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْفَـٰحِشَةَ mean?","options":["will split open","[the] immorality","suffer","and tamarisks"],"correct":1,"explanation":"\"[the] immorality\", from the word-by-word gloss at 4:15."},{"type":"fill_blank","question":"Type the root of بِفَـٰحِشَةٍۢ in Arabic (three letters).","correct":"فحش","explanation":"فحش. Diacritics are ignored when checking, so ف ح ش is enough."}]', '["root-Emr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fjr', 'The root فجر (ف ج ر)', 'grammar', 4, '{"explanation":"The root فجر occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VII, V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فُجِّرَتْ","transliteration":"","meaning":"are made to gush forth","rule":"82:3"},{"arabic":"فَاجِرًۭا","transliteration":"","meaning":"a wicked","rule":"71:27"},{"arabic":"ٱلْفُجَّارَ","transliteration":"","meaning":"the wicked","rule":"82:14"},{"arabic":"تَفْجِيرًا","transliteration":"","meaning":"abundantly","rule":"17:91"},{"arabic":"كَٱلْفُجَّارِ","transliteration":"","meaning":"like the wicked","rule":"38:28"},{"arabic":"فُجُورَهَا","transliteration":"","meaning":"(to distinguish) its wickedness","rule":"91:8"}],"rules":[{"name":"Words on فجر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فُجِّرَتْ","فَاجِرًۭا","ٱلْفُجَّارَ","تَفْجِيرًا","كَٱلْفُجَّارِ","فُجُورَهَا","وَفَجَّرْنَا","فَٱنفَجَرَتْ"]},{"name":"Parts of speech attested for فجر","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 18 glossed words attested.","examples":["فُجِّرَتْ","فَاجِرًۭا","ٱلْفُجَّارَ","تَفْجِيرًا","كَٱلْفُجَّارِ","فُجُورَهَا"]},{"name":"Verb forms attested for فجر","description":"Where this root is tagged as a verb, the corpus attests derived Forms VII, V, II.","examples":["فُجِّرَتْ","فَاجِرًۭا","ٱلْفُجَّارَ","تَفْجِيرًا","كَٱلْفُجَّارِ","فُجُورَهَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فجر?","options":["لِتُشْرِكَ","شَىْءٌ","فُجِّرَتْ","بِٱلْإِثْمِ"],"correct":2,"explanation":"فُجِّرَتْ — glossed \"are made to gush forth\" at 82:3 — carries the root فجر. The others come from different roots."},{"type":"multiple_choice","question":"What does فَاجِرًۭا mean?","options":["And believe","a wicked","your partners","(The) curse of Allah"],"correct":1,"explanation":"\"a wicked\", from the word-by-word gloss at 71:27."},{"type":"fill_blank","question":"Type the root of ٱلْفُجَّارَ in Arabic (three letters).","correct":"فجر","explanation":"فجر. Diacritics are ignored when checking, so ف ج ر is enough."}]', '["root-fH$"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-gDb', 'The root غضب (غ ض ب)', 'grammar', 4, '{"explanation":"The root غضب occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, in verb form III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْغَضَبُ","transliteration":"","meaning":"the anger","rule":"7:154"},{"arabic":"غَضَبٌۭ","transliteration":"","meaning":"wrath","rule":"7:152"},{"arabic":"وَغَضِبَ","transliteration":"","meaning":"and will fall the wrath","rule":"4:93"},{"arabic":"غَضَبٍۢ","transliteration":"","meaning":"wrath","rule":"2:90"},{"arabic":"غَضِبُوا۟","transliteration":"","meaning":"they are angry","rule":"42:37"},{"arabic":"غَضَبِى","transliteration":"","meaning":"My Anger","rule":"20:81"}],"rules":[{"name":"Words on غضب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْغَضَبُ","غَضَبٌۭ","وَغَضِبَ","غَضَبٍۢ","غَضِبُوا۟","غَضَبِى","مُغَـٰضِبًۭا","غَضْبَـٰنَ"]},{"name":"Parts of speech attested for غضب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 14 glossed words attested.","examples":["ٱلْغَضَبُ","غَضَبٌۭ","وَغَضِبَ","غَضَبٍۢ","غَضِبُوا۟","غَضَبِى"]},{"name":"Verb forms attested for غضب","description":"Where this root is tagged as a verb, the corpus attests derived Form III.","examples":["ٱلْغَضَبُ","غَضَبٌۭ","وَغَضِبَ","غَضَبٍۢ","غَضِبُوا۟","غَضَبِى"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غضب?","options":["بِٱلْـَٔايَـٰتِ","وَيَشْفِ","ٱلْغَضَبُ","ٱللَّهِ"],"correct":2,"explanation":"ٱلْغَضَبُ — glossed \"the anger\" at 7:154 — carries the root غضب. The others come from different roots."},{"type":"multiple_choice","question":"What does غَضَبٌۭ mean?","options":["with a thing","wrath","(of) the ancient","the males"],"correct":1,"explanation":"\"wrath\", from the word-by-word gloss at 7:152."},{"type":"fill_blank","question":"Type the root of وَغَضِبَ in Arabic (three letters).","correct":"غضب","explanation":"غضب. Diacritics are ignored when checking, so غ ض ب is enough."}]', '["root-fjr"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-jhl', 'The root جهل (ج ه ل)', 'grammar', 4, '{"explanation":"The root جهل occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 9 distinct glossed words, tagged in the corpus as N, PN, V, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْجَـٰهِلِيَّةِ","transliteration":"","meaning":"(of) [the] ignorance","rule":"3:154"},{"arabic":"ٱلْجَـٰهِلِينَ","transliteration":"","meaning":"the ignorant","rule":"2:67"},{"arabic":"ٱلْجَـٰهِلُونَ","transliteration":"","meaning":"the ignorant ones","rule":"25:63"},{"arabic":"يَجْهَلُونَ","transliteration":"","meaning":"(are) ignorant","rule":"6:111"},{"arabic":"تَجْهَلُونَ","transliteration":"","meaning":"ignorant","rule":"7:138"},{"arabic":"ٱلْجَاهِلُ","transliteration":"","meaning":"the ignorant one","rule":"2:273"}],"rules":[{"name":"Words on جهل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْجَـٰهِلِيَّةِ","ٱلْجَـٰهِلِينَ","ٱلْجَـٰهِلُونَ","يَجْهَلُونَ","تَجْهَلُونَ","ٱلْجَاهِلُ","بِجَهَـٰلَةٍۢ","جَـٰهِلُونَ"]},{"name":"Parts of speech attested for جهل","description":"The morphology corpus tags words on this root as N, PN, V, ADJ — 4 distinct parts of speech across the 9 glossed words attested.","examples":["ٱلْجَـٰهِلِيَّةِ","ٱلْجَـٰهِلِينَ","ٱلْجَـٰهِلُونَ","يَجْهَلُونَ","تَجْهَلُونَ","ٱلْجَاهِلُ"]},{"name":"Where جهل occurs","description":"The 9 glossed words on this root are attested across 8 distinct surahs.","examples":["ٱلْجَـٰهِلِيَّةِ (3:154)","ٱلْجَـٰهِلِينَ (2:67)","ٱلْجَـٰهِلُونَ (25:63)","يَجْهَلُونَ (6:111)","تَجْهَلُونَ (7:138)","ٱلْجَاهِلُ (2:273)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جهل?","options":["ٱلْجَـٰهِلِيَّةِ","ٱللَّهُ","وَٱلْإِثْمَ","تُؤْفَكُونَ"],"correct":0,"explanation":"ٱلْجَـٰهِلِيَّةِ — glossed \"(of) [the] ignorance\" at 3:154 — carries the root جهل. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْجَـٰهِلِينَ mean?","options":["he believes","the ignorant","(the) bottom","they mention"],"correct":1,"explanation":"\"the ignorant\", from the word-by-word gloss at 2:67."},{"type":"fill_blank","question":"Type the root of ٱلْجَـٰهِلُونَ in Arabic (three letters).","correct":"جهل","explanation":"جهل. Diacritics are ignored when checking, so ج ه ل is enough."}]', '["root-gDb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-kwd', 'The root كود (ك و د)', 'grammar', 4, '{"explanation":"The root كود occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَكَادُ","transliteration":"","meaning":"Almost","rule":"19:90"},{"arabic":"وَكَادُوا۟","transliteration":"","meaning":"and were about to","rule":"7:150"},{"arabic":"يَكَادُونَ","transliteration":"","meaning":"do they seem","rule":"4:78"},{"arabic":"أَكَادُ","transliteration":"","meaning":"I almost","rule":"20:15"},{"arabic":"كِدتَّ","transliteration":"","meaning":"you almost","rule":"17:74"},{"arabic":"كَادُوا۟","transliteration":"","meaning":"they were near","rule":"2:71"}],"rules":[{"name":"Words on كود","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَكَادُ","وَكَادُوا۟","يَكَادُونَ","أَكَادُ","كِدتَّ","كَادُوا۟","يَكَادُ","يَكَدْ"]},{"name":"Parts of speech attested for كود","description":"The morphology corpus tags words on this root as V — one part of speech across the 10 glossed words attested.","examples":["تَكَادُ","وَكَادُوا۟","يَكَادُونَ","أَكَادُ","كِدتَّ","كَادُوا۟"]},{"name":"Where كود occurs","description":"The 10 glossed words on this root are attested across 9 distinct surahs.","examples":["تَكَادُ (19:90)","وَكَادُوا۟ (7:150)","يَكَادُونَ (4:78)","أَكَادُ (20:15)","كِدتَّ (17:74)","كَادُوا۟ (2:71)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كود?","options":["وَأَخَوَٰتُكُم","ٱذْهَبُوا۟","تَكَادُ","ٱللَّهِ"],"correct":2,"explanation":"تَكَادُ — glossed \"Almost\" at 19:90 — carries the root كود. The others come from different roots."},{"type":"multiple_choice","question":"What does وَكَادُوا۟ mean?","options":["has come (to) them","and were about to","any reward","And we were given"],"correct":1,"explanation":"\"and were about to\", from the word-by-word gloss at 7:150."},{"type":"fill_blank","question":"Type the root of يَكَادُونَ in Arabic (three letters).","correct":"كود","explanation":"كود. Diacritics are ignored when checking, so ك و د is enough."}]', '["root-jhl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mrD', 'The root مرض (م ر ض)', 'grammar', 4, '{"explanation":"The root مرض occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مَرَضًۭا","transliteration":"","meaning":"(in) disease","rule":"2:10"},{"arabic":"مَّرِيضًا","transliteration":"","meaning":"sick","rule":"2:184"},{"arabic":"مَّرْضَىٰٓ","transliteration":"","meaning":"ill","rule":"4:43"},{"arabic":"ٱلْمَرْضَىٰ","transliteration":"","meaning":"the sick","rule":"9:91"},{"arabic":"مَرِيضًا","transliteration":"","meaning":"sick","rule":"2:185"},{"arabic":"مَرِضْتُ","transliteration":"","meaning":"I am ill","rule":"26:80"}],"rules":[{"name":"Words on مرض","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مَرَضًۭا","مَّرِيضًا","مَّرْضَىٰٓ","ٱلْمَرْضَىٰ","مَرِيضًا","مَرِضْتُ","مَّرَضٌۭ","ٱلْمَرِيضِ"]},{"name":"Parts of speech attested for مرض","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 11 glossed words attested.","examples":["مَرَضًۭا","مَّرِيضًا","مَّرْضَىٰٓ","ٱلْمَرْضَىٰ","مَرِيضًا","مَرِضْتُ"]},{"name":"Where مرض occurs","description":"The 11 glossed words on this root are attested across 8 distinct surahs.","examples":["مَرَضًۭا (2:10)","مَّرِيضًا (2:184)","مَّرْضَىٰٓ (4:43)","ٱلْمَرْضَىٰ (9:91)","مَرِيضًا (2:185)","مَرِضْتُ (26:80)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مرض?","options":["ذِكْرِ","أَحَدًۭا","مَرَضًۭا","أَتَى"],"correct":2,"explanation":"مَرَضًۭا — glossed \"(in) disease\" at 2:10 — carries the root مرض. The others come from different roots."},{"type":"multiple_choice","question":"What does مَّرِيضًا mean?","options":["Allah has fulfilled","sick","and takes","That you may believe"],"correct":1,"explanation":"\"sick\", from the word-by-word gloss at 2:184."},{"type":"fill_blank","question":"Type the root of مَّرْضَىٰٓ in Arabic (three letters).","correct":"مرض","explanation":"مرض. Diacritics are ignored when checking, so م ر ض is enough."}]', '["root-kwd"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rqb', 'The root رقب (ر ق ب)', 'grammar', 4, '{"explanation":"The root رقب occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as N, V, in verb forms VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَرْقُبُوا۟","transliteration":"","meaning":"they do not regard (the ties)","rule":"9:8"},{"arabic":"رَقِيبٌ","transliteration":"","meaning":"(is) an observer","rule":"50:18"},{"arabic":"مُّرْتَقِبُونَ","transliteration":"","meaning":"(too are) watching","rule":"44:59"},{"arabic":"يَتَرَقَّبُ","transliteration":"","meaning":"(and) was vigilant","rule":"28:18"},{"arabic":"رَّقِيبًۭا","transliteration":"","meaning":"an Observer","rule":"33:52"},{"arabic":"وَٱرْتَقِبُوٓا۟","transliteration":"","meaning":"And watch","rule":"11:93"}],"rules":[{"name":"Words on رقب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَرْقُبُوا۟","رَقِيبٌ","مُّرْتَقِبُونَ","يَتَرَقَّبُ","رَّقِيبًۭا","وَٱرْتَقِبُوٓا۟","يَرْقُبُونَ","ٱلرِّقَابِ"]},{"name":"Parts of speech attested for رقب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 16 glossed words attested.","examples":["يَرْقُبُوا۟","رَقِيبٌ","مُّرْتَقِبُونَ","يَتَرَقَّبُ","رَّقِيبًۭا","وَٱرْتَقِبُوٓا۟"]},{"name":"Verb forms attested for رقب","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, V.","examples":["يَرْقُبُوا۟","رَقِيبٌ","مُّرْتَقِبُونَ","يَتَرَقَّبُ","رَّقِيبًۭا","وَٱرْتَقِبُوٓا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رقب?","options":["يَرْقُبُوا۟","تَأْوِيلَهُۥ","ٱللَّهُ","شَآءَ"],"correct":0,"explanation":"يَرْقُبُوا۟ — glossed \"they do not regard (the ties)\" at 9:8 — carries the root رقب. The others come from different roots."},{"type":"multiple_choice","question":"What does رَقِيبٌ mean?","options":["and your sin","and you believe","(The) Promise of Allah","(is) an observer"],"correct":3,"explanation":"\"(is) an observer\", from the word-by-word gloss at 50:18."},{"type":"fill_blank","question":"Type the root of مُّرْتَقِبُونَ in Arabic (three letters).","correct":"رقب","explanation":"رقب. Diacritics are ignored when checking, so ر ق ب is enough."}]', '["root-mrD"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-vmr', 'The root ثمر (ث م ر)', 'grammar', 4, '{"explanation":"The root ثمر occurs 24 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, V, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ثَمَرٌۭ","transliteration":"","meaning":"fruit","rule":"18:34"},{"arabic":"ثَمَرَٰتٍۢ","transliteration":"","meaning":"fruits","rule":"35:27"},{"arabic":"ثَمَرَةٍۢ","transliteration":"","meaning":"fruit","rule":"2:25"},{"arabic":"ثَمَرَٰتُ","transliteration":"","meaning":"fruits","rule":"28:57"},{"arabic":"وَٱلثَّمَرَٰتِ","transliteration":"","meaning":"and [the] fruits","rule":"2:155"},{"arabic":"بِثَمَرِهِۦ","transliteration":"","meaning":"his fruits","rule":"18:42"}],"rules":[{"name":"Words on ثمر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ثَمَرٌۭ","ثَمَرَٰتٍۢ","ثَمَرَةٍۢ","ثَمَرَٰتُ","وَٱلثَّمَرَٰتِ","بِثَمَرِهِۦ","ثَمَرَٰتِ","أَثْمَرَ"]},{"name":"Parts of speech attested for ثمر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 11 glossed words attested.","examples":["ثَمَرٌۭ","ثَمَرَٰتٍۢ","ثَمَرَةٍۢ","ثَمَرَٰتُ","وَٱلثَّمَرَٰتِ","بِثَمَرِهِۦ"]},{"name":"Verb forms attested for ثمر","description":"Where this root is tagged as a verb, the corpus attests derived Form IV.","examples":["ثَمَرٌۭ","ثَمَرَٰتٍۢ","ثَمَرَةٍۢ","ثَمَرَٰتُ","وَٱلثَّمَرَٰتِ","بِثَمَرِهِۦ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ثمر?","options":["شُرَكَآءَهُمْ","أُخْتَهَا","ثَمَرٌۭ","ٱللَّهُ"],"correct":2,"explanation":"ثَمَرٌۭ — glossed