INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lbs', 'The root لبس (ل ب س)', 'grammar', 4, '{"explanation":"The root لبس occurs 23 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 18 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَلِبَاسُ","transliteration":"","meaning":"But the clothing","rule":"7:26"},{"arabic":"وَلِيَلْبِسُوا۟","transliteration":"","meaning":"and that they make confusing","rule":"6:137"},{"arabic":"تَلْبِسُوا۟","transliteration":"","meaning":"mix","rule":"2:42"},{"arabic":"يَلْبَسُونَ","transliteration":"","meaning":"Wearing garments","rule":"44:53"},{"arabic":"وَلَلَبَسْنَا","transliteration":"","meaning":"and certainly We (would) have obscured","rule":"6:9"},{"arabic":"وَلِبَاسُهُمْ","transliteration":"","meaning":"and their garments","rule":"22:23"}],"rules":[{"name":"Words on لبس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَلِبَاسُ","وَلِيَلْبِسُوا۟","تَلْبِسُوا۟","يَلْبَسُونَ","وَلَلَبَسْنَا","وَلِبَاسُهُمْ","وَيَلْبَسُونَ","يَلْبِسَكُمْ"]},{"name":"Parts of speech attested for لبس","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 18 glossed words attested.","examples":["وَلِبَاسُ","وَلِيَلْبِسُوا۟","تَلْبِسُوا۟","يَلْبَسُونَ","وَلَلَبَسْنَا","وَلِبَاسُهُمْ"]},{"name":"Where لبس occurs","description":"The 18 glossed words on this root are attested across 10 distinct surahs.","examples":["وَلِبَاسُ (7:26)","وَلِيَلْبِسُوا۟ (6:137)","تَلْبِسُوا۟ (2:42)","يَلْبَسُونَ (44:53)","وَلَلَبَسْنَا (6:9)","وَلِبَاسُهُمْ (22:23)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لبس?","options":["يَأْكُلُ","شَاكِرًا","وَلِبَاسُ","۞ أَتَأْمُرُونَ"],"correct":2,"explanation":"وَلِبَاسُ — glossed \"But the clothing\" at 7:26 — carries the root لبس. The others come from different roots."},{"type":"multiple_choice","question":"What does وَلِيَلْبِسُوا۟ mean?","options":["two others","(would) be the polytheists","and that they make confusing","dangling low"],"correct":2,"explanation":"\"and that they make confusing\", from the word-by-word gloss at 6:137."},{"type":"fill_blank","question":"Type the root of تَلْبِسُوا۟ in Arabic (three letters).","correct":"لبس","explanation":"لبس. Diacritics are ignored when checking, so ل ب س is enough."}]', '["root-grq"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-m$y', 'The root مشي (م ش ي)', 'grammar', 4, '{"explanation":"The root مشي occurs 23 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as V, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَمْشِى","transliteration":"","meaning":"walking","rule":"28:25"},{"arabic":"تَمْشِىٓ","transliteration":"","meaning":"was going","rule":"20:40"},{"arabic":"فَٱمْشُوا۟","transliteration":"","meaning":"so walk","rule":"67:15"},{"arabic":"يَمْشُونَ","transliteration":"","meaning":"(to) walk","rule":"7:195"},{"arabic":"مَّشَوْا۟","transliteration":"","meaning":"they walk","rule":"2:20"},{"arabic":"تَمْشِ","transliteration":"","meaning":"walk","rule":"17:37"}],"rules":[{"name":"Words on مشي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَمْشِى","تَمْشِىٓ","فَٱمْشُوا۟","يَمْشُونَ","مَّشَوْا۟","تَمْشِ","مَّشَّآءٍۭ","تَمْشُونَ"]},{"name":"Parts of speech attested for مشي","description":"The morphology corpus tags words on this root as V, N, ADJ — 3 distinct parts of speech across the 13 glossed words attested.","examples":["تَمْشِى","تَمْشِىٓ","فَٱمْشُوا۟","يَمْشُونَ","مَّشَوْا۟","تَمْشِ"]},{"name":"Where مشي occurs","description":"The 13 glossed words on this root are attested across 12 distinct surahs.","examples":["تَمْشِى (28:25)","تَمْشِىٓ (20:40)","فَٱمْشُوا۟ (67:15)","يَمْشُونَ (7:195)","مَّشَوْا۟ (2:20)","تَمْشِ (17:37)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مشي?","options":["يَسْتَـْٔخِرُونَ","تَمْشِى","ذُكْرَانًۭا","تُؤَاخِذْنَآ"],"correct":1,"explanation":"تَمْشِى — glossed \"w