INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fTr', 'The root فطر (ف ط ر)', 'grammar', 4, '{"explanation":"The root فطر occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, in verb form VII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَاطِرَ","transliteration":"","meaning":"Creator","rule":"12:101"},{"arabic":"فَطَرَ","transliteration":"","meaning":"created","rule":"6:79"},{"arabic":"فُطُورٍۢ","transliteration":"","meaning":"flaw","rule":"67:3"},{"arabic":"فِطْرَتَ","transliteration":"","meaning":"Nature","rule":"30:30"},{"arabic":"فَطَرَنِى","transliteration":"","meaning":"created me","rule":"36:22"},{"arabic":"يَتَفَطَّرْنَ","transliteration":"","meaning":"get torn","rule":"19:90"}],"rules":[{"name":"Words on فطر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَاطِرَ","فَطَرَ","فُطُورٍۢ","فِطْرَتَ","فَطَرَنِى","يَتَفَطَّرْنَ","فَطَرَكُمْ","فَطَرَهُنَّ"]},{"name":"Parts of speech attested for فطر","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 14 glossed words attested.","examples":["فَاطِرَ","فَطَرَ","فُطُورٍۢ","فِطْرَتَ","فَطَرَنِى","يَتَفَطَّرْنَ"]},{"name":"Verb forms attested for فطر","description":"Where this root is tagged as a verb, the corpus attests derived Form VII.","examples":["فَاطِرَ","فَطَرَ","فُطُورٍۢ","فِطْرَتَ","فَطَرَنِى","يَتَفَطَّرْنَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فطر?","options":["فَاطِرَ","تُؤْفَكُونَ","وَذُرِّيَّـٰتِهِمْ","لِتَشْقَىٰٓ"],"correct":0,"explanation":"فَاطِرَ — glossed \"Creator\" at 12:101 — carries the root فطر. The others come from different roots."},{"type":"multiple_choice","question":"What does فَطَرَ mean?","options":["created","And He gave you","And We gave them","(for final) determination"],"correct":0,"explanation":"\"created\", from the word-by-word gloss at 6:79."},{"type":"fill_blank","question":"Type the root of فُطُورٍۢ in Arabic (three letters).","correct":"فطر","explanation":"فطر. Diacritics are ignored when checking, so ف ط ر is enough."}]', '["root-drj"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-fqh', 'The root فقه (ف ق ه)', 'grammar', 4, '{"explanation":"The root فقه occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 6 distinct glossed words, tagged in the corpus as V, in verb form V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَفْقَهُونَ","transliteration":"","meaning":"(to) understand","rule":"4:78"},{"arabic":"يَفْقَهُوا۟","transliteration":"","meaning":"That they may understand","rule":"20:28"},{"arabic":"تَفْقَهُونَ","transliteration":"","meaning":"you understand","rule":"17:44"},{"arabic":"يَفْقَهُوهُ","transliteration":"","meaning":"they understand it","rule":"6:25"},{"arabic":"لِّيَتَفَقَّهُوا۟","transliteration":"","meaning":"that they may obtain understanding","rule":"9:122"},{"arabic":"نَفْقَهُ","transliteration":"","meaning":"we understand","rule":"11:91"}],"rules":[{"name":"Words on فقه","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَفْقَهُونَ","يَفْقَهُوا۟","تَفْقَهُونَ","يَفْقَهُوهُ","لِّيَتَفَقَّهُوا۟","نَفْقَهُ"]},{"name":"Parts of speech attested for فقه","description":"The morphology corpus tags words on this root as V — one part of speech across the 6 glossed words attested.","examples":["يَفْقَهُونَ","يَفْقَهُوا۟","تَفْقَهُونَ","يَفْقَهُوهُ","لِّيَتَفَقَّهُوا۟","نَفْقَهُ"]},{"name":"Verb forms attested for فقه","description":"Where this root is tagged as a verb, the corpus attests derived Form V.","examples":["يَفْقَهُونَ","يَفْقَهُوا۟","تَفْقَهُونَ","يَفْقَهُوهُ","لِّيَتَفَقَّهُوا۟","نَفْقَهُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root فقه?","options":["وَيَأْمُرُونَ","شَيْـًٔا","يَفْقَهُونَ","ءَابَآءَنَآ"],"correct":2,"explanation":"يَفْقَهُونَ — glossed \"(to) understand\" at 4:78 — carries the root فقه. The others come from different roots."},{"type":"multiple_choice","question":"What does يَفْقَهُوا۟ mean?","options":["the painful","(of) our gods","That they may understand","and the faith"],"correct":2,"explanation":"\"That they may understand\", from the word-by-word gloss at 20:28."},{"type":"fill_blank","question":"Type the root of تَفْقَهُونَ in Arabic (three letters).","correct":"فقه","explanation":"فقه. Diacritics are ignored when checking, so ف ق ه is enough."}]', '["root-fTr"]', 30, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-k$f', 'The root كشف (ك ش ف)', 'grammar', 4, '{"explanation":"The root كشف occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 15 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَاشِفَةٌ","transliteration":"","meaning":"any remover","rule":"53:58"},{"arabic":"كَـٰشِفَـٰتُ","transliteration":"","meaning":"removers","rule":"39:38"},{"arabic":"كَشَفْنَا","transliteration":"","meaning":"We removed","rule":"7:135"},{"arabic":"كَاشِفُوا۟","transliteration":"","meaning":"(will) remove","rule":"44:15"},{"arabic":"كَشْفَ","transliteration":"","meaning":"(to) remove","rule":"17:56"},{"arabic":"فَكَشَفْنَا","transliteration":"","meaning":"and We removed","rule":"21:84"}],"rules":[{"name":"Words on كشف","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَاشِفَةٌ","كَـٰشِفَـٰتُ","كَشَفْنَا","كَاشِفُوا۟","كَشْفَ","فَكَشَفْنَا","فَيَكْشِفُ","وَيَكْشِفُ"]},{"name":"Parts of speech attested for كشف","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 15 glossed words attested.","examples":["كَاشِفَةٌ","كَـٰشِفَـٰتُ","كَشَفْنَا","كَاشِفُوا۟","كَشْفَ","فَكَشَفْنَا"]},{"name":"Where كشف occurs","description":"The 15 glossed words on this root are attested across 11 distinct surahs.","examples":["كَاشِفَةٌ (53:58)","كَـٰشِفَـٰتُ (39:38)","كَشَفْنَا (7:135)","كَاشِفُوا۟ (44:15)","كَشْفَ (17:56)","فَكَشَفْنَا (21:84)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كشف?","options":["أَتَأْخُذُونَهُۥ","ذَرْعُهَا","كَاشِفَةٌ","ٱلْإِنسِ"],"correct":2,"explanation":"كَاشِفَةٌ — glossed \"any remover\" at 53:58 — carries the root كشف. The others come from different roots."},{"type":"multiple_choice","question":"What does كَـٰشِفَـٰتُ mean?","options":["testifies","they perceive","Allah wishes","removers"],"correct":3,"explanation":"\"removers\", from the word-by-word gloss at 39:38."},{"type":"fill_blank","question":"Type the root of كَشَفْنَا in Arabic (three letters).","correct":"كشف","explanation":"كشف. Diacritics are ignored when checking, so ك ش ف is enough."}]', '["root-fqh"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-lEb', 'The root لعب (ل ع ب)', 'grammar', 4, '{"explanation":"The root لعب occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَلْعَبُونَ","transliteration":"","meaning":"playing","rule":"6:91"},{"arabic":"لَـٰعِبِينَ","transliteration":"","meaning":"(for) playing","rule":"21:16"},{"arabic":"وَيَلْعَبْ","transliteration":"","meaning":"and play","rule":"12:12"},{"arabic":"وَلَعِبًۭا","transliteration":"","meaning":"and fun","rule":"5:57"},{"arabic":"لَعِبٌۭ","transliteration":"","meaning":"a play","rule":"6:32"},{"arabic":"وَلَعِبٌۭ","transliteration":"","meaning":"and play","rule":"29:64"}],"rules":[{"name":"Words on لعب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَلْعَبُونَ","لَـٰعِبِينَ","وَيَلْعَبْ","وَلَعِبًۭا","لَعِبٌۭ","وَلَعِبٌۭ","ٱللَّـٰعِبِينَ","لَعِبًۭا"]},{"name":"Parts of speech attested for لعب","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 10 glossed words attested.","examples":["يَلْعَبُونَ","لَـٰعِبِينَ","وَيَلْعَبْ","وَلَعِبًۭا","لَعِبٌۭ","وَلَعِبٌۭ"]},{"name":"Where لعب occurs","description":"The 10 glossed words on this root are attested across 7 distinct surahs.","examples":["يَلْعَبُونَ (6:91)","لَـٰعِبِينَ (21:16)","وَيَلْعَبْ (12:12)","وَلَعِبًۭا (5:57)","لَعِبٌۭ (6:32)","وَلَعِبٌۭ (29:64)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root لعب?","options":["وَيُذْهِبْ","فَـَٔاتَيْنَا","يَلْعَبُونَ","ٱللَّهُ"],"correct":2,"explanation":"يَلْعَبُونَ — glossed \"playing\" at 6:91 — carries the root لعب. The others come from different roots."},{"type":"multiple_choice","question":"What does لَـٰعِبِينَ mean?","options":["for the later (generations)","for the believers","remember","(for) playing"],"correct":3,"explanation":"\"(for) playing\", from the word-by-word gloss at 21:16."},{"type":"fill_blank","question":"Type the root of وَيَلْعَبْ in Arabic (three letters).","correct":"لعب","explanation":"لعب. Diacritics are ignored when checking, so ل ع ب is enough."}]', '["root-k$f"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-mry', 'The root مري (م ر ي)', 'grammar', 4, '{"explanation":"The root مري occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, V, in verb forms VIII, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَفَتُمَـٰرُونَهُۥ","transliteration":"","meaning":"Then will you dispute with him","rule":"53:12"},{"arabic":"مِرَآءًۭ","transliteration":"","meaning":"(with) an argument","rule":"18:22"},{"arabic":"تُمَارِ","transliteration":"","meaning":"argue","rule":"18:22"},{"arabic":"تَمْتَرُنَّ","transliteration":"","meaning":"(be) doubtful","rule":"43:61"},{"arabic":"ٱلْمُمْتَرِينَ","transliteration":"","meaning":"the doubters","rule":"2:147"},{"arabic":"تَمْتَرُونَ","transliteration":"","meaning":"doubt","rule":"6:2"}],"rules":[{"name":"Words on مري","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَفَتُمَـٰرُونَهُۥ","مِرَآءًۭ","تُمَارِ","تَمْتَرُنَّ","ٱلْمُمْتَرِينَ","تَمْتَرُونَ","مِرْيَةٍۢ","تَتَمَارَىٰ"]},{"name":"Parts of speech attested for مري","description":"The morphology corpus tags words on this root as N, V — 2 distinct parts of speech across the 11 glossed words attested.","examples":["أَفَتُمَـٰرُونَهُۥ","مِرَآءًۭ","تُمَارِ","تَمْتَرُنَّ","ٱلْمُمْتَرِينَ","تَمْتَرُونَ"]},{"name":"Verb forms attested for مري","description":"Where this root is tagged as a verb, the corpus attests derived Forms VIII, III.","examples":["أَفَتُمَـٰرُونَهُۥ","مِرَآءًۭ","تُمَارِ","تَمْتَرُنَّ","ٱلْمُمْتَرِينَ","تَمْتَرُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root مري?","options":["فَخُذُوهُمْ","أَفَتُمَـٰرُونَهُۥ","وَٱلْأُولَىٰ","نَتَّخِذَهُۥ"],"correct":1,"explanation":"أَفَتُمَـٰرُونَهُۥ — glossed \"Then will you dispute with him\" at 53:12 — carries the root مري. The others come from different roots."},{"type":"multiple_choice","question":"What does مِرَآءًۭ mean?","options":["(for) the first of the two","(with) an argument","(is) surely severe","safe"],"correct":1,"explanation":"\"(with) an argument\", from the word-by-word gloss at 18:22."},{"type":"fill_blank","question":"Type the root of تُمَارِ in Arabic (three letters).","correct":"مري","explanation":"مري. Diacritics are ignored when checking, so م ر ي is enough."}]', '["root-lEb"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nfx', 'The root نفخ (ن ف خ)', 'grammar', 4, '{"explanation":"The root نفخ occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 10 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَنُفِخَ","transliteration":"","meaning":"and (will be) blown","rule":"18:99"},{"arabic":"يُنفَخُ","transliteration":"","meaning":"will be blown","rule":"6:73"},{"arabic":"نَفْخَةٌۭ","transliteration":"","meaning":"a blast","rule":"69:13"},{"arabic":"فَتَنفُخُ","transliteration":"","meaning":"then you breath","rule":"5:110"},{"arabic":"وَنَفَخَ","transliteration":"","meaning":"and breathed","rule":"32:9"},{"arabic":"فَنَفَخْنَا","transliteration":"","meaning":"so We breathed","rule":"21:91"}],"rules":[{"name":"Words on نفخ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَنُفِخَ","يُنفَخُ","نَفْخَةٌۭ","فَتَنفُخُ","وَنَفَخَ","فَنَفَخْنَا","ٱنفُخُوا۟","نُفِخَ"]},{"name":"Parts of speech attested for نفخ","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 10 glossed words attested.","examples":["وَنُفِخَ","يُنفَخُ","نَفْخَةٌۭ","فَتَنفُخُ","وَنَفَخَ","فَنَفَخْنَا"]},{"name":"Where نفخ occurs","description":"The 10 glossed words on this root are attested across 9 distinct surahs.","examples":["وَنُفِخَ (18:99)","يُنفَخُ (6:73)","نَفْخَةٌۭ (69:13)","فَتَنفُخُ (5:110)","وَنَفَخَ (32:9)","فَنَفَخْنَا (21:91)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نفخ?","options":["أَمْرِهِۦ","وَنُفِخَ","أَخَذَ","أَبَىٰ"],"correct":1,"explanation":"وَنُفِخَ — glossed \"and (will be) blown\" at 18:99 — carries the root نفخ. The others come from different roots."},{"type":"multiple_choice","question":"What does يُنفَخُ mean?","options":["will be blown","(to) one of you","[and] payment","You commanded me"],"correct":0,"explanation":"\"will be blown\", from the word-by-word gloss at 6:73."},{"type":"fill_blank","question":"Type the root of نَفْخَةٌۭ in Arabic (three letters).","correct":"نفخ","explanation":"نفخ. Diacritics are ignored when checking, so ن ف خ is enough."}]', '["root-mry"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nxl', 'The root نخل (ن خ ل)', 'grammar', 4, '{"explanation":"The root نخل occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِنَخْلٍۢ","transliteration":"","meaning":"with date-palms","rule":"18:32"},{"arabic":"وَنَخِيلٌۭ","transliteration":"","meaning":"and date-palms","rule":"13:4"},{"arabic":"وَنَخْلٍۢ","transliteration":"","meaning":"and date-palms","rule":"26:148"},{"arabic":"ٱلنَّخِيلِ","transliteration":"","meaning":"the date-palm","rule":"16:67"},{"arabic":"وَنَخْلًۭا","transliteration":"","meaning":"and date-palms","rule":"80:29"},{"arabic":"نَخْلٍ","transliteration":"","meaning":"(of) date-palms","rule":"69:7"}],"rules":[{"name":"Words on نخل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِنَخْلٍۢ","وَنَخِيلٌۭ","وَنَخْلٍۢ","ٱلنَّخِيلِ","وَنَخْلًۭا","نَخْلٍ","ٱلنَّخْلَةِ","وَٱلنَّخْلُ"]},{"name":"Parts of speech attested for نخل","description":"The morphology corpus tags words on this root as N — one part of speech across the 14 glossed words attested.","examples":["بِنَخْلٍۢ","وَنَخِيلٌۭ","وَنَخْلٍۢ","ٱلنَّخِيلِ","وَنَخْلًۭا","نَخْلٍ"]},{"name":"Where نخل occurs","description":"The 14 glossed words on this root are attested across 11 distinct surahs.","examples":["بِنَخْلٍۢ (18:32)","وَنَخِيلٌۭ (13:4)","وَنَخْلٍۢ (26:148)","ٱلنَّخِيلِ (16:67)","وَنَخْلًۭا (80:29)","نَخْلٍ (69:7)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نخل?","options":["ٱلْمُؤْمِنِينَ","بِنَخْلٍۢ","ٱللَّهُ","ٱلْأُنثَىٰ"],"correct":1,"explanation":"بِنَخْلٍۢ — glossed \"with date-palms\" at 18:32 — carries the root نخل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَنَخِيلٌۭ mean?","options":["grateful","(again) believed","and date-palms","(to) eat"],"correct":2,"explanation":"\"and date-palms\", from the word-by-word gloss at 13:4."},{"type":"fill_blank","question":"Type the root of وَنَخْلٍۢ in Arabic (three letters).","correct":"نخل","explanation":"نخل. Diacritics are ignored when checking, so ن خ ل is enough."}]', '["root-nfx"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-nzE', 'The root نزع (ن ز ع)', 'grammar', 4, '{"explanation":"The root نزع occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 16 distinct glossed words, tagged in the corpus as V, N, in verb forms VI, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَنَـٰزَعْتُمْ","transliteration":"","meaning":"you disagree","rule":"4:59"},{"arabic":"وَتَنَـٰزَعْتُمْ","transliteration":"","meaning":"and you fell into dispute","rule":"3:152"},{"arabic":"لَنَنزِعَنَّ","transliteration":"","meaning":"surely, We will drag out","rule":"19:69"},{"arabic":"فَتَنَـٰزَعُوٓا۟","transliteration":"","meaning":"Then they disputed","rule":"20:62"},{"arabic":"نَزَعْنَـٰهَا","transliteration":"","meaning":"We withdraw it","rule":"11:9"},{"arabic":"يَنزِعُ","transliteration":"","meaning":"stripping","rule":"7:27"}],"rules":[{"name":"Words on نزع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَنَـٰزَعْتُمْ","وَتَنَـٰزَعْتُمْ","لَنَنزِعَنَّ","فَتَنَـٰزَعُوٓا۟","نَزَعْنَـٰهَا","يَنزِعُ","وَٱلنَّـٰزِعَـٰتِ","يَتَنَـٰزَعُونَ"]},{"name":"Parts of speech attested for نزع","description":"The morphology corpus tags words on this root as V, N — 2 distinct parts of speech across the 16 glossed words attested.","examples":["تَنَـٰزَعْتُمْ","وَتَنَـٰزَعْتُمْ","لَنَنزِعَنَّ","فَتَنَـٰزَعُوٓا۟","نَزَعْنَـٰهَا","يَنزِعُ"]},{"name":"Verb forms attested for نزع","description":"Where this root is tagged as a verb, the corpus attests derived Forms VI, III.","examples":["تَنَـٰزَعْتُمْ","وَتَنَـٰزَعْتُمْ","لَنَنزِعَنَّ","فَتَنَـٰزَعُوٓا۟","نَزَعْنَـٰهَا","يَنزِعُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نزع?","options":["شُفَعَـٰٓؤُا۟","شَيْـًۭٔا","تَنَـٰزَعْتُمْ","تَأْمُرُونَ"],"correct":2,"explanation":"تَنَـٰزَعْتُمْ — glossed \"you disagree\" at 4:59 — carries the root نزع. The others come from different roots."},{"type":"multiple_choice","question":"What does وَتَنَـٰزَعْتُمْ mean?","options":["You believe","He refused","and you fell into dispute","And Allah will surely make evident"],"correct":2,"explanation":"\"and you fell into dispute\", from the word-by-word gloss at 3:152."},{"type":"fill_blank","question":"Type the root of لَنَنزِعَنَّ in Arabic (three letters).","correct":"نزع","explanation":"نزع. Diacritics are ignored when checking, so ن ز ع is enough."}]', '["root-nxl"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-rbw', 'The root ربو (ر ب و)', 'grammar', 4, '{"explanation":"The root ربو occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"رِّبًۭا","transliteration":"","meaning":"usury","rule":"30:39"},{"arabic":"ٱلرِّبَوٰٓا۟","transliteration":"","meaning":"[the] usury","rule":"2:278"},{"arabic":"رَبْوَةٍۢ","transliteration":"","meaning":"a high ground","rule":"23:50"},{"arabic":"رَّابِيًۭا","transliteration":"","meaning":"rising","rule":"13:17"},{"arabic":"بِرَبْوَةٍ","transliteration":"","meaning":"on a height","rule":"2:265"},{"arabic":"رَبَّيَانِى","transliteration":"","meaning":"they brought me up","rule":"17:24"}],"rules":[{"name":"Words on ربو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["رِّبًۭا","ٱلرِّبَوٰٓا۟","رَبْوَةٍۢ","رَّابِيًۭا","بِرَبْوَةٍ","رَبَّيَانِى","وَيُرْبِى","يَرْبُوا۟"]},{"name":"Parts of speech attested for ربو","description":"The morphology corpus tags words on this root as N, V, ADJ — 3 distinct parts of speech across the 14 glossed words attested.","examples":["رِّبًۭا","ٱلرِّبَوٰٓا۟","رَبْوَةٍۢ","رَّابِيًۭا","بِرَبْوَةٍ","رَبَّيَانِى"]},{"name":"Verb forms attested for ربو","description":"Where this root is tagged as a verb, the corpus attests derived Forms IV, II.","examples":["رِّبًۭا","ٱلرِّبَوٰٓا۟","رَبْوَةٍۢ","رَّابِيًۭا","بِرَبْوَةٍ","رَبَّيَانِى"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ربو?","options":["وَٱذْكُرْ","بِـَٔايَـٰتِ","رِّبًۭا","أَمَرْتَنِى"],"correct":2,"explanation":"رِّبًۭا — glossed \"usury\" at 30:39 — carries the root ربو. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلرِّبَوٰٓا۟ mean?","options":["anyone","[the] usury","we believe","they had been reminded"],"correct":1,"explanation":"\"[the] usury\", from the word-by-word gloss at 2:278."},{"type":"fill_blank","question":"Type the root of رَبْوَةٍۢ in Arabic (three letters).","correct":"ربو","explanation":"ربو. Diacritics are ignored when checking, so ر ب و is enough."}]', '["root-nzE"]', 31, NULL);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes, category) VALUES ('root-snw', 'The root سنو (س ن و)', 'grammar', 4, '{"explanation":"The root سنو occurs 20 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N, T. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَنَةٍ","transliteration":"","meaning":"year(s)","rule":"29:14"},{"arabic":"سَنَةًۭ","transliteration":"","meaning":"years","rule":"5:26"},{"arabic":"سَنَا","transliteration":"","meaning":"(the) flash","rule":"24:43"},{"arabic":"سَنَةٍۢ","transliteration":"","meaning":"year(s)","rule":"2:96"},{"arabic":"بِٱلسِّنِينَ","transliteration":"","meaning":"with years (of famine)","rule":"7:130"},{"arabic":"ٱلسِّنِينَ","transliteration":"","meaning":"(of) the years","rule":"10:5"}],"rules":[{"name":"Words on سنو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَنَةٍ","سَنَةًۭ","سَنَا","سَنَةٍۢ","بِٱلسِّنِينَ","ٱلسِّنِينَ","سِنِينَ"]},{"name":"Parts of speech attested for سنو","description":"The morphology corpus tags words on this root as N, T — 2 distinct parts of speech across the 7 glossed words attested.","examples":["سَنَةٍ","سَنَةًۭ","سَنَا","سَنَةٍۢ","بِٱلسِّنِينَ","ٱلسِّنِينَ"]},{"name":"Where سنو occurs","description":"The 7 glossed words on this root are attested across 7 distinct surahs.","examples":["سَنَةٍ (29:14)","سَنَةًۭ (5:26)","سَنَا (24:43)","سَنَةٍۢ (2:96)","بِٱلسِّنِينَ (7:130)","ٱلسِّنِينَ (10:5)"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سنو?","options":["سَنَةٍ","بِأَمْرِهِۦ","يَأْتُونَنَا","أَحَدَكُم"],"correct":0,"explanation":"سَنَةٍ — glossed \"year(s)\" at 29:14 — carries the root سنو. The others come from different roots."},{"type":"multiple_choice","question":"What does سَنَةًۭ mean?","options":["then let them ask permission","through your brother","years","the man"],"correct":2,"explanation":"\"years\", from the word-by-word gloss at 5:26."},{"type":"fill_blank","question":"Type the root of سَنَا in Arabic (three letters).","correct":"سنو","explanation":"سنو. Diacritics are ignored when checking, so س ن و is enough."}]', '["root-rbw"]', 31, NULL);
